In this section we define higher categories following \cite[\S 3]{GepnerHeine}, \cite[\S 4]{GepnerHeine}.

\subsection{$\infty$-categories}

In this subsection we define $\infty$-categories following \cite[\S 3]{GepnerHeine}. 

\begin{definition}
Let $\mV$ be a category that admits finite limits.
A category object in $\mV$ is a	functor $X: \Delta^\op \to \mV$ such that for every $n \geq 0$
the induced morphism $X_n \to X_1 \times_{X_0} ... \times_{X_0} X_1$ is an equivalence.
\end{definition}

\begin{notation}Let $\mV$ be a presentable category such that the unique left adjoint functor
$\mS \to \mV$ preserving the final object is fully faithful.
Let $\Cat_0(\mV) \subset \Fun(\Delta^\op,\mV)$ be the full subcategory of category objects
$X$ such that $X_0$ belongs to the essential image of the functor $\mS \to \mV$.

\end{notation}

%By ... for every presentable cartesian closed category $\mV$ such that the unique left adjoint functor $\mS \to \mV$ preserving the final object is fully faithful, 
If moreover the embedding $\mS \to \mV$ admits a left adjoint, 
by \cite[2.0.6., 2.0.7.]{GepnerHeine} the category $\Cat_0(\mV)$
is presentable cartesian closed and the unique left adjoint functor
$\mS \to \Cat_0(\mV)$ preserving the final object is fully faithful and admits a left adjoint.
Moreover any left adjoint functor between two such presentable cartesian closed categories $\mV,\mW$ induces a left adjoint functor $\Cat_0(\mV) \to \Cat_0(\mW).$

\begin{definition}
For every $n \geq 0$ we inductively define the presentable cartesian closed category $n\Cat$ of small (non-univalent) $n$-categories by setting:
$$0\Cat :=\mS,\ (n+1)\Cat:= \Cat_0(n\Cat).$$

\end{definition}

\begin{notation}
For every $n \geq 0$ we inductively define colocalizations
$n\Cat \rightleftarrows (n+1)\Cat: \iota_n,$
where both adjoints  preserve finite products and filtered colimits.
Let
$$0\Cat= \mS \rightleftarrows 1\Cat = \Cat_0(\mS) : \iota_0 $$ be the unique colocalization whose left adjoint preserves finite products. Let $$(n+1)\Cat= \Cat_0(n\Cat) \rightleftarrows (n+2)\Cat= \Cat_0((n+1)\Cat):\iota_{n+1}:= (\iota_n)_!. $$
%be the induced adjunction.	

\end{notation}

\begin{definition}The presentable cartesian closed category $\infty\Cat$ of small %(non-univalent) 
$\infty$-categories is the limit
$$\infty\Cat:= \lim(...\xrightarrow{\iota_{n}} n \Cat \xrightarrow{\iota_{n-1}} ... \xrightarrow{\iota_0} 0 \Cat) $$
of presentable cartesian closed categories and right adjoint functors. 

\end{definition}

%The next observation is \cite[Remark 2.6.12.]{stefanich2020presentable}:

Since forming category objects preserves limits, we obtain the following:

\begin{remark}\label{fix}

There is a canonical equivalence
$ \infty\Cat \simeq \Cat_0(\infty\Cat). $
%that restricts to equivalences
%$$\infty\Cat^\univ \simeq \Cat_0^{\univ}(\infty\Cat^\univ),$$
%$$\infty\Cat^{\mathrm{strict}} \simeq \Cat(\infty\Cat^{\mathrm{strict}},\Set).$$
%where the enrichment is with respect to the cartesian symmetricmonoidal structures.

\end{remark}

\begin{notation}
Let $\Mor: \infty\Cat_{\partial\bD^1/} \to \infty\Cat$
be the functor $$\infty\Cat_{\partial\bD^1/} \simeq \mS_{* \coprod */}\times_\mS \Cat_0(\infty\Cat) \to \infty\Cat $$
sending $(\mC,X,Y)$ to $\Mor_\mC(X,Y):= \{X\}\times_{\mC_0}\mC_1 \times_{\mC_0} \{Y\}.$
\end{notation}

\begin{remark}\label{homfil}
The functor $\Mor: \infty\Cat_{\partial\bD^1/} \to \infty\Cat$ preserves small limits and small filtered colimits.
% and univalent and strict $\infty$-categories.

\end{remark}

\begin{notation}
For every $0 \leq n \leq \m$ the left adjoint embeddings $n\Cat \leftrightarrows \m\Cat$ preserve small limits and thus induce a left adjoint embedding $n\Cat \leftrightarrows \infty\Cat: \iota_n$ that preserves small limits
and so admits a left adjoint $\tau_n: \infty\Cat \to n\Cat$ by presentability.

%Similarly, we obtain left adjoint embeddings $$n\Cat^{\mathrm{univ}}\leftrightarrows \infty\Cat^{\mathrm{univ}}: \iota_n, n\Cat^{\mathrm{strict}}\leftrightarrows \infty\Cat^{\mathrm{strict}}: \iota_n$$ that preserve small limits and so admit left adjoints, which we also denote by $\tau_n.$

\end{notation}

Bt the limit definition of $\infty\Cat$ we have the following filtration \cite[Lemma 2.3.10.]{GepnerHeine}:

\begin{lemma}\label{decom}
Let $\mC$ be an $\infty$-category.
The sequential diagram $$\iota_0(\mC) \to ... \to \iota_n(\mC) \to \iota_{n+1}(\mC) \to ... \to \mC$$ exhibits $\mC$ as the colimit in $\infty\Cat$ of the diagram $\iota_0(\mC) \to ... \to \iota_n(\mC) \to \iota_{n+1}(\mC) \to ....$
\end{lemma}

