\begin{definition}Let $ n \geq 1.$ By induction on $n$ we define $n$-univalent $\infty$-categories.
%Any $\infty$-category is 0-univalent.
An $\infty$-category is 1-univalent if it is local with respect to the unique functor $\{0 \simeq 1 \} \to *$.
An $\infty$-category is $n$-univalent if it is 1-univalent and all morphism $\infty$-categories are $n$-1-univalent.
An $\infty$-category is univalent if it is $n$-univalent for every $n \geq 0.$
\end{definition}

\begin{definition}Let $ n \geq 0.$ By induction on $n$ we define $n$-strict $\infty$-categories.
An $\infty$-category is 0-strict if the underlying space is a set. 
A $\infty$-category is $n$-strict if it is 0-strict and all morphism $\infty$-categories are $n$-1-strict.
An $\infty$-category is strict if it is $n$-strict for every $n \geq 0.$
\end{definition}

\begin{definition}%Let $ n \geq 1.$
%An $\infty$-category is $n$-gaunt if it is $n$-strict and $n$-univalent.
An $\infty$-category is gaunt if it is strict and univalent.
\end{definition}

