\subsubsection{Homotopy categories}

\begin{definition}
For every $n \geq 0$ we inductively define the presentable cartesian closed category $(n,n)\Cat$ of small (non-univalent) $(n,n)$-categories by setting:
$$(0,0)\Cat :=\Set,\ (n+1,n+1)\Cat:= \Cat_0((n,n)\Cat).$$

\end{definition}

\begin{definition}

For every $n \geq 0$ we inductively define the functor of homotopy $(n,n)$-category
$$\Ho_n: \infty\Cat \to (n,n)\Cat$$ by setting
$$\Ho_0:=\pi_0 \iota_0 : \infty\Cat \to \Set, \ 
\Ho_n:=(\Ho_{n-1})_! : \infty\Cat\simeq  \Cat_0({\infty\Cat}) \to (n,n)\Cat= \Cat_0((n-1,n-1)\Cat).$$
\end{definition}

\begin{remark}Note that $\Ho_n \simeq \Ho_n \circ \iota_n.$

\end{remark}

\begin{definition}Let $n \geq 0.$
A functor $\F: \mC \to \mD$ is an $n$-equivalence
if it induces an equivalence on homotopy $n$-categories. % for any $0 \leq \m \leq n$.
\end{definition}

\begin{remark}\label{reft} Let $n \geq 1.$
By the inductive definition of the homotopy $n$-category a functor is an $n$-equivalence if and only if it is essentially surjective and induces on morphism $\infty$-categories $n$-1-equivalences.
Moreover every $n$-equivalence is in particular a $\m$-equivalence for every $\m \leq n.$

\end{remark}

\begin{lemma}\label{homt} A functor $\F: \mC \to \mD$ is an equivalence if and only if it is an $n$-equivalence for every $n \geq 0.$
\end{lemma}

\begin{proof}
The only if-direction is clear. We prove the other direction.	
We first reduce to the case that $\mC,\mD$ are $\bk$-categories for some $\bk \geq 0.$
%Let $\lambda_n: (n+1,n+1)\Cat \to (n,n)\Cat$ be the inductively defined functorsuch that $\lambda_0 $ is the functor sending a discrete category to the set of isomorphism classes of objects and $$\lambda_{n+1}:= (\lambda_n)_*: (n+2,n+2)\Cat= {_{(n+1,n+1)\Cat}\Cat} \to (n+1,n+1)\Cat= {_{(n,n)\Cat}\Cat}.$$
Let $n \geq 0.$ For every $\infty$-category $\mB$ and $\bk \leq n$ the $(n,n)$-category $\Ho_{n}(\iota_\bk\mC)$ is the underlying $n,\bk$-category of $\Ho_n(\mC).$	
Consequently, if $\F$ is an $n$-equivalence, the functor $\iota_\bk\F$ is an $n$-equivalence for every $\bk \geq 0.$
So if $\F$ is an $n$-equivalence for every $n \geq 0,$ then $\iota_\bk\F$ is an $n$-equivalence for every $n,\bk \geq 0.$
Thus $\iota_\bk\F$ is an equivalence for every $\bk \geq 0$ if we have proven the result in case that $\mC,\mD$ are $\bk$-categories.
So we can assume that $\mC,\mD$ are $\bk$-categories.
We proceed by induction on $\bk \geq 0.$
For $n=0$ the result follows from the fact that a map of spaces is an equivalence if it induces isomorphisms on all homotopy groups.
We assume the statement for $\bk$ and let $\F:\mC \to \mD$ be a functor of $\bk+1$-categories that is an $n$-equivalence for every $n \geq 0.$
Then $\F$ is a $0$-equivalence, i.e. induces an equivalence on the set of equivalence classes.
In particular, $\F$ is essentially surjective. So $\F$ is an equivalence if
$\F$ is fully faithful. By \cref{reft} for every $X,Y \in \mC$ the induced functor $\Mor_\mC(X,Y)\to \Mor_\mD(\F(X),\F(Y))$ is a functor of $\bk$-categories that is an $n$-equivalence for every $n \geq 0.$ So by induction hypothesis the functor $\Mor_\mC(X,Y)\to \Mor_\mD(\F(X),\F(Y))$ is an equivalence. 	
\end{proof}	

