\subsubsection{Suspension}

%Proposition \ref{susp} \cite[Definition 4.3.21.]{GEPNER2015575} 
By \cite[Definition 3.4.2.]{GepnerHeine} there is an $\infty$-category satisfying the following: %definition: 

\begin{definition}\label{suspi}
Let $\mC$ be an $\infty$-category. The categorical suspension of $\mC$, denoted by $S(\mC),$
is the $\infty$-category whose underlying space has two elements $0,1$ and whose morphism $\infty$-categories are $$\Mor_{S(\mC)}(1,0)\simeq \emptyset, \ \Mor_{S(\mC)}(0,1)\simeq \mC, \ \Mor_{S(\mC)}(0,0)\simeq \Mor_{S(\mC)}(1,1) \simeq *$$ 
and such that for every $\infty$-category $\mD$ containing objects $Y,Z \in \mD$
the induced map \begin{equation*}
\infty\Cat_{\partial\bD^1/}((S(\mC), 0,1),(\mD, Y,Z) ) \to \infty\Cat(\mC, \Mor_\mD(Y,Z)) \end{equation*} is an equivalence.

\end{definition}

\begin{remark}
The functor $S: \infty\Cat \to \infty\Cat_{\partial\bD^1/}$ preserves strictness and univalence.
%For every gaunt $\infty$-category $\mC$ the categorical suspension $S(\mC)$ is gaunt.
%To see this it suffices to observe that every non-identity morphism of $S(\mC)$ is not invertible since it goes from 0 to 1
%and there is no morphism from 1 to 0 in $S(\mC).$

\end{remark}

\begin{definition}\label{susa}
For every $\infty$-category $\mC$ the categorical cosuspension of $\mC$ is $S'(\mC):=S(\mC^\co)^\co.$

\end{definition}

