\begin{definition}Let $n \geq 0$.
The $n$-disk (or walking $n$-morphism) is $\bD^n:= S^{n}(*).$

\end{definition}

\begin{definition}Let $n \geq 0$.
The boundary of the $n$-disk is $\partial\bD^n:= S^{n}(\emptyset).$

\end{definition}

\begin{remark}
The functor $\emptyset \subset *$ induces inclusions $\partial\bD^n \subset \bD^n$ for every $n \geq 0.$

\end{remark}

\begin{example}
Then $\partial\bD^0=\ast, \partial\bD^1=S(\emptyset)=*\coprod*$ is the set with two elements.	
\end{example}

