\begin{definition}\label{conn} Let $n \geq 0$.
An $\infty$-category $\mC$ is $n$-connected if the underlying space of $\mC$ is $n$-connected and all morphism $\infty$-categories are $n$-1-connected.
Every $\infty$-category is -1-connected by convention.
\end{definition}

\begin{remark}
Let $n \geq 0$. By induction an $\infty$-category is $n$-connected if it is $n$+1-connected.

\end{remark}

