$$B^{n+1}: \Mon_{\bE_{n+1}}(\infty\Cat)\simeq \Mon(\Mon_{\bE_n}(\infty\Cat)) \rightleftarrows \Mon(\infty\Cat) \rightleftarrows \infty\Cat_*: \Omega^{n+1}$$
preserves finite products and induces an equivalence to the full subcategory of $n$-connected $\infty$-categories with distinguished object.

\end{proof}

\begin{corollary}\label{connel} Let $n \geq0.$
The full subcategory of $\infty\Cat_*$ of $n$-1-connected $\infty$-categories with distinguished object is generated under small colimits by the essential image of $\Sigma^n: \infty\Cat_* \to \infty\Cat_*.$

\end{corollary}

\begin{proof}
The category $ \Mon_{\bE_n}(\infty\Cat)$ is generated under small colimits by the free functor
$\infty\Cat_* \to  \Mon_{\bE_n}(\infty\Cat)$. So the result follows from \cref{deloop} and that the functor $\Sigma^n: \infty\Cat_* \to \infty\Cat_*$ factors as the free functor followed by $B^n.$	

\end{proof}

