\begin{corollary}\label{autoeq} Let $n \geq \m \geq 0.$

\begin{enumerate}
\item There is a canonical isomorphism of monoids $\pi_0(\infty\Cat_*(S^n,S^n)) \cong \bN.$

\item There is a canonical isomorphism $\pi_0(\infty\Cat_*(S^n,S^\m)) \cong *.$

\item There is a canonical isomorphism $\pi_0(\infty\Cat_*(S^\m,S^n)) \cong \pi_{n-\m}(\Free_{\bE_\m}(*)).$

\item There is a canonical isomorphism of monoids $\pi_0((\iota_0\infty\Cat_*)(S^n,S^n)) \cong \bN^\times \cong 0.$
\end{enumerate}	

\end{corollary}

\begin{proof}

(1): By \cref{freesp} there is a canonical equivalence of $\bA_\infty$-spaces  $$\infty\Cat_*(S^n,S^n) \simeq \Mon_{\bE_n}(\infty\Cat)(\Free_{\bE_n}(*),\Free_{\bE_n}(*)) \simeq \infty\Cat(*,\Free_{\bE_n}(*)) \simeq \Free_{\bE_n}(*).$$
The latter induces an isomorphism of monoids $\pi_0(\infty\Cat_*(S^n,S^n)) \cong \pi_0(\Free_{\bE_n}(*)).$
By universal property there is a canonical isomorphism of monoids
$\pi_0(\Free_{\bE_n}(*))\cong \bN.$

(2): By \cref{freesp} there is a canonical equivalence of spaces  $$\infty\Cat_*(S^\m,S^n) \simeq \Mon_{\bE_\m}(\infty\Cat)(\Free_{\bE_\m}(*),B^{n-\m}\Free_{\bE_n}(*)) \simeq \infty\Cat(*,B^{n-\m}\Free_{\bE_n}(*)).$$
The latter induces an isomorphism $\pi_0(\infty\Cat_*(S^\m,S^n)) \cong \pi_0(\infty\Cat(*,B^{n-\m}\Free_{\bE_n}(*))) \cong *.$

(3): By \cref{freesp} there is a canonical equivalence of spaces  $$\infty\Cat_*(S^n,S^\m) \simeq \Mon_{\bE_n}(\infty\Cat)(\Free_{\bE_n}(*),\Omega^{n-\m}\Free_{\bE_\m}(*)) \simeq \infty\Cat(*,\Omega^{n-\m}\Free_{\bE_\m}(*)).$$
The latter induces an isomorphism $$\pi_0(\infty\Cat_*(S^n,S^\m)) \cong \pi_0(\infty\Cat(*,\Omega^{n-\m}\Free_{\bE_\m}(*))) \cong \pi_{n-\m}(\Free_{\bE_\m}(*)).$$
(4) follows immediately from (1).
\end{proof}

