\begin{notation}\begin{itemize}Let $\mV,\mW$ be presentably monoidal categories.
\item Let $\mC$ be a left $\mV$-enriched category and $X,Y \in \mC.$	
Then we denote the object of morphisms $X \to Y$ as $\L\Mor_\mC(X, Y) \in \mV$ and call it the left morphism object.

\item Let $\mC$ be a right $\mW$-enriched category and $X,Y \in \mC.$	
Then we denote the object of morphisms $X \to Y$ as $\R\Mor_\mC(X, Y) \in \mW$ and call it the right morphism object.

\item Let $\mC$ be a $\mV, \mW$-bienriched category and $X,Y \in \mC. $	
Then we denote the object of morphisms $X \to Y$ as $\Mor_\mC(X, Y) \in \mV \ot \mW$ and call it the total morphism object.

\end{itemize}

\end{notation}


\begin{notation}
There are involutions $$ _\mV\Enr \simeq \Enr_\mV, {_\mV \Enr_\mW} \simeq {_\mW \Enr_\mV}
%{_\mV\P\Enr} \simeq \P\Enr_\mV, {_\mV \P\Enr_\mW} \simeq {_\mW \P\Enr_\mV}
$$ denoted by $(-)^\circ$ that take the opposite enriched categories.
\end{notation}

\begin{definition}Let $\mV,\mW$ be presentably monoidal categories.

\begin{enumerate}

\item Let $\mC$ be a left $\mV$-enriched category and $X \in \mC, V \in \mV.$	 
The left tensor of $V$ and $X$ is the object $V \ot X \in \mC $ such that there is a morphism
$V \to \L\Mor_\mC(X, V \ot X) $ in $\mV$ that induces for every $Y \in \mC$ an equivalence
$$ \L\Mor_\mC(V \ot X,Y) \to \L\Mor_\mV(V, \L\Mor_\mC(X,Y)). $$ 

\item Let $\mC$ be a right $\mW$-enriched category and $X \in \mC, W \in \mW.$
The right tensor of $X$ and $W$ is the object $X \ot W \in \mC $ that is the left tensor of $W $ and $X$ for the corresponding left $\mW^\rev$-enriched category.

\item Let $\mC$ be a left $\mV$-enriched category, $X \in \mC, V \in \mV.$
The left cotensor of $V$ and $X$ is the object ${^V X} \in \mC $ that is the right tensor of $X $ and $V$ for the opposite right $\mV$-enriched category $\mC^\circ.$


\item Let $\mC$ be a right $\mW$-enriched category and $X \in \mC, W \in \mW$.
The right cotensor of $X$ and $W$ is the object $X^W \in \mC $ that is the left cotensor of $W $ and $X$ for the corresponding left $\mW^\rev$-enriched category.

\end{enumerate}

\end{definition}		

\begin{definition}Let $\mV,\mW$ be presentably monoidal categories and $\mC$ a $\mV,\mW$-bienriched category and $X \in \mC, V \in \mV, W \in \mW.$

\begin{enumerate}
\item The left tensor of $V$ and $X$ is the object $V \ot X$ that is the left tensor of
$ V \ot \tu_\mW \in \mV \ot \mW$ and $X \in \mC$ for the corresponding left $\mV \ot \mW^\rev$-enriched category.

\item The right tensor of $X$ and $W$ is the left tensor of $W$ and $X$ for the corresponding
$\mW^\rev, \mV^\rev$-bienriched category.

\item The left cotensor of $V$ and $X$ is the right tensor of $X$ and $V$ for the opposite
$\mW, \mV$-bienriched category $\mC^\circ.$

\item The right cotensor of $X$ and $W$ is the left cotensor of $W$ and $X$ for the corresponding
$\mW^\rev, \mV^\rev$-bienriched category.

\end{enumerate}

\end{definition}		

