\begin{definition}\label{suspi2}Let $\mV$ be a presentably monoidal category and 
$\mC$ a left $\mV$-enriched category. The categorical suspension of $\mC$, denoted by $S(\mC),$
is the left $\mV$-enriched category whose space of objects has two elements $0,1$ and whose morphism objects are $$\Mor_{S(\mC)}(1,0)\simeq \emptyset, \ \Mor_{S(\mC)}(0,1)\simeq \mC, \ \Mor_{S(\mC)}(0,0)\simeq \Mor_{S(\mC)}(1,1) \simeq \tu_\mV$$ 
and such that for every left $\mV$-enriched category $\mD$ containing objects $Y,Z$
the induced map \begin{equation*}
{_\mV\Enr}_{\partial\bD^1/}((S(\mC), 0,1),(\mD, Y,Z) ) \to {_\mV\Enr}(\mC, \Mor_\mD(Y,Z)) \end{equation*} is an equivalence.

\end{definition}

\begin{lemma}\label{susk}Let $\mV, \mW$ be presentably monoidal categories, $K\in\mW$ and $\mC$ a $\mV,\mW$-enriched category.
Let $\mC[K] \in {_\mV\Enr}$ be the pullback of evaluation at the target $\mC^{\bD^1}\to \mC$ along the left
$\mV$-enriched functor $(-)^K: \mC \to \mC$ taking the right cotensor with $K.$	
There is a left $\mV$-enriched equivalence over $\mC \times \mC$
$$\mC[K] \simeq {\Enr\Fun_\mW}(S(K),\mC)$$	
sending $(Y,X \to Y^K)$ to $(X,Y, K \to \R\Mor_\mC(X,Y)).$	

\end{lemma}

\begin{proof}

Let $\mB$ be a left $\mV$-enriched category.
By Yoneda it is enough to see that equivalence classes of left $\mV$-enriched functors $\mB \to \mC[K]$ naturally correspond to equivalence classes of left $\mV$-enriched functors $\mB \to {\Enr\Fun_\mV}(S(K),\mC)$.
There are canonical equivalences of categories $$ _\mV\Enr\Fun(\mB, \mC[K]) \simeq {_\mV\Enr\Fun}(\mB, \mC)[K]$$
and $$_\mV\Enr\Fun(\mB, {\Enr\Fun_\mW}(S(K),\mC)) \simeq \Enr\Fun_\mW(S(K), {_\mV\Enr\Fun}(\mB,\mC)).$$
So it is enough to show that there is a natural bijection of equivalence classes of objects of
$\mC[K] $ and $ {\Enr\Fun_\mW}(S(K),\mC).$
An object of $\mC[K]$ is pair $(Y,X \to Y^K)$ that corresponds to a triple $(X,Y,K \to \R\Mor_\mC(X,Y)),$ which is precisely an object of ${\Enr\Fun_\mW}(S(K),\mC).$

\end{proof}

\subsubsection{Gray enrichment}

Next we specialize to enrichment in the Gray tensor product and Gray smash product
following \cite[\S 4]{GepnerHeine}.

\begin{definition}
\begin{enumerate}
\item A left (right) Gray-category is a category left (right) enriched in $(\infty\Cat,\boxtimes).$

\item A left (right) Gray-functor is a functor left (right) enriched in $(\infty\Cat,\boxtimes).$

\item A Gray-category is a category bienriched in $(\infty\Cat,\boxtimes), (\infty\Cat,\boxtimes).$

\item A Gray-functor is a functor enriched in $(\infty\Cat,\boxtimes), (\infty\Cat,\boxtimes).$

\item A weakly reduced left (right) Gray-category is a category left (right) enriched in $(\infty\Cat_*,\wedge).$

\item A weakly reduced left (right) Gray-functor is a functor left (right) enriched in $(\infty\Cat_*,\wedge).$

\item A weakly reduced Gray-category is a category bienriched in $(\infty\Cat_*,\wedge), (\infty\Cat_*,\wedge).$

\item A weakly reduced Gray-functor is a functor enriched in $(\infty\Cat_*,\wedge), (\infty\Cat_*,\wedge).$

\end{enumerate}

\end{definition}

For the next definition let $\widehat{\mP}(\mC)$ be the monoidal category of presheaves on a not necessarily small monoidal category $\mC.$

\begin{definition}
\begin{enumerate}

\item A left (right) pseudo Gray-category is a category left (right) enriched in $(\widehat{\mP}(\infty\Cat),\boxtimes).$

\item A (pseudo-) Gray-category is a category bienriched in $(\widehat{\mP}(\infty\Cat),\boxtimes), (\widehat{\mP}(\infty\Cat),\boxtimes).$

\item A weakly reduced (pseudo-) left (right) Gray-category is a category left (right) enriched in $(\widehat{\mP}(\infty\Cat_*),\wedge).$

\item A weakly reduced (pseudo-) Gray-category is a category bienriched in $(\widehat{\mP}(\infty\Cat_*),\wedge), (\widehat{\mP}(\infty\Cat_*),\wedge).$

\end{enumerate}

\end{definition}

