\begin{notation}
Let $\mC$ be a (left) (right) Gray-category and $X \in \mC.$
There is a forgetful (left) (right) Gray-functor
%$\mC_{/X} \to \mC^{\bD^1} \to \mC^{\{0\}}, 
$\mC_{X/} \to \mC^{\bD^1} \to \mC^{\{1\}}.$	
Every morphism $X \to Y$ in $\mC$ gives rise to a (left) (right) Gray-functor
$ \mC_{Y/}  \to \mC_{X/} $ over $\mC.$
%If $\mC$ admits small weakly contractible conical colimits, $\mC_{X/}$ admits small conical colimits.

\end{notation}

\begin{remark}Let $\mC$ be a (left) (right) Gray-category and $X \in \mC.$ Let $X \to Y, X \to Z$ morphisms in $\mC.$
The induced morphism $$\ast\to \Mor_{\mC_{X/}}(X,X) \to \Mor_{\mC_{X/}}(X,Z)$$ is an equivalence and the following induced commutative square is a pullback square:
$$\begin{xy}
\xymatrix{
\Mor_{\mC_{X/}}(Y,Z) \ar[d]^{} \ar[r]
& \Mor_{\mC}(Y,Z) \ar[d] \ar[d]^{}
\\ 
\ast \simeq \Mor_{\mC_{X/}}(X,Z) \ar[r] & \Mor_{\mC}(X,Z)
}
\end{xy}$$	

In particular, the identity of $X$ is initial in $\mC_{X/}$ and if $\mC$ admits small weakly contractible conical colimits, $\mC_{X/}$ admits small conical colimits.	

\end{remark}

\begin{remark}\label{left adjoint slice} Let $\mC$ be a (left) (right) Gray-category that has conical pushouts and $X \to Y$ a morphism in $\mC$.
The (left) (right) Gray-functor $ \mC_{Y/}  \to \mC_{X/} $ admits a left adjoint.
Indeed, let $X \to W, Y \to T $ morphisms in $\mC.$
%By assumption there is a conical pushout $ Y \coprod_X W$.
%The canonical morphism $Y \to Y \coprod_X W$ 
The induced morphism
$ \Mor_{\mC_{Y/}}(Y \coprod_X W,T) \to  \Mor_{\mC_{X/}}(W,T)$
factors as $$ \Mor_{\mC_{Y/}}(Y \coprod_X W,T) \simeq \ast \times_{\Mor_{\mC}(Y,T) } \Mor_{\mC}(Y \coprod_X W,T) \simeq $$$$ \ast \times_{\Mor_{\mC}(Y,T)} \Mor_{\mC}(Y,T) \times_{\Mor_{\mC}(X,T)} \Mor_{\mC}(W,T) \simeq \Mor_{\mC_{X/}}(W,T).$$

\end{remark}


