\begin{corollary}\label{freespar} Let $n \geq 0$.	
There is a canonical equivalence of $n$-categories with distinguished object $$(-)_+\wedge (S^1)^{\wedge n} \simeq B^n \circ \Free_{\bE_n}.$$

\end{corollary}

\begin{proof}
The functor $$\infty\Cat_* \xrightarrow{\Omega^n} \Mon_{\bE_n}(\infty\Cat) \to \infty\Cat$$
factors as $\infty\Cat_* \xrightarrow{\Omega^n} \infty\Cat_* \to \infty\Cat.$
Hence by uniqueness of left adjoints the functor $\Sigma^n \circ (-)_+$ factors as
$B^n \circ \Free_{\bE_n}.$
By \cref{uuupo} there is a canonical equivalence $\Sigma^n \simeq (-) \wedge (S^1)^{\wedge n}.$

\end{proof}

%\begin{remark}Since the functor $\infty\Cat_* \xrightarrow{\Omega^n}\Mon_{\bE_n}(\infty\Cat) \to \infty\Cat$ factors as $\infty\Cat_* \xrightarrow{\Omega^n} \infty\Cat_* \to \infty\Cat$,by uniqueness of left adjoints there is a canonical equivalence$$B^n \circ  \Free_{\bE_n} \simeq \Sigma^n \circ (-)_+.$$\end{remark}

\begin{corollary}\label{freespart} Let $n \geq 0$.	
There is a canonical equivalence of $n$-categories with distinguished object $$(S^1)^{\wedge n} \simeq B^n \Free_{\bE_n}(*).$$

\end{corollary}

\cref{freesp} implies the following:

\begin{corollary}Let $n \geq 0$. There is a canonical equivalence of $n$-categories with distinguished object $$(S^1)^{\wedge n} \simeq S^n.$$

\end{corollary}	

