\begin{corollary}\label{conesto} Let $n,m \geq 0$ and $X \in \infty\Cat_*$ be $n$-connected 
and $Y \in \infty\Cat_*$ be $m$-connected.  Then $X \wedge Y$ is $n+m+1$-connected.

\end{corollary}

\begin{proof}
By 	\cref{connel} the full subcategory $\infty\Cat_*$ of $n$-connected $\infty$-categories with distinguished object is generated under small colimits by $\Sigma^n.$
Hence it suffices to see that for every $n,m \geq 0$ and $X,Y \in \infty\Cat_*$ the $\infty$-category with distinguished object $X \wedge Y$ is in the essential image of the functor
$\Sigma^{n+m+1}.$
By \cref{smarem}, \cref{ahoit}, \cref{dua} there are canonical equivalences
$ X \wedge \Sigma(Y) \simeq \Sigma(X \wedge Y)$ and $ \Sigma(X) \wedge Y \simeq \Sigma'(X^{\co\op}) \wedge Y \simeq \Sigma'(X^{\co\op} \wedge Y) \simeq \Sigma((X^{\co\op} \wedge Y)^{\co\op}) \simeq  \Sigma(X \wedge Y^{\co\op}).$	
\end{proof}

