\begin{proposition}\label{reduc}Let $\mC$ be a reduced pseudo-Gray-category.

\begin{enumerate}\item If $\mC$ admits suspensions, the reduced left Gray-functor $\Sigma: \mC \to \mC$ refines to a reduced Gray-functor $\mC^\cop \to \mC.$

\item If $\mC$ admits endomorphisms, the reduced left Gray-functor $\Omega: \mC \to \mC$ refines to a reduced Gray-functor $\mC \to \mC^\cop.$

\item If $\mC$ admits suspensions and endomorphisms, there is a Gray-adjunction
$\Sigma: \mC^\cop \rightleftarrows \mC: \Omega .$ 

\item If $\mC$ admits cosuspensions, the reduced right Gray-functor $\Sigma': \mC \to \mC$ refines to a reduced Gray-functor ${^\cop\mC} \to \mC.$

\item If $\mC$ admits coendomorphisms, the reduced right Gray-functor $\Omega': \mC \to \mC$ refines to a reduced Gray-functor $ \mC \to {^\cop\mC}.$

\item If $\mC$ admits cosuspensions and coendomorphisms, there is a Gray-adjunction
$\Sigma': {^\cop\mC} \rightleftarrows \mC: \Omega' .$ 

\item Let $\mC$ be a reduced pseudo-Gray-category that admits small colimits and left and right tensors. Then $\Sigma: \mC \to \mC$ factors as
$$\mC \ot_{\infty\Cat_*} \Sigma: \mC \simeq \mC {\ot_{\infty\Cat_*} \infty\Cat_*}  \to \mC {\ot_{\infty\Cat_*} \infty\Cat_*} \simeq \mC$$ and $\Sigma': \mC \to \mC$ factors as
$$\Sigma' \ot_{\infty\Cat_*} \mC : \mC \simeq {\infty\Cat_* \ot_{\infty\Cat_*}} \mC \to \infty\Cat_* {\ot_{\infty\Cat_*} \mC} \simeq \mC.$$

\item There is an equivalence of reduced Gray-functors $\Sigma \simeq \Sigma' \circ (-)^{\co\op}: \infty\Cat_*^\cop\to \infty\Cat_*.$

\item There is an equivalence of reduced Gray-functors $\Sigma \circ (-)^{\co\op}\simeq (-)^{\co\op} \circ \Sigma: {^\cop\infty\Cat_*} \to \infty\Cat_*.$

\end{enumerate}	
\end{proposition}

\begin{proof}
%By ... it is enough to see that the functor $$\Sigma \circ \Sigma: \infty\Cat_* \to \infty\Cat_{*}$$ is $(\infty\Cat,\boxtimes), (\infty\Cat,\boxtimes)$-bienrichedsince this functor preserves the zero object.For every $\infty$-category $\mC$ let $\rho: \infty\Cat_{\mC/} \to \infty\Cat_*$ be the $(\infty\Cat,\boxtimes), (\infty\Cat,\boxtimes)$-bienriched functor that takes the pushout along the functor $\mC \to *$ of \cref{bien}.

(1) is dual to (4). (2) is dual to (5). (3) is dual to (6). We prove (1), (2), (3), (7), (8).

(1): We first assume that $\mC:= \infty\Cat_*$. The functor $\Sigma$ factors as small colimits preserving functors
$ \infty\Cat_{*} \xrightarrow{S} \infty\Cat_{\bD^1/} \to \infty\Cat_*,$
where the latter functor takes the pushout along the functor $\bD^1 \to *$.
In particular, $\Sigma$ preserves the zero object.
By \cref{alfas} (1) the first functor in the composition refines to a Gray-functor
$ \infty\Cat_{*}^\cop \to \infty\Cat_{\bD^1/}.$ By \cref{left adjoint slice} the second functor in the composition refines to a Gray-functor $\infty\Cat_{\bD^1/} \to \infty\Cat_*.$  So the composition refines to a reduced Gray-functor $\infty\Cat_{*}^\cop \to \infty\Cat_{*}.$

Next we prove linearity. We first prove left linearity.
We like to see that for every $\mC,\mD \in \infty\Cat_*$
the canonical functor $\mC \wedge \Sigma(\mD)\to \Sigma(\mC\wedge\mD)$
%, \ \Sigma(\mC) \wedge \mD \to \Sigma(\mC\wedge\mD^{\co\op}) $$
is an equivalence.
The latter functor identifies with the canonical equivalence $\mC \wedge (\mD \wedge S^1) \simeq (\mC \wedge \mD) \wedge S^1.$
We continue with right linearity. We like to see that for every $\mC,\mD \in \infty\Cat_*$ the canonical functor $ \Sigma(\mC) \wedge \mD \to \Sigma(\mC\wedge\mD^{\co\op}) $ is an equivalence.
Since $\infty\Cat_*$ is generated under left tensors by $S^0$ and $\Sigma$ is left linear as we have shown, we can assume that $\mC=S^0.$
In this case the latter functor identifies with the
canonical equivalence $S^1 \wedge \mD \simeq \Sigma'(\mD) \simeq \Sigma(\mD^{\co\op})$ of
\cref{smarem} and \cref{ahoit}.

We assume next that $\mC$ is a reduced pseudo-Gray-category that admits %small colimits and 
left and right (co)tensors. % and left and right cotensors. %such that forming left and right tensors is compatible with small colimits componeny-wise.
The reduced left adjoint Gray-functor $ \Sigma: \infty\Cat^\cop_{*} \to \infty\Cat_*$ 
gives rise to a reduced %small colimits preserving 
linear Gray-functor \begin{equation}\label{kulr}
\mC^\cop \simeq \mC {\ot_{\infty\Cat_*} \infty\Cat^\cop_{*} } \to \mC {\ot_{\infty\Cat_*} \infty\Cat_*} \simeq \mC\end{equation}
whose underlying left Gray-functor factors as
$ \mC \simeq \mC {\ot_{\infty\Cat_*} \infty\Cat_*} \xrightarrow{\mC \ot {((-)\wedge S^1)}} \mC {\ot_{\infty\Cat_*} \infty\Cat_*} \simeq \mC$ and so identifies with $\Sigma \simeq (-)\wedge S^1 : \mC \to \mC.$
Since the latter admits a right adjoint, by \cref{adj} the Gray-functor \ref{kulr} admits a right adjoint $\Omega: \mC^\cop \to \mC$ refining the right adjoint of the reduced left Gray-functor
$\Sigma : \mC \to \mC.$
Let $\mC$ be a reduced pseudo-Gray-category that admits endomorphisms.
The Gray-Yoneda-embedding gives an endomorphisms preserving reduced Gray-embedding $$\mC \hookrightarrow \mD:={\wedge\Fun\wedge}(\mC^\circ, \infty\Cat_*\boxplus \infty\Cat_*)$$ into a reduced pseudo-Gray-category that admits left and right (co)tensors. Since the embedding preserves endomorphisms, 
the reduced Gray-functor $\Omega_\mD: \mD \to \mD^\cop$ restricts to a reduced Gray-functor $\Omega_\mC: \mC \to \mC^\cop$.

Let $\mC$ be a reduced pseudo-Gray-category that admits suspensions
and $\mE \subset {\wedge\Fun\wedge}(\mC^\circ, \infty\Cat_*\boxplus \infty\Cat_*)$ the full subcategory of reduced Gray-functors preserving coendomorphisms.
By  \cite[Lemma 3.80.(1)]{heine2024higher} the Gray-embedding $\mE \subset \mD$ admits a left adjoint $L$ so that $\mE$ is a reduced pseudo-Gray-category that admits left and right (co)tensors.
By \cite[Lemma 3.80.(2)]{heine2024higher} the reduced Gray-embedding $\mC \subset \mD$ induces a suspensions preserving reduced Gray-embedding $\mC \subset \mE$. So the reduced Gray-functor $\Sigma_\mE: \mE^\cop \to \mE$ restricts to a reduced Gray-functor $\Sigma_\mC: \mC^\cop \to \mC$.

The Gray-left adjoint $L: \mD \to \mE$ gives rise to a canonical equivalence $\Sigma_\mE \circ L \simeq L \circ \Sigma_\mD$ 
of reduced Gray-functors $\mD^\cop \to \mE$. By adjointness the reduced Gray-functor 
$\Omega_\mE$ is the restriction of the reduced Gray-functor $\Omega_\mD$.
So if $\mC$ admits suspensions and endomorphisms, the reduced Gray-functor 
$\Omega_\mC$ is the restriction of the reduced Gray-functor $\Omega_\mE$.
The reduced Gray-adjunction $\Sigma_\mE: \mE^\cop \rightleftarrows \mE: \Omega_\mE$ restricts to a reduced  Gray-adjunction $ \Sigma_\mC: \mC \rightleftarrows \mC^\cop: \Omega_\mC.$

(7): Let $\mC$ be a reduced pseudo-Gray-category that admits small colimits and left and right tensors. Let $\mE \subset \mD:={\wedge\Fun\wedge}(\mC^\circ, \infty\widehat{\Cat}_*\boxplus \infty\widehat{\Cat}_*)$ be the full subcategory of reduced Gray-functors preserving coendomorphisms and $\mB \subset \mE$ the full subcategory of reduced Gray-functors preserving small limits and left and right cotensors.
By  \cite[Lemma 3.80.(1)]{heine2024higher} the Gray-embedding $\bj: \mB \subset \mE$ admits a left adjoint $L$ so that $\mB$ is a reduced pseudo-Gray-category that admits left and right (co)tensors.
So there is a canonical equivalence of reduced Gray-functors $L \circ \Sigma_\mE \simeq \Sigma_\mB \circ L$ and so a canonical map of reduced Gray-functors $ \Sigma_\mE \circ \bj \to \bj \circ \Sigma_\mB. $
By \cite[Lemma 3.80.(2)]{heine2024higher} the reduced Gray-embedding $\mC \subset \mD$ induces a suspensions preserving reduced Gray-embedding $\mC \subset \mE$
and a small colimits and left and right tensors preserving reduced Gray-embedding $\bi: \mC \subset \mB$.
So the reduced Gray-functor $\Sigma_\mB:  \mB^\cop \to \mB$ restricts to $\Sigma_\mC: \mC^\cop \to \mC$. Thus the canonical map $ \Sigma_\mE \circ \bj \to \bj \circ \Sigma_\mB $
induces a canonical map $ \Sigma_\mE \circ \bj \circ \bi \to \bj \circ \Sigma_\mB \circ \bi \simeq \bj \circ \bi \circ \Sigma_\mC$ of reduced Gray-functors, which induces on underlying reduced left Gray-functors an equivalence since $\bj \circ \bi$ preserves suspensions.
In other words $\Sigma_\mE$ restricts to $\Sigma_\mC= \mC \ot_{\infty\Cat_*} \Sigma $, which proves (7). The second part of (7) is proven similar.

%Hence the reduced Gray-adjunction $\mD^\cop \rightleftarrows \mD $  refining (\cref{koly})  restricts along the embeddings of Gray-categories $\mC \hookrightarrow \mD, \mC^\cop \hookrightarrow \mD^\cop$ to a reduced Gray-adjunction $ \mC^\cop \rightleftarrows \mC$ refining (\cref{koly2}).


%By \cite[Lemma 3.80., Remark 3.85.]{heine2024higher} there is a suspension preserving reduced Gray-embedding $\mC \hookrightarrow \mE$ into a reduced pseudo-Gray-category that admitsleft and right (co)tensors. Since the embedding preserves suspensions, the reduced Gray-functor $\Sigma_\mE: \mE^\cop \to \mE$ restricts tothe reduced Gray-functor $\Sigma_\mC: \mC^\cop \to \mC$.
%Consequently, the reduced Gray-functor $ \mD^\cop \to \mD$ refining $\Sigma_\mD: \mD \to \mD$ restricts along the embeddings of Gray-categories $\mC \hookrightarrow \mD, \mC^\cop \hookrightarrow \mD^\cop$ to a reduced Gray-functor $ \mC^\cop \to \mC$ refining $\Sigma_\mC: \mC \to \mC$.

Statements (8) and (9) follow immediately from \cref{alfas} (3), (4), where 
we use that there is a canonical commutative square of Gray-categories and Gray-functors
\begin{equation*}
\begin{xy}
\xymatrix{\infty\Cat_{\bD^1/}   \ar[d] \ar[r]^{\tau \circ (-)^{\co\op}} 
& \infty\Cat_{\bD^1/}   \ar[d]
\\ 
\infty\Cat_\ast \ar[r]^{(-)^{\co\op}} & \infty\Cat_\ast.}
\end{xy}
\end{equation*}
Here $\tau$ is induced by the non-identity duality on $\bD^1$ and the vertical functors take the pushout along the functor $\bD^1 \to *$.
This follows from the existence of a commutative square of left adjoints provided by \cref{left adjoint slice}.

\end{proof}

\subsection{Oplax oriented pullbacks}

In this subsection we follow \cite[4.4.]{GepnerHeine} and apply the theory of weighted colimits
\cite[\S 3]{heine2024higher}, \cite{hinich2021colimits}, the enriched analogon of the notion of colimit, to define (op)lax oriented pushouts and pullbacks.

\begin{notation}
Let $\sigma: \{0,1\}^{\triangleright} \to \infty\Cat$ be the functor
classifying the diagram $ \{0\} \subset \bD^1 \supset \{1\}$ that sends 0 to $\{0\}$ and 1 to $\{1\}.$	

\end{notation}

\begin{definition}Let $\mC$ be a right Gray-category.

\begin{enumerate}
\item Let  $ C \to A, C \to B$ be morphisms in $\mC$ corresponding to a (right Gray) functor $\theta: \{0,1\}^{\triangleleft} \to \mC$ sending $ 0$ to $A$, $1$ to $B.$
The oplax left pushout of two morphisms $C \to A, C \to B$ in $\mC$ denoted by $ {\overset{\overset{\rightarrow}{\oplax}}{A \coprod_C} B}$ is the colimit of $\theta$ weighted with respect to the right weight $\sigma: \{0,1\}^{\triangleright} \to \infty\Cat.$

\item The oplax right pushout of two morphisms $C \to A, C \to B$ in $\mC$ denoted by $ {\overset{\overset{\leftarrow}{\oplax}}{A \coprod_C} B}$ is $ {\overset{\overset{\rightarrow}{\oplax}}{B \coprod_C} A}$.

\item The oplax left pullback of two morphisms $A \to C, B \to C$ in $\mC$ denoted by $ {\overset{\overset{\rightarrow}{\oplax}}{A \prod_C} B}$ is the oplax left pushout of the corresponding morphisms $C \to A, C \to B$ in the right Gray-category $\mC^\op$.

\item The oplax right pullback of two morphisms $A \to C, B \to C$ in $\mC$ denoted by $ {\overset{\overset{\leftarrow}{\oplax}}{A \prod_C} B}$ is $ {\overset{\overset{\rightarrow}{\oplax}}{B \prod_C} A}$.

\end{enumerate}

\end{definition}

\begin{definition}Let $\mC$ be a left Gray-category. % and $C \to A, C \to B$ be morphisms in $\mC$. % corresponding to a right (Gray) functor $\theta: \{0,1\}^{\triangleleft} \to \mC$ sending $ 0$ to $A$ and $1$ to $B.$

\begin{enumerate}
\item The lax left pullback of two morphisms $A \to C, B \to C$ in $\mC$ denoted by $ {\overset{\overset{\rightarrow}{\lax}}{A \prod_C} B}$ is the oplax left pushout of the corresponding morphisms $C \to A, C \to B$ in the right Gray-category $\mC^{\circ}$.	

\item The lax right pullback of two morphisms $A \to C, B \to C$ in $\mC$ denoted by $ {\overset{\overset{\leftarrow}{\lax}}{A \prod_C} B}$ is $ {\overset{\overset{\rightarrow}{\lax}}{B \prod_C} A}$.

\item The lax left pushout of two morphisms $C \to A, C \to B$ in $\mC$ denoted by $ {\overset{\overset{\rightarrow}{\lax}}{A \coprod_C} B}$ is the oplax left pushout of the corresponding morphisms $C \to A, C \to B$ in the right Gray-category $(\mC^\op)^\circ \simeq (\mC^\circ)^\op$.

\item The lax right pushout of two morphisms $C \to A, C \to B$ in $\mC$ denoted by $ {\overset{\overset{\leftarrow}{\lax}}{A \coprod_C} B}$ is $ {\overset{\overset{\rightarrow}{\lax}}{B \coprod_C} A}$.

\end{enumerate}	

\end{definition}


\begin{definition}Let $\mC$ be a Gray-category.

\begin{itemize}

\item The oplax left (right) pushout of two morphisms $C \to A, C \to B$ in $\mC$ is the oplax left (right) pushout in the underlying right Gray-category of $\mC$.		

\item The lax left (right) pushout of two morphisms $C \to A, C \to B$ in $\mC$ is the lax left (right)
pushout in the underlying left Gray-category of $\mC$.

\item The oplax left (right) pullback of two morphisms $A \to C, B \to C$ in $\mC$ is the oplax left (right) pullback in the underlying right Gray-category of $\mC$.

\item The lax left (right) pullback of two morphisms $A \to C, B \to C$ in $\mC$ is the lax left (right)
pullback in the underlying left Gray-category of $\mC$.

\end{itemize}	

\end{definition}


