\begin{definition}Let $\mC$ be a reduced right Gray-category and $\phi: A \to B$ a morphism in $\mC.$ 
\begin{enumerate}
\item The oplax left cofiber of $\phi$ %denoted by %$\overset{\hspace{-6mm}\rightarrow}{\overset{\hspace{-6mm}\oplax}{\cofib(\phi)}} $ 
is ${\overset{\overset{\rightarrow}{\oplax}}{0 \coprod_A} B} $.

\item The oplax right cofiber of $\phi$ is ${\overset{\overset{\rightarrow}{\oplax}}{B \coprod_A} 0}$.

\end{enumerate}	

\end{definition}
\begin{definition}Let $\mC$ be a reduced right Gray-category and $\phi: B \to A$ a morphism in $\mC.$ 
\begin{enumerate}
\item The oplax left fiber of $\phi$ is ${\overset{\overset{\rightarrow}{\oplax}}{0 \prod_A} B} $.

\item The oplax right fiber of $\phi$ is ${\overset{\overset{\rightarrow}{\oplax}}{B \prod_A} 0} $.

\end{enumerate}	

\end{definition}

\begin{definition}Let $\mC$ be a reduced left Gray-category and $\phi: A \to B$ a morphism in $\mC.$ 
\begin{enumerate}
\item The lax left cofiber of $\phi$ is ${\overset{\overset{\rightarrow}{\lax}}{0 \coprod_A} B} $.

\item The lax right cofiber of $\phi$ is ${\overset{\overset{\rightarrow}{\lax}}{B \coprod_A} 0} $.
\end{enumerate}	

\end{definition}


\begin{definition}Let $\mC$ be a reduced left Gray-category and $\phi: B \to A$ a morphism in $\mC.$ 
\begin{enumerate}
\item The lax left fiber of $\phi$ is ${\overset{\overset{\rightarrow}{\lax}}{0 \prod_A} B} $.

\item The lax right fiber of $\phi$ is ${\overset{\overset{\rightarrow}{\hspace{1mm}\lax}}{B \prod_A} 0} $.
\end{enumerate}	

\end{definition}

\begin{definition}

A reduced right Gray-category admits oplax (co)fibers if it admits the oplax left (co)fiber and the oplax right (co)fiber of any morphism.
A reduced left Gray-category admits lax (co)fibers if it admits the lax left (co)fiber and the lax right (co)fiber of any morphism.

\end{definition}

\begin{notation}
Let $\bD^1$ be always equipped with the initial object.
Let $(\bD^1)^\op$ denote $\bD^1$ equipped with the final object.

\end{notation}

\begin{corollary}\label{redfib}

\begin{enumerate}

\item Let $\mC$ be a reduced right Gray-category that admits pushouts and reduced right tensors with $\bD^1$ and $C \to A$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \oplax}}{0 \coprod_C} A}  \simeq  C \wedge \bD^1 \coprod_{C \wedge S^0}A .$$	

\item Let $\mC$ be a reduced right Gray-category that admits pullbacks and reduced right cotensors with $\bD^1$ and $A \to C$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \oplax}}{0 \prod_C} A} \simeq C^{\bD^1}_*\times_{C^{S^0}_*} A.$$	

\item Let $\mC$ be a reduced right Gray-category that admits pullbacks and reduced right tensors with $\bD^1$ and $C \to A$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \oplax}}{A \coprod_C} 0} \simeq A \coprod_{C \wedge S^0} C \wedge (\bD^1)^\op .$$	

\item Let $\mC$ be a reduced right Gray-category that admits pullbacks and reduced right cotensors with $\bD^1$ and $A \to C$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \oplax}}{A \prod_C} 0}  \simeq A \times_{C^{S^0}_*} C^{(\bD^1)^\op}_*$$	

\item Let $\mC$ be a reduced left Gray-category that admits pushouts and reduced left tensors with $\bD^1$ and $C \to B$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \lax}}{0 \coprod_C} B}\simeq \bD^1 \wedge C   \coprod_{S^0 \wedge C} B .$$	

\item Let $\mC$ be a reduced left Gray-category that admits pushouts and reduced left cotensors with $\bD^1$ and $B \to C$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \lax}}{0 \prod_C} B} \simeq {^{\bD^1}C}_* \times_{^{S^0}C_*} B. $$	

\item Let $\mC$ be a reduced left Gray-category that admits pushouts and reduced left tensors with $\bD^1$ and $C \to A$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \lax}}{A \coprod_C} 0} \simeq A  \coprod_{S^0 \wedge C} (\bD^1)^\op \wedge C .$$	

\item Let $\mC$ be a reduced left Gray-category that admits pushouts and reduced left cotensors with $\bD^1$ and $A \to C$ a morphism in $\mC$.
There is a canonical equivalence $${\overset{\overset{\hspace{2mm}\rightarrow}{\hspace{2mm} \lax}}{A \prod_C} 0}\simeq A \times_{^{S^0}C_*} {^{(\bD^1)^\op}C}_* .$$	


\end{enumerate}

\end{corollary}

