\begin{lemma}\label{spli}
Let $\mC$ be a reduced right Gray-category that admits oplax pushouts.
There is a commutative square 
\begin{equation}\label{sqlo}
\begin{xy}
\xymatrix{
{\overset{\overset{\hspace{0.5mm}\rightarrow}{\hspace{1mm} \oplax}}{A \coprod_C} B} \ar[d] \ar[r]
&{\overset{\overset{\hspace{0.0mm}\rightarrow}{\hspace{0mm} \oplax}}{0 \coprod_C} B} %\simeq \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod 0}(C \to A) 
\ar[d]
\\ 
{\overset{\overset{\hspace{0.0mm}\rightarrow}{\hspace{1mm} \oplax}}{A \coprod_C} 0} %\simeq \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod 0}(C \to B) 
\ar[r] & {\overset{\overset{\hspace{0.0mm}\rightarrow}{\hspace{0mm} \oplax}}{0 \coprod_C} 0}\simeq \Sigma(C) 
}
\end{xy}
\end{equation}
natural in $ (A \leftarrow C \to B) \in \mC^{\Lambda_0^2}$ determining a functor $\sigma: \mC^{\Lambda_0^2} \to \mC^{\bD^1 \times \bD^1}$.
If $\mC$ is a reduced Gray-category that admits oplax pullbacks, the functor $\sigma: \mC^{\Lambda_0^2} \to \mC^{\bD^1 \times \bD^1}$ is canonically a reduced left Gray-functor.

%If $\mC$ is spectral  $\sigma$ is spectral, too.

%In particular, there is a natural transformation $\overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod}  \to \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod 0}' \rho' \times_{\Sigma \ev_0} \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod 0} \rho$ of reduced Gray-functors $\mC^{\Lambda_0^2} \to \mC.$

\end{lemma}

\begin{proof}
The reduced (right) Gray-functors $\rho: \mC^{\Lambda_0^2} \to \mC^{\bD^1}, (A \leftarrow C \to B) \mapsto (A \leftarrow C), \rho': \mC^{\Lambda_0^2} \to \mC^{\bD^1}, (A \leftarrow C \to B) \mapsto (C \to B), \rho'': \mC^{\bD^1} \to \mC, (A \to B) \mapsto A$ admit fully faithful right adjoints sending
$A \leftarrow C$ to $ A \leftarrow C \to 0$, $C \to B$ to $0 \leftarrow C \to B $ and 
$A \to B$ to $A \to 0$, respectively.
The units give rise to a commutative square of reduced (right) Gray-functors $\mC^{\Lambda_0^2} \to \mC^{\Lambda_0^2}:$
$$\begin{xy}
\xymatrix{
\id  \ar[d] \ar[r]
&\rho' \ar[d]
\\ 
\rho \ar[r] & \rho''\rho \simeq \rho'' \rho' \simeq \ev_0.
}
\end{xy}
$$
The latter is a pullback square by the description of adjoints and induces a commutative square 
$$\begin{xy}
\xymatrix{
\overset{\overset{\hspace{0.5mm}\rightarrow}{\hspace{0mm} \oplax}}{ \coprod}  \ar[d] \ar[r]
& \overset{\overset{\hspace{0.5mm}\rightarrow}{\hspace{0mm} \oplax}}{ \coprod} \circ \rho \simeq \overset{\overset{\hspace{-2.5mm}\rightarrow}{\hspace{-3mm} \oplax}}{ \coprod 0} \circ \rho \ar[d]
\\ 
\overset{\overset{\hspace{1.0mm}\rightarrow}{\hspace{1mm} \oplax}}{\coprod} \circ \rho' \simeq \overset{\overset{\hspace{2.0mm}\rightarrow}{\hspace{2mm} \oplax}}{0 \coprod} \circ \rho' \ar[r] & \overset{\overset{\hspace{0.5mm}\rightarrow}{\hspace{0mm} \oplax}}{ \coprod } \circ \ev_0 \simeq \Sigma  \ev_0
}
\end{xy}
$$
of (reduced left Gray-) functors $\mC^{\Lambda_0^2} \to \mC$ that yields at any $ (A \leftarrow C \to B) \in \mC^{\Lambda_0^2}$ square \ref{sqlo}.
\end{proof}

\begin{lemma}\label{compa}
Let $\mC$ be a reduced right Gray-category that admits oplax left fibers.	
There is a map $$\xi: \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\coprod} \to \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\prod} \circ \Sigma$$ of functors $ \mC^{\bD^1} \to \mC$.
If $\mC$ is a reduced Gray-category that admits oplax left fibers, then $\xi$ is a map of reduced left Gray-functors $ \mC^{\bD^1} \to \mC$.

\end{lemma}

\begin{proof}By \cref{redfib} the oplax left cofiber is the colimit weighted with respect to the right weight $ S^0 \to \bD^1$ and so by \cite[Corollary 3.43.]{heine2024higher} there is an adjunction $ L:=(-)\wedge (S^0 \to \bD^1) : \mC \rightleftarrows \mC^{\bD^1} : \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\prod}$. 
Moreover if $\mC$ is a reduced Gray-category, the latter adjunction is a reduced left Gray-adjunction.
%	and a spectral left Gray-adjunction $ L:=\wedge (S^0 \to \Sigma^\infty(\bD^1)) : \Sp \rightleftarrows \Sp^{\bD^1} : \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\prod} 0.$  
By \cite[Proposition 4.40.(3)]{heine2024bienriched} the map $${\wedge\Fun}(\infty\Cat_*^{\bD^1},\infty\Cat_*^{\bD^1})(L \circ \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\coprod}, \Sigma)  \to \infty\Cat_*^{\bD^1\times \bD^1}((S^0 \to \bD^1) \to (\bD^1 \to \bD^2), (0 \to S^1) \to \id_{S^1})$$
restricting along the Gray-Yoneda-embedding $\infty\Cat_*^{\bD^1\times \bD^1} \simeq {\Fun}(\bD^1,\infty\Cat_*^{\bD^1})  \simeq {\wedge\Fun}(\bD^1,\infty\Cat_*^{\bD^1}) \hookrightarrow {\wedge\Fun}(\infty\Cat_*^{\bD^1},\infty\Cat_*^{\bD^1})$ is an equivalence. 
%$$\R\Mor_{{\wedge\Fun}(\Sp^{\bD^1},\Sp^{\bD^1})}(L \circ \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod 0}, \Sigma)  \to \R\Mor_{\Sp^{\bD^1\times \bD^1}}((S^0 \to \bD^1) \to (\bD^1 \to \bD^2), (0 \to S^1) \to \id_{S^1}).$$
Let $\kappa: L \circ \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\coprod} \to \Sigma$ be the map of left adjoint reduced left Gray-functors $ \infty\Cat_*^{\bD^1} \to \infty\Cat_*^{\bD^1}$ corresponding to the following commutative square in $\infty\Cat_*^{\bD^1}:$
$$\begin{xy}
\xymatrix{
S^0 \wedge S^0 \to S^0 \wedge \bD^1 \ar[d] \ar[rr]
&& 0 \to S^1 \ar[d]
\\ 
\bD^1 \wedge S^0 \simeq \bD^1 \to \bD^1 \wedge \bD^1 \simeq \bD^2 \ar[rr] && \id_{S^1},
}
\end{xy}
$$	
where the functor $\bD^2 \to S^1$ in the square is the composition of 1-truncation $\bD^2 \to \bD^1$ and the quotient functor $\bD^1 \to S^1$.
%, which corresponds to the functor $\bD^1 \to \bN$ classifying the identity of the generator.
%in which all functors preserve the canonical two distinguished objects, and that induces on morphism $\infty$-categories between the two distinguished objects the commutative square in $\infty\Cat:$
%$$\begin{xy}
%\xymatrix{
%\emptyset \to \{1\} \ar[d] \ar[rr]
%&& 0 \to  \bN \ar[d]
%\\ 
%0 \to \bD^1 \ar[rr] && \bN\to \bN,
%}
%\end{xy}
%$$	where the functor $\bD^1 \to \bN$ is the only possible one fitting in the square, which classifies the identity of the generator.	
%Let $\kappa: L \circ \overset{\overset{\hspace{-0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{\coprod 0} \to \Sigma$ be the map of left adjoint spectral left Gray-functors $ \Sp^{\bD^1} \to \Sp^{\bD^1}$ corresponding to the image of the latter commutative square in $\Sp^{\bD^1}$ under $\Sigma^\infty.$ 
Let $\kappa_\mC:=\mC {\ot_{\infty\Cat_*} \kappa} :  L \circ \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\coprod} \to \Sigma$.
Then $\kappa_\mC$ is a map of left adjoint functors $ \mC^{\bD^1} \to \mC^{\bD^1}$,
which is a map of reduced left Gray-functors if $\mC$ is a reduced Gray-category.
The map $\kappa_\mC$ gives rise to the desired map $\xi: \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\coprod} \to \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\prod} \circ L \circ \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\coprod} \to \overset{\overset{\hspace{2.5mm}\rightarrow}{\hspace{2.5mm} \oplax}}{0\prod} \circ \Sigma$. % of reduced left Gray-functors $ \mC^{\bD^1} \to \mC$.

