\begin{notation}

\begin{itemize}For the following notation we use \cref{presol}:

\item Let $\Cat_{\mathrm{oqst}}\wedge \subset {\Cat\wedge}$ be the subcategory of oplax quasi-stable right Gray-categories and right Gray-functors preserving suspensions.

\item Let ${\wedge}\Cat_\mathrm{lqst} \subset \wedge\Cat$ be the subcategory of lax quasi-stable left Gray-categories and left Gray-functors preserving cosuspensions.

\item Let ${\wedge\Cat_\mathrm{oqst}\wedge} \subset \wedge\Cat\wedge$ be the subcategory of oplax quasi-stable Gray-categories and Gray-functors preserving suspensions.

\item Let $\wedge\Cat_{\mathrm{lqst}}\wedge \subset \wedge\Cat\wedge$ be the subcategory of lax quasi-stable Gray-categories and Gray-functors preserving cosuspensions.

\item Let ${\wedge}\Cat_{\mathrm{qst}}\wedge \subset \wedge\Cat\wedge$ be the subcategory of quasi-stable Gray-categories and Gray-functors preserving suspensions and cosuspensions.

\end{itemize}

\end{notation}

\begin{definition}
A left Gray-category $\mC$ is lax stable if the following conditions are satisfied:

\begin{enumerate}
\item $\mC$ is lax quasi-stable.

\item $\mC$ admits lax fibers and lax cofibers.

%\item \Lax pushouts (pullbacks) commute with oplax pullbacks (pushouts).

\end{enumerate}

\end{definition}

%\begin{remark}Condition (3) in the latter definition precisely means that the right Gray-functorassiging the lax pushout (pullback), which exists by condition (2), preserves (all existing) oplax pullbacks (pushouts).\end{remark}

\begin{definition}
A right Gray-category $\mC$ is oplax stable if the left Gray-category $\mC^\co$ is lax stable.

\end{definition}

\begin{definition}
A reduced Gray-category is oplax stable if its underlying right Gray-category is oplax stable.	
A reduced Gray-category is lax stable if its underlying left Gray-category is lax stable.	

\end{definition}

\begin{definition}
A Gray-category is stable if it is lax and oplax stable.

\end{definition}

\begin{remark}\label{agos2}
A left (right) Gray-category $\mC$ is (op)lax stable if and only if the left (right) Gray-category 
$\mC^\op$ is (op)lax stable since (op)lax cofibers in $\mC$ are (op)lax fibers in $\mC^\op$.
%and (op)lax pullbacks in $\mC$ agree with (op)lax pushouts in $\mC^\op$.
Thus a Gray-category $\mC$ is stable if and only if $\mC^\op$ is stable if and only if $\mC^\co$ is stable if and only if $\mC^{\co\op}$ is stable.

\end{remark}

\begin{example}

Any stable category viewed as a Gray-category is stable.

\end{example}

