\subsection{Pre-spectrum objects}

In this subsection we introduce pre-spectrum objects, a generalization of spectrum objects.

\begin{notation}

Let $\mC$ be a reduced Gray-category that admits endomorphisms.
Let $$\mC^\Omega:= \mC^{[1]}\times_{\mC^{\{1\}}}\mC^\cop$$ be the pullback in $\wedge\Cat\wedge$ of evaluation at the target along $\Omega: \mC^\cop \to \mC.$
There are two canonical Gray-functors, the composition $\mC^\Omega \to \mC^{[1]} \to \mC^{\{0\}}$ and the projection $ \mC^{[1]}\times_{\mC^{\{1\}}}\mC^\cop \to \mC^\cop$.

\end{notation}

\begin{definition}
The Gray-category of pre-spectrum objects in $\mC$ is the following limit in $\wedge\Cat\wedge$:
$$\Pre\Sp(\mC):= ... \times_{\mC^\cop} \mC^\Omega \times_{\mC}(\mC^\cop)^\Omega \times_{\mC^\cop} \mC^\Omega. $$

\end{definition}

\begin{remark}
A pre-spectrum in $\mC$ consists of a sequence $(X_0,X_1,X_2,...)$ of objects in $\mC$ and bonding morphisms $X_n \to \Omega(X_{n+1})$ in $\mC$ for every $n \geq 0$.

\end{remark}

\begin{example}

The Gray-category $\Pre\Sp(\mS)$ is the usual category of pre-spectra viewed as a Gray-category.	

\end{example}

\begin{remark}

Since $\mC$ admits a zero object and endomorphisms, by \cite[Theorem 3.94., Proposition 4.44.]{heine2024higher} also $\mC^\Omega$ admits a zero object and endomorphisms. This guarantees by \cite[Proposition 4.44.]{heine2024higher} that also the limit $\Pre\Sp(\mC)$ admits a zero object and endomorphisms.	

\end{remark}

\begin{definition}
The Gray-category of pre-spectra is $$\Pre\Sp:=\Pre\Sp(\infty\Cat_*).$$

\end{definition}


\begin{lemma}\label{comp}
Let $\mC$ be a reduced Gray-category that admits endomorphisms
and $X,Y \in \Pre\Sp(\mC).$ There is a canonical equivalence of $\infty$-categories:	
$$\Mor_{\Pre\Sp(\mC)}(X,Y) \simeq \Mor_{\mC}(X_0,Y_0)\times_{\Mor_{\mC}(X_{0},\Omega(Y_1))} 
\Mor_{\mC}(X_1,Y_1)\times_{\Mor_{\mC}(X_1,\Omega(Y_2))} ... $$ %\Mor_{\mC}(X_4,Y_4) ... $$ %\times_{\Mor_{\mC}(X_{4},\Omega^2(Y_{6}))} ... .$$	
\end{lemma}

\begin{proof}

By the limit definition of $\Pre\Sp(\mC)$ the $\infty$-category of morphisms 
$\Mor_{\Pre\Sp(\mC)}(X,Y)$ is the limit of $\infty$-categories:
$$ \Mor_{\mC^\Omega}(X_0 \to \Omega(X_1), Y_0 \to \Omega(Y_1)) \times_{\Mor_\mC(X_1,Y_1)} \Mor_{\mC^\Omega}(X_1 \to \Omega(X_2), Y_2 \to \Omega(Y_2))  \times_{\Mor_\mC(X_2,Y_2)} ....$$
For every $n \geq 0$ there is a canonical equivalence 
$$ \Mor_{\mC^\Omega}(X_n \to \Omega(X_{n+1}), Y_n \to \Omega(Y_{n+1})) \simeq \Mor_\mC(X_n,Y_n)\times_{\Mor_\mC(X_{n},\Omega(Y_{n+1}))} \Mor_\mC(X_{n+1},Y_{n+1}).$$
Hence by the pasting law there is a canonical equivalence
$$\Mor_{\Pre\Sp(\mC)}(X,Y) \simeq \Mor_\mC(X_0,Y_0)\times_{\Mor_\mC(X_{0},\Omega(Y_{1}))} 
\Mor_\mC(X_1,Y_1)\times_{\Mor_\mC(X_{1},\Omega(Y_{2}))}...$$
% \Mor_\mC(X_4,Y_4)\times_{\Mor_\mC(X_{4},\Omega^2(Y_{6}))} ... .$$

\end{proof}

\begin{corollary}\label{compo}
Let $\mC$ be a reduced Gray-category that admits endomorphisms
and $X \in \Pre\Sp(\mC), Y \in \Sp(\mC).$ There is a canonical equivalence of $\infty$-categories:	
$$\Mor_{\Pre\Sp(\mC)}(X,Y) \simeq \lim(... \to \Mor_{\mC}(X_2,Y_2) \rightarrow
\Mor_{\mC}(X_1,Y_1) \rightarrow \Mor_{\mC}(X_0,Y_0)).$$	

\end{corollary}

\subsubsection{Spectrification}

\begin{notation}Let $\mC$ be a reduced Gray-category that admits endomorphisms.
Let $$\gamma: \Pre\Sp(\mC) \to \mC$$
be the composition of projection to the final object of the diagram $\Pre\Sp(\mC) \to \mC^\Omega $
followed by the composition $\mC^\Omega \to \mC^{[1]} \to \mC^{\{0\}}$.	
\end{notation}

\begin{example}Let $\mC$ be a reduced Gray-category that admits endomorphisms and suspensions. Let $X \in \mC.$ The infinite suspension pre-spectrum $\Sigma^\infty(X)$ of $X$ is the pre-spectrum $(X, \Sigma(X),\Sigma^2(X),...)$ in $\mC$, where the bonding morphisms are the unit $ \Sigma^n(X) \to \Omega(\Sigma(\Sigma^n(X))).$
Hence $\gamma(\Sigma^\infty(X)) \simeq X$.
\end{example}

\begin{lemma}\label{embes}
Let $\mC$ be a reduced Gray-category that admits endomorphisms.
There is an embedding of Gray-categories 
$$\Sp(\mC) \subset \Pre\Sp(\mC)$$
whose essential image precisely consists of the pre-spectra whose bonding morphisms are equivalences.

\end{lemma}

\begin{proof}

Let $(\mC^\Omega)' \subset \mC^\Omega$ be the full subcategory of objects
$(X,Y, \alpha: X \to \Omega(Y))$ such that $\alpha$ is an equivalence.
The Gray-functor $\mC^{[1]}\to \mC^{\{1\}}$ restricts to an equivalence to the full subcategory spanned by the equivalences so that the restricted projection $(\mC^\Omega)' \subset \mC^\Omega \to \mC^\cop$ is an equivalence.
The resulting embedding $\mC^\cop\simeq (\mC^\Omega)' \subset \mC^\Omega$ is a Gray-functor over $\mC \times \mC^\cop$ when we view $\mC^\cop$ over $\mC \times \mC^\cop$ via the Gray-functors $\Omega, \id$, and so induces an embedding of Gray-categories 
$$\Sp(\mC) \simeq \lim(... \xrightarrow{\Omega} \mC \xrightarrow{\Omega} \mC^\cop \xrightarrow{\Omega}\mC) \simeq ... \times_{\mC^\cop} \mC^\cop \times_{\mC} \mC \times_{\mC^\cop} \mC^\cop \subset $$$$ \Pre\Sp(\mC)=... \times_{\mC^\cop} \mC^\Omega \times_{\mC}(\mC^\cop)^\Omega \times_{\mC^\cop} \mC^\Omega.$$

\end{proof}

\begin{lemma}\label{infs} Let $\mC$ be a reduced Gray-category that admits endomorphisms and suspensions. Let $X \in \mC, Y \in \Pre\Sp(\mC).$ The Gray-functor $\gamma: \Pre\Sp(\mC) \to \mC $ induces an equivalence of $\infty$-categories:
$$\Mor_{\Pre\Sp(\mC)}(\Sigma^\infty(X),Y) \to \Mor_{\mC}(\gamma(\Sigma^\infty(X)),\gamma(Y)) \simeq \Mor_{\mC}(X,\gamma(Y)). $$

In particular, the Gray-functor $\gamma: \Pre\Sp(\mC) \to \mC $ admits a fully faithful left adjoint $\Sigma^\infty$ that sends $X$ to $\Sigma^\infty(X).$ 

\end{lemma}

\begin{proof}
Using \cref{comp} the Gray-functor $\gamma: \Pre\Sp(\mC) \to \mC $ induces the following functor:
$$\Mor_{\Pre\Sp(\mC)}(\Sigma^\infty(X),Y) \simeq $$$$ \Mor_{\mC}(X,Y_0)\times_{\Mor_{\mC}(X,\Omega(Y_1))} 
\Mor_{\mC}(X,\Omega(Y_1))\times_{\Mor_{\mC}(X,\Omega^2(Y_2))} \Mor_{\mC}(X,\Omega^2(Y_2))\times_{\Mor_{\mC}(X,\Omega^3(Y_{3}))} ...$$
$$ \simeq %\mC(X,\lim(Y_0 \to \Omega^2(Y_1) \to \Omega^4(Y_2) \to  \Omega^6(Y_3) \to ...)) \simeq 
\Mor_{\mC}(X,Y_0). $$	

\end{proof}


\begin{definition}\label{hiul}
Let $\mC$ be a reduced Gray-category that admits endomorphisms and sequential colimits and let $X \in \Pre\Sp(\mC)$. The associated spectrum of $X$ is the following spectrum $X'$:
for every $n \geq 0$ let $$X'_n := \colim(X_n \to \Omega(X_{n+1}) \to \Omega^2(X_{n+2}) \to ...).$$
The bonding morphism $X'_n \to \Omega(X'_{n+1})$ is the canonical equivalence
$$  \colim(X_n \to \Omega(X_{n+1}) \to \Omega^2(X_{n+2}) \to ...) \simeq \colim(\Omega(X_{n+1}) \to \Omega^2(X_{n+2}) \to \Omega^3(X_{n+3}) \to ...) $$$$\simeq \Omega(\colim(X_{n+1} \to \Omega(X_{n+2}) \to \Omega^2(X_{n+3}) \to ...)).$$

\end{definition}

\begin{remark}

There is a morphism $X \to X'$ in $\Pre\Sp(\mC)$
such that for every $n \geq 0$ the morphism $X_n \to X'_n$ is the canonical morphism to the colimit using the canonical factorization $$X_n \to \Omega^2(X_{n+2}) \to \Omega^2(X'_{n+2}) \simeq X'_n$$ of the morphism $X_n \to X'_n.$

\end{remark}

\begin{proposition}\label{spectri}

Let $\mC$ be a reduced Gray-category that admits endomorphisms and sequential colimits and let $X \in \Pre\Sp(\mC)$ and $Y \in \Sp(\mC).$
The induced functor $$\Mor_{\Pre\Sp(\mC)}(X',Y) \to \Mor_{\Pre\Sp(\mC)}(X,Y)$$
is an equivalence. The Gray-embedding $$\Sp(\mC)\subset \Pre\Sp(\mC)$$ admits a left adjoint that sends $X \in \Pre\Sp(\mC)$ to $X'$.

\end{proposition}

\begin{proof}
Using \cref{comp} the induced functor $\Mor_{\Pre\Sp(\mC)}(X',Y) \to \Mor_{\Pre\Sp(\mC)}(X,Y)$
factors as 
$$\theta: \lim(\Mor_{\mC}(X'_0,Y_0) \leftarrow
\Mor_{\mC}(X'_1,Y_1) \leftarrow \Mor_{\mC}(X'_2,Y_2)\leftarrow ...) ... \to $$$$ \lim(\Mor_{\mC}(X_0,Y_0) \leftarrow
\Mor_{\mC}(X_1,Y_1) \leftarrow \Mor_{\mC}(X_2,Y_2)\leftarrow ...). $$
For every $n \geq 0$ there is a canonical equivalence
$$ \Mor_{\mC}(X'_n,Y_n) \simeq \lim(\Mor_{\mC}(X_n,Y_n) \leftarrow
\Mor_{\mC}(\Omega(X_{n+1}),Y_n) \leftarrow \Mor_{\mC}(\Omega^2(X_{n+2}),Y_n)\leftarrow ...)
\simeq $$$$\lim(\Mor_{\mC}(X_n,Y_n) \leftarrow
\Mor_{\mC}(\Omega(X_{n+1}),\Omega(Y_{n+1})) \leftarrow \Mor_{\mC}(\Omega^2(X_{n+2}),\Omega^2(Y_{n+2})) \leftarrow ...) \simeq $$
$$ \lim(\Mor_{\mC}(X_0,Y_0) \leftarrow ... \leftarrow \Mor_{\mC}(X_n,Y_n) \leftarrow
\Mor_{\mC}(\Omega(X_{n+1}),\Omega(Y_{n+1})) \leftarrow \Mor_{\mC}(\Omega^2(X_{n+2}),\Omega^2(Y_{n+2})) \leftarrow ...).$$
Commuting limits with limits we find that $\theta$ is an equivalence.
The second part follows from \cref{adj} and the observation that $\Sp(\mC)$ is closed in $\Pre\Sp(\mC)$ under left and right cotensors:
the left cotensor is formed object-wise. The right cotensor of any $X \in \infty\Cat_* $ and $\E \in \Pre\Sp(\mC)$ is in even degree $n \geq 0$ the right cotensor $\E_n^X$ and in odd degree
$n \geq 0$ the right cotensor $\E_n^{X^\op}$ and for every even $n \geq 0$ the bonding morphism
$\E_n^X \to \Omega(\E_{n+1}^{X^\op}) \simeq \Omega(\E_{n+1})^X$ is induced by the bonding morphism $\E_n \to \Omega(\E_{n+1})$ and  for odd $n \geq 0$ the bonding morphism
$\E_n^{X^\op} \to \Omega(\E_{n+1}^{X}) \simeq \Omega(\E_{n+1})^{X^\op}$ is induced by the bonding morphism $\E_n \to \Omega(\E_{n+1})$.

\end{proof}

