\begin{corollary}\label{spectrii}

Let $\mC$ be a reduced compactly generated Gray-category.
The left adjoint of the embedding $\Sp(\mC)\subset \Pre\Sp(\mC)$ of Gray-categories 
preserves finite limits and left and right cotensors with finite $\infty$-categories with distinguished object.

\end{corollary}	

\begin{proof}

The statement follows from the description of the left adjoint \ref{hiul}, \cref{spectri} and the fact that filtered colimits commute with finite limits and cotensors with finite $\infty$-categories with distinguished object since $\mC$ is compactly generated.

\end{proof}

\begin{corollary}\label{infsus} Let $\mC$ be a reduced Gray-category that admits endomorphisms, suspensions and sequential colimits such that endomorphisms preserve sequential colimits.
The Gray-functor $\Omega^\infty: \Sp(\mC) \to \mC $ admits a left adjoint $\Sigma^\infty: \mC \to \Sp(\mC) $, which we call infinite suspension. \end{corollary}

\begin{remark}Let $\mC$ be a reduced Gray-category that admits endomorphisms and small filtered colimits such that endomorphisms preserve small filtered colimits.
Then the Gray-functor $\Omega^\infty: \Sp(\mC) \to \mC $ preserves small filtered colimits so that the left adjoint $\Sigma^\infty: \mC \to  \Sp(\mC) $ preserves compact objects. 	

\end{remark}

\begin{corollary}\label{domonos}

Let $\mC, \mD$ be reduced Gray-categories that admit endomorphisms and sequential colimits and $\phi: \mC \to \mD$ a  reduced Gray-functor that preserves sequential colimits and endomorphisms.
The induced reduced Gray-functor $\phi_*: \Pre\Sp(\mC) \to \Pre\Sp(\mD)$ descends to a 
reduced Gray-functor $\phi_!: \Sp(\mC) \to \Sp(\mD)$, which is the restriction of the reduced Gray-functor $\Pre\Sp(\mC) \to \Pre\Sp(\mD).$

If $\mC,\mD$ admit suspensions and $\phi$ preserves suspensions, $\phi_*$ and $\phi_!$ preserve suspensions. In this case $\phi_*$ preserves infinite suspension pre-spectra and $\phi_!$
preserves infinite suspension spectra.

\end{corollary}

\begin{proof}
Since $\phi: \mC \to \mD$ preserves endomorphisms, the reduced Gray-functor $\phi_* : \Pre\Sp(\mC) \to \Pre\Sp(\mD)$  restricts to a reduced Gray-functor $\Sp(\mC) \to \Sp(\mD).$
By \cref{spectri} the Gray-embeddings $\Sp(\mC) \subset \Pre\Sp(\mC), 
\Sp(\mD) \subset \Pre\Sp(\mD)$ admit left adjoints.
Since $\phi$ preserves sequential colimits and endomorphisms, $\phi_*$ preserves local equivalences by the description of local equivalences of \cref{spectri}.
Hence $\phi_*$ descends to a reduced Gray-functor $\phi_*: \Sp(\mC) \to \Sp(\mD)$,
which necessarily agrees with $\phi_!$.
If $\mC,\mD$ admit suspensions and $\phi$ preserves suspensions, $\phi_*$ preserves suspensions as such are formed object-wise. Hence also $\phi_!$ preserves suspensions.
This implies that $\phi_*$ preserves infinite suspension pre-spectra. Since $\phi_*$ descends to $\phi_!$, we find that $\phi_!$ preserves infinite suspension spectra.

\end{proof}

\begin{lemma}Let $\mC$ be a Gray-category that admits a final object and the coproduct of any object with the final object.
The forgetful Gray-functor $\mC_* \to \mC$ admits a left adjojnt $(-)_+$ that sends  $X$ to $ X \coprod *.$ 

\end{lemma}

\begin{proof}
By \cite[Lemma 3.80., Remark 3.85.]{heine2024higher} there is a Gray-embedding of $\mC$ into a presentable Gray-category preserving the final object and the coproduct of any object with the final object. So we can assume that $\mC$ is a presentable Gray-category. In this case the statement follows from \cref{bien}.

\end{proof}

\begin{notation}Let $\mC$ be a Gray-category that admits a final object, the coproduct of any object with the final object, small filtered colimits and endomorphisms such that endomorphisms preserve small filtered colimits. Then $\mC_*$ satisfies the assumptions of \cref{infsus} and so the forgetful Gray-functor $\Sp(\mC) \to \mC_*$ admits a left adjoint $\Sigma^\infty.$
Let $$\Sigma^\infty_+:= \Sigma^\infty \circ (-)_+: \mC \to \mC_* \to \Sp(\mC),$$ which is left adjoint to
$\Omega^\infty:\Sp(\mC) \to \mC_* \to \mC.$

\end{notation}

\begin{remark}

The Gray-localization $\tau_0: \infty\Cat \rightleftarrows \mS$ of \cref{Grayspaces}
gives rise to a Gray-localization $$ \Pre\Sp \rightleftarrows \Pre\Sp(\mS)$$
that descends to a Gray-localization $\tau_0: \Sp \rightleftarrows \Sp(\mS)$ using \cref{spectri},
where the left adjoint takes the spectrification of the degreewise classifying space.

\end{remark}

\subsubsection{Spherical density}

\begin{lemma}\label{Geh}Let $\mC$ be a reduced Gray-category that admits endomorphisms. There is a canonical equivalence of left Gray-categories
$$\Pre\Sp(\mC) \simeq {\Fun\wedge}(S(S^1)\coprod_{\bD^0} S(S^1) \coprod_{\bD^0} ...,\mC).$$
\end{lemma}

\begin{proof}

By \cref{susk} there is a canonical equivalence of (underlying) left Gray-categories over $\mC \times \mC:$
$$\mC^\Omega \simeq {\Fun\wedge}(S(S^1),\mC)$$
sending $(Y,X \to \Omega(Y))$ to $(X,Y, S^1 \to \R\Mor_\mC(X,Y)).$
Hence there is an equivalence of (underlying) left Gray-categories
$$\Pre\Sp(\mC) \simeq ... \times_\mC \mC^\Omega \times_\mC \mC^\Omega \simeq $$$$ ... \times_\mC {\Fun\wedge}(S(S^1),\mC) \times_{\mC} {\Fun\wedge}(S(S^1),\mC) $$$$ \simeq {\Fun\wedge}(S(S^1)\coprod_{\bD^0} S(S^1) \coprod_{\bD^0} ..., \mC).$$

\end{proof}

\begin{proposition}\label{spgen}Let $\mC$ be a reduced presentable Gray-category.
The Gray-category $\Sp(\mC)$ is generated under small colimits and left tensors by the following spectra in $\mC$ for $n \geq 0$ and $Y \in \mC$:
$$(Y \wedge (-))_!( \Omega^n(S^0)).$$

The full subcategory of $\Sp$ spanned by the negative spheres $\Omega^n(S^0)$ for $n \geq 0$
is dense in the left Gray-category $\Sp$.
% is strongly generated by the spectra $\Omega^n(S^0)$ for $n \geq 0$.

\end{proposition}

