\subsection{The higher algebra of stable presentable Gray-categories}

In this subsection we construct a tensor product of stable presentable Gray-categories
(Theorem \ref{stten}).
This tensor product gives rise to a monoidal structure on the Gray-category of categorical spectra
(\cref{unicity}).
In \cite[Theorem 4.2.1.]{Masuda} the author gives an alternative construction of a tensor product of categorical spectra.

\begin{definition}\label{stmon}
A presentably monoidal reduced Gray-category is a presentably monoidal category $\mC$ equipped with a left adjoint monoidal functor $\phi: \infty\Cat_* \to \mC.$

A left adjoint monoidal reduced Gray-functor $\mC \to \mD$ between presentably monoidal reduced Gray-categories is a left adjoint monoidal functor $\mC \to \mD$ under $ \infty\Cat_*.$

\end{definition}

\begin{remark}
Any presentably monoidal reduced Gray-category $(\mC, \phi)$ has an underlying reduced presentable Gray-category by restricting the canonial biaction of $\mC$ over $\mC, \mC$ along $\phi.$

Similarly, every left adjoint monoidal reduced Gray-functor between presentably monoidal reduced Gray-categories has an underlying left adjoint reduced Gray-functor.

\end{remark}

\begin{definition}

A presentably monoidal reduced Gray-category is left stable, right stable, stable, respectively, if its underlying presentable reduced Gray-category is left stable, right stable, stable.	

\end{definition}

The category $ \wedge \Pr^L\wedge$ carries a canonical monoidal structure given by the relative tensor product of $\infty\Cat_*, \infty\Cat_*$-bimodules in $\Pr^L$ \cite[\S 4.4.]{lurie.higheralgebra}.
By \cite[Corollary 3.4.1.7.]{lurie.higheralgebra} the category of associative algebras in $ \wedge \Pr^L\wedge$ is equivalent to the category of associative algebras in $\Pr^L$ under $\infty\Cat_*$, which is the category of presentably monoidal categories under $\infty\Cat_*$,
i.e. presentably monoidal reduced Gray-categories.

\begin{theorem}\label{stten}

There is a monoidal structure on the $\infty$-category ${\wedge}\Pr^L_{\mathrm{st}}\wedge$ 
of presentable stable Gray-categories whose tensor unit is $\Sp$
such that the embedding ${\wedge}\Pr^L_{\mathrm{st}}\wedge \subset \wedge \Pr^L\wedge$ refines to a lax monoidal embedding.
\end{theorem}

\begin{proof}

By \cref{qqq} (3) there is a localization $L$ of $\wedge\Pr^L\wedge$ whose local objects are the stable Gray-categories, that sends $\mC $ to $\Sp^\co(\Sp(\mC))=\Sp \ot_{\infty\Cat_*} \mC \ot_{\infty\Cat_*} \Sp.$
This implies by \cite[Lemma 3.13.]{heine2024localglobalprincipleparametrizedinftycategories} that the full subcategory ${\wedge}\Pr^L_{\mathrm{st}}\wedge$ of local objects inherits an oplax monoidal structure such that the embedding ${{\wedge}\Pr^L_{\mathrm{st}}\wedge} \subset \wedge\Pr^L\wedge$ is a lax monoidal embedding and such that the local tensor product of $\mC_1,...,\mC_n \in {\wedge}\Pr^L_{\mathrm{st}}\wedge$ for $n \geq 0$ is $L(\mC_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC_n).$
If $n \geq 1$ we have that $$ L(\mC_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC_n) \simeq \Sp \ot_{\infty\Cat_*} \mC_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC_n \ot_{\infty\Cat_*} \Sp \simeq \mC_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC_n.$$
If $n=0$, we have that $L(\infty\Cat_*)\simeq \Sp \ot_{\infty\Cat_*} \Sp \simeq \Sp(\Sp)\simeq \Sp.$
Consequently, to see that this oplax monoidal structure on ${\wedge}\Pr^L_{\mathrm{st}}\wedge$ is a monoidal structure it is enough to see that for every $\mC^1_1,...,\mC^1_{n_1}, \mC^2_1,...,\mC^2_{n_2},..., \mC^\ell_1,...,\mC^\ell_{n_\ell} \in {\wedge}\Pr^L_{\mathrm{st}}\wedge$ for $\ell \geq 2, n_1, ...,n_\ell \geq 0$ the canonical morphism
$$\theta: L(\mC^1_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^1_{n_1} \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\ell_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\ell_{n_\ell}) \to $$$$ L(L(\mC^1_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^1_{n_1}) \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} L(\mC^\ell_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\ell_{n_\ell}))$$
is an equivalence. 
Assume first that $ n_\bj=0$ for every $0 \leq \bj \leq \ell.$
In this case $\theta$ factors as $$\Sp \simeq \Sp \ot_{\infty\Cat_*} \infty\Cat^{\ot_{\infty\Cat_*}\ell} \ot_{\infty\Cat_*} \Sp \to \Sp \ot_{\infty\Cat_*} \Sp^{\ot_{\infty\Cat_*} \ell} \ot_{\infty\Cat_*} \Sp \simeq \Sp$$ and so is the identity.
So we assume that $ n_\bj \geq 1 $ for some $0 \leq \bj \leq \ell.$
In this case $\theta$ identifies with
$$\mC^1_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^1_{n_1} \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\ell_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\ell_{n_\ell} \to $$$$ L(\mC^1_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^1_{n_1}) \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} L(\mC^\ell_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\ell_{n_\ell}).$$
For every $1 \leq \bj \leq \ell$ the reduced Gray-functor $\mC^\bj_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\bj_{n_\bj} \to L(\mC^\bj_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\bj_{n_\bj})$ is an equivalence if $n_\bj \geq 1$ as in this case $\mC^\bj_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\bj_{n_\bj}$ is local.
If $n_\bj=0$, the reduced Gray-functor $$\mC^\bj_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\bj_{n_\bj} \to L(\mC^\bj_1 \ot_{\infty\Cat_*} ... \ot_{\infty\Cat_*} \mC^\bj_{n_\bj})$$ is the canonical reduced Gray-functor $\infty\Cat_* \to \Sp$.
So by induction on $\ell$ it is enough to see that for every stable presentable Gray-category $\mC$
the canonical reduced Gray-functors $$\mC \simeq \infty\Cat_* \ot_{\infty\Cat_*} \mC \to \Sp \ot_{\infty\Cat_*} \mC, \mC \simeq \mC \ot_{\infty\Cat_*} \infty\Cat_* \to \mC \ot_{\infty\Cat_*} \Sp$$ are equivalences. The latter identify with the stabilization functors and so are equivalences.
\end{proof}

\begin{corollary}\label{unicity}

The category of stable presentably monoidal Gray-categories admits an initial object 
whose underlying stable Gray-category is $\Sp.$
In particular, the Gray-functor $\Sigma^\infty: \infty\Cat \to \Sp$ is monoidal.
\end{corollary}

\begin{remark}

In recent work \cite[Theorem 4.2.1.]{Masuda} the author gives a different proof of \cref{unicity} via a theory of idempotent $\bE_0$-algebras and idempotent $\bE_1$-algebras. % and studies the Gray smash product on $\Sp$.

\end{remark}

\subsection{Spectral Gray-categories}

In this subsection we study spectral Gray-categories, which we relate to stable Gray-categories in section \ref{SpecStab}.

\begin{definition}
\begin{itemize}

\item A spectral left (right) Gray-category is a category left (right) enriched in $(\Sp,\wedge).$

\item A left spectral Gray-category is a category bienriched in $(\Sp,\wedge), (\infty\Cat_*,\wedge)$.

\item A right spectral Gray-category is a category bienriched in $(\infty\Cat_*,\wedge), (\Sp,\wedge)$.

\item A spectral Gray-category is a category bienriched in $(\Sp,\wedge), (\Sp,\wedge)$.

\end{itemize}

\end{definition}

\begin{notation}We fix the following notation:

\begin{itemize}
\item Let ${\barwedge}\Cat:= {_{(\Sp,\wedge)}\Enr}$
be the category of spectral left Gray-categories.

\item Let $\Cat\barwedge:= {\Enr_{(\Sp,\wedge)}}$
be the category of spectral right Gray-categories.	

\item Let ${\barwedge}\Cat\wedge:= {_{(\Sp,\wedge) } \Enr_{(\infty\Cat_*,\wedge)}}$
be the category of left spectral Gray-categories.

\item Let ${\wedge}\Cat\barwedge:= {_{(\infty\Cat_*,\wedge) } \Enr_{(\Sp,\wedge)}}$
be the category of right spectral Gray-categories.

\item Let ${\barwedge}\Cat\barwedge:= {_{(\Sp,\wedge) } \Enr_{(\Sp,\wedge)}}$
be the category of spectral Gray-categories.

\end{itemize}
\end{notation}
We refer to morphims in ${\barwedge}\Cat$ as spectral left Gray-functors, to morphims in $\Cat\barwedge$ as spectral right Gray-functors, to morphisms in ${\barwedge}\Cat\wedge$ as left spectral Gray-functors, to morphisms in ${\wedge}\Cat\barwedge$ as right spectral Gray-functors and to morphims in ${\barwedge}\Cat\barwedge$ as spectral Gray-functors. 
A spectral left (right) (pseudo-) Gray-category, left (right) spectral, spectral (pseudo-) Gray-category is presentable if the respective bi(pseudo-)enriched category is presentable.

\begin{definition}
A spectral left Gray-category, right Gray-category, Gray-category, left spectral Gray-category, right spectral Gray-category is reduced if it admits a zero object.

\end{definition}

\begin{remark}
A spectral left Gray-category, right Gray-category, Gray-category, left spectral Gray-category, right spectral Gray-category is reduced if it admits an initial object or final object \cite[Proposition 2.5.2.]{GepnerHeine}. 
Moreover any spectral left Gray-functor, right Gray-functor, Gray-functor between reduced spectral left Gray-categories, right Gray-categories, Gray-categories, left spectral Gray-categories, right spectral Gray-categories, respectively, preserves the zero object \cite[Proposition 2.5.3.]{GepnerHeine}.

\end{remark}

