\begin{lemma}\label{specstab}

\begin{enumerate}

\item Let $\mC$ be a reduced spectral right Gray-category that admits endomorphisms. The underlying reduced right Gray-category of $\mC$ is oplax stable.

\item Let $\mC$ be a reduced spectral left Gray-category that admits coendomorphisms. The underlying reduced left Gray-category of $\mC$ is lax stable.

\end{enumerate}

\end{lemma}

\begin{proof}
We prove (1). (2) is dual. %By ... there is a left spectral Gray-embedding of $\mC$ into a presentable spectral left Gray-category $\mD$ that preserves cosuspensions and coendomorphisms.Hence the underlying left Gray-category of $\mC$ is oplax stable if the underlying left Gray-category of $\mD$ is oplax stable. So we can assume that $\mC$ is presentable. In this case 
%The suspension of any $X \in \mC$ is the oplax pushout $ 0 \coprod_X^\oplax 0$, which is the right tensor with $S^1.$ 
The endomorphisms of any $X \in \mC$ is the oplax pullback $ 0 \prod_X^\oplax 0$, which is the right cotensor with $S^1.$ 
Since $S^1$ is tensor-invertible in $\Sp$, the claim follows.

\end{proof}

\begin{lemma}\label{exacto}

\begin{enumerate}
\item Any right spectral Gray-functor between reduced right spectral Gray-categories having endomorphisms preserves endomorphisms.

\item Every left spectral Gray-functor between reduced left spectral Gray-categories having coendomorphisms preserves coendomorphisms.	

\item Every spectral Gray-functor between reduced spectral Gray-categories having endomorphisms and
coendomorphisms preserves endomorphisms and coendomorphisms.	

\end{enumerate}

\end{lemma}

\begin{proof}

We prove (1). The proofs of (2), (3) are similar.
Let $\phi: \mC \to \mD$ be a right spectral Gray-functor between reduced right spectral Gray-categories having endomorphisms and $X \in \mC.$
By \cref{specstab} the underlying reduced right Gray-categories of $\mC, \mD$ are oplax stable.
Hence there are equivalences
$$  \R\Mor_\mC(\Omega(X), \Omega(X)) \simeq  \Sigma(\R\Mor_\mC(X, \Omega(X))), $$
$$ \R\Mor_\mD(\Omega(\phi(X)), \phi(\Omega(X))) \simeq \Sigma(\R\Mor_\mD(\phi(X),\phi(\Omega(X)))).$$
The induced functor $$ \R\Mor_\mC(\Omega(X), \Omega(X)) \simeq  \Sigma(\R\Mor_\mC(X, \Omega(X))) \to $$$$ \Sigma(\R\Mor_\mD(\phi(X),\phi(\Omega(X)))) \simeq \R\Mor_\mD(\Omega(\phi(X)), \phi(\Omega(X)))$$ sends the identity of $\Omega(X)$ 
to a morphism $ \Omega(\phi(X)) \to \phi(\Omega(X)) $ in $\mD.$ 
This morphism is inverse to the canonical morphism $\phi(\Omega(X)) \to \Omega(\phi(X)) $.

\end{proof}

