\begin{definition}\label{oplaxexact} Let $\mC$ be a reduced spectral right Gray-category.
A sequence
$$... \xrightarrow{\gamma_{n-1}} A_n \xrightarrow{\alpha_n} B_n \xrightarrow{\beta_n} C_n \xrightarrow{\gamma_n} A_{n+1} \xrightarrow{\alpha_{n+1}} B_{n+1}  \xrightarrow{\beta_{n+1}}  ... $$
in $\mC$ is oplax exact if 
\begin{itemize}
\item for every even $n \in \bZ$ the morphism $\beta_n $ is the oplax left cofiber of $\alpha_n$ and fiber of $\gamma_n$,
\item for every even $n \in \bZ$ the morphism $ \gamma_n$ is the cofiber of $ \beta_n$ and oplax left fiber of $ \alpha_{n+1}$,
\item for every odd $n \in \bZ$ the morphism $\beta_n $ is the oplax right cofiber of $\alpha_n$ and fiber of $\gamma_n$,
\item for every odd $n \in \bZ$ the morphism $ \gamma_n$ is the cofiber of $ \beta_n$ and oplax right fiber of $ \alpha_{n+1}.$
\end{itemize}

Dually, we define lax exact sequences in reduced left Gray-categories.

\end{definition}

\begin{corollary}\label{oplaxexacto} Let $\mC$ be a reduced spectral right Gray-category that admits oplax cofibers and oplax fibers.

\begin{enumerate}
\item There is an oplax exact sequence in $\mC:$
$$... \xrightarrow{\gamma_{n-1}} A_n \xrightarrow{\alpha_n} B_n \xrightarrow{\beta_n} C_n \xrightarrow{\gamma_n} A_{n+1} \xrightarrow{\alpha_{n+1}} B_{n+1}  \xrightarrow{\beta_{n+1}}  ...$$

\item Let $\mD$ be a reduced spectral right Gray-category that admits oplax cofibers and oplax fibers.
The oplax exact sequence of (1) is preserved by any spectral right Gray-functor $\phi :\mC \to \mD$.
\end{enumerate}	
\end{corollary}	

\begin{proof}


Let $\phi: A \to B$ a morphism in $\mC.$
Consider the following diagram in $\mC:$
\[
\begin{tikzcd}
A \ar{d} \ar{r} & B \ar{r}{} \ar{d}[swap]{} & 0  \ar{d}{} \\
0 \ar[double]{ur}{} \ar{r} & \overset{\overset{\hspace{-3.0mm}\rightarrow}{\hspace{-3.0mm} \oplax}}{0 \coprod_A B} \simeq \overset{\overset{\hspace{-14.0mm}\rightarrow}{\hspace{-14.0mm} \oplax}}{0 \prod_{\Sigma(B)} \Sigma(A)} \ar[d]  \ar{r}[swap]{} & \overset{\overset{\hspace{-2.0mm}\rightarrow}{\hspace{-2.0mm} \oplax}}{0 \coprod_A 0}  \simeq \Sigma(A) \ar[d] \\
& 0 \ar[double]{ur}{} \ar{r}[swap]{} & \Sigma(B),
\end{tikzcd}
\]
in which the left hand upper square is an oplax left pushout square and right hand lower square is an oplax left pullback square. By \cref{specstab} (2) the reduced spectral right Gray-category $\mC$ is right stable.
So by the pasting law (\cref{pasting}) and its dual version the right hand upper square is a pushout and pullback square.  By \cref{preserv} and the pasting law (\cref{pasting}) and its dual version 
the oplax left pushout, pushout, pullback and oplax left pullback in the latter diagram are preserved by any spectral right Gray-functor.
The reduced Gray-functor $\Sigma: \infty\Cat_*^\cop \to \infty\Cat_*$ sends the latter diagram
to a diagram 
\[
\begin{tikzcd}
A \ar{d} \ar{r} & B  \ar[double]{ld}{}  \ar{r}{} \ar{d}[swap]{} & 0  \ar{d}{} \\
0 \ar{r} & \overset{\overset{\hspace{-3.0mm}\rightarrow}{\hspace{-3.0mm} \oplax}}{0 \coprod_A B} \simeq \overset{\overset{\hspace{-14.0mm}\rightarrow}{\hspace{-14.0mm} \oplax}}{0 \prod_{\Sigma(B)} \Sigma(A)} \ar[d]  \ar{r}[swap]{} & \overset{\overset{\hspace{-2.0mm}\rightarrow}{\hspace{-2.0mm} \oplax}}{0 \coprod_A 0}  \simeq \Sigma(A)  \ar[double]{ld}{} \ar[d] \\
& 0 \ar{r}[swap]{} & \Sigma(B),
\end{tikzcd}
\]
in which the left hand upper square is an oplax right pushout square and right hand lower square is an oplax right pullback square and the right hand upper square is a pushout and pullback square.
\end{proof}

\subsection{Oplax fibers detect equivalences} %in spectral Gray-categories

In this subsection we categorify the result that equivalences in any stable $(\infty,1)$-category are detected by fibers.
We prove that  in any spectral right Gray-category equivalences are detected by oplax fibers:

\begin{theorem}\label{Fibb}

Let $\mC$ be a reduced spectral right Gray-category and
$$\begin{xy}
\xymatrix{
A  \ar[rd]_\alpha \ar[rr]^\phi
&& B \ar[ld]^\beta
\\ 
& C
}
\end{xy}$$
a commutative triangle in $\mC$ such that $\alpha, \beta$ admit oplax left fibers. Then $\phi$ is an equivalence if and only if the following induced morphism on oplax left fibers is an equivalence: 
$$\overset{\overset{\hspace{0.0mm}\rightarrow}{\hspace{0.0mm} \oplax}}{0 \prod_\mE \phi}: \overset{\overset{\hspace{-1.0mm}\rightarrow}{\hspace{-1.0mm} \oplax}}{0 \prod_\mE \mC} \to \overset{\overset{\hspace{-1.0mm}\rightarrow}{\hspace{-1.0mm} \oplax}}{0 \prod_\mE \mD}. $$ 

\end{theorem}

