\begin{proposition}\label{riol}

Let $$\begin{xy}
\xymatrix{
\mC  \ar[rd]_\alpha \ar[rr]^\phi
&& \mD \ar[ld]^\beta
\\ 
& \mE
}
\end{xy}$$
be a commutative triangle of $\infty$-categories. The functor $\phi$ is an equivalence if and only if for every $Z \in \mE$ the following induced functor on oplax left fibers is an equivalence:
\begin{equation}\label{refs} \overset{\overset{\hspace{3.0mm}\rightarrow}{\hspace{3.0mm} \oplax}}{\{Z\} \prod_\mE \phi}: \overset{\overset{\hspace{3.0mm}\rightarrow}{\hspace{3.0mm} \oplax}}{\{Z\} \prod_\mE \mC} \to \overset{\overset{\hspace{2.0mm}\rightarrow}{\hspace{2.0mm} \oplax}}{\{Z\}\prod_\mE \mD}. \end{equation} 

\end{proposition}

\begin{proof}
We prove the non-trivial implication. Assume that the induced functor on oplax left fibers is an equivalence for every $Z \in \mE.$ We prove by induction on $n \geq 0$ that $\phi$ is an $n$-equivalence for every $n \geq 0.$ By \cref{homt} this implies that $\phi$ is an equivalence.

We first prove that $\phi$ is a $0$-equivalence, i.e. induces a bijection on equivalence classes. We start with proving  that $\phi$ is essentially surjective: 
let $Y \in \mD$. Then $(Y, \id: \beta(Y)\to \beta(Y)) \in \overset{\overset{\hspace{6.0mm}\rightarrow}{\hspace{7.0mm} \oplax}}{\{\beta(Y)\}\prod_\mE \mD}$. So by assumption there is an object $(X, \sigma:  \beta(Y)\to \alpha(X)) \in \overset{\overset{\hspace{6.0mm}\rightarrow}{\hspace{7.0mm} \oplax}}{\{\beta(Y)\}\prod_\mE \mC}$ such that
$\phi(X)\simeq Y$ and such that $\sigma$ factors as $ \beta(Y) \simeq \beta(\phi(X)) \simeq \alpha(X).$
So $\phi$ is essentially surjective.
We prove next that $\phi$ is essentially injective: let $Y,Z \in \mC$ and $\kappa: \phi(Y)\simeq \phi(Z)$ an equivalence. Then the objects $ (\phi(Y), \alpha(Y) \simeq \beta(\phi(Y)))$ and $ (\phi(Z), \alpha(Y) \simeq \beta(\phi(Y))\simeq \beta(\phi(Z)) )$ are equivalent in $ \overset{\overset{\hspace{6.0mm}\rightarrow}{\hspace{7.0mm} \oplax}}{\{\alpha(Y)\}\prod_\mE \mD}$ via $\kappa.$
So by assumption there is an equivalence between $ (Y, \id: \alpha(Y) \to \alpha(Y))$ and $ (Z,  \alpha(Y) \simeq \beta(\phi(Y)) \simeq \beta(\phi(Z)) \simeq \alpha(Z))$ in $\overset{\overset{\hspace{6.0mm}\rightarrow}{\hspace{7.0mm} \oplax}}{\{\alpha(Y)\}\prod_\mE \mD}$.
Thus $Y \simeq Z.$ 
So $\phi$ is a $0$-equivalence.

We prove next that $\phi$ is an $n+1$-equivalence assuming that a functor $\phi$ is an $n$-equivalence if for every $Z \in \mE$ the functor \ref{refs} is an equivalence.
The functor $\phi$ is an $n+1$-equivalence if for every $X,Y \in \mC$ 
the induced functor $\Mor_{\mC}(X,Y)\to \Mor_{\mD}(\phi(X),\phi(Y))$ is an $n$-equivalence.
By induction hypothesis this holds if for every morphism $\sigma: \alpha(X) \to \alpha(Y)$ in $\mE$ the induced functor on oplax left fibers $$
\overset{\overset{\hspace{-13.0mm}\rightarrow}{\hspace{-13.0mm} \oplax}}{\{\sigma\} \prod_{\Mor_{\mE}(\alpha(X),\alpha(Y))} \Mor_{\mC}(X,Y)} 
\to \overset{\overset{\hspace{-25.0mm}\rightarrow}{\hspace{-25.0mm} \oplax}}{\{\sigma\} \prod_{\Mor_{\mE}(\alpha(X),\alpha(Y))}\Mor_{\mD}(\phi(X),\phi(Y))} $$ is an equivalence.
By \cref{hom} the latter functor identifies with the induced functor $$\Mor_{ \overset{\overset{\hspace{5.0mm}\rightarrow}{\hspace{5.0mm} \oplax}}{\{\alpha(X)\}\prod_\mE \mC}}((X, \sigma), (Y, \id)) \to \Mor_{ \overset{\overset{\hspace{5.0mm}\rightarrow}{\hspace{5.0mm} \oplax}}{\{\alpha(X)\}\prod_\mE \mD}}((\phi(X), \sigma), (\phi(Y), \id)),$$ 
which is an equivalence since the functor \ref{refs} is an equivalence.

\end{proof}

We prove the following refinement of \cref{riol}:

\begin{proposition}\label{riok}

Let $$\begin{xy}
\xymatrix{
\mC  \ar[rd]_\alpha \ar[rr]^\phi
&& \mD \ar[ld]^\beta
\\ 
& \mE
}
\end{xy}$$
be a commutative triangle of $\infty$-categories and $Z \in \mE$
such that the induced functor on oplax left fibers 
$$\overset{\overset{\hspace{3.0mm}\rightarrow}{\hspace{3.0mm} \oplax}}{\{Z\} \prod_\mE \phi}: \overset{\overset{\hspace{3.0mm}\rightarrow}{\hspace{3.0mm} \oplax}}{\{Z\} \prod_\mE \mC} \to \overset{\overset{\hspace{2.0mm}\rightarrow}{\hspace{2.0mm} \oplax}}{\{Z\}\prod_\mE \mD} $$ 
is fully faithful.
%\item Every object of $\mD$ lying over $Z$ has a pre-image under $\phi$.
For every $Y \in \mC$ lying over $Z$ and $X \in \mC$ the following induced functor is an equivalence:
$$ \Mor_{\mC}(X,Y)\to \Mor_{\mD}(\phi(X),\phi(Y)).$$

\end{proposition}

\begin{proof}
Let $Y \in \mC$ lying over $Z$ and $X \in \mC$ and $\sigma: \alpha(X) \to \alpha(Y)\simeq Z$ a morphism in $\mE$.
By assumption the induced functor $$\Mor_{(\{Z\} \prod^\lax_\mE \mD)}((X, \sigma), (Y, \id)) \to \Mor_{(\{Z\} \prod^\lax_\mE \mD)}((\phi(X), \sigma), (\phi(Y), \id)) $$ is an equivalence.
By \cref{hom} the latter functor identifies with the functor
$$\{\sigma\} \prod^\lax_{\Mor_{\mE}(\alpha(X),\alpha(Y))} \Mor_{\mC}(X,Y) \to \{ \sigma\}\prod^\lax_{\Mor_{\mE}(\alpha(X),\alpha(Y))} \Mor_{\mD}(\phi(X),\phi(Y)).$$
Hence by \cref{riol} the functor $ \Mor_{\mC}(X,Y)\to \Mor_{\mD}(\phi(X),\phi(Y))$ is an equivalence.

\end{proof}

\begin{corollary}\label{opost}

Let $$\begin{xy}
