\begin{corollary} \label{homolog}
Consider the following commutative diagram of categorical spectra of whose top and bottom sequences are oplax exact:
$$	
\begin{tikzcd}
... \ar{r}{\gamma_{n-1}} & A_n \ar{r}{\alpha_n} \ar{d}{\psi_n^A} & B_n \ar{d}{\psi^B_n} \ar{r}{\beta_n} & C_n \ar{d}{\psi^C_n}  \ar{r}{\gamma_n} & A_{n+1} \ar{d}{\psi^A_{n+1}} \ar{r}{\alpha_{n+1}} & B_{n+1} \ar{d}{\psi^B_{n+1}} \ar{r}{\beta_{n+1}} & ... \\ 
... \ar{r}{\gamma'_{n-1}} & A'_n \ar{r}{\alpha'_n} & B'_n \ar{r}{\beta'_n} & C'_n \ar{r}{\gamma'_n} & A'_{n+1} \ar{r}{\alpha'_{n+1}} & B'_{n+1} \ar{r}{\beta'_{n+1}} & ...
\end{tikzcd}
$$	
If any two of $\psi^A_*, \psi^B_*, \psi^C_*$ are equivalences, then so is the third.

\end{corollary}

\begin{proof}
If $\psi^A_*, \psi^B_*$ are equivalences, then trivially also $\psi^C_*$ is an equivalence by functoriality of taking oplax cofibers.
If $\psi^B_*, \psi^C_*$ are equivalences, then $\psi^A_*$ is an equivalence by Theorem \ref{Fibb}.
If $\psi^A_*, \psi^C_*$ are equivalences, then $\psi^B_*$ is an equivalence by the dual of Theorem \ref{Fibb}.

\end{proof}

