\subsection{Infinite delooping} 

In this subsection we prove that every symmetric monoidal $\infty$-category
canonically deloops to a categorical spectrum.

We start with proving that every stable Gray-category is preadditive.

\begin{definition}
A (left) (right) Gray-category is preadditive if it is reduced, it admits finite coproducts and finite products and for every $A,B \in \mC$ the canonical morphism $A \coprod B \to A \times B$ is an equivalence.	

\end{definition}

See also \cite[A.5.]{Secondary} or \cite[A.9.]{heine2021realktheorywaldhauseninfinity} for preadditive enriched categories.

\begin{proposition}\label{preadd}
Every oplax quasi-stable right Gray-category is preadditive.	
\end{proposition}

\begin{proof}

By oplax quasi-stability for every $X, Y \in \mC$ there is a canonical equivalence of $\infty$-categories
$$\R\Mor_{\mC}(X,Y) \simeq \R\Mor_{\mC}(X,\Omega(\Sigma(Y))) \simeq \Omega(\R\Mor_{\mC}(X,\Sigma(Y)))$$ 
that endows $\R\Mor_{\mC}(X,Y)$ with the structure of a monoidal $\infty$-category
whose tensor unit is the zero morphism.
The tensor product functor $$\R\Mor_{\mC}(X,Y \times Y) \simeq \R\Mor_{\mC}(X,Y) \times \R\Mor_{\mC}(X,Y) \to \R\Mor_{\mC}(X,Y) $$ sends the identity of $Y \times Y$ to a morphism $\mu_Y: Y \times Y \to Y.$
By construction of $\mu_Y$ for every morphism $\alpha: Y \to Z$ the morphism $\alpha \circ \mu_Y$
is equivalent to $\mu_Z \circ (\alpha \times \alpha)$ and for every $X,Y \in \mC$
the morphism $\mu_{X\times Y}$ factors as $(X\times Y) \times (X\times Y) \simeq (X\times X) \times (Y\times Y) \xrightarrow{\mu_X \times \mu_Y} X \times Y.$
Moreover by unitality of the monoidal structure on $\R\Mor_{\mC}(X,Y)$
the composition $Y \simeq Y \times * \to Y \times X\xrightarrow{\mu_Y} Y$ is the identity.
By \cite[Proposition 2.4.3.19.]{lurie.higheralgebra} this implies that $\mC$ is preadditive.

\end{proof}

\begin{corollary}
Every lax quasi-stable left Gray-category is preadditive.	

\end{corollary}

\begin{notation}
Let $\Pr^L \subset \widehat{\Cat}$ be the subcategory of presentable categories and left adjoint functors.	

\end{notation}
\begin{notation}
Let $\Pr^L_{\mathrm{preadd}} \subset \Pr^L$ be the full subcategory of preadditive presentable categories.

\end{notation}

By \cite[Theorem 4.6.]{Gepner_2015} there is a symmetric monoidal localization \begin{equation}\label{loo}\Mon_{\bE_\infty}:\Pr^L \rightleftarrows \Pr^L_{\mathrm{preadd}},\end{equation} where $\Mon_{\bE_\infty}$ assigns to any presentable category $\mD$ the category of commutative monoid objects in $\mD$ and the unit is the free functor.
The localization \ref{loo} gives rise to a localization on associative algebras whose  local objects are precisely the preadditive presentably monoidal categories:  \begin{equation}\label{adjass}
\Mon_{\bE_\infty}:\Alg(\Pr^L) \rightleftarrows \Alg(\Pr^L_{\mathrm{preadd}}).\end{equation}
Moreover it gives rise to localizations, where the subsprict preadd refers to the full subcategories of preadditive presentable reduced (left) (right) Gray-categories:
$$ \Mon_{\bE_\infty}: \wedge \Pr^L\rightleftarrows \wedge \Pr^L_{\mathrm{preadd}}, \  \Mon_{\bE_\infty}: \Pr^L\wedge \rightleftarrows \Pr^L_{\mathrm{preadd}}\wedge, \  \Mon_{\bE_\infty}: \wedge \Pr^L\wedge \rightleftarrows \wedge {\Pr^L_{\mathrm{preadd}}\wedge} .$$

\begin{corollary}\label{hhoo}\emph{ }
\begin{enumerate}
\item Let $\mC$ be a presentable lax stable left Gray-category.
The left adjoint left Gray-functor $\Free_{\bE_\infty}: \mC \to \Mon_{\bE_\infty}(\mC)$ is an equivalence inverse to the forgetful left Gray-functor.

\item Let $\mC$ be a presentable oplax stable right Gray-category.
The left adjoint right Gray-functor $\Free_{\bE_\infty}: \mC \to \Mon_{\bE_\infty}(\mC)$ is an equivalence inverse to the forgetful right Gray-functor.

\item Let $\mC$ be a presentable lax stable or oplax stable Gray-category.
The left adjoint Gray-functor $\Free_{\bE_\infty}: \mC \to \Mon_{\bE_\infty}(\mC)$ is an equivalence inverse to the forgetful Gray-functor.

\end{enumerate}
\end{corollary}

\begin{definition}
Let $\mC$ be a category that admits sequential colimits and finite products that commute with each other. 
By	\cite[Corollary 3.1.3.4.]{lurie.higheralgebra} the forgetful functor $\Mon_{\bE_\infty}(\mC) \to \mC_*$ admits a left adjoint that we call free reduced $\bE_\infty$-monoid functor.
\end{definition}

\begin{remark}

By adjointness the free $\bE_\infty$-monoid functor $\mC \to \Mon_{\bE_\infty}(\mC)$ factors as the functor $(-)_+: \mC \to \mC_*$
followed by the free reduced $\bE_\infty$-monoid functor.	

\end{remark}

\begin{remark}\label{symolu}

The free reduced $\bE_\infty$-monoid functor sends $X \in \mC_*$ to the sequential colimit $$\colim((X^{\times 0})_{\Sigma_0} \to (X^{\times 1})_{\Sigma_1} \to (X^{\times 2})_{\Sigma_2} \to ...),$$
where the sequential diagram is induced by the morphism $X^{\times n} \to X^{\times n+1}$
that uses the morphism $* \to X$ in the last factor.
This follows from \cite[Corollary 3.1.3.4.]{lurie.higheralgebra}: let $\Fin^\inj \subset \Fin$ be the subcategory of injective maps and for every $n \geq 0$ let $\Fin^\inj_n \subset \Fin^\inj$
be the full subcategory of finite sets with less than $n+1$-elements.
The morphism $* \to X$ gives rise to a functor $\rho: \Fin^\inj \to \mC, \{1,...,n\} \mapsto X^{\times n} $ whose colimit is the free reduced commutative monoid on $X$ by 
\cite[Corollary 3.1.3.4.]{lurie.higheralgebra}. The category $\Fin^\inj$ is the sequential colimit of the diagram $ \Fin^\inj_0 \subset \Fin^\inj_1 \subset ...$ so that $\colim(\rho)$ is the sequential colimit of the diagram $ \colim(\rho_{\mid \Fin^\inj_0}) \to \colim(\rho_{\mid \Fin^\inj_1}) \to ....$
The embedding $B\Sigma_n \subset \Fin^\inj_n$ of the full subcategory spanned by the finite sets with precisely $n$-elements is cofinal so that $\colim(\rho_{\mid \Fin^\inj_n}) \simeq \colim(\rho_{\mid B\Sigma_n}) \simeq (X^{\times n})_{\Sigma_n}.$

\end{remark}


%\begin{proof}By \cref{preadd} the Gray-category $\mC$ is preadditive.So the left adjoint Gray-functor $\Free: \mC \to \Mon_{\bE_\infty}(\mC)$ induces an equivalence on underlying categories and so is an equivalence by \cref{adj} and \cref{ahoo}.\end{proof}

\begin{remark}\label{rero} Let $\mC$ be a presentable Gray-category.
The left adjoint reduced Gray-functor $\Sigma^\infty:\mC_* \to \Sp(\mC_*)$
induces a left adjoint reduced Gray-functor $$\Mon_{\bE_\infty}(\Sigma^\infty): \Mon_{\bE_\infty}(\mC) \simeq \Mon_{\bE_\infty}(\mC_*) \to \Mon_{\bE_\infty}(\Sp(\mC_*)) \simeq \Sp(\mC_*), $$
where we use \cref{hhoo}, and $\Sigma^\infty$ factors as the free functor $ \mC_* \to  \Mon_{\bE_\infty}(\mC_*) $ followed by $\Mon_{\bE_\infty}(\Sigma^\infty).$
Hence $\Sigma_+^\infty$ factors as the free functor $ \mC \to  \Mon_{\bE_\infty}(\mC_*) $ followed by $\Mon_{\bE_\infty}(\Sigma^\infty).$
\end{remark}

In the following we prove that every symmetric monoidal $\infty$-category
uniquely deloops to a connective categorical spectrum.

