\begin{lemma}\label{hujt} Let $n,m \geq 0$ and $X \in \Mon_{\bE_\infty}(\infty\Cat)$ be $n$-connected 
and $Y \in \Mon_{\bE_\infty}(\infty\Cat) $ be $m$-connected.  Then $X \wedge Y$ is $n+m+1$-connected.

\end{lemma}

\begin{proof}Let $\infty\Cat^{\leq n} \subset \infty\Cat$ be the full subcategory of $n$-connected $\infty$-categories.
The embedding $\infty\Cat^{\leq n} \subset \infty\Cat$ preserves finite products and admits a right adjoint and so induces a left adjoint embedding $ \Mon_{\bE_\infty}(\infty\Cat^{\leq n}) \subset  \Mon_{\bE_\infty}(\infty\Cat)$ whose essential image precisely consists of the symmetric monoidal $\infty$-categories whose underlying $\infty$-category is $n$-connected.
The category $ \Mon_{\bE_\infty}(\infty\Cat^{\leq n})$ is generated under small colimits by the essential image of the free functor $ \infty\Cat^{\leq n}_* \to  \Mon_{\bE_\infty}(\infty\Cat^{\leq n}).$
Hence the full subcategory $ \Mon_{\bE_\infty}(\infty\Cat^{\leq n}) \subset \Mon_{\bE_\infty}(\infty\Cat)$ is generated under small colimits by the essential image of the restricted free functor $ \infty\Cat^{\leq n}_* \subset \infty\Cat_* \to  \Mon_{\bE_\infty}(\infty\Cat).$
Since the free functor $ \infty\Cat_* \to  \Mon_{\bE_\infty}(\infty\Cat)$ is monoidal, the result follows from \cref{conesto}.
\end{proof}

Next we introduce the the Picard spectrum.

\begin{notation}For every category $\mD$ that admits finite products let $\Grp_{\bE_\infty}(\mD)$ be the full subcategory of $\Mon_{\bE_\infty}(\mD)$ spanned by the group objects.

\end{notation}

\begin{remark}\label{ahoo}

%By \cite[Proposition 2.3.]{Gepner_2015} for every preadditive category $\mD$ the forgetful functor $\Mon_{\bE_\infty}(\mD)\to \mD$ is an equivalence.
