\begin{definition}

The embedding $ \Grp_{\bE_\infty}(\mS)  \subset  \Mon_{\bE_\infty}(\mS) $ admits a right adjoint that sends an $\bE_\infty$-space to the full $\bE_\infty$-subspace spanned by the invertible objects.
The Picard space functor $\Pic$ is the following composition of the functor induced by $\iota_0$ and the right adjoint: $$\Pic: \Mon_{\bE_\infty}(\infty\Cat) \xrightarrow{\Mon_{\bE_\infty}(\iota_0)} \Mon_{\bE_\infty}(\mS) \to \Grp_{\bE_\infty}(\mS).$$	

\end{definition}

For the next definition we use \cref{ahoo} and \cref{hhoo}:
\begin{definition}
The Picard spectrum functor $\mathrm{pic}$ is the following composition
$$ \Sp \simeq \Mon_{\bE_\infty}(\Sp) \simeq  \Sp(\Mon_{\bE_\infty}(\infty\Cat)) \xrightarrow{\Sp(\Pic)} \Sp(\Grp_{\bE_\infty}(\mS)) \simeq \Grp_{\bE_\infty}(\Sp(\mS)) \simeq \Sp(\mS).$$
%induced by the Picard space functor $\Pic: \Mon_{\bE_\infty}(\infty\Cat) \to \Grp_{\bE_\infty}(\mS).$

\end{definition}

\begin{lemma}

There is a colocalization $  \Sp(\mS)\rightleftarrows \Sp: \mathrm{pic},$
where the left adjoint is the canonical embedding.

\end{lemma}

\begin{proof}
The colocalization $\mS \rightleftarrows \infty\Cat : \iota_0 $ gives rise to a colocalization $$\Mon_{\bE_\infty}(\mS) \rightleftarrows \Mon_{\bE_\infty}(\infty\Cat) : \iota_0.$$
%There is a colocalization $\Grp_{\bE_\infty}(\mS) \rightleftarrows \Mon_{\bE_\infty}(\mS) : \Pic.$
By the limit definition of spectra the composition of colocalizations $$\Grp_{\bE_\infty}(\mS) \rightleftarrows \Mon_{\bE_\infty}(\mS) \rightleftarrows \Mon_{\bE_\infty}(\infty\Cat): \Pic\circ \iota_0$$ 
gives rise to a colocalization $$ \Sp(\Grp_{\bE_\infty}(\mS)) \simeq \Grp_{\bE_\infty}(\Sp(\mS)) \simeq \Mon_{\bE_\infty}(\Sp(\mS)) \simeq \Sp(\mS)\rightleftarrows $$$$ \Sp(\Mon_{\bE_\infty}(\infty\Cat)) \simeq \Mon_{\bE_\infty}(\Sp) \simeq \Sp: \mathrm{pic}.$$
%where the right adjoint takes degreewise the Picard space.	

\end{proof}

\begin{remark}
The Picard spectrum of the Morita spectrum of $R$ of \cref{Morita} is the Brauer spectrum of \cite[§3]{MR3190610}.
In particular, $\pi_0(\mathrm{pic}(\mathrm{morita}(\mC)))$ is the Brauer group of $R.$

\end{remark}

\section{Categorical homology theories}

This section is devoted to the definition and study of categorical homology theories,
the central notion of this article.
To define categorical homology theories we develop a theory of oplax excisive and lax excisive Gray-functors, which categorify the Mayer-Vietoris excision axiom of homology.

\subsection{Oplax excision}

%\begin{remark}Let $\F:\mC \to \mD$ be a right $\mV$-linear functor and $K \in \mV.$$ \F \circ ((-)\ot K) \simeq ((-)\ot K) \circ \F.$$	\end{remark}

\begin{notation}Let $\mC$ be a reduced Gray-category that has left tensors and $\mD$ a reduced Gray-category. 
By \cite[Notation 5.27., Proposition 5.107.]{heine2024bienriched} %Theorem 5.33.
the reduced left pseudo-Gray-category ${\Fun\wedge}(\mC,\mD)$ of reduced right Gray-functors underlies a reduced pseudo-Gray-category that admits right tensors.

%Let $\mC$ be a small Gray-category that admits right tensors and $\mD$ a presentable Gray-category. By ??? there is a right presentable Gray-category ${\wedge\Fun}(\mC,\mD)$ of left Gray-functors.

\end{notation}

\begin{remark}
Moreover if $\mD$ admits left tensors, by \cite[Proposition 5.30.]{heine2024bienriched} the reduced pseudo-Gray-category ${\Fun\wedge}(\mC,\mD)$ also admits left tensors, which are formed object-wise.

\end{remark}

\begin{definition}Let $\mC, \mD$ be reduced right Gray-categories. %such that $\mC$ admits suspensions and $\mD$ admits endomorphisms.
A reduced right Gray-functor $\F: \mC \to \mD$ is oplax excisive if for every oplax pushout square
\[
\begin{tikzcd}
X \ar{r}{} \ar{d}[swap]{} & 0 \ar[double]{dl}{} \ar{d}{} \\
0 \ar{r}[swap]{} & Y
\end{tikzcd}
\]
in $\mC$ the induced lax square 
\[
\begin{tikzcd}
H(X) \ar{r}{} \ar{d}[swap]{} & 0 \ar[double]{dl}{} \ar{d}{} \\
0 \ar{r}[swap]{} & H(Y)
\end{tikzcd}
\]
in $\mD$ is an oplax pullback square.

%for every $X \in \mC$ the canonical morphism is an equivalence: $$\F(X)\to \Omega(\F(\Sigma(X))).$$

\end{definition}

\begin{definition}
Let $\mC, \mD$ be reduced left Gray-categories. A reduced left Gray-functor $\F: \mC \to \mD$ is lax excisive if the reduced right Gray-functor $\F^\co: \mC^\co \to \mD^\co$ is oplax excisive.

\end{definition}

\begin{definition}
Let $\mC, \mD$ be reduced Gray-categories.  

\begin{enumerate}
\item A reduced Gray-functor $\F: \mC \to \mD$ is oplax excisive if its underlying right Gray-functor is oplax excisive.

\item A reduced Gray-functor $\F: \mC \to \mD$ is lax excisive if its underlying left Gray-functor is lax excisive.

\item A reduced Gray-functor $\F: \mC \to \mD$ is excisive if it is lax and oplax excisive.	

\end{enumerate}

\end{definition}

\begin{notation}

Let $\mC, \mD$ be reduced right Gray-categories. 
Let $${\Oplax\Exc\wedge}(\mC,\mD) \subset {\Fun\wedge}(\mC,\mD)$$
be the full subcategory of oplax exicisive right Gray-functors.

Let $\mC, \mD$ be reduced left Gray-categories. 
Let $${\wedge \mathrm{Lax} \Exc}(\mC,\mD) \subset {\wedge\Fun}(\mC,\mD)$$
be the full subcategory of lax exicisive left Gray-functors.

\end{notation}
\begin{notation}

Let $\mC, \mD$ be reduced Gray-categories. 
Let $${\wedge\Lax\Exc\wedge}(\mC,\mD), \ {\wedge\Oplax\Exc\wedge}(\mC,\mD),\ {\wedge\Exc\wedge}(\mC,\mD) \subset {\wedge\Fun\wedge}(\mC,\mD)$$
be the full subcategories of lax excisive, oplax exicisive, excisive reduced Gray-functors.

\end{notation}

%\begin{definition}Let $\mC, \mD$ be reduced Gray-categories.A reduced Gray-functor $\F:\mC \to \mD$ is (oplax) lax excisive if its underlying reduced (left) right Gray-functor is (oplax) lax excisive.	\end{definition}

%\begin{definition}Let $\mC, \mD$ be reduced Gray-categories such that $\mC$ admits double cosuspensions and $\mD$ admits double coendomorphisms.A reduced left Gray-functor $\F: \mC \to \mD$ is co-lax excisive if the right Gray-functor $\F^\co: \mC^\co \to \mD^\co$ is excisive.\end{definition}

%\begin{notation}Let $\mC, \mD$ be reduced Gray-categories. % such that $\mC$ admits double suspensions and $\mD$ admits double endomorphisms.Let $${\wedge\Exc\wedge}(\mC,\mD) \subset {\wedge\Fun\wedge}(\mC,\mD)$$be the full subcategory of reduced and lax exicisive Gray-functors.\end{notation}

\begin{lemma}\label{coext}Let $\mD$ be a reduced Gray-category and $\E\in \Sp^\co(\mD).$  The right Gray-functor $$\L\Mor_{\Sp^\co(\mD)}(-, \E): \Sp^\co(\mD)^\circ \to \infty\Cat_*$$ is oplax excisive. 
\end{lemma}
\begin{proof}

The right adjoint right Gray-functor $\L\Mor_{\Sp^\co(\mD)}(-, \E): \Sp^\co(\mD)^\circ \xrightarrow{} \infty\Cat_*$ preserves endomorphisms. So for every $Z \in \Sp^\co(\mD) $ the canonical functor $$ \L\Mor_{\Sp^\co(\mD)}(\Sigma'(Z), \E) \to \Omega(\L\Mor_{\Sp^\co(\mD)}(Z, \E))$$
is an equivalence. Since $\Sp^\co(\mD)$ is lax quasi-stable by \cref{crstab}, the canonical functor $$ \L\Mor_{\Sp^\co(\mD)}(Z, \E) \to \Omega(\L\Mor_{\Sp^\co(\mD)}(\Omega'(Z), \E))$$ is an equivalence. Note that the coendomorphisms $\Omega'$ of $\Sp^\co(\mD) $ are the suspension of $\Sp^\co(\mD)^\circ.$

\end{proof}

\begin{remark}\label{Homt}
Let $\mB, \mC, \mD, \mE$ be reduced right Gray-categories  and $\F: \mC \to \mD$ a reduced and oplax excisive right Gray-functor, $\phi: \mB \to \mC$ a reduced right Gray-functor that preserves suspensions and $\rho: \mD \to \mE$ a reduced right Gray-functor that preserves endomorphisms. Then the reduced right Gray-functor $\rho \circ \F\circ \phi: \mB \to \mE$ is oplax excisive.

\end{remark}

\begin{remark}
Let  $\mC$ be a reduced right Gray-category that admits suspensions and $\mD$ a reduced right Gray-category that admits small filtered colimits and endomorphisms such that both commute with each other. By the very definition of oplax excision the full subcategory ${\Op\lax\Exc\wedge}(\mC,\mD)$
is  closed in ${\Fun\wedge}(\mC, \mD) $ under small filtered colimits.

\end{remark}

\begin{proposition}\label{impol}Let $\mC, \mD$ be reduced pseudo-Gray-categories.

\begin{enumerate}
\item If $\mC,\mD$ admit endomorphisms, there is a transformation of endofunctors of ${\wedge\Fun\wedge}(\mC,\mD):$
$$\F \mapsto \F \circ \Omega_\mC \to \Omega_\mD \circ \F.$$

\item  If $\mC,\mD$ have coendomorphisms, there is a transformation of endofunctors of ${\wedge\Fun\wedge}(\mC,\mD):$
$$\F \mapsto \F \circ \Omega'_\mC \to \Omega'_\mD \circ \F.$$

\item If $\mC,\mD$ admit suspensions, there is a transformation of endofunctors of ${\wedge\Fun\wedge}(\mC,\mD):$
$$\F \mapsto \Sigma_\mD \circ \F \to \F \circ \Sigma_\mC. $$

\item If $\mC,\mD$ have cosuspensions, there is a transformation of endofunctors of ${\wedge\Fun\wedge}(\mC,\mD):$
$$\F \mapsto \Sigma'_\mD \circ \F \to \F \circ \Sigma'_\mC. $$

