\begin{proposition}\label{lifti}

\begin{enumerate}\item 
Let $\mC$ be a reduced pseudo-Gray-category that admits endomorphisms and
$\mD$ a reduced pseudo-Gray-category that admits suspensions.
The reduced Gray-functor $\Omega^\infty: \Sp(\mC) \to \mC $ induces an equivalence:
\begin{equation*}\label{ravelo}
{\wedge\Oplax\Exc\wedge}(\mD, \Sp(\mC)) \to {\wedge\Oplax\Exc\wedge}(\mD, \mC).	
\end{equation*}
The inverse sends $\F$ to $\{\F \circ \Sigma^n, \F \circ \Sigma^n \simeq \Omega \circ \F \circ \Sigma^{n+1} \}.$

\item 
Let $\mC$ be a reduced pseudo-Gray-category that admits coendomorphisms and
$\mD$ a reduced pseudo-Gray-category that admits cosuspensions.
The reduced Gray-functor $\Omega^\infty: \Sp^\co(\mC) \to \mC $ induces an equivalence:
\begin{equation*}\label{ravelo2}
{\wedge\Lax\Exc\wedge}(\mD, \Sp^\co(\mC)) \to {\wedge\Lax\Exc\wedge}(\mD, \mC).	
\end{equation*}
The inverse sends $\F$ to $\{\F \circ \Sigma'^n, \F \circ \Sigma'^n \simeq \Omega' \circ \F \circ \Sigma'^{n+1} \}.$

\item Let $\mC$ be a reduced pseudo-Gray-category that admits endomorphisms and coendomorphisms and $\mD$ a reduced pseudo-Gray-category that admits suspensions and cosuspensions.The reduced Gray-functor $\Omega^\infty: \Sp^\co(\Sp(\mC)) \simeq \Sp(\Sp^\co(\mC)) \to \mC $ induces an equivalence:
\begin{equation*}\label{ravelo3}
{\wedge\Exc\wedge}(\mD, \Sp^\co(\Sp(\mC))) \to {\wedge\Exc\wedge}(\mD, \mC).\end{equation*}

%The inverse sends $\F$ to $\{\F \circ \Sigma^n, \F \circ \Sigma^n \simeq \Omega \circ \F \circ \Sigma^{n+1} \}.$

\end{enumerate}

\end{proposition}
\begin{proof}

(1): By \cref{Homt} the Gray-functors $\Omega_*, \Sigma^*: {\wedge\Fun\wedge}(\mD, \mC) \to {\wedge\Fun\wedge}(\mD, \mC)$ postcomposing with $\Omega:\mC \to \mC$ and precomposing with $\Sigma: \mD \to \mD $ restrict to functors $\Omega_*, \Sigma^*: {\wedge\Oplax\Exc\wedge}(\mD, \mC) \to {\wedge\Oplax\Exc\wedge}(\mD, \mC).$
By \cref{impol} there is a natural transformation $ \sigma: \id \to \Omega_* \circ \Sigma^* \simeq \Sigma* \circ \Omega_*$ of endofunctors of ${\wedge\Fun\wedge}(\mD, \mC)$
whose component at any $\F \in {\wedge\Fun\wedge}(\mD, \mC)$ is the canonical morphism $\F \to \Omega \circ \F \circ \Sigma.$ The latter is an equivalence if $\F \in {\wedge\Oplax\Exc\wedge}(\mD, \mC)$. Hence the natural transformation $\sigma$ restricts to an equivalence $\id \to \Omega_* \circ \Sigma^* \simeq \Sigma^* \circ \Omega_*$ of endofunctors of ${\wedge\Oplax\Exc\wedge}(\mD, \mC)$.
So the functors $\Omega_*, \Sigma^*: {\wedge\Oplax\Exc\wedge}(\mD, \mC) \to {\wedge\Oplax\Exc\wedge}(\mD, \mC)$ are inverse to each other.
The functor of the statement factors as
$${\wedge\Oplax\Exc\wedge}(\mD, \Sp(\mC)) \simeq \lim(... \xrightarrow{\Omega_*} {\wedge\Oplax\Exc\wedge}(\mD, \mC)) \xrightarrow{\gamma} {\wedge\Oplax\Exc\wedge}(\mD, \mC),$$
where $\gamma$ is the projection to the rightmost object.
Since $\Omega_*: {\wedge\Oplax\Exc\wedge}(\mD, \mC) \to {\wedge\Oplax\Exc\wedge}(\mD, \mC)$ is an equivalence, $\gamma$ is an equivalence.
(2) follows from (1) by replacing $\mC$ by $\mC^\co.$

(3): By the description of inverse the equivalence of (1) restricts to an equivalence $${\wedge\Exc\wedge}(\mD, \Sp(\mC)) \to {\wedge\Exc\wedge}(\mD, \mC)$$
and the equivalence of (2) restricts to an equivalence ${\wedge\Exc\wedge}(\mD, \Sp^\co(\mC)) \to {\wedge\Exc\wedge}(\mD, \mC)$. So the latter gives an equivalence ${\wedge\Exc\wedge}(\mD, \Sp^\co(\Sp(\mC))) \to {\wedge\Exc\wedge}(\mD, \Sp(\mC))$ since $\Sp(\mC)$ admits coendomorphisms if $\mC$ does. 
The functor of (3) factors as $${\wedge\Exc\wedge}(\mD, \Sp^\co(\Sp(\mC))) \to {\wedge\Exc\wedge}(\mD, \Sp(\mC)) \to {\wedge\Exc\wedge}(\mD, \mC).$$

\end{proof}

\begin{lemma}\label{collif}
Let $\mC$ be a reduced pseudo-Gray-category that admits endomorphisms and
$\mD$ a reduced pseudo-Gray-category that admits suspensions.

An oplax excisive reduced Gray-functor $\F:\mD \to \Sp(\mC)$ preserves small colimits and left and right tensors if the oplax excisive reduced Gray-functor $\Omega^\infty \circ \F: \mD \to \mC$ 
preserves small colimits and left and right tensors.	

\end{lemma}

\begin{proof}

Let $K \in \infty\Cat_*, X \in \mC$. The canonical morphism $\Omega^\infty\Sigma^n(K \wedge \F(X)) \to \Omega^\infty\Sigma^n(\F(K \wedge X)) $ 
identifies with the morphism
$$   \colim_{\bk \geq 0} \Omega^\bk(K \wedge \Omega^\infty(\F(\Sigma^{n+\bk}(X)))) \to 
\colim_{\bk \geq 0} \Omega^\bk(\Omega^\infty(\F(K \wedge\Sigma^{n+\bk}(X)))) \simeq $$$$ \colim_{\bk \geq 0} \Omega^\bk(\Omega^\infty(\F(\Sigma^{n+\bk}(K \wedge X)))) \simeq \Omega^\infty(\F(\Sigma^n(K \wedge X))).$$ 
The case of right tensors is similar.
Let $\mJ$ be a category and $\phi: \mJ \to \mD$ a functor.
The canonical morphism $\Omega^\infty\Sigma^n(\colim(\F \circ \phi)) \to \Omega^\infty\Sigma^n(\F(\colim(\phi)) $ 
identifies with the morphism
$$ \colim_{\bk \geq 0} \Omega^\bk(\colim(\Omega^\infty \circ \F \circ \Sigma^{n+\bk} \circ \phi))  \to 
\colim_{\bk \geq 0} \Omega^\bk(\Omega^\infty(\F(\colim(\Sigma^{n+\bk} \circ \phi)))) $$$$ \simeq \colim_{\bk \geq 0} \Omega^\bk(\Omega^\infty(\F(\Sigma^{n+\bk}(\colim(\phi))))) \simeq \Omega^\infty(\F(\Sigma^n(\colim(\phi)))).$$ 

\end{proof}

In the following we construct and study excisive approximations.

\begin{notation}

Let $\mC,\mD$ be reduced Gray-categories such that $\mC$ admits suspensions and $\mD$ admits endomorphisms and sequential colimits and endomorphisms commute with sequential colimits.
Let $\F:\mC \to \mD$ be a reduced Gray-functor.
For every $\ell \geq 0$ the unit $\id \to \Omega\circ \Sigma$ and the canonical map $\Sigma \circ \F \to \F\circ \Sigma$ of reduced Gray-functors $\mC \to \mD$ give rise to a map of reduced Gray-functors $\mC \to \mD$:
$$ \Omega^\ell \circ \F \circ \Sigma^\ell \to \Omega^\ell \circ \Omega \circ \Sigma \circ \F \circ \Sigma^\ell \to
\Omega^{\ell} \circ \Omega \circ \F \circ \Sigma \circ \Sigma^{\ell} = \Omega^{\ell+1} \circ \F \circ \Sigma^{\ell+1}.$$	

Let $$ L(\F):= \colim(\F \to \Omega \circ \F \circ \Sigma \to ... \to \Omega^\ell \circ \F \circ \Sigma^\ell \to \Omega^{\ell+1} \circ \F \circ \Sigma^{\ell+1}\to ...)$$ be the sequential colimit of Gray-functors $\mC \to \mD$
and $\alpha_\F: \F \to L(\F)$ the map to the zero-th term.

\end{notation}

\begin{remark}
%For any reduced Gray-functor $\F: \mC \to \mD$ t
The canonical map $ L(\F) \to \Omega \circ L(\F) \circ \Sigma$ identifies with the canonical equivalence
$$ \colim_{\ell \geq 0}(\Omega^\ell \circ \F \circ \Sigma^\ell) \to \colim_{\ell \geq 0}(\Omega^{\ell+1} \circ \F \circ \Sigma^{\ell+1})\simeq \colim_{\ell \geq 1}(\Omega^\ell \circ \F \circ \Sigma^\ell).$$
Hence $L(\F)$ is reduced and oplax excisive.	
So sending $\F$ to $L(\F)$ defines a functor ${\wedge\Fun\wedge}(\mC,\mD) \to {\wedge\Oplax\Exc\wedge}(\mC,\mD)$ and the canonical map $\F \to L(\F)$ defines a natural transformation $\alpha: \id \to L$.

If $\F:\mC \to \mD$ is lax excisive, also $ \Omega^\ell \circ \F \circ \Sigma^\ell$ is lax excisive for every $\ell \geq 0$ by \cref{Homt} . So if sequential colimits in $\mD$ commute with coendomorphisms, the sequential colimit $L(\F)$ is lax excisive and so excisive.

\end{remark}

\begin{proposition}\label{excista}
Let $\mC,\mD$ be reduced Gray-categories such that $\mC$ admits suspensions and $\mD$ admits endomorphisms and sequential colimits such that endomorphisms commute with sequential colimits. Let $\F:\mC \to \mD$ be a reduced Gray-functor.
The map $\alpha_\F: \F \to L(\F)$ induces for every reduced oplax excisive Gray-functor $\G:\mC \to \mD$ an equivalence $$ {\wedge\Fun\wedge}(\mC,\mD)(L(\F),\G) \to {\wedge\Fun\wedge}(\mC,\mD)(\F,\G).$$	

In other words, the natural transformation $\alpha: \id \to L$ exhibits $L$ as left adjoint of the embedding $$ {\wedge\Oplax\Exc\wedge}(\mC,\mD) \subset {\wedge\Fun\wedge}(\mC,\mD).$$

If sequential colimits in $\mD$ commute with coendomorphisms, the localization
$L:  {\wedge\Fun\wedge}(\mC,\mD) \rightleftarrows  {\wedge\Oplax\Exc\wedge}(\mC,\mD)$
restricts to a localization
$L:  {\wedge\Oplax\Exc\wedge}(\mC,\mD) \rightleftarrows  {\wedge\Exc\wedge}(\mC,\mD)$.

\end{proposition}

\begin{proof}

If $\F$ is oplax excisive, the canonical map $\F \to \Omega^\ell \circ \F \circ \Sigma^\ell$
is an equivalence so that all maps under $\F$ in the sequential diagram for $L(\F)$ are equivalences. Hence the map $\alpha_\F: \F \to L(\F)$ is an equivalence. 
% so that $\xi_{L(\F)}$ is an equivalence by what we have shown. 
By \cite[Proposition 5.2.7.4]{lurie.HTT} it suffices to show that the map $L(\alpha_\F): L(\F) \to L(L(\F))$ is an equivalence. It identifies with the following identity:
$$ \colim_{\ell \geq 0}(\Omega^\ell \circ \F \circ \Sigma^\ell) \to \colim_{\ell \geq 0}(\Omega^\ell \circ \colim_{\bk \geq 0}(\Omega^\bk \circ \F \circ \Sigma^\bk) \circ \Sigma^\ell) \simeq$$$$ \colim_{\ell,\bk \geq 0}(\Omega^{\ell+\bk} \circ \F \circ \Sigma^{\ell+\bk}) \simeq \colim_{\ell \geq 0}(\Omega^{2\ell} \circ \F \circ \Sigma^{2\ell}) \simeq \colim_{\ell \geq 0}(\Omega^\ell \circ \F \circ \Sigma^\ell).$$
The second equivalence holds since sequential diagrams are filtered and so sifted and the last equivalence holds by cofinality.
%Consequently, $L$ induces a functor $L: {\wedge\Fun\wedge}(\mC,\mD) \to {\wedge\Exc\wedge}(\mC,\mD)$.

%$\xi_{L(\F)}$.

\end{proof}	

\begin{corollary}\label{excis}
Let $\mC$ be a Gray-category that admits suspensions and endomorphisms and $n \geq 0$. 
The unit $\Sigma^n \to \Omega^\infty\Sigma^\infty\Sigma^n$
induces for every reduced oplax excisive Gray-functor $\G:\mC \to \mD$ an equivalence $$ {\wedge\Fun\wedge}(\mC,\mD)(\Omega^\infty\Sigma^\infty\Sigma^n,\G) \to {\wedge\Fun\wedge}(\mC,\mD)(\Sigma^n,\G).$$	
The unit $\Omega^n \to \Omega^n\Omega^\infty\Sigma^\infty$
induces for every reduced oplax excisive Gray-functor $\G:\mC \to \mD$ an equivalence $$ {\wedge\Fun\wedge}(\mC,\mD)(\Omega^n\Omega^\infty\Sigma^\infty,\G) \to {\wedge\Fun\wedge}(\mC,\mD)(\Omega^n,\G).$$		

\end{corollary}

\begin{lemma}Let $\mC,\mD$ be reduced Gray-categories such that $\mD$ admits left and right tensors.

\begin{enumerate}

\item A reduced Gray-functor $\mC \to \mD$ is oplax excisive if and only if it is local with respect to the canonical maps $$((-)\wedge Y\wedge(-)) \circ \Sigma \circ \Omega \circ \Mor_\mC(X,-) \to ((-)\wedge Y\wedge(-)) \circ \Mor_\mC(X,-)$$ in $ {\wedge\Fun\wedge}(\mC,\mD)$ for $X \in \mC$ and $Y \in \mD.$

\item A reduced Gray-functor $\mC \to \mD$ is lax excisive if and only if it is local with respect to the canonical maps $$((-)\wedge Y\wedge(-)) \circ \Sigma' \circ \Omega' \circ \Mor_\mC(X,-) \to ((-)\wedge Y\wedge(-)) \circ \Mor_\mC(X,-)$$ in $ {\wedge\Fun\wedge}(\mC,\mD)$ for $X \in \mC$ and $Y \in \mD.$
\end{enumerate}

\end{lemma}

\begin{proof}

(1) is dual to (2). We prove (1). There is a canonical equivalence $$\Omega \circ \Mor_\mC(X,-) \simeq 
\Mor_\mC(X,-) \circ \Omega \simeq \Mor_\mC(\Sigma(X),-)$$ of reduced Gray-functors 
$\mC \to \infty\Cat_* \boxplus \infty\Cat_*$.
The first equivalence holds since by \cref{impol} right adjoint reduced Gray-functors commute with $\Omega.$ The second equivalence holds since $\Sigma$ is left adjojnt to $\Omega$ as reduced Gray-functors. 
For every reduced Gray-functor $\F:\mC \to \mD$ the induced map $$ {\wedge\Fun\wedge}(\mC,\mD)(((-)\wedge Y\wedge(-)) \circ \Mor_\mC(X,-) ,\F) \to {\wedge\Fun\wedge}(\mC,\mD)(((-)\wedge Y\wedge(-)) \circ \Sigma \circ \Mor_\mC(\Sigma(X),-) ,\F) $$ identifies by adjointness with the map
$$ {\wedge\Fun\wedge}(\mC,\infty\Cat_*\boxplus \infty\Cat_*)(\Mor_{\mC}(X,-), \Mor_{\mD}(Y,-) \circ \F)\to$$$$ {\wedge\Fun\wedge}(\mC,\infty\Cat_*\boxplus \infty\Cat_*)(\Mor_{\mC}(\Sigma(X),-), \Omega \circ \Mor_{\mD}(Y,-) \circ \F)$$
which identifies by the enriched Yoneda-lemma with the map
$$ \Mor_\mD(Y, \F(X)) \to  \Mor_\mD(Y, \Omega(\F(\Sigma(X)))) \simeq \Omega(\Mor_\mD(Y, \F(\Sigma(X))))$$  induced by the canonical morphism
$\F(X) \to \Omega(\F(\Sigma(X))).$

\end{proof}

