\begin{proposition}\label{appro}
Let $\mC$ be a small reduced right Gray-category that admits suspensions,	
$\mD$ a reduced right presentable Gray-category and $X \in \infty\Cat_*.$
Let $\F \in {\Fun\wedge}(\mC,\mD) $ and $\F'$ the oplax excisive appoximation of
$\F$.
The canonical map $$ \colim_{n \geq 0} \Omega^n(\F(X \wedge S^n))\to\colim_{n \geq 0} \Omega^n(\F'(X \wedge S^n))\simeq \F'(X) $$
is an equivalence.

\end{proposition}

\begin{proof}

The reduced left Gray-functor $$\nu_X: {\Fun\wedge}(\mC,\mD) \to \Pre\Sp(\mD)$$
preserves local objects and local equivalences by \cref{locpre}, and so sends the universal local equivalence $\F \to \F'$ to a local equivalence $\F(X \wedge S^\bullet) \to \F'(X \wedge S^\bullet)$ that corresponds to an equivalence $$ L(\F(X \wedge S^\bullet))\simeq \F'(X \wedge S^\bullet) $$ of spectra in $\mD,$ where $L$ is the spectrification.
Hence by \cref{spectri} evaluating at the zeroth term of a prespectrum in $\mD$ we obtain the following equivalence
in $\mD:$ 
$$\F'(X) \simeq \Omega^\infty(L(\F(X \wedge S^\bullet))) \simeq \colim_{n\geq 0} \Omega^n(\F(X \wedge S^n)).$$	

\end{proof}

\begin{corollary}Let $\mD$ be a reduced right presentable Gray-category.

\begin{enumerate}
\item Let $\mC$ be a reduced right Gray-category that admits suspensions, endomorphism and sequential colimits and $\F:  \mC \to \mD$ a reduced right Gray-functor that preserves sequential colimits and endomorphisms. The unit $\F \to \F \circ \Omega^\infty\circ  \Sigma^\infty$
exhibits $ \F \circ \Omega^\infty\circ  \Sigma^\infty$ as the oplax excisive approximation of
$\F.$

\item Let $\mC$ be a reduced right Gray-category that admits suspensions and $\F:  \mC \to \mD$ a reduced right Gray-functor that preserves suspensions. The unit $\F \to \Omega^\infty\circ  \Sigma^\infty \circ \F $ exhibits $ \Omega^\infty\circ  \Sigma^\infty \circ \F $ as the oplax excisive approximation of $\F.$

\end{enumerate}	

\end{corollary}

\begin{proof}
(1) : Let $\F'$ be the oplax excisive approximation of $\F: \mC \to \mD$.
By \cref{Homt} the right Gray-functor $ \F \circ \Omega^\infty\circ  \Sigma^\infty$ is excisive.
So there is a canonical morphism $\F'  \to  \F \circ \Omega^\infty\circ  \Sigma^\infty$
that induces at any $X \in \mC$ the canonical functor
$$\colim_{\ell \geq 0} \Omega^\ell(\F(X \wedge S^\ell)) \simeq \F(\colim_{\ell \geq 0} \Omega^\ell(X \wedge S^\ell))  \to \F(\Omega^\infty( \Sigma^\infty(X)))$$
induced by the functor 
$$\colim_{\ell \geq 0} \Omega^\ell(X \wedge S^\ell)  \to  \Omega^\infty( \Sigma^\infty(X)).$$
The latter is an equivalence by \cref{infsus}.

(2): Let $\F'$ be the oplax excisive approximation of $\F: \mC \to \mD$.
By \cref{Homt} the right Gray-functor $ \Omega^\infty\circ  \Sigma^\infty \circ \F $ is excisive.
So there is a canonical morphism $\F'  \to \Omega^\infty\circ  \Sigma^\infty \circ \F $
that induces at any $X \in \mC $ the canonical functor
$$\colim_{\ell \\geq 0} \Omega^\ell(\F(X \wedge S^\ell)) \simeq \colim_{\ell \\geq 0} \Omega^\ell(\F(X) \wedge S^\ell)  \to \Omega^\infty( \Sigma^\infty(\F(X)).$$
The latter is an equivalence by \cref{infsus}.

\end{proof}

\begin{corollary}\label{excend}Let $\mB$ be a reduced right Gray-category that admits suspensions,
$\mC,\mD$ reduced presentable Gray-categories and $\F: \mC \to \mD$ a reduced Gray-functor.
Assume that in $\mD$ sequential colimits commute with finite limits and left cotensors with finite $\infty$-categories with distinguished object.
The reduced left Gray-functor $$\F_!: {\Oplax\Exc\wedge}(\mB,\mC) \to {\Oplax\Exc\wedge}(\mB,\mD)$$
preserves finite limits and left cotensors with finite $\infty$-categories with distinguished object.

\end{corollary}

\begin{proof}

By definition of excisiveness the full subcategory ${\Oplax\Exc\wedge}(\mB,\mD) \subset {\Fun\wedge}(\mB,\mD)$
is closed under left cotensors and small limits. 
%The full subcategory ${\Fil\wedge}(\infty\Cat_*,\mD) \subset {\Fun\wedge}(\infty\Cat_*,\mD)$is closed under left cotensors with finite $\infty$-categories with distinguished object and finite limitsbecause filtered colimits commute with finite limits and left cotensors with finite $\infty$-categories with distinguished object. 
Hence for any $X \in \mB$ the left Gray-functor $\nu^X: {\Oplax\Exc\wedge}(\mB,\mD) \to \Sp(\mD) , \F \mapsto \F(X \wedge S^\bullet)$ preserves small limits and left cotensors. % since $\mD$ is compactly generated.
So it is enough to see that for every $ X \in \mB$
the reduced left Gray-functor $$ {\Oplax\Exc\wedge}(\mB, \mC) \xrightarrow{\F_!} {\Oplax\Exc\wedge}(\mB, \mD) \xrightarrow{\nu^X} \Sp(\mD)$$ preserves finite limits and left cotensors with finite $\infty$-categories with distinguished object.

By \cref{appro} the latter factors as reduced left Gray-functors
$$ 	{\Oplax\Exc\wedge}(\mB,\mC) \xrightarrow{\rho} %\Fil{\Exc\wedge}(\infty\Cat_*,\mC)^\bN \xrightarrow{\colim_{n \geq 0 } \Omega^n \circ \nu^{\Sigma^n(X)} }  
\Sp(\mD)^{\bN} \xrightarrow{\colim} \Sp(\mD),$$
where $\rho$ induces in degree $n \geq 0$ the reduced left Gray-functor $ \Omega^n \circ \nu^{\Sigma^n(X)}$ and $\colim$ assigns the sequential colimit.
So the result follows from the fact that in $\Sp(\mD)$ sequential colimits commute with finite limits and left cotensors with finite $\infty$-categories if this holds in $\mD$.


\end{proof}

