\section{Categorical homology}

In this section we prove several key results about categorical homology that demonstrate
that categorical homology often behaves like classical homology.

%Among these results are a categorified Dold-Thom theorem and 

%\subsection{Directed homology and strict symmetric monoidal $\infty$-categories}

\subsection{A categorical Dold-Thom theorem}

In this section we prove a categorified Dold-Thom theorem (\cref{redfree}).

\begin{notation}

Let $ \C\mon:=\Mon_{\bE_\infty}(\Set)$ be the category of commutative monoids.

\end{notation}

The canonical embedding $\Set \subset \mS$ gives an embedding $ \C\mon=\Mon_{\bE_\infty}(\Set) \subset \Mon_{\bE_\infty}(\mS).$

\begin{definition}
The Eilenberg-MacLane categorical spectrum functor $H$ is the following composition of embeddings,
where $B^\infty$ is by \cref{symsp}:
$$\C\mon= \Mon_{\bE_\infty}(\Set) \subset \Mon_{\bE_\infty}(\mS) \xrightarrow{B^\infty} \Sp.$$

\end{definition}

%\begin{definition}The directed Eilenberg-MacLane spectrum functor is the embedding$H: \Mon_{\bE_\infty}(\mS) \subset \Mon_{\bE_\infty}(\infty\Cat) \subset \Sp.$\end{definition}The canonical left adjoint monoidal embedding $ H: \Mon_{\bE_\infty}(\mS) \subset \Sp $ factors as left adjoint monoidal functors $$\Mon_{\bE_\infty}(\mS) \to {_{\Sp}\Enr\Fun_{\Sp}^L(\Sp, \Sp)} \to \Sp.$$

\begin{definition}Let $R$ be a commutative monoid.
Oplax $R$-homology, denoted by $ H(-; R)$, is the categorical homology theory associated to the spectrum $H(R).$	
For $R=\bN$ we skip $R.$

\end{definition}

\begin{example}Let $R$ be a commutative monoid and $n \geq 0.$ The categorical $R$-homology of $S^n$ is 
$$ \Omega^\infty(H(R)\wedge  S^n) \simeq \Omega^\infty(H(R)\wedge \Sigma^n(S^0)) \simeq  \Omega^\infty(\Sigma^n(H(R)\wedge S^0)) \simeq \Omega^\infty(\Sigma^n(H(R))) \simeq B^n(R).$$


\end{example}

\subsubsection{Strict symmetric monoidal $\infty$-categories}

%\begin{notation}Let $\Sym$ be the left adjoint of the forgetful functor $\C\mon \to \Set$ and$\widetilde{\Sym} $ the left adjoint of the forgetful functor $\C\mon \to \Set_* $.\end{notation}

\begin{notation}

Let $ \C\mon^{\mathrm{free},\fin} \subset \C\mon$ be the full subcategory of commutative monoids free on a finite set.

%image of $\Fin$under the free functor $\Sym$ or equivalently, the image of $\Fin_*$under the free functor $\widetilde{\Sym}$.

\end{notation}

\begin{remark}\label{rempuy}
The category $\C\mon$ is preadditive and the full subcategory $\C\mon^{\mathrm{free},\fin} \subset \C\mon$ is generated by $\bN$ under finite products. In particular, $\C\mon^{\mathrm{free},\fin} \subset \C\mon$ is closed under finite products and therefore also preadditive.
Since $\bN$ is the tensor unit of the canonical closed symmetric monoidal structure on $\C\mon$,
the canonical closed symmetric monoidal structure on $\C\mon$ restricts to $\C\mon^{\mathrm{free},\fin}$ and every object of $\C\mon^{\mathrm{free},\fin} $ is dualizable in $ \C\mon$ with respect to the canonical closed symmetric monoidal structure. Hence taking the dual provides a symmetric monoidal equivalence 
$(\C\mon^{\mathrm{free},\fin})^\op \simeq \C\mon^{\mathrm{free},\fin}.$

\end{remark}

The category $ (\C\mon^{\mathrm{free},\fin})^\op $ is the Lawvere theory for commutative monoids.
So in view of \cref{rempuy} we make the following definition:

\begin{notation}

Let $\mC$ be a category that admits finite products.
The category of strict commutative monoid objects in $\mC$ is the full subcategory $\C\mon(\mC) \subset \Fun(\C\mon^{\mathrm{free},\fin} ,\mC)$ of functors $\C\mon^{\mathrm{free},\fin} \to \mC$ preserving finite products.

\end{notation}

\begin{remark}\label{Preaddd}
The category $\C\mon(\mC)$ is preadditive by \cite[Corollary 2.4.]{Gepner_2015}. 
\end{remark}

\begin{notation}

The forgetful functor $\C\mon(\mC) \to \mC$ is the restriction of the functor
$$ \Fun(\C\mon^{\mathrm{free},\fin},\mC) \to \mC$$ evaluating at $\bN$.

\end{notation}

\begin{remark}\label{sift1}Let $\mC$ be a category that admits finite products
and $\mK$ a collection of categories.
If $\mC$ admits $\mK$-indexed limits, $ \C\mon(\mC)$ admits $\mK$-indexed limits and the forgetful functor $\C\mon(\mC) \to \mC$ preserves $\mK$-indexed limits because the full subcategory $ \C\mon(\mC)\subset \Fun(\C\mon^{\mathrm{free},\fin},\mC) $ is closed under $\mK$-indexed limits as $\mK$-indexed limits commute with finite products.

If $\mK$ consists of sifted categories and $\mC$ admits $\mK$-indexed colimits, $ \C\mon(\mC)$ admits $\mK$-indexed colimits and the forgetful functor $\C\mon(\mC) \to \mC$ preserves $\mK$-indexed colimits since the full subcategory $ \C\mon(\mC)\subset \Fun(\C\mon^{\mathrm{free},\fin},\mC) $ is closed under $\mK$-indexed colimits as $\mK$-indexed colimits commute with finite products as every category of $\mK$ is sifted.


\end{remark}

\begin{notation}

Let $\mC$ be a category that admits finite products.
The category of $\bE_\infty$-monoid objects in $\mC$ is the full subcategory
$\Mon_{\bE_\infty}(\mC) \subset \Fun(\Fin_* ,\mC)$ of functors $X: \Fin_* \to \mC$ 
such that for every $n \geq0$ the induced morphism $X(\{1,...,n\}_+) \to \prod_{\bi=1}^n X(\{1\}_+) $ is an equivalence.

\end{notation}

\begin{remark}\label{Preaddd2}
The category $\Mon_{\bE_\infty}(\mC)$ is preadditive by \cite[Proposition 2.3.]{Gepner_2015}. 
\end{remark}

\begin{remark}\label{sift2}

Let $\mC$ be a category that admits finite products and $\mK$ a collection of categories.
If $\mC$ admits $\mK$-indexed limits, $ \Mon_{\bE_\infty}(\mC)$ admits $\mK$-indexed limits and the forgetful functor $\Mon_{\bE_\infty}(\mC) \to \mC$ preserves $\mK$-indexed limits because the full subcategory $ \Mon_{\bE_\infty}(\mC) \subset \Fun(\Fin_*,\mC) $ is closed under $\mK$-indexed limits as $\mK$-indexed limits commute with finite products.

If $\mK$ consists of sifted categories and $\mC$ admits $\mK$-indexed colimits, $ \Mon_{\bE_\infty}(\mC)$ admits $\mK$-indexed colimits and the forgetful functor $\Mon_{\bE_\infty}(\mC) \to \mC$ preserves $\mK$-indexed colimits since the full subcategory $ \Mon_{\bE_\infty}(\mC)\subset \Fun(\Fin_*,\mC) $ is closed under $\mK$-indexed colimits as $\mK$-indexed colimits commute with finite products as every category of $\mK$ is sifted.


%Let $\mC$ be a category that admits finite products.
%If $\mC$ admits small limits (small sifted colimits), then $ \Mon_{\bE_\infty}(\mC)$ admits small limits (small sifted colimits) and the forgetful functor $\Mon_{\bE_\infty}(\mC) \to \mC$ preserves small limits (small sifted colimits) becausethe full subcategory $ \Mon_{\bE_\infty}(\mC)\subset \Fun(\Fin_*,\mC) $ is closed under small limits (small sifted colimits) as small limits and small sifted colimits commute with finite products.

\end{remark}

\begin{remark}\label{locquip}

Let $\mC$ be a $\kappa$-compactly generated category for some regular cardinal $\kappa.$
An object of $ \Fun(\C\mon^{\mathrm{free},\fin},\mC)$ belongs to $\C\mon(\mC)$
if and only if it is local with respect to the set of morphisms
$\coprod_{\bi=1}^n \C\mon^{\mathrm{free},\fin}(\bN,-) \ot Z  \to  \C\mon^{\mathrm{free},\fin}(\bN^{\times n},-) \ot Z $
for every $Z \in \mC^\kappa$ if and only if it is local with respect to the set of morphisms
$\coprod_{\ell=1}^\bk \C\mon^{\mathrm{free},\fin}(\bN^{\times n_\ell},-) \ot Z  \to  \C\mon^{\mathrm{free},\fin}(\bN^{\times{n_1 + ... + n_\bk}},-) \ot Z $
for every $Z \in \mC^\kappa$ and $\bk, n_1, ..., n_\bk \geq 0$.
Thus $\C\mon(\mC) \subset  \Fun(\C\mon^{\mathrm{free},\fin},\mC)$ is an accessible localization.

Similarly, an object of $ \Fun(\Fin_*,\mC)$ belongs to $\Mon_{\bE_\infty}(\mC)$
if and only if it is local with respect to the set of morphisms
$\coprod_{\bi=1}^n \Fin_*(\{1\}_+) \ot Z  \to \Fin_*(\{1,...,n\}_+) \ot Z $
for every $Z \in \mC^\kappa$ if and only if it is local with respect to the set of morphisms
$\coprod_{\ell=1}^\bk \Fin_*(\{1,..., n_\ell\},-) \ot Z  \to  \Fin_*(\{1,...,n_1 + ... + n_\bk\},-) \ot Z $
for every $Z \in \mC^\kappa$ and $\bk, n_1, ..., n_\bk \geq 0$.
Thus $\Mon_{\bE_\infty}(\mC) \subset   \Fun(\Fin_*,\mC)$ is an accessible localization.

\end{remark}

\begin{notation}\label{heuty}
Let $\mC$ be a presentable category. By \cref{locquip} the full subcategory $\C\mon(\mC) \subset \Fun(\C\mon^{\mathrm{free},\fin},\mC)$ is an accessible localization.
The functor $ \Fun(\C\mon^{\mathrm{free},\fin},\mC) \to \mC$ evaluating at $\bN$ admits a left adjoint $\phi$ that sends an object $X $ of $\mC$ to $\C\mon^{\mathrm{free},\fin}(\bN,-) \times X.$ 
Consequently, the forgetful functor $ \C\mon(\mC) \to \mC$ admits a left adjoint $$\Sym: \mC \to \C\mon(\mC) $$ that factors as $\phi$ followed by the localization. 
We call $\Sym$ the free strict commutative monoid functor.

Since $\C\mon(\mC)$ is presentable, also the forgetful functor $ \C\mon(\mC) \to \mC_*$ admits a left adjoint $$\widetilde{\Sym}: \mC _* \to \C\mon(\mC).$$ 
We call $\widetilde{\Sym}$ the free reduced strict commutative monoid functor.

\end{notation}

\begin{remark}\label{naturalis}

%The left adjoint $\phi$ sends the final object $*$ of $\mC$ to $\C\mon^{\mathrm{free},\fin}(\bN,-) \times *.$ 
If $\mC$ is cartesian closed, the functor $(-)\times *: \mS \to \mC$ preserves finite products.
In this case $\phi(*)\simeq \C\mon^{\mathrm{free},\fin}(\bN,-) \times *$ preserves finite products and so is already local and so agrees with $\Sym(*).$ 
In particular, 
%Hence $\phi(*)\simeq  \C\mon^{\mathrm{free},\fin}(\bN,-) \times *$ is the free strict commutative monoid in $\mC$ generated by the final object whose 
the image of $\Sym(*) \simeq \widetilde{\Sym}(*\coprod *)$ in $\mC$ under the forgetful functor is $\C\mon^{\mathrm{free},\fin}(\bN,\bN) \times * \simeq \bN \times *.$

\end{remark}

\begin{remark}\label{holuk}
The category $\Set_*$ of pointed sets is a symmetric monoidal category via the smash product (\cref{smasho}).
The smash monoidal structure restricts to $\Fin_*$. By \cite[Theorem 4.6.]{Gepner_2015} the free functor $\Set_* \to \C\mon$ is symmetric monoidal. Hence the symmetric monoidal structure on $\C\mon$ restricts to
$\C\mon^{\mathrm{free},\fin}$, the image of $\Fin_*$ under the free functor, and the symmetric monoidal free functor $\Set_* \to \C\mon$ restricts to a symmetric monoidal functor $\Fin_* \to \C\mon^{\mathrm{free},\fin}. $
\end{remark}

\begin{notation}\label{restrii}

For every category $\mC$ that admits finite products the restricted free functor $\Fin_* \to \C\mon^{\mathrm{free},\fin}$ induces a functor $ \Fun(\C\mon^{\mathrm{free},\fin}, \mC) \to \Fun(\Fin_*,\mC),$ which restricts to a functor $$\nu: \C\mon(\mC) \to \Mon_{\bE_\infty}(\mC).$$	

\end{notation}

\begin{remark}
Since the category $ (\C\mon^{\mathrm{free},\fin})^\op $ is the Lawvere theory for commutative monoids, for every $(1,1)$-category $\mC$ that admits finite products the forgetful functor $\nu: \C\mon(\mC) \to \Mon_{\bE_\infty}(\mC)$	is an equivalence.

\end{remark}

\begin{remark}\label{rerul}

Let $\mC$ be a category that admits finite products.
By Remarks \cref{sift1}, \cref{sift2} the categories $\C\mon(\mC), \Mon_{\bE_\infty}(\mC)$ admit finite products and the conservative forgetful functors $\C\mon(\mC) \to \mC, \Mon_{\bE_\infty}(\mC) \to \mC $ preserve finite products. So $\nu: \C\mon(\mC)\to \Mon_{\bE_\infty}(\mC) $ preserves finite products and so also finite coproducts because
$ \C\mon(\mC), \Mon_{\bE_\infty}(\mC)$ are preadditive by Remarks \cref{Preaddd}, \cref{Preaddd2}.

If $\mC$ admits small sifted colimits, $\nu: \C\mon(\mC)\to \Mon_{\bE_\infty}(\mC) $ preserves small sifted colimits because 
$ \C\mon(\mC),  \Mon_{\bE_\infty}(\mC)$ admit small sifted colimits and the forgetful functors $ \C\mon(\mC)\to \mC, \Mon_{\bE_\infty}(\mC) \to \mC$ preserve such (Remarks \cref{sift1}, \cref{sift2}). So $\nu$ preserves small colimits as $\nu$ preserves finite coproducts.

\end{remark}

\begin{remark}

For every presentably monoidal category $\mC$ the Day-convolution monoidal structures
on $\Fun(\Fin_*,\mC), \Fun(\C\mon^{\mathrm{free},\fin},\mC)$ using \cref{holuk} are compatible with the localizations of \cref{locquip} by the description of generating local equivalences.
Hence the full subcategories $ \Mon_{\bE_\infty}(\mC) \subset \Fun(\Fin_*,\mC)$ and
$ \C\mon(\mC) \subset \Fun(\C\mon^{\mathrm{free},\fin},\mC)$ inherit monoidal structures such that
the full subcategory inclusions are lax monoidal and admit monoidal left adjoints.

\end{remark}

\begin{remark}\label{laxcomp}

%The free functor $\Set_* \to \C\mon$ sends $\{1,...,n\}_+ $ to $\bN^{\times n}$ for every $n \geq 0$ and so induces a functor $\Fin_* \to \C\mon^{\mathrm{free},\fin}$.

%By ... the free functor $\Set_* \to \C\mon$ is symmetric monoidal and so also the induced functor $\Fin_* \to \C\mon^{\mathrm{free},\fin}$ is symmetric monoidal, where $\Set_*$ carries the smash product symmetric monoidal structure that restricts to $\Fin_*.$ 

By properties of the Day-convolution \cite[Recollection 2.2.(3)]{heine2024topologicalmodelcellularmotivic} for every presentably monoidal category $\mC$ the functor $ \Fun(\C\mon^{\mathrm{free},\fin}, \mC) \to \Fun(\Fin_*,\mC)$ induced by the symmetric monoidal functor $\Fin_* \to \C\mon^{\mathrm{free},\fin}$ and the functors
$ \Fun(\C\mon^{\mathrm{free},\fin}, \mC) \to \mC, \Fun(\Fin_*,\mC) \to \mC $ evaluating at 
$\bN, \{0\}_+$, respectively, are lax monoidal and admit a monoidal left adjoint. 
Thus also the restriction $\C\mon(\mC) \to \Mon_{\bE_\infty}(\mC)$ of \cref{restrii} and the 
forgetful functors
$ \C\mon(\mC) \to \mC, \Mon_{\bE_\infty}(\mC) \to \mC $ are lax monoidal and admit a monoidal left adjoint. 

In particular, the categories $ \C\mon(\infty\Cat), \Mon_{\bE_\infty}(\infty\Cat)$ carry canonical monoidal structures induced by the Gray-tensor product on $\infty\Cat$, and
the free functors $\infty\Cat \to \C\mon(\infty\Cat), \infty\Cat \to \Mon_{\bE_\infty}(\infty\Cat),  \Mon_{\bE_\infty}(\infty\Cat) \to \C\mon(\infty\Cat)$ are monoidal and the respective right adjoints are lax monoidal. 
Thus $\C\mon(\infty\Cat),  \Mon_{\bE_\infty}(\infty\Cat)$ are presentably monoidal reduced Gray-categories and the free functors $\infty\Cat \to \C\mon(\infty\Cat), \infty\Cat \to \Mon_{\bE_\infty}(\infty\Cat),  \Mon_{\bE_\infty}(\infty\Cat) \to \C\mon(\infty\Cat)$ are left adjoint monoidal reduced Gray-functors.
\end{remark}


\begin{definition}

Let $n \geq 0$. The functor $\D^n: \mS \to \mS $ of strict $n$-th symmetric power is the unique small sifted colimits preserving extension of the functor $$ \Fin \xrightarrow{(-)^{\times n}_{\Sigma_n} } \Fin \subset \mS.$$
\end{definition}

\begin{remark}
Let $n \geq 0$.
The functor $\D^n: \mS \to \mS$ preserves the final object and so gives rise to a functor
$\mS_* \to \mS_*$ that preserves sifted colimits, and so is uniquely determined by its restriction to $\Fin_*.$
\end{remark}
\begin{construction}
Let $n \geq 0$ and $\gamma_n: \Fin_* \to \Fin_*$ the functor sending $X $ to $X^{\times n}$. % and $\nu: \Fin_* \to \Fin$ the forgetful functor.
The canonical natural transformation $* \to  \id $ of functors $\Fin_* \to \Fin_*$, which is trivially $\Sigma_n$-equivariant, and the identity of $\gamma_n $ give rise to a $\Sigma_n$-equivariant natural transformation $ \gamma_n \to \gamma_n \times \id \simeq \gamma_{n+1} $ of functors $\Fin_* \to \Fin_* $. Here we view $\gamma_{n+1}$ as $\Sigma_n$-equivariant by restriction along the inclusion $\Sigma_n \subset \Sigma_{n+1}$ that extends a bijection to the bijection preserving the maximum.
The natural transformation $ \gamma_n \to \gamma_{n+1} $ yields a natural transformation $ \D^n_{\mid\Fin_*} \to \D^{n+1}_{|\Fin_*}$ of functors $\Fin_* \to \Fin_* $ that uniquely extends to a natural transformation $ \D^n \to \D^{n+1}$ of functors $\mS_* \to \mS_* $.
%which by naturality is under $\D^n(*) \simeq * \simeq \D^{n+1}(*).$
%We obtain a natural transformation $ \D^n \to \D^{n+1}$ of functors $\mS_* \to \mS_*$.

\end{construction}

\begin{definition}
The functor $\D^\infty: \mS \to \mS $ of strict $\infty$-th symmetric power is the sequential colimit
$$ \D^0 \to \D^1 \to \D^2  \to .... $$

\end{definition}

\begin{lemma}\label{polujk}

\begin{enumerate}
\item There is a canonical equivalence $$ \Sym \simeq \coprod_{n \geq 0} \D^n$$
of endofunctors of $\mS$ under $\id \simeq \D^1. $	

\item There is a canonical equivalence $$ \widetilde{\Sym} \simeq \D^\infty$$ of endofunctors of $\mS_*$ under $\id \simeq \D^1. $	

\end{enumerate}	

\end{lemma}

\begin{proof}

(1): The functor $\Sym: \mS \to \mS$ sends the final space to $\bN$ and so sends any finite set $\{1,...,n\} $ to $\bN^{\times n}$ by preadditivity of $\C\mon(\mS).$ 
In particular, $\Sym$ sends finite sets to sets and therefore sends a finite set to the strict commutative algebra generated by it. Consequently, by \cite[Corollary 3.1.3.5.]{lurie.higheralgebra} there is a canonical equivalence $ \coprod_{n \geq 0} (-)^{\times n}_{\Sigma_n} \simeq \Sym_{\mid \Fin}$ of functors $\Fin \to \Set. $
Since the embedding $\Set \subset \mS$ preserves small coproducts, the latter equivalence uniquely extends to an equivalence $ \coprod_{n \geq 0} \D^n \simeq \Sym$ of functors $\mS \to \mS. $

(2): Every finite pointed set is isomorphic to $\{1,...,n\}_+ $ for some $n \geq 0$.
Thus the functor $\widetilde{\Sym}: \mS \to \mS$ sends finite pointed sets to sets and so sends a finite pointed set to the strict pointed commutative algebra generated by it. Consequently, by \cite[Corollary 3.1.3.5.]{lurie.higheralgebra} there is a canonical equivalence $\D^\infty_{|\Fin_*} \simeq \colim_{n \geq 0} (-)^{\times n}_{\Sigma_n} \simeq \widetilde{\Sym}_{\mid \Fin_*}$ of functors $\Fin_* \to \Set_*. $
Since the embedding $\Set_* \subset \mS_*$ preserves small filtered colimits, the latter equivalence uniquely extends to an equivalence $\D^\infty \simeq \widetilde{\Sym}$ of functors $\mS_* \to \mS_*. $

\end{proof}

\begin{notation}
Let $ n \geq 0 $. The functor $\D^n: \infty\Cat \to \infty\Cat$ of strict $n$-th symmetric power is the composition $$  \infty\Cat \subset \Fun(\Theta^\op, \mS) \xrightarrow{\D^n_*} \Fun(\Theta^\op, \mS)  \to \infty\Cat.$$

\end{notation}

\begin{notation}
Let $ n \geq 0 $. The functor $\D^\infty: \infty\Cat_* \to \infty\Cat_*$ of strict $\infty$-th symmetric power is the composition $$  \infty\Cat_* \subset \Fun(\Theta^\op, \mS)_* \simeq \Fun(\Theta^\op, \mS_*) \xrightarrow{\D^\infty_*}  \Fun(\Theta^\op, \mS_*) \simeq \Fun(\Theta^\op, \mS)_*  \to \infty\Cat_*.$$	

\end{notation}

\begin{remark}
Let $n \geq 0.$ The functor $\D^n: \infty\Cat \to \infty\Cat$ preserves the final object and so gives rise to a functor
$\D^n: \infty\Cat_* \to \infty\Cat_*$.
The definition of $\D^\infty: \infty\Cat_* \to \infty\Cat_*$ immediately implies that $\D^\infty: \infty\Cat_* \to \infty\Cat_*$ is the sequential colimit
$$ \D^\infty = \colim(\D^0 \to \D^1 \to \D^2 \to ...)$$ of functors $\D^\infty: \infty\Cat_* \to \infty\Cat_*$.

\end{remark}

\begin{remark}

Let $\mJ \subset \infty\Cat$ be a dense full subcategory that contains $\Theta.$
By density the restricted Yoneda-embedding $\infty\Cat \to \Fun(\mJ^\op, \infty\Cat)$ 
factors as the restricted Yoneda-embedding $\infty\Cat \to \Fun(\Theta^\op, \infty\Cat)$ 
followed by right-Kan extension along the embedding $\Theta^\op \subset \mJ^\op.$
Hence the restricted Yoneda-embedding $\infty\Cat \to \Fun(\Theta^\op, \infty\Cat)$ 
factors as the restricted Yoneda-embedding $\infty\Cat \to \Fun(\mJ^\op, \infty\Cat)$ 
followed by restriction along $\Theta^\op \subset \mJ^\op$ and by adjointness
the localization functor $ \Fun(\mJ^\op, \infty\Cat) \to \infty\Cat$ factors as restriction
along $\Theta^\op \subset \mJ^\op$ followed by the localization functor
$ \Fun(\Theta^\op, \infty\Cat) \to \infty\Cat.$ 

Hence the composition $$  \infty\Cat \subset \Fun(\mJ^\op, \mS) \xrightarrow{\D^n_*} \Fun(\mJ^\op, \mS)  \to \infty\Cat$$
factors as $$  \infty\Cat \subset \Fun(\mJ^\op, \mS) \xrightarrow{\D^n_*} \Fun(\mJ^\op, \mS)  \to\Fun(\Theta^\op, \mS)  \to \infty\Cat, $$
where the second last functor is restriction, and so identifies with $\D^n: \infty\Cat \to \infty\Cat.$
In other words the definition of $\D^n$ does not depend on any choice of dense full subcategory of
$\infty\Cat$ containg $\Theta.$
We could for example replace $\Theta$ by the category $\cube$ of oriented cubes in the definition of $\D^n.$
\end{remark}

\begin{lemma}\label{leoopi}

\begin{enumerate}
\item There is a canonical equivalence $$ \Sym \simeq \coprod_{n \geq 0} \D^n$$
of endofunctors of $\infty\Cat$ under $\id \simeq \D^1. $	
\item There is a canonical equivalence $$ \widetilde{\Sym} \simeq \D^\infty $$
of endofunctors of $\infty\Cat_*$ under $\id \simeq \D^1. $	
\end{enumerate}	
\end{lemma}

\begin{proof}

By \cref{theta}  there is a localization $ \Fun(\Theta^\op, \mS) \rightleftarrows \infty\Cat$ 
whose left adjoint preserves finite products, and so gives rise to a localization
$$ \Fun(\Theta^\op, \C\mon(\mS)) \simeq \C\mon(\Fun(\Theta^\op, \mS) ) \rightleftarrows \C\mon(\infty\Cat).$$
Consequently, the functor $\Sym: \infty\Cat \to \infty\Cat$ factors as 
$$  \infty\Cat \subset \Fun(\Theta^\op, \mS) \xrightarrow{\Sym_*} \Fun(\Theta^\op, \mS)  \to \infty\Cat$$ and the functor $\widetilde{\Sym}: \infty\Cat \to \infty\Cat_*$ factors as 
$$  \infty\Cat \subset \Fun(\Theta^\op, \mS) \xrightarrow{\widetilde{\Sym}_*}\Fun(\Theta^\op, \mS_*) \simeq \Fun(\Theta^\op, \mS)_*  \to \infty\Cat_* .$$

So (1) follows from \cref{polujk} (1) and that the left adjoint functor
$  \Fun(\Theta^\op, \mS)  \to \infty\Cat$ preserves small coproducts.
And (2) follows from \cref{polujk} (2) and that the left adjoint functor  $  \Fun(\Theta^\op, \mS)  \to \infty\Cat$ preserves small filtered colimits.


\end{proof}

