\end{proof}

\begin{corollary} Let $\mC \in \infty\Cat_*$ be connected.

\begin{enumerate}
\item Then $H(\mC)$ is connected and the functor
$\Omega(\mC) \to \Omega(H(\mC)) $ induces on weak equivalence classes the universal map to the abelianization.

\item Let $ n > 0$ and $\mC$ be $n$-connected. Then $H(\mC)$ is $n$-connected
and the functor $\Omega^{n+1}(\mC) \to \Omega^{n+1}(H(\mC))$ induces an isomorphism on 
weak equivalence classes.
\end{enumerate}

\end{corollary}

