By \cite[Definition 3.5.21.]{GepnerHeine} for every $n \geq 0$ there is a gaunt $n$-category $\bDelta^n$, the $n$-th oriental, whose 1-truncation is the totally ordered set $[n]=\{0<...<n\},$ and that has a unique non-degenerate $n$-mprphism.
Moreover there is a functor $\bDelta: \Delta \to \infty\Cat$
whose composition with the functor $\tau_1: \infty\Cat \to \infty\Cat$ is the canonical embedding.

\begin{example}

Let $\mC$ be a strict $\infty$-category.
The Street nerve of $\mC$ is the stratified simplicial set whose underlying simplicial set is $ \infty\Cat^\strict(\bDelta^{(-)},\mC)$ and whose thin %non-degenerate
$n$-simplices for $n \geq 1$ are precisely 
the functors $\bDelta^n \to \mC$ that send the unique non-degenerate $n$-morphism of $\bDelta^n$ 
to a degenerate $n$-morphism.

\end{example}

The Street-Roberts conjecture proven in \cite[Theorem 266]{Verity2} asserts that the Street nerve $ \infty\Cat^\strict \to \Strat$ is fully faithful and characterizes the essential image: a stratified simplicial set lies in the essential image if and only if it is a strict complicial set \cite[Definition 1.4.5.]{Riehl2018}, a stratified simplicial set that uniquely satisfies a horn lifting condition and thinness extension condition %in a unique way
that ensures the existence of composites of 
%providing strictly associative and unital composition of 
arbitrary dimensional morphisms and that thin simplices are closed under composition.

%(see \cite[Definition 1.4.2., Example 1.4.6.]{Riehl2018} for details).
By \cite[Theorem 1.25.]{Complicial} there is a cartesian combinatorial model structure on $\Strat$ whose cofibrations are the monomorphisms in $\Strat$, the maps that are objectwise injective. The fibrant objects 
are a weakening of strict complicial sets, the complicial sets \cite[Definition 1.21.]{Complicial}, stratified simplicial sets satisfying a horn lifting condition and thinness extension condition
in a not necessarily unique way, and also satisfy a saturation condition that ensures Rezk-completeness.
%providing composition of arbitrary dimensional morphisms (see \cite[Definition 1.4.2., Example 1.4.6.]{Riehl2018} for details).
%generalizing the horn lifting condition in a quasi-category ... 
By \cite[Theorem 3.3.2.5.]{loubaton2024complicialmodelinftyomegacategories} complicial sets are a model for $\infty$-categories: there is a canonical equivalence
$$\Strat[\mathrm{weak} \ \mathrm{equivalences}] \simeq \infty\Cat.$$

\begin{definition}

A stratified simplicial commutative monoid is a pair $(X,\mE)$,
where $X$ is a simplicial commutative monoid and $\mE$ is a set of simplices of $X$ containing all degenerate simplices and such that
for every $n \geq 0$ the monoid structure on $X_n$ restricts to $X_n \cap \mE.$
A map of stratified simplicial commutative monoids $(X,\mE) \to (Y,\mF)$ is a map $X \to Y$ of simplicial commutative monoids sending $\mE $ to $\F$.

\end{definition}

\begin{remark}

In other words a stratified simplicial commutative monoid is a pair $(X,\mE)$,
where $X$ is a simplicial commutative monoid such that $(X,\mE)$ is a stratified simplicial set and
for every $n \geq 0$ the monoid structure on $X_n$ preserves thinness.
A map of stratified simplicial commutative monoids $(X,\mE) \to (Y,\mF)$ is a map $X \to Y$ of simplicial commutative monoids that is also a map of stratified simplicial sets $(X,\mE) \to (Y,\mF).$

\end{remark}

\begin{remark}

A stratified simplicial commutative monoid is precisely a commutative monoid in $\Strat.$
A map of stratified simplicial commutative monoids is precisely a map of commutative monoids in $\Strat.$

\end{remark}

\begin{notation}
We write $\C\mon(\Strat)$ for the category of commutative monoid objects in $\Strat$, the category of stratified commutative monoids.	

\end{notation}

\begin{example}
The forgetful functor $\C\mon(\Strat) \to \Strat$ admits a left adjoint, the free stratified simplicial commutative monoid functor, that sends a stratified simplicial set $(X,\mE)$
to the stratified simplicial commutative monoid $(\N[X],\bN[\mE])$,
where $ \bN[X]$ is the free simplicial commutative monoid on $X$ satisfying 
$  \bN[X]_n = \bN[X_n] $ for every $n \geq 0$ and $\N[\mE]$ is the graded set satisfying 
$  \bN[\mE]_n = \bN[\mE_n] $.

\end{example}

We will prove the following theorem:
\begin{theorem}\label{Strattrans}

There is a right induced (and so combinatorial) model structure on the category $\C\mon(\mathrm{Strat})$ of stratified commutative monoids.	

\end{theorem}

The next definitions  are \cite[\S 2]{FarjounDiagram}.

\begin{definition}

Let $\mD$ be a category. A functor $\phi: \mD \to \Set$ is a free diagram if it is a coproduct 
of functors of the form $\mD(X,-)$ for some $X \in \mD.$	

\end{definition}

\begin{definition}Let $\mD$ be a category and $\phi: \mD \to \Set$ a functor. 
A collection $\{ (\zeta_\alpha, X_\alpha) \mid \alpha \in \mJ \}$, where $X_\alpha \in \mD$ and $\zeta_\alpha \in \phi(X_\alpha)$ for every $\alpha \in \mJ$ corresponds to a transformation
$\theta:  \coprod_{\alpha \in \mJ} \mD(X_\alpha,-) \to \phi.$ 
We say that $\{ (\zeta_\alpha, X_\alpha) \mid \alpha \in \mJ \}$ generates $\phi$ if $\theta$ is an isomorphism. In this case we call $\{ (\zeta_\alpha, X_\alpha) \mid \alpha \in \mJ \}$ a collection of generators of $\phi.$

\end{definition}

\begin{remark}
A functor $\mD \to \Set$ is a free diagram if and only if there is a collection of generators.
But in general the collection of generators is not unique.

\end{remark}

%\begin{terminology}

%Let $\F:\mD \to \Set$ be a free diagram.Then there is a set $\mJ$ and a family $(X_\alpha)_{\alpha \in \mJ} $ of objects of $\mD$ and an isomorphism $ \F \cong \coprod_{\alpha \in \mJ} \mD(X_\alpha,-).$
%We obtain for every $\alpha \in \mJ$ a transformation $ \mD(X_\alpha,-) \to \F$ corresponding to
%an element $\zeta_\alpha $ of $\F(X_\alpha).$ We say that $\zeta_\alpha$ is a generator of $\F$ at $ X_\alpha$ and call the collection $\{ (\zeta_\alpha, X_\alpha) \mid \alpha \in \mJ \}$ the collection of generators of $\F.$\end{terminology}

\begin{definition}

Let $\mD$ be a category. A functor $\phi: \mD \to \Set^{\Delta^\op}$ is a free diagram if the following two conditions hold:

\begin{enumerate}
\item For every $n \geq 0$ the functor $  \mD \xrightarrow{\phi} \Set^{\Delta^\op} \xrightarrow{\ev_n} \Set$ is a free diagram, where $\ev_n$ evaluates at $n$.

\item For every $n \geq 0$ there is a collection of generators $\mQ_n= \{ (\zeta_\alpha, X_\alpha) \mid \alpha \in \mJ_n \}$ of $\ev_n \circ \phi$ such that $\cup_{n \geq 0}\mQ_n$ is closed under degeneracies, i.e. for any order preserving surjection $\sigma: [\m] \to [n]$ and $\alpha \in \mJ_n$ the map $\sigma^*: \ev_n(\phi(X_\alpha)) \to \ev_\m(\phi(X_\alpha)) $ sends $\zeta_\alpha$ to $\zeta_\beta$ for some $\beta \in \mJ_\m$ with $X_\beta=X_\alpha.$

\end{enumerate}

\end{definition}

\begin{definition}

Let $\mD$ be a category. A functor $\phi: \mD \to \Strat$ is a free diagram if the following two conditions hold:

\begin{enumerate}
\item The functor $\phi: \mD \to \Strat \xrightarrow{\mathrm{forget}} \Set^{\Delta^\op}	$ is a free diagram.

\item For every $n \geq 0$ the functor $  \mD \xrightarrow{\phi} \Strat \to \Set$ is a free diagram, where the last functor assigns the set of thin $n$-simplices.

\end{enumerate}

\end{definition}

Next we consider our example of interest.

\begin{notation}

Let $\G$ be a group and $\mC$ a category.
Let $\mC[\G]:= \Fun(B\G,\mC)$ be the category of objects in $\mC$ with $\G$-action.

The orbit category of $\G$ is the full subcategory $\mO(\G) \subset \Set[\G]$ spanned by the $\G$-sets of the form $\G/H$ for some subcategory $H$ of $\G.$

\end{notation}

\begin{notation}
Let $\G$ be a group. The canonical embedding $B\G \subset \Set[\G]$ hitting $\G$ induces an embedding $B\G \subset \mO(\G).$ 
Let $\mC$ be a category that admits small limits. The induced functor $ \Fun(\mO(\G),\mC) \to \Fun(B\G,\mC)=\mC[\G]$ admits a right adjoint that sends $X \in \mC[\G]$ to the functor
$\widehat{X}: \mO(\G) \to \mC, \G/H \mapsto X^H.$ 	

\end{notation}

\begin{remark}
The functor $B\G \subset \mO(\G)$ is cofinal as functor of $(1,1)$-categories.
Hence for every $(1,1)$-category $\mC$ that admits the necessary colimits and object $X \in \mC[\G]$ the canonical map
$  X_\G:=\colim(X) \to \colim(\widehat{X} )$ is an equivalence.

\end{remark}

\begin{example}\label{Free}Let $\G$ be a group.

\begin{enumerate}

\item Let $X $ be a set with $\G$-action.
The functor $\widehat{X}: \mO(\G)^\op \to \Set, \G/ H \mapsto X^H $ is a free diagram.

\item Let $X $ be a simplicial set with $\G$-action.
The functor $\widehat{X}: \mO(\G)^\op \to \Set^{\Delta^\op}, \G/ H \mapsto X^H $ is a free diagram.

\item Let $X $ be a stratified simplicial set with $\G$-action.
The functor $\widehat{X}: \mO(\G)^\op \to \Strat, \G/ H \mapsto X^H $ is a free diagram.

\end{enumerate}

The first and second examples are \cite[\S 2.7.]{FarjounDiagram}.
The third example follows immediately from the first and second since the forgetful 
functors $\Strat \to \Set^{\Delta^\op}, \Strat \to \Set^{\bN}$ assigning the underlying simplicial set, the 
sets of thin arrows, respectively, preserve small limits.

\end{example}

\begin{lemma}\label{cell}

Let $\mD$ be a category.
Every free diagram $X: \mD \to \Strat$ is projectively cofibrant.	

\end{lemma}

\begin{proof}

For every $n \geq 0$ and $X \in \Strat$ let $X_{\leq n} \in \Strat$ be the stratified simplicial subset of $X$ such that the inclusion $ X_{\leq n} \to X$ in $\Strat$ is the identity on underlying simplicial sets and on thin simplices of dimension smaller $n+1$ and such that all thin simplices of  $ X_{\leq n}$ of dimension larger $n$ are degenerate.
Then $X_{\leq 0}$ is the minimal stratification on the underlying simplicial set of $X.$ 
For every $\m \geq n \geq 0$ we obtain a functor $ (-)_{\leq n}: \Strat \to \Strat$
and transformations $ (-)_{\leq n} \to (-)_{\leq \m}, (-)_{\leq \m} \to \id$.
Trivially, the inclusions $  X_{\leq n} \to  X$ in $\Strat$ give rise to an isomorphism
$ \colim(X_{\leq0} \to X_{\leq1} \to ...  ) \to X$ in $\Strat.$ 

The functor $ (-)_{\leq n}: \Strat \to \Strat$ gives rise to a functor $  (-)_{\leq n}: \Fun(\mD,\Strat) \to \Fun(\mD, \Strat)$ that we denote by the same name.
So for every functor $X: \mD \to \Strat$ and $n \geq 0$ there are inclusions
$ X_{\leq n} \to X$ in $\Fun(\mD,\Strat)$ that give rise to an isomorphism
$ \colim(X_{\leq0} \to X_{\leq 1} \to ...  ) \to X$ in $\Fun(\mD,\Strat).$ 
We prove first that for every functor $X: \mD \to \Strat$, which is a free diagram, 
the functor $X_{\leq 0} : \mD \to \Strat$ is projectively cofibrant.

For that it is enough to prove the following: for every functor $Y: \mD \to \Set^{\Delta^\op}$, which is a free diagram, the functor $Y^\flat: \mD \to \Strat$ is projectively cofibrant.
By \cite[Proposition 2.5.]{FarjounDiagram} the functor $Y: \mD \to \Set^{\Delta^\op}$ is a $\mD$-CW-complex, i.e. $Y$ is the sequential colimit of a diagram $Y^{-1} := \emptyset \to Y^0 \to Y^1 \to ...$ and for every $n \geq 0 $ the morphism $Y^{n-1} \to Y^{n} $ is the co-base change of a coproduct of morphisms of the form $ \mD(Z,-) \times \partial\bD^n  \to \mD(Z,-) \times \bD^n $ for $n \geq 0$ and $ Z \in \mD. $
Since the functor $(-)^\flat: \Set^{\Delta^\op} \to \Strat$ is a left adjoint and so preserves colimits,
the functor $Y^\flat: \mD \to \Strat$ is a sequential colimit of the diagram $(Y^{-1})^\flat = \emptyset \to (Y^0)^\flat \to (Y^1)^\flat \to ... $ in $\Strat$ and for every $n \geq 0 $ the morphism $(Y^{n-1})^\flat \to (Y^{n})^\flat $ is the co-base change of a coproduct of morphisms of the form $\mD(Z,-)\times (\partial\bD^n)^\flat  \to \times \mD(Z,-)\times (\bD^n)^\flat$ for $ n \geq 0$ and $ Z \in \mD.$
The functor $\Fun(\mD,\Strat) \to \Strat$ evaluating at $Z \in \mD$ is right adjoint to the functor
$ A \mapsto \mD(Z,-) \times A.$ Since fibrations and trivial fibrations for the projective model structure are object-wise, the functor $\Fun(\mD,\Strat) \to \Strat$ evaluating at $Z \in \mD$ is a right Quillen functor so that its left adjoint is a left Quillen functor. 
For every $n \geq 0$ the map $ (\partial\bD^n)^\flat  \to (\bD^n)^\flat $ is a cofibration in $\Strat$
so that for every $Z \in \mD$ the morphism $ \mD(Z,-)\times (\partial\bD^n)^\flat \to \mD(Z,-)\times (\bD^n)^\flat $ in $\Fun(\mD,\Strat) $ is a projective cofibration. 
Since cofibrations in any model category are closed under co-base-change and transfinite compositions, we find that for every $n \geq 0$ the map $(Y^{n-1})^\flat  \to (Y^n)^\flat$
and so the map $\emptyset =(Y^{-1} )^\flat \to Y^\flat $ are projective cofibrations. In other words $Y^\flat$ is projectively cofibrant.

We have seen that for every functor $X: \mD \to \Strat$ the functor $X_{\leq 0}$ is projectively cofibrant.
Consequently, it suffices to show that for every $n \geq 0$ the inclusion $ X_{\leq n-1} \to X_{\leq n}$ is a projective cofibration. For every $n \geq 0$ the canonical map $ (\bD^n)^\flat \to (\bD^n)^t$ is a cofibration in $\Strat$ so that for every $Z \in \mD$ the morphism $ \mD(Z,-)\times (\bD^n)^\flat \to\mD(Z,-)\times (\bD^n)^t $ in $\Fun(\mD,\Strat) $ is a projective cofibration.

Since cofibrations in any model category are closed under co-base-change and transfinite compositions, it is enough to see that for every $n \geq 0$ the inclusion $ X_{\leq n-1} \to X_{\leq n}$ is a co-base change of a coproduct of morphisms of the form
$ \mD(Z,-)\times (\bD^n)^\flat  \to \mD(Z,-)\times (\bD^n)^t $ for $Z \in \mD$.

For every $n \geq 0$ the functor $ \mD \xrightarrow{X} \Strat \xrightarrow{ } \Set$,
where the last functor takes the thin $n$-simplices, is a free diagram and so there is a collection of generators $\mQ= \{ (\zeta_\alpha, T_\alpha) \mid \alpha \in \mJ \}$ of the latter functor.
Let $\mJ' \subset \mJ$ be the subset of elements $\alpha$ such that the thin $n$-simplex $ \zeta_\alpha $ of $ X(T_\alpha)$ is degenerate.

For every $\alpha \in \mJ$ the thin $n$-simplex $ \zeta_\alpha $ of $ X(T_\alpha)$ corresponds to a map $ \mD(T_\alpha,-) \times (\Delta^n)^t \to X$ in $\Fun(\mD,\Strat)$
that induces a map $ \mD(T_\alpha,-) \times (\Delta^n)^t \to X_{\leq n}$ in $\Fun(\mD,\Strat)$.
We obtain a map $\coprod_{\alpha \in \mJ'} \mD(T_\alpha,-) \times (\Delta^n)^t \to X_{\leq n}$ in $\Fun(\mD,\Strat)$.
We obtain a commutative square in $\Fun(\mD,\Strat)$:
$$\begin{xy}
 \xymatrix{
\coprod_{\alpha \in \mJ'} \mD(T_\alpha,-) \times (\Delta^n)^\flat \ar[d] \ar[r]
& \coprod_{\alpha \in \mJ'} \mD(T_\alpha,-) \times (\Delta^n)^t  \ar[d]
\\ 
X_{\leq n-1} \ar[r]  & X_{\leq n}.
}
 \end{xy}$$	
We complete the proof by showing that this commutative square is a pushout square in
$\Fun(\mD,\Strat)$.
Both horizontal maps in the latter square forget to the identities in $\Fun(\mD,\Set^{\Delta^\op})$
and induce object-wise the identities on thin simplices of dimension different from $n.$ 
In particular, the latter square lies over a pushout square in $\Fun(\mD,\Set^{\Delta^\op})$.
The forgetful functor $\Strat \to \Set^{\Delta^\op}$ admits a right adjoint taking the maximal stratification and so preserves small colimits. Hence the map in $\Fun(\mD,\Strat)$ from the pushout to $X_{\leq n}$ forgets to the identity in $\Fun(\mD,\Set^{\Delta^\op})$, and 
induces object-wise the identities on thin simplices of dimension different from $n.$ 
So it remains to see that for every $Z \in \mD$ every thin $n$-simplex of $X_{\leq n}(Z)$, i.e. thin $n$-simplex of $X(Z)$, belongs to the pushout evaluated at $Z.$
By definition every degenerate $n$-simplex of $X(Z)$ belongs to $X_{\leq n-1}(Z)= X(Z)_{\leq n-1}$. Hence we need to see that every non-degenerate thin $n$-simplex $\sigma$ of $X(Z)$ belongs to the pushout evaluated at $Z.$
By generation there is an $\alpha \in \mJ$ and a morphism $\kappa: T_\alpha \to Z$
such that the induced map $X(\kappa): X(T_\alpha) \to X(Z)$ sends $\zeta_\alpha$ to $\sigma.$ 
If $\zeta_\alpha$ would be degenerate, also the image $\sigma$ of $\zeta_\alpha$ under $X(\kappa)$ 
would be degenerate. So $\zeta_\alpha$ is non-degenerate, so that $\alpha \in \mJ'$ and
$\sigma$ is the image of $\kappa$ and the unique non-degenerate $n$-simplex of $\Delta^n$ under the right vertical map of the latter square.



%a cellular object for the set of morphisms $\mQ:= \{ \partial\bD^n \times \mD(Z,-) \to \bD^n \times \mD(Z,-), \mid n \geq 0, Z \in \mD \}, $ i.e. $Y$ is the sequential colimit of$Y^{-1} := \emptyset \to Y^0 \to Y^1 \to ...$ and for every $\bi \leq -1$ the morphism $Y^\bi \to Y^{\bi+1} $ is the co-base change of a coproduct of morphisms that belong to $\mQ.$


\end{proof}

\begin{corollary}\label{projcof}

Let $\G$ be a group and $X $ an object in $\Strat$ with $\G$-action. %, i.e. a functor
%$B\G \to \Strat.$
The functor $ \mO(\G)^\op \to \Strat, % \mO(\G)^\op \subset \Strat[\G]^\op \xrightarrow{\Strat[\G](-,X)}  \Strat, 
\G/ H \mapsto X^H $ is projectively cofibrant. %in the category of functors$\mO(\G)^\op \to \Strat.$	

\end{corollary}

\begin{proof}
The functor $ \widehat{X}: \mO(\G)^\op \to \Strat, \G/ H \mapsto X^H $ is a free diagram by \cref{Free}.
We apply \cref{cell}.

\end{proof}

The next proposition is an adaption of \cite[Theorem 1.3.]{Casacuberta}. We are grateful to David White who made us aware of \cite{Casacuberta}.

\begin{proposition}\label{Symso} For every $n \geq 0$ the functor
$ \Strat \to \Strat, X \mapsto (X^{\times n})_{\Sigma_n}$ preserves weak equivalences.

\end{proposition}

\begin{proof}
For every map $X \to Y$ in $\Strat$ the induced map
$ (X^{\times n})_{\Sigma_n} \to (Y^{\times n})_{\Sigma_n}$
is the induced map on colimits $\colim(\widehat{X^{\times n}}) \to \colim(\widehat{Y^{\times n}})$
and by \cref{projcof} the induced map on homotopy colimits.
Thus the induced map
$ (X^{\times n})_{\Sigma_n} \to (Y^{\times n})_{\Sigma_n}$
is a weak equivalence if for every $\Sigma^n/H \in \mO(\Sigma^n)$
the induced morphism 
$\widehat{X^{\times n}}(\Sigma^n/H)= (X^{\times n})^H \to \widehat{Y^{\times n}}(\Sigma^n/H) = (Y^{\times n})^H $ is a weak equivalence. 
The latter map identifies with the map $X^{\times\m}  \to Y^{\times\m}$,
where $\m \leq n$ is the index of $H$ in $\Sigma_n$ \cite[Remark 4.1.]{RecognitionBadzioch}.
So the statement follows from the fact that weak equivalences in $\Strat$ are closed under finite products since the model structure on $\Strat$ is cartesian and every object is cofibrant
\cite[Theorem 1.25.]{Complicial}.

%\cite[Observation 74.]{Verity1}.

\end{proof}

\begin{corollary}\label{Symsoi} The functor
$\Sym: \Strat \to \Strat, X \mapsto \coprod_{n \geq 0} (X^{\times n})_{\Sigma_n} $ preserves weak equivalences.	
\end{corollary}

\begin{proof}
By \cref{Symso} for every $n \geq 0$ the functor
$ \Strat \to \Strat, X \mapsto (X^{\times n})_{\Sigma_n}$ preserves weak equivalences.
In any model category arbitrary coproducts of trivial cofibrations are trivial cofibrations.
So by Ken-Brown's Lemma arbitrary coproducts of weak equivalences between cofibrant objects are weak equivalences. Since every object of $\Strat $ is cofibrant, the functor
$\Sym: \Strat \to \Strat, X \mapsto \coprod_{n \geq 0} (X^{\times n})_{\Sigma_n} $ preserves weak equivalences.	

\end{proof}

\begin{proof}[Proof of \cref{Strattrans}]

This follows from \cite[Theorem 5.2.]{White} and \cref{Symsoi}.

\end{proof}






The canonical functor $\mathrm{Strat} \to \mathrm{Strat}[\mathrm{weak} \ \mathrm{equivalences}]$ preserves finite products since weak equivalences in $\mathrm{Strat} $ are closed under finite products %\cite[Observation 74.]{Verity1}. 
since the model structure on $\Strat$ is cartesian and every object is cofibrant
\cite[Theorem 1.25.]{Complicial}. Hence the latter functor induces a functor
$ \C\mon(\mathrm{Strat}) \to \C\mon(\mathrm{Strat}[\mathrm{weak} \ \mathrm{equivalences}])$ that inverts weak equivalences and so gives rise to a functor 
