\subsection{Multiplicativity of categorical homology}

In this subsection we study multiplicativity of categorical homology. 
We prove that categorical $R$-homology for any rig $R$ multiplicatively lifts to the Gray-category of $(R,R)$-bimodule categorical spectra (\cref{liftos}).

We start with defining rigs:
%The next definition generalizes the concept of ring:

\begin{definition}
A rig space is an associative algebra for the presentably monoidal structure on $\Mon_{\bE_\infty}(\mS).$ 
%Let $\mathrm{Rig}:= \Alg(\Mon_{\bE_\infty}(\mS)).$
A rig is an associative algebra for the presentably monoidal structure on $\C\mon=\Mon_{\bE_\infty}(\Set).$ 
\end{definition}

\begin{notation}
Let $\mathrm{Rig}\mS:= \Alg(\Mon_{\bE_\infty}(\mS))$ and $\mathrm{Rig}:= \Alg(\C\mon).$	
\end{notation}

\begin{example}
The natural numbers $(\bN,+,\bullet)$ are a rig.	
The free symmetric monoidal category $\Sigma$ generated by one object is a rig space.
\end{example}

\begin{example}

By adjunction \ref{adjass} the symmetric monoidal localization $\pi_0: \mS \rightleftarrows \Set$ induces a symmetric monoidal localization \begin{equation}\label{rig}
\Mon_{\bE_\infty}(\mS) \rightleftarrows \C\mon=\Mon_{\bE_\infty}(\Set).\end{equation}
% whose left adjoint is monoidal and whose right adjoint is therefore lax monoidal.
% embedding$\Mon_{\bE_\infty}(\Set) \subset \Mon_{\bE_\infty}(\Set),$ which therefore becomes lax monoidal.
Adjunction \ref{rig} gives rise to a localization $\mathrm{Rig}\mS \rightleftarrows \mathrm{Rig}.$
Via the fully faithful right adjoint every rig may be viewed as a rig space.

\end{example}

\begin{proposition}

The functor $B^\infty: \Mon_{\bE_\infty}(\mS) \to \Sp$ is monoidal. Hence the restriction $H: \C\mon \subset \Mon_{\bE_\infty}(\mS) \xrightarrow{B^\infty} \Sp$ is lax monoidal.

\end{proposition}

\begin{proof}

The reduced Gray-functor $\Sigma^\infty: \infty\Cat_* \to \Sp$ is monoidal by \cref{unicity} and by \cref{symsp} induces a left adjoint monoidal embedding $$B^\infty: \Mon_{\bE_\infty}(\infty\Cat) \simeq \Mon_{\bE_\infty}(\infty\Cat_*) \to \Mon_{\bE_\infty}(\Sp) \simeq \Sp.$$
By \cref{Grayspaces} the canonical embedding $\mS \subset \infty\Cat$ is monoidal, where the right hand side carries the Gray monoidal structure, and so induces a left adjoint monoidal embedding $\Mon_{\bE_\infty}(\mS) \subset \Mon_{\bE_\infty}(\infty\Cat)$ by adjunction \ref{adjass}.
%We obtain a left adjoint monoidal embedding $$B^\infty: \Mon_{\bE_\infty}(\mS) \subset \Mon_{\bE_\infty}(\infty\Cat) \subset \Sp.$$
\end{proof}

\begin{corollary}


The functor $B^\infty: \Mon_{\bE_\infty}(\mS) \to \Sp$ induces a functor
$ \mathrm{Rig} \mS \to \Alg(\Sp)$.
% that restricts to a functor$B^\infty: \mathrm{Rig} \to \Alg(\Sp).$

\end{corollary}

We will prove the following theorem:

\begin{theorem}\label{bimo}

Let $A$ be a rig space. There is a monoidal functor $$\Sp \to {_{B^\infty(A)}\Mod_{B^\infty(A)}(\Sp)}, Z \mapsto B^\infty(A) \wedge Z \simeq Z \wedge B^\infty(A).$$

\end{theorem} 

We obtain the following immediate corollary:

\begin{corollary}\label{bimo2} 
Let $A$ be a rig space. There is a lax monoidal functor 
$$ \infty\Cat_* \to {_{A}\Mod_{A}(\infty\Cat_*)}, Z \mapsto \Omega^\infty(B^\infty(A) \wedge Z) \simeq \Omega^\infty(Z \wedge B^\infty(A)) .$$	

\end{corollary} 

Moreover we obtain the following theorem as an immediate corollary:

\begin{theorem}\label{liftos} Let $A$ be a rig. Categorical $A$-homology $ \infty\Cat_* \to \infty\Cat_*$ lifts to a left adjoint reduced monoidal Gray-functor 
$ \infty\Cat_* \to {_{A}\Mod_{A}(\Sp)}.$
\end{theorem}

