\section{Categorical spectral enrichment of stable Gray-categories}\label{SpecStab}

In this section we prove that every stable Gray-category is uniquely enriched in the monoidal category of categorical spectra (\cref{spectral}, \cref{specenr}).

\begin{notation}
By \cite[Notation 5.36., Theorem 4.89.]{heine2024bienriched} for every small reduced left Gray-category $\mC$ there is a reduced left Gray-embedding $$\mC \hookrightarrow {\Fun\wedge}(\mC^\circ, \infty\Cat_*),$$
which we call left Gray-Yoneda-embedding, that preserves left weighted limits \cite[Corollary 3.68.(3)]{heine2024higher}.

By \cite[Notation 5.36., Theorem 4.89.]{heine2024bienriched} for every small reduced right Gray-category $\mC$ there is a reduced right Gray-embedding $$\mC \hookrightarrow {\wedge\Fun}(\mC^\circ, \infty\Cat_*),$$
which we call right Gray-Yoneda-embedding, that preserves right weighted limits \cite[Corollary 3.68.(3)]{heine2024higher}.

\end{notation}

\begin{remark}
Let $\mC$ be an oplax quasi-stable right Gray-category. By oplax quasi-stability the full subcategory $ {\Oplax\Exc\wedge}(\mC, \infty\Cat_*) \subset {\Fun\wedge}(\mC, \infty\Cat_*) $ precisely consists of the reduced right Gray-functors preserving endomorphisms.
In particular, for every lax quasi-stable left Gray-category $\mC$ the left Gray-Yoneda-embedding induces a left Gray-embedding $$\mC \hookrightarrow {\Oplax\Exc \wedge}(\mC^\circ, \infty\Cat_*)$$ 
into a presentable left Gray-category \ref{excprese} that preserves left weighted limits \cite[Lemma 3.80.(2)]{heine2024higher}.

Dually, let $\mC$ be a lax quasi-stable left Gray-category. By lax quasi-stability $ {\wedge\Lax\Exc}(\mC, \infty\Cat_*) \subset {\wedge\Fun}(\mC, \infty\Cat_*) $ precisely consists of the reduced left Gray-functors preserving coendomorphisms.
In particular, for every oplax quasi-stable right Gray-category $\mC$ the right Gray-Yoneda-embedding induces a right Gray-embedding $$\mC \hookrightarrow {\wedge\Lax\Exc}(\mC^\circ, \infty\Cat_*)$$ into a presentable right Gray-category that preserves right weighted limits.

\end{remark}

\begin{proposition}

\begin{enumerate}
\item Let $\mC$ be an oplax quasi-stable right Gray-category. The following reduced presentable left Gray-category is lax stable: $$ {\Oplax\Exc\wedge}(\mC, \infty\Cat_*).$$

\item Let $\mC$ be a lax quasi-stable left Gray-category. The following reduced presentable right Gray-category is oplax stable: $$ {\wedge\Lax\Exc}(\mC, \infty\Cat_*). $$

\end{enumerate}	

\end{proposition}

\begin{proof}The proof of (2) is similar to the one of (1).
We prove (1). 
By \cref{forgeto} for every $X \in \mC$ there is a reduced left Gray-functor $nu_X: {\Oplax\Exc\wedge}(\mC, \infty\Cat_*) \to \Sp$ sending $\F$ to $\F(X \wedge S^\bullet)$ that preserves small limits, left cotensors, small colimits and left tensors by \cref{locpre2}, and so in particular preserves cosuspensions and coendomorphisms.
Since the family $(nu_X)_{X \in \mC}$ of functors is jointly conservative, ${\Oplax\Exc\wedge}(\mC, \infty\Cat_*)$ is lax stable since $\Sp$ is lax stable \ref{stab}.

\end{proof}

\begin{corollary}
\begin{enumerate}
\item Let $\mC$ be an oplax quasi-stable right Gray-category.  There is a canonical functorial right Gray-embedding $\mC \hookrightarrow \mD$ preserving right weighted limits into an oplax stable presentable right Gray-category.

\item Let $\mC$ be a lax quasi-stable left Gray-category.  There is a canonical functorial left Gray-embedding $\mC \hookrightarrow \mD$ preserving left weighted limits into a lax stable presentable left Gray-category.

\end{enumerate}

\end{corollary}

\begin{corollary}\label{spectral0}
\begin{enumerate}

\item Every oplax quasi-stable right Gray-category $\mC$ underlies a spectral right Gray-category $\bar{\mC}.$ 

\item Every lax quasi-stable left Gray-category $\mC$ underlies a spectral left Gray-category $\bar{\mC}.$ 

\end{enumerate}		

\end{corollary}

\begin{notation}
Let $\mC$ be a presentable reduced left Gray-category and $\mD$ a presentable reduced right Gray-category. The category $\mC \ot \mD$ is canonically a category presentably bitensored over
$\infty\Cat_*$ and so a presentable Gray-category that we denote by $\mC \boxplus \mD.$

\end{notation}

\begin{definition}
Let $\mC, \mD$ be presentable reduced Gray-categories. The category $\mC \ot \mD$ is canonically a category presentably bitensored over $\infty\Cat_* \ot \infty\Cat_*$ and so $\mC \boxplus \mD$
carries extra structure that guarantees by \cite[Theorem 5.51., Theorem 4.89.]{heine2024bienriched} that for every small reduced Gray-category $\mB$ the category $$ {\wedge\Fun\wedge}(\mB, \mC\boxplus \mD)$$ refines to a presentable Gray-category.
\end{definition}

\begin{remark}\label{tencot} By \cite[Proposition 5.15.]{heine2024bienriched} the left tensor with $X\in\infty\Cat_*$ is the reduced right Gray-functor $$(\mC \boxplus (X \wedge (-)))_*:  {\wedge\Fun\wedge}(\mB, \mC\boxplus \mD) \to {\wedge\Fun\wedge}(\mB, \mC\boxplus \mD)$$
and the right tensor with $X\in\infty\Cat_*$ is the reduced left Gray-functor $$(((-) \wedge X)\boxplus\mD)_*:  {\wedge\Fun\wedge}(\mB, \mC\boxplus \mD) \to {\wedge\Fun\wedge}(\mB, \mC\boxplus \mD).$$	

\end{remark}

\begin{notation}
By \cite[Notation 5.36., Theorem 4.89.]{heine2024bienriched} for every small reduced Gray-category $\mC$ there is a reduced Gray-embedding $$\mC \hookrightarrow {\wedge\Fun\wedge}(\mC^\circ, \infty\Cat_*\boxplus \infty\Cat_*),$$
which we call Gray-Yoneda-embedding, that preserves weighted limits \cite[Corollary 3.68.(3)]{heine2024higher}.

\end{notation}

