\section{A categorical Whitehead theorem}

In this section we prove a categorified Whitehead theorem for a nice class of $\infty$-categories and 
categorical spectra (\cref{homten}, \cref{maf}).

\subsection{The Gray tensor product descends to $\infty$-categories with adjoints}

In this section we prove that the Gray monoidal structure descends to the full subcategory of $\infty$-categories with adjoints. The latter are studied in  \cite[Definition 2.3.13.]{Cob} %the following and which were studied in
and \cite[Definition 2.3.]{gwilliam2018dualsadjointshighermorita}.

\begin{definition}
\begin{itemize}
\item An $\infty$-category $\mC$ admits left adjoints, right adjoints, adjoints for morphisms of dimension smaller 2 if every morphism in the underlying 2-category of $\mC$ admits a left adjoint,
right adjoint, both a left and a right adjoint, respectively.

\item Let $\bk \geq 2$.
An $\infty$-category $\mC$ admits (left) (right) adjoints for morphisms of dimension smaller $\bk$ if $\mC$ admits (left) (right) adjoints for morphisms of dimension smaller 2 and all morphism $\infty$-categories of $\mC$ admit (left) (right) adjoints for morphisms of dimension smaller $\bk-1$. 


\item An $\infty$-category $\mC$ admits (left) (right) adjoints if it admits (left) (right) adjoints for morphisms of dimension smaller $\bk$ for every $\bk \geq 2$.

\end{itemize}	

\end{definition}

%\begin{definition}Let $n \geq 2$.An $n+1$-category $\mC$ admits left (right) adjoints if all morphism $n$-categories of $\mC$ and the underlying $2$-category of $\mC$ admit left (right) adjoints.\end{definition}

\begin{notation}
Let $$\mathrm{Lad}\infty\Cat,\mathrm{Rad}\infty\Cat,\mathrm{Ad}\infty\Cat \subset \infty\Cat$$ be the respective full subcategories of small $\infty$-categories having left adjoints, right adjoints, adjoints.

\end{notation}

\begin{remark}Let $ \bk \geq 2.$
%An $n$-category $\mC$ seen as $\infty$-category admits left (right) adjoints if and only if it admits left (right) adjoints for morphisms of dimension smaller $\bk$ for every $\bk \geq 2$.
An $\infty$-category $\mC$ admits left (right) adjoints for morphisms of dimension smaller $\bk$ if and only if for every $\ell > \bk$ there is an $n > \ell$ such that the underlying $n$-category of $\mC$ admits left (right) adjoints of dimension smaller $\bk.$
An $\infty$-category $\mC$ admits left (right) adjoints if and only if for every $n \geq 2$ the underlying $n$-category of $\mC$ admits left (right) adjoints of dimension smaller $n.$

%Let $n \geq 2$.An $n$-category $\mC$ admits left (right) adjoints of dimension smaller $n$ if and only if if all morphism $n$-1-categories of $\mC$ and the underlying $2$-category of $\mC$ admit left (right) adjoints of dimension smaller $2.$

\end{remark}

\begin{example}\label{aadk}
Every full subcategory of an $\infty$-category having left (right) adjoints admits left (right) adjoints.

\end{example}

\begin{definition} By \cite[Definition 2.2.10., Variant 2.2.11.]{Cob} for every $n \geq 0$ there is an $n$-category $\mathrm{Bord}_n$
whose objects are $0$-dimensional oriented framed manifolds, whose $i$-morphisms for $ 1 \leq \bi \leq n$ are $i$-dimensional oriented framed cobordisms, whose $n+1$-morphisms are diffeomorphisms between $n$-dimensional oriented framed cobordisms and whose
$i$-morphisms for $ i \geq n+2 $ are smooth homotopies.
Moreover there is a functor $\mathrm{Bord}_n  \to \mathrm{Bord}_{n+1}$ \cite[Example 3.3.12.]{Cob}.
Let	$$\mathrm{Bord}_\infty$$ be the colimit in $\infty\Cat$ of the following sequential diagram:
$$\mathrm{Bord}_1 \to ... \to \mathrm{Bord}_n \to ...$$

\end{definition}

\begin{example}
For every $2 \leq n \leq \infty $ the $n$-category $\mathrm{Bord}_n$ admits adjoints for morphisms of dimension smaller $n$ by \cite[Example 2.3.23.]{Cob}.

\end{example}

\begin{lemma}\label{anop}
Let $n \geq 1$ and $\mC$ an $n$-category that admits left (right) adjoints for morphisms of dimension smaller than $n+1$. Then $\mC$ is a space.
In particular, every $n$-category that admits left (right) adjoints is a space.

\end{lemma}

\begin{proof}We prove the case of left adjoints. The case of right adjoints is dual.
We proceed by induction on $n \geq 1$. Assume the statement holds for $n$ and let $\mC$ be an $n+1$-category that admits left adjoints for morphisms of dimension smaller than $n+2$. Then $\mC$ has left adjoints for morphisms of dimension smaller 2 and for every objects $ X, Y \in \mC$ the $n$-category $\Mor_\mC(X,Y)$ admits left adjoints for morphisms of dimension smaller than $n+1$ and so by induction hypothesis is a space. Thus $\mC$ is a 1-category that admits left adjoints for morphisms of dimension smaller $2.$

So it remains to prove the case $n=1$.
Let $g: Y \to X$ be a morphism in $\mC$. Then $g$ has a left adjoint $f: X \to Y$. So there are $\eta: \id \to g \circ f $ and $\varepsilon: f  \to \id,$ which are equivalences since $\mC$ is a $1$-category. So $g$ is an equivalence. Thus $\mC$ is a space.

\end{proof}

