\begin{theorem}\label{Grayloc}

The full subcategories $$\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat \subset \infty\Cat$$ are accessible monoidal localizations,
where $\infty\Cat$ carries the Gray monoidal structure.

\end{theorem}

\begin{proof}Let $\mQ= \mathrm{Lad}\infty\Cat,\mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat.$
We prove that the full subcategory $\mQ\subset \infty\Cat$ is a localization. If this is shown, \cref{Grayadj} implies that this localization is monoidal.
In view of \cref{gtr} it suffices to show that the embedding $\iota: \mQ \subset \infty\Cat$ admits a right adjoint $\G$ such that $\iota \circ \G$ preserves small limits and small filtered colimits.
Let $\G(\mC) \subset \mC$ be the subcategory of morphisms of arbitrary dimension that admit a left adjoint, right adjoint, both a left and right adjoint, respectively, depending on 
the choice of $\mQ.$
For every $\mB \in \mQ $ the induced embedding
$$ \infty\Cat(\mB, \G(\mC)) \to \infty\Cat(\mB,\mC)$$ is an equivalence since $\G(\mB)=\mB.$
So the embedding $\iota: \mQ \subset \infty\Cat$ admits a right adjoint $\G$.
The functor $\iota \circ \G$ preserves small limits and small filtered colimits because adjoints in limits are formed component-wise and adjoints in filtered colimits are formed
summand-wise.

\end{proof}

\begin{corollary}
The categories $\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat$
carry presentably monoidal structures such that the embedding to $\infty\Cat$ is lax monoidal.

\end{corollary}

\begin{corollary}\label{Graypre}
The full subcategories $$\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat \subset \infty\Cat$$ are accessible Gray-localizations and so
$\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat$
are presentable Gray-categories.
\end{corollary}

\subsection{The Gray-smash product descends to categorical spectra with adjoints}

In the following we prove that the smash product of categorical spectra descends to  the full subcategory of categorical spectra with adjoints (\cref{smashadj}).

\begin{definition}

A categorical spectrum with left adjoints, right adjoints, adjoints, respectively, is a spectrum of $\infty$-categories whose levels admit left adjoints, right adjoints, adjoints, respectively.

\end{definition}

\begin{definition}
A monoidal $\infty$-category $\mC$ admits left (right) duals if $B\mC$
admits left (right) adjoints.	
A symmetric monoidal $\infty$-category admits left (right) duals if the underlying monoidal $\infty$-category admits left (right) duals.

\end{definition}

\begin{example}
For every $\infty$-category having left (right) adjoints $\mC$ and every $X \in \mC$
the monoidal $\infty$-category $\Omega(C,X)$ admits left (right) duals
because $B\Omega(C,X)$ is the full subcategory of $\mC$ spanned by $X,$ 
which admits left (right) adjoints by \cref{aadk}.

\end{example}

\begin{remark}

The full subcategories $\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat$ are closed in $\infty\Cat$ under endomorphisms.
However, they are not closed under coendomorphisms since $\Omega' \simeq (-)^\circ \circ \Omega.$
In fact the Gray-functor $\Omega': \infty\Cat \to \infty\Cat$ restricts to Gray-functors
$\mathrm{Lad}\infty\Cat \to \mathrm{Rad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Lad}\infty\Cat.$


\end{remark}

\begin{notation}
Let $$\mathrm{Lad}\Sp:= \Sp(\mathrm{Lad}\infty\Cat),$$
$$\mathrm{Rad}\Sp:= \Sp(\mathrm{Rad}\infty\Cat),$$
$$\mathrm{Ad}\Sp:= \Sp(\mathrm{Ad}\infty\Cat).$$

\end{notation}

\begin{remark}\label{endloc}
For every categorical spectrum $\mC$ with left (right) adjoints and any $n \geq 0$ the symmetric monoidal $\infty$-category $\Omega^\infty(\Sigma^n(\mC))$ admits duals
since $\Omega^\infty(\Sigma^n(\mC)) \simeq \Omega(\Omega^\infty(\Sigma^{n+1}(\mC)))$
and the right hand side admits left (right) adjoints.

\end{remark}

In particular, we can consider categorical homology theories in $\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat \subset \infty\Cat$.

\begin{definition}
Categorical cobordism is the categorical homology theory associated to the categorical spectrum
$B^\infty(\mathrm{Bord}_\infty)$ with adjoints.	

\end{definition}

\cref{Graypre} implies the following:

\begin{theorem}\label{smashadj}

The full subcategories $\mathrm{Lad}\Sp, \mathrm{Rad}\Sp, \mathrm{Ad}\Sp \subset \Sp $ are accessible monoidal localizations. %, where $\Sp$ carries the Gray smash monoidal structure.

\end{theorem}

\begin{proof}
By \cref{Graypre} the Gray-categories $\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat$ are presentable so that also the Gray-categories $\mathrm{Lad}\Sp, \mathrm{Rad}\Sp, \mathrm{Ad}\Sp$ are presentable.
The accessible Gray-localizations $$\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat \subset \infty\Cat$$ of \cref{Graypre} give rise to accessible Gray-localizations $\mathrm{Lad}\Sp, \mathrm{Rad}\Sp, \mathrm{Ad}\Sp \subset \Sp$.
A spectrum is local if and only if all its levels are local if and only if all its even levels are local
since endomorphisms preserve locality by \cref{endloc}.
%Hence a spectrum is local if and only if it is local with respect to the class of morphisms $T:= \Omega^n(\Sigma^\infty(\alpha))$, where $n \geq 0$ even and $\alpha$ is a local equivalence for the respective localization $\mathrm{Lad}\infty\Cat, \mathrm{Rad}\infty\Cat, \mathrm{Ad}\infty\Cat \subset \infty\Cat$.
We like to prove that for every spectrum $X$ and local spectrum $Y$ the left and right internal homs
$Y^X, {^X Y}$ are local, which is equivalent to say that for every even $n \in \bZ$ the $\infty$-categories
$\Omega^\infty(\Omega^n(Y^X)), \Omega^\infty(\Omega^n({^X Y}))$ are local.
Since $n \in \bZ $ is even, there are equivalences
$$ \Omega^n(Y^X) \simeq Y^{\Sigma^n(X)}, \ \Omega^n({^X Y}) \simeq  {^{\Sigma^n(X)} Y}.$$
So it remains to show that for any spectrum $X$ and local spectrum $Y$ the $\infty$-categories $\Omega^\infty(Y^X), \Omega^\infty({^X Y})$ are local.
There are canonical equivalences $\Omega^\infty(Y^X) \simeq \L\Mor_\Sp(X,Y),  \Omega^\infty(^XY) \simeq \R\Mor_\Sp(X,Y)$, and the $\infty$-categories $\L\Mor_\Sp(X,Y), \R\Mor_\Sp(X,Y)$ are local
because $Y$ is local and the full subcategories $\mathrm{Lad}\Sp, \mathrm{Rad}\Sp, \mathrm{Ad}\Sp \subset \Sp$ are Gray-localizations by \cref{Graypre}.

