\subsection{A Whitehead theorem for $\infty$-categories with adjoints}

In this section we prove a directed analogue of Whitehead's theorem \cite[Theorem 1.1.,1.2.]{Whitehead} for $\infty$-categories with adjoints (\cref{homten})
and categorical spectra with adjoints (\cref{maf}).

%\subsection{Spectra with duals}

\subsubsection{Homotopy monoidal categories}

\begin{definition}

Let $\mC$ be an $\infty$-category, $X \in \mC$ and $n \in \bN.$
The $n$-th homotopy monoidal category is 
$$\Pi_n(\mC,X):= \Ho_1(\Omega^{n}(\mC,X)).$$	

\end{definition}

\begin{remark}

Since $\Omega^{n}(\mC,X)$ is an $\bE_n$-monoidal $\infty$-category,
$\Pi_n(\mC,X)= \Ho_1(\Omega^{n}(\mC,X))$ is an $\bE_n$-monoidal $(1,1)$-category, i.e.
a monoidal $(1,1)$-category for $n=1$, a braided monoidal $(1,1)$-category for $n=2$
and a symmetric monoidal $(1,1)$-category for $n> 2.$

\end{remark}

\begin{example}
Let $\mC$ be a space, $X \in \mC $ and $\ell \geq 0.$ 
The category $\Pi^\ell(\mC,X)$ is a Picard groupoid and so its underlying groupoid 
is the product of the set of isomorphism classes and the delooping of the group of automorphisms of the tensor unit: there is a canonical equivalence $\Pi^\ell(\mC,X) \simeq 
\pi^\ell(\mC,X) \times B \pi^{\ell+1}(\mC,X).$ 

\end{example}

\begin{definition}
Let $\mC$ be a categorical spectrum and $n \in \bZ$. 
The $n$-th stable homotopy monoidal category is 
% and $X \in \Omega^\infty(\mC)$. %$$\Pi_0(\mC):=\Ho_1_0( \Omega^\infty(\mC)), $$%$ \Pi_1(\mC):=\Ho_1_1( \Omega^\infty(\mC)),$$
$$\Pi_n(\mC):= \Ho_1(\Omega^\infty(\Omega^{n}(\mC)).$$	

\end{definition}

\begin{remark}Let $\mC$ be a categorical spectrum and $n \geq 0.$ There is a canonical equivalence $$\Pi_n(\mC) \simeq \Pi_n(\Omega^\infty(\mC),\tu).$$	

\end{remark}

For the following proposition note that for every $\infty$-category
$\mC$ the canonical map $\pi_0\iota_0(\mC) \to \pi_0\tau_0(\mC)$ exhibits the target as the quotient of the set of equivalence classes of objects of $\mC$ modulo the equivalence relation $\sim$ that two objects are linked by a zig-zag of morphisms.

\begin{proposition}
Let $\ell \geq 0 $ and $\mC$ an $\infty$-category that admits left (right) adjoints, $X \in \mC$
and $A,B \in \Pi_\ell(\mC,X)$.
The canonical map 
$$ \Pi_\ell(\mC,X)(A,B) \to \Pi_\ell(\tau_0\mC,X)(A,B)$$
identifies with the quotient map 
$$\{ \mathrm{Equivalence} \ \mathrm{classes} \ \mathrm{in} \ \Omega^\ell(\mC,X)(A,B) \}  \to \{ \mathrm{Equivalence} \ \mathrm{classes} \ \mathrm{in} \ \Omega^\ell(\mC,X)(A,B) \}/\sim .$$

%$$ \pi_0\iota_0(\Omega^\ell(\mC,X)(A,B)) \to \pi_0\tau_0(\Omega^\ell(\mC,X)(A,B)).$$

\end{proposition}

\begin{proof}
Let $n \geq m \geq 1 $ and $\mC$ an $\infty$-category that admits left (right) adjoints
for morphisms of dimension smaller $n+1$ and $X \in \mC.$
By \cref{korfh} the canonical functor $$\tau_{1}(\Omega^\ell(\mC, X)) \to \Omega^\ell(\tau_{0}(\mC),X)$$	
is an equivalence. The latter induces an equivalence
$$\Ho(\tau_{1}(\Omega^\ell(\mC, X))) \to \Ho(\Omega^\ell(\tau_{0}(\mC),X)).$$	
Hence the canonical functor
$ \Ho(\Omega^\ell(\mC,X)) \to \Ho(\Omega^\ell(\tau_{0}(\mC),X))$
identifies with the functor
$$ \Ho(\Omega^\ell(\mC,X)) \to \Ho(\tau_{1}(\Omega^\ell(\mC, X))) $$
that induces on hom sets between two objects $A,B \in \Ho(\Omega^\ell(\mC,X))$
the canonical map $$ \pi_0\iota_0(\Omega^\ell(\mC,X)(A,B)) \to \pi_0\tau_0(\Omega^\ell(\mC,X)(A,B)).$$

\end{proof}

%We will prove the following Whitehead theorem:

\begin{theorem}\label{homten}Let $\mC$ be an $\infty$-category that admits left (right) adjoints and $n \geq 1$.
A functor $\F: \mC \to \mD$ is an $n$-equivalence if and only if for every $X \in \mC$ the induced functor $\Pi_\m(\mC,X) \to \Pi_\m(\mD, \F(X))$ is an equivalence for every $\m < n.$
In particular, $\F: \mC \to \mD$ is an equivalence if and only if for every $X \in \mC$ the induced graded functor $\Pi_*(\mC,X) \to \Pi_*(\mD, \F(X))$ is an equivalence.

\end{theorem}

\begin{proof}
For $n=1$ the statement is tautological. So let $n > 1.$
If $\F: \mC \to \mD$ is an $n$-equivalence, it is an $\m+1$-equivalence for any $\m < n.$ 
Thus for every $X \in \mC$ the induced functor $\Omega^{\m}(\mC,X) \to \Omega^{\m}(\mD, \F(X))$ is a 1-equivalence, i.e. induces an equivalence on homotopy categories, so that the induced functor $\Pi_{\m}(\mC,X) \to \Pi_{\m}(\mD, \F(X))$ is an equivalence.

Next we prove the converse by induction on $n \geq 1.$ We prove the case of right adjoints. The case of left adjoints is dual.
Assume the converse holds for $n$ and let $\Pi_\m(\mC,X) \to \Pi_\m(\mD, \F(X))$ be an equivalence for every $\m < n+1.$ We wish to see that $\F$ is an $n+1$-equivalence.
By \cref{reft} the functor $\F$ is an $n+1$-equivalence if and only if $\F$ is essentially surjective and for every $X,Y \in \mC$ the induced functor $\theta_{X,Y}: \Mor_\mC(X,Y) \to \Mor_\mD(\F(X),\F(Y))$ is an $n$-equivalence.
Since $\F$ induces an equivalence on $\Pi_1$, the functor $\F$ and the functor $\theta_{X,Y}$ are essentially surjective.
Again by \cref{reft} the functor $\theta_{X,Y}$ is an $n$-equivalence if and only if it it is essentially surjective and induces for every morphisms $\alpha, \beta: X \to Y$ in $\mC$ an $n$-1-equivalence $\rho:\Mor_{ \Mor_\mC(X,Y)}(\alpha,\beta) \to \Mor_{\Mor_\mD(\F(X),\F(Y))}(\F(\alpha),\F(\beta)).$
So it remains to see that for every morphisms $\alpha, \beta: X \to Y$ in $\mC$ the functor $\rho$ is an $n$-1-equivalence.

Since $\F$ induces an equivalence on $\Pi_\m$ for every $\m < n+1,$ the functor $\theta_{X,X}$ induces an equivalence on $\Pi_\m$ for every $\m < n.$ So by induction hypothesis $ \theta_{X,X} $ is an $n$-equivalence.
Since $\theta_{X,X}$ is an $n$-equivalence, $\rho$ is an $n$-1-equivalence for $X=Y$ and arbitrary $\alpha, \beta.$
Let $\gamma$ be a right adjoint of $\alpha.$ We obtain an induced adjunction
$ \alpha_*: \Mor_\mC(X,X) \rightleftarrows \Mor_\mC(X,Y): \gamma_*$
giving an equivalence $$\Mor_{\Mor_\mC(X,Y)}(\alpha,\beta) \simeq \Mor_{\Mor_\mC(X,X)}(\id, \gamma \circ \beta).$$
Since $\gamma$ is right adjoint to $\alpha$, also $\F(\gamma)$ is right adjoint to $\F(\alpha)$. We obtain an induced adjunction
$$ \F(\alpha)_*: \Mor_\mD(\F(X),\F(X)) \rightleftarrows \Mor_\mD(\F(X),\F(Y)): \F(\gamma)_*$$
giving an equivalence $  \Mor_{\Mor_\mD(\F(X),\F(Y))}(\F(\alpha),\F(\beta)) \simeq \Mor_{\Mor_\mD(\F(X),\F(X))}(\id, \F(\gamma) \circ \F(\beta)).$

The functor $\rho$ identifies with the $n$-1-equivalence:
$$\Mor_{\Mor_\mC(X,Y)}(\alpha,\beta) \simeq \Mor_{\Mor_\mC(X,X)}(\id, \gamma \circ \beta) \xrightarrow{} \Mor_{\Mor_\mD(\F(X),\F(X))}(\id, \F(\gamma) \circ \F(\beta))$$$$ \simeq  \Mor_{\Mor_\mD(\F(X),\F(Y))}(\F(\alpha),\F(\beta)).$$


\end{proof}

\begin{corollary}\label{homtent}
Let $\mC$ be an $\infty$-category that admits left (right) adjoints.
A functor $\F: \mC \to \mD$ between connected $\infty$-categories is an equivalence if and only if the induced graded functor $\Pi_{*+1}(\mC) \to \Pi_{*+1}(\mD)$ is an equivalence.	

\end{corollary}

\begin{proof}
The functor $\Pi_{*}\F$ is an equivalence if and only if $\Pi_{*+1}\F$ is an equivalence:
if $\Pi_{1}\F$ is an equivalence, the essentially surjective functor $\Pi_{0}\F$
is fully faithful and so an equivalence. So the statement follows from \cref{homten}. 

\end{proof}

\begin{corollary}\label{klop} Let $\mC$ be a monoidal $\infty$-category that admits left (right) duals. A monoidal functor $\F: \mC \to \mD$ is an equivalence if and only if the induced graded functor $\Pi_*(\mC,\tu) \to \Pi_*(\mD,\tu)$ is an equivalence.

\end{corollary}

\begin{proof}
A monoidal functor $\F: \mC \to \mD$ is an equivalence if and only if the 
delooping $B\F: B\mC \to B\mD$ is an equivalence.
Since $B\mC$ admits left (right) adjoints, $B\F$ is an equivalence if and only if
$\Pi_{*+1}B\F$ is an equivalence by \cref{homtent}. So the statement follows from the equivalence $\Pi_{*+1}B\F \simeq \Pi_{*}\F.$

\end{proof}

\begin{theorem}\label{maf} Let $\mC$ be a categorical spectrum with left (right) adjoints.
A map $\F: \mC \to \mD$ of spectra is an equivalence if and only if the induced $\bZ$-graded functor $\Pi_*(\mC) \to \Pi_*(\mD)$ is an equivalence.

\end{theorem}

%\cref{klop} implies \cref{maf}.
\begin{proof}%[Proof of \cref{maf}]

The only-if implication is clear. A map of spectra $\F: \mC \to \mD$ is an equivalence 
if and only if for every $n \in \bZ$ the induced functor $ \Omega^\infty(\Omega^n(\F))$ is an equivalence. The latter functor underlies a symmetric monoidal functor whose source  admits left (right) duals.
Hence by \cref{klop} it suffices to verify that for every $\ell \geq 0$ the functor $\Pi_\ell(\Omega^\infty(\Omega^n(\mC)), \tu) \to \Pi_\ell(\Omega^\infty(\Omega^n(\mD)),\tu)$ is an equivalence. The latter functor identifies with the functor $\Pi_{n+\ell}(\mC) \to \Pi_{n+\ell}(\mD)$.

\end{proof}

