\section*{Appendix A\label{appendixA}}

\setcounter{equation}{0}
In this appendix we do the details with respect to scaling of the model equations. 

We only need to consider a system of the form 
\begin{align}
    -\partial_z e + \mu_0 \partial_t h &= 0,\label{eq1} \\
   \partial_z h - \epsilon_0 \partial_t (e + p_L) &=  \epsilon_0\partial_t p.\label{eq2}
\end{align}
By letting $p_L=p_1, p_2, p_3$, in front of the slab, inside the slab, and behind the slab, and letting $p=0$ in front of the slab and behind the slab, we recover the model equations from the text.

We start by introduce arbitrary scales for all dependent and independent variables ion the equation. At this point, the scales are unknown.
\begin{align}
t&=\bar{t} t'\nonumber\\
z&=\bar{z} z' \nonumber\\
e&=\bar{e} e'\nonumber\\
h&=\bar{h} h'\nonumber\\
p&=\bar{p} p'
\end{align}
Here $e'$, $h'$, and $p'$ are functions of of dimensionless variables $z',t'$,
\begin{align}
e'(z', t') &= \frac{e(\bar{z} z', \bar{t} t')}{\bar{e}}\nonumber\\
h'(z', t') &= \frac{h(\bar{z} z', \bar{t} t')}{\bar{h}}\nonumber\\
p'(z', t') &= \frac{p(\bar{z} z', \bar{t} t')}{\bar{p}}
\end{align}
Given this, we evidently have
\begin{equation}
\partial_{t'} e' = \partial_{t'} \frac{e(\bar{z} z', \bar{t} t')}{\bar{e}} = \frac{\bar{t}}{\bar{e}} \partial_t e(z, t). 
\end{equation}
Treating derivative $e$ with respect to $z$ in the same way, we have
\begin{align}
\partial_t e &= \frac{\bar{e}}{\bar{t}} \partial_{t'} e' \nonumber \\
\partial_z e &= \frac{\bar{e}}{\bar{z}} \partial_{z'} e'.
\end{align}
Similar formulas hold for $h$ and $p$
\begin{align}
\partial_t h &= \frac{\bar{h}}{\bar{t}} \partial_{t'} h', \nonumber \\
\partial_z h &= \frac{\bar{h}}{\bar{z}} \partial_{z'} h',\nonumber\\
\partial_t p &= \frac{\bar{p}}{\bar{t}} \partial_{t'} p'.
\end{align}

Inserting these expressions into equation (\ref{eq1}) we get
\begin{align}
-\frac{\bar{e}}{\bar{z}} \partial_{z'} e' + \frac{\mu_0 \bar{h}}{\bar{t}} \partial_{t'} h' &= 0 \\
&\Downarrow\\
-\partial_{z'} e' + \frac{\mu_0 \bar{z} \bar{h}}{\bar{t} \bar{e}} \partial_{t'} h' &= 0 \\
&\Downarrow\\
-\partial_{z'} e' + \varepsilon_1 \partial_{t'} h' &= 0,\label{DimensionlessEq1}
\end{align}
where we have introduced the dimensionless quantity
\begin{equation}
\varepsilon_1 = \frac{\mu_0 \bar{z} \bar{h}}{\bar{t} \bar{e}} \label{eps1}
\end{equation}
From equation (42) we get
\begin{align}
\frac{\bar{h}}{\bar{z}} \partial_{z'} h' + \frac{\varepsilon_0}{\bar{t}} \partial_{t'} \left( \bar{e} e' + p_L\right)  &= \frac{\epsilon_0\bar{p}}{\bar{t}} \partial_{t'} p'\\
&\Downarrow \\\partial_{z'} h' - \frac{\varepsilon_0 \bar{e} \bar{z}}{\bar{h} \bar{t}} \partial_{t'} \left( e' + \frac{p_L}{\bar{e}}  \right) &= \frac{\epsilon_0\bar{z}\bar{p}}{\bar{h}\bar{t}} \partial_{t'} p'\\
&\Downarrow \\\partial_{z'} h' - \epsilon_2 \partial_{t'} \left( e' + \frac{p_L}{\bar{e}} \right) &= \epsilon_4 \partial_{t'} p',
\end{align}
where we have  define two  additional dimensionless quantities
\begin{align}
    \epsilon_2&=\frac{\varepsilon_0 \bar{e} \bar{z}}{\bar{h} \bar{t}},\\
    \epsilon_4&=\frac{\epsilon_0\bar{z}\bar{p}}{\bar{h}\bar{t}}.
\end{align}
For the linear polarization term we have
\begin{align}
    \frac{p_L}{\bar{e}}(z,t) &= \frac{1}{\bar{e}}\int_{-\infty}^{t} ds \, \chi_L(s - t) e(z, s)\nonumber\\
    &=\bar{t}\;\overline{\chi_L}\int_{-\infty}^{t'} ds' \, \frac{\chi_L(\bar{t}(t'-s'))}{\overline{\chi_{L}}} \frac{e(\bar{z} z',\bar{t},s')}{\bar{e}}\nonumber\\
    &=\epsilon_3\int_{-\infty}^{t'} ds' \, \chi'_L(s' - t') e'(z', s'),\label{DimesionlessDispersion}
\end{align}
where  $\overline{\chi_{L}}$ is a dimensional constant measuring the size of $\chi_L$, and where 

\begin{align}
    \chi'_L(\xi)&=\frac{\chi_L(\xi)}{\overline{\chi_{L}}},\nonumber\\
    \epsilon_3&=\bar{t}\;\overline{\chi_L}.\label{chiAndEps4}
\end{align}
From the above derivations and definitions we conclude that the dimensionless version of equation (\ref{eq1}), is
\begin{align}
     \partial_z' h' - \epsilon_2 \partial_t' (e' + \epsilon_3 p'_L) &=  \epsilon_4\partial_t' p',\nonumber
\end{align}
where 
\begin{align}
    p'_L=\int_{-\infty}^{t'} ds' \, \chi'_L(s' - t') e'(z', s').\label{DimensionlessEq2}
\end{align}

The dimensionless equations (\ref{DimensionlessEq1}) and (\ref{DimensionlessEq2}) is simplified by choosing scales such that $\epsilon_1=\epsilon_2=\epsilon_3=1$. It is easy to see that these conditions are satisfied if 
\begin{align}
    \bar{z}&=c\bar{t},\nonumber\\
    \bar{e}&=\sqrt{Z_0 \bar{I}},\nonumber\\
     \bar{h}&=\sqrt{\frac{\bar{I}}{Z_0}},\nonumber\\
    \overline{\chi_L}&=\frac{1}{\bar{t}},\label{Scales}
\end{align}
where $c$ is the speed of light,  $Z_0=\sqrt{\frac{\mu_0}{\epsilon_0}}$ is the vacuum impedance, and $\bar{I}=\bar{e}\bar{h}$ is equal to the intensity for a mode of the electromagnetic field of amplitude $(\bar{h},\bar{e})$ traveling along the $z$-axis.

Note that the scales $\bar{I}$, $\bar{t}$, and $\bar{p}$, are still arbitrary at this point, and that the sole remaining dimensionless parameter in the model is
\begin{align}
     \epsilon\equiv\epsilon_4=\frac{\epsilon_0c\sqrt{Z_0}\bar{p}}{\sqrt{\bar{I}}}.
\end{align}

In this paper we assume that the formulas for the Fourier transform looks the same in scaled and unscaled variables. For this to be the case there need to be a particular relation between the scales for the Fourier transform of the function and the scales for the function and time. There also needs to be a particular relation between the scales for frequency and time.
We introduce scales for $f$, $\hat{f}$, and $\omega$ through the identities
\begin{align}
  f&=\bar{f} f',\nonumber\\
  \hat{f}&=\bar{\hat{f}}\hat{f}',\nonumber\\
  \omega&=\bar{\omega}\omega'.\label{FourierScales}
\end{align}
Inserting these expressions into the first of the equations defining the Fourier transform (\ref{MyFourier}), we have 
\begin{align}
    \bar{\hat{f}}\frac{\hat{f}(\bar{\omega}\omega')}{\bar{\hat{f}}}&=\bar{f}\bar{t}\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{\infty}dt'\;\frac{f(\bar{t}t')}{\bar{f}}e^{i\bar{\omega}\bar{t}\omega' t'},\nonumber\\
    &\Downarrow\nonumber\\
    \hat{f}'(\omega')&=\frac{\bar{f}\bar{t}}{ \bar{\hat{f}}}\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{\infty}dt'\;f'(t')e^{i\bar{\omega}\bar{t}\omega' t'},\label{DFourier1}  
\end{align}
where we have defined the dimensionless functions 
\begin{align}
    f'(t')&=\frac{f(\bar{t}t')}{\bar{f}},\nonumber\\
    \hat{f}'(\omega')&=\frac{\hat{f}(\bar{\omega}\omega')}{\bar{\hat{f}}}.\label{DimensionlessFourierTransformPair}
\end{align}
From (\ref{DFourier1}) it is evident that the Fourier transform relation connecting the unscaled variables $f$, and $\hat{f}$ are the same as the one connecting the scaled Fourier transform variables $f'$, and $\hat{f}'$ only if 
\begin{align}
    \bar{\hat{f}}&=\bar{f}\bar{t},\nonumber\\
    \bar{\omega}&=\frac{1}{\bar{t}}.\label{FourierScales}
\end{align}
It is easy to check that if we assume the choice of scales (\ref{FourierScales}), then the second equation defining the Fourier transform also looks the same in scaled and unscaled variables.

In section 3 of the main text we introduce a specific choice for the nonlinear polarization
\begin{align}
    p(z,t)&=\left((1 - \theta) p_K(z,t) + \theta p_R(z,t)\right).\label{NonlinearPolarization}
\end{align}
Here  $\theta$ is a dimensionless constant measuring the relative size of the two components $p_K$ and $p_R$, which are given by 

\begin{align}
    p_K(z, t) &=  e(z, t) \int_{-\infty}^{t} ds \, \chi_K(s - t) e^2(z, s), \\
    p_R(z, t) &= e(z, t) \int_{-\infty}^{t} ds \, \chi_R(s - t) e^2(z, s).
\end{align}
Note that at this point all variables are dimensional quantities, scales have not been introduced yet.
Introducing the scales in the expression for $p_K$ we have
\begin{align}
   p_K(z, t) &=  \bar{e}^3\;\overline{\chi}\bar{t}\;\;\frac{e(\bar{z}z', \bar{t}t')}{\bar{e}} \int_{-\infty}^{t'} ds' \, \frac{\chi_K(\bar{t}(s' - t'))}{\overline{\chi}} \left(\frac{e(\bar{z}z', \bar{t}s')}{\bar{e}}\right)^2, \\  
 &=\left(\frac{\overline{\chi}}{\overline{\chi_L}}\right)\bar{e}^3\;\overline{\chi_L}\bar{t}\;\;\frac{e(\bar{z}z', \bar{t}t')}{\bar{e}} \int_{-\infty}^{t'} ds' \, \frac{\chi_K(\bar{t}(s' - t'))}{\overline{\chi}} \left(\frac{e(\bar{z}z', \bar{t}s')}{\bar{e}}\right)^2, \\  
 &=\left(\frac{\overline{\chi}}{\overline{\chi_L}}\right)\bar{e}^3\;\;e'(z',t')\int_{-\infty}^{t'} ds' \,\chi'_K(s'-t') e'(z',s')^2,\\
 &=\eta\bar{e}^3\;\;e'(z',t')\int_{-\infty}^{t'} ds' \,\chi'_K(s'-t') e'(z',s')^2,
\end{align}
where by definition 
\begin{align}
    \chi'_K(\xi)&=\frac{\chi_K(\bar{t}\xi)}{\overline{\chi}},
\end{align}
and where
\begin{align}
    \eta=\left(\frac{\overline{\chi}}{\overline{\chi_L}}\right),
\end{align}
is a dimensional constant measuring the relative size of the nonlinear and linear polarization.

Treating the expression for the other component of the nonlinear polarization, $p_R$, in the same way, we get from (\ref{NonlinearPolarization}) that
\begin{align}
    p(z,t)=\bar{p}\left((1 - \theta) p'_K(z',t') + \theta p'_R(z',t')\right),
\end{align}
where $z=\bar{z}z',t=\bar{t}t'$ and where
\begin{align}
    \bar{p}&=\eta\bar{e}^3,\\
    p'_K(z',t')&=e'(z',t')\int_{-\infty}^{t'} ds' \,\chi'_K(s'-t') e'(z',s')^2,\\
    p'_R(z',t')&=e'(z',t')\int_{-\infty}^{t'} ds' \,\chi'_R(s'-t') e'(z',s')^2,\\
\end{align}


