  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
    \obsWiggly{0}{0}
  \end{tikzpicture}=
  \begin{bmatrix}
    1 & 0 \\ 
    0 & 1-p
  \end{bmatrix},
\end{equation}
while the active gate is the same as the active gate in the $p=1$ case
multiplied by a factor of $p$,
\begin{equation}\label{eq:defActiveP}
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \propS{0}{0}{colUactive}{black}
  \end{tikzpicture}=
  p\ 
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \prop{0}{0}{colUactive}
  \end{tikzpicture},\qquad
  \begin{tikzpicture}[baseline={([yshift=-0.85ex]current bounding box.center)},scale=0.5]
    \prop{0}{0}{colUactive}
    \node at (-0.875,-0.875) {$m$};
    \node at (0.875,-0.875) {$n$};
