    \foreach \t in {7,...,9}{\MErd{18-\t}{\t-0.5}}
  \end{tikzpicture}
  = 2^{-(2l-1+t)}\left[1+(1-p)^t\right]^{2l-1}
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \foreach \x in {6}{
