    \foreach \t in {7,...,9}{\obsZero{18-\t}{\t-0.5}}
    \foreach \t in {4,5}{\obsZero{5+\t}{\t+0.5}}
    \foreach \t in {4,5}{\obsZero{5+\t}{\t+1.5}}
    \foreach \t in {4}{\obsZero{5+\t}{\t+2.5}}
    \foreach \t in {4}{\obsZero{5+\t}{\t+3.5}}
  \end{tikzpicture}
  =2^{-t}=T_{t}(1).
\end{equation}
To find the upper bound we use that the diagonal transformation in~\eqref{eq:defInactiveP} together with the projector to the state $1$ sum up to the identity,
\begin{equation}
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
    \obsWiggly{0}{0}
  \end{tikzpicture}+
  p\,
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
    \obsOne{0}{0}
  \end{tikzpicture}=
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
  \end{tikzpicture},
\end{equation}
which -- together with the positivity of all the entries of the local gate -- gives
\begin{equation}
\label{eq:SMlowerb}
  T_{t}(p)\le 
  2^{-t}
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \foreach \x in {6}{
      \foreach \y in {2,4,6,8}{
        \bendLud{\x+2}{\y+0.5}{\y+1.5}
      }
    }
    \foreach \t in {4,6,8}{\propS{8.5}{\t}{colU}{black}}
    \foreach \t in {5,7}{\propS{9.5}{\t}{colU}{black}}
    \foreach \t in {6}{\propS{10.5}{\t}{colU}{black}}
    \foreach \t in {3,...,6}{\MEld{5+\t}{\t-0.5}}
    \foreach \t in {7,...,10}{\MErd{18-\t}{\t-0.5}}
  \end{tikzpicture}=1=T_{t}(0).
\end{equation}

In summary, we have the following bounds on the $p$-dependent partition sum,
\begin{equation}\label{eq:BoundsZinfty}
  2^{-t}
  \left(\frac{1+(1-p)^t}{2}\right)^{2l-1}
  \le
  \lim_{s\to\infty} Z_{l,t}(p,s)
  \le
  \left(\frac{1+(1-p)^t}{2}\right)^{2l-1}.
\end{equation}
In particular, this means that the partition sum in the $s\to\infty$ limit is in general larger than at $p=1$,
\begin{equation}
  \lim_{s\to\infty} Z_{l,t}(p,s)\ge
  \lim_{s\to\infty} Z_{l,t}(1,s).
\end{equation}

The above bounds hold for any $p$, and are tight, since they are saturated
by the two deterministic limits of the model. However, we can find an alternative
lower bound that is tighter for $p\le \frac{1}{2}$. By decomposing the
transformation~\eqref{eq:defInactiveP} as 
\begin{equation}
\label{eq:bluedot}
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
    \obsWiggly{0}{0}
  \end{tikzpicture}=
  (1-p)\,
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
  \end{tikzpicture}+
  p\,
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \tgridLine{0}{-0.5}{0}{0.5}
    \obsZero{0}{0}
  \end{tikzpicture},
\end{equation}
we have
\begin{equation}
  T_t(p)\ge (1-p)^t T_t(0)=(1-p)^t.
\end{equation}
This gives 
\begin{equation}\label{eq:StricterLowerBoundZinfty}
  \lim_{s\to\infty} Z_{l,t}(p,s)\ge
  \left(\frac{1+(1-p)^t}{2}\right)^{2l-1}(1-p)^t.
\end{equation}

\subsection{Phase transition in the dynamical large deviations}
The occurrence of the phase transition is a consequence of different scaling of
$Z_{l,t}(p,s)$ with the subregion size in the two limits. To show this, we
define the cumulant generating function $F_{l,t}(p,s)$, and its asymptotic
value $F(p,s)$ as
\begin{equation}
  F_{l,t}(p,s)=\frac{1}{l t} \log Z_{l,t}(p,s),\qquad
  F(p,s)=\lim_{l\to\infty} F_{l,l\xi}(p,s),
\end{equation}
where we introduced $\xi$ to represent the asymptotic ratio between the two
sizes of the space-time region, $\xi=t/l$.  Plugging in the results above we
have a well-behaved expansion around $s\approx 0$,
\begin{equation}\label{eq:AsymptoticScaling1}
    F(p,s)=-p s + \frac{1}{2} p s^2 (1+A_p) + \mathcal{O}(s^3),\qquad
   -\min\{1,\frac{3 p}{2}\} \le A_p \le \frac{p}{2},
\end{equation}
where we introduced $A_p$ to denote a $p$-dependent constant that we can bound
as shown above.  On the other hand, in the limit $t\to \infty$ the rescaled
cumulant generating function vanishes,
\begin{equation}\label{eq:AsymptoticScaling2}
    \lim_{s\to\infty} F(p,s) = 0.
\end{equation}
We now note that for finite $l,t$ by definition $F_{l,t}(p,s)$ is analytic and
\emph{convex} \cite{touchette2009the-large}. Combining this with the above
asymptotic scaling we have that in the thermodynamic limit the first derivative
must become discontinuous, and the model exhibits a first-order phase
transition.

\subsection{Trotter limit}
In the appropriate scaling limit of large $t$ and small $p$, the stochastic Floquet-East
model reproduces the dynamics of the standard continuous-time stochastic
East model~\cite{jackle1991a-hierarchically,ritort2003glassy}. Interestingly,
the above argument carries over to this limit as well. 

We start by introducing the continuous-time partition sum
$\mathcal{Z}_{l,t}(\Gamma,s)$, where $t$ now denotes \emph{real time} (and not
the number of time-steps), $l$ is as before the size of the subsystem of
interest, and $\Gamma$ is the rate with which the spins in the continuous-time
model flip. The dynamics of the continuous-time model is approximated by the
stochastic Floquet-East when for a small $\Delta$ we scale the number of
time-steps as $t/\Delta$, while the probability parameter goes as $\Delta
\Gamma$. This gives the following continuous-time limit of the partition sum
\begin{equation}
  \mathcal{Z}_{l,t}(\Gamma,s)=\lim_{\Delta\to 0}Z_{l,\frac{t}{\Delta}}(\Gamma \Delta,s).
\end{equation}
Using the small-$s$ expansion of the discrete-time partition sum we get,
\begin{equation}
  \mathcal{Z}_{l,t}(\Gamma,s)=1-s\Gamma l t + s^2 \frac{l t \Gamma}{2}(1+l t \Gamma) +
  \mathcal{O}(s^3),
\end{equation}
where we used that the upper and lower bounds in Eq.~\eqref{eq:boundSecondOrderZ}
coincide in the Trotter limit, and give us an exact expression.  Similarly, we
can plug-in the $s\to\infty$ bounds to obtain
\begin{equation}
  \mathrm{e}^{-\Gamma t} \left(\frac{1+\mathrm{e}^{-\Gamma t}}{2}\right)^{2l-1}
  \le\lim_{s\to\infty} \mathcal{Z}_{l,t}(\Gamma,s) \le
  \left(\frac{1+\mathrm{e}^{-\Gamma t}}{2}\right)^{2l-1}.
\end{equation}
Note that here we need to use the lower bound given by Eq.~\eqref{eq:StricterLowerBoundZinfty}, 
since for small $p$ it is stricter than that of Eq.~\eqref{eq:BoundsZinfty}.

We now have all the ingredients to understand the scaling of the
thermodynamic-limit of the continuous-time cumulant generating function,
\begin{equation}
  \mathcal{F}(\Gamma,s)=\lim_{l,t\to\infty} \frac{1}{l t} \log \mathcal{Z}_{l,t}(\Gamma,s).
\end{equation}
As before, for small $s$ it has a well-behaved expansion around $0$, while it goes to zero for $s\to\infty$. 
\begin{equation}
  \left.\mathcal{F}(\Gamma,s)\right|_{s\approx 0}
  =-\Gamma s +\frac{s^2}{2}\Gamma +\mathcal{O}(s^3),\qquad
  \lim_{s\to\infty} \mathcal{F}(\Gamma,s)=0,
\end{equation}
therefore our results prove the existence of the phase transition also in the Trotter limit.

\section{Distribution of empty space-time regions}\label{sec:zeros}
\begin{figure}
\includegraphics[width=14cm]{Fig3.jpg}
