\subsection{The ``row-based'' algorithm behind \texttt{causal-dot-product\_torch}}
\label{al:performer}


\citet[Equation~(11)]{choromanski2020rethinking} introduced a prefix sum algorithm for causal linear attention. 
In each iteration, it returns one row of the output matrix, and we thus refer to this algorithm as the ``row-based algorithm. 


Vectors $\mtx c_j, \mtx b_j \in \mathbb{R}^{1 \times r}$, and $\mtx v_j \in \mathbb{R}^{1 \times d}$ represent the $j$-th row-vectors in matrices $\mtx{C}, \mtx{B},\mtx{V}$, respectively.
A single row of the output matrix $\mtx O$ is then computed as:
\begin{align}
\label{equ:performer1}
\mtx{O}_i=\sum_{j=1}^i \mtx b_i \mtx c_j^T \mtx v_j = \mtx b_i\sum_{j=1}^i\mtx c_j^T \mtx v_j \in \mb R^{1 \times d}
\end{align}
Let $\mtx{U}_i = \sum_{j=1}^i\mtx c_j^T\mtx v_j \in \mathbb{R}^{r \times d}$, then \Cref{equ:performer1} can be realized through  recursion:
\begin{align}
\label{equ:performer2}
\mtx{O}_i = \mtx b_i \mtx{U}_i, \quad \text{where~} \mtx{U}_i = \mtx{U}_{i-1}+\mtx c_i^T \mtx v_i.
\end{align}
The full row-based algorithm is described in Algorithm~\ref{al:row_based}.
The time complexity for processing each row of $\mtx{O}$ is $\m O(rd)$, leading to a total time complexity of $\m O(Nrd)$. The space complexity is $\m O(Nd+rd)$.

\begin{algorithm}[!t]
  \caption{\small\label{al:row_based} \texttt{Row-based} Algorithm}
  \begin{algorithmic}[1]
    \REQUIRE Matrices $\mtx{B}, \mtx{C} \in \mathbb{R}^{N \times r}$, $\mtx{V} \in \mathbb{R}^{N \times d}$.
    \STATE Initialize $\mtx{U} = (\mtx 0)_{r \times d} \in \mathbb{R}^{r \times d}$, $\mtx{O} = (\mtx 0)_{N \times d} \in \mathbb{R}^{N \times d}$.
    \FOR{$1 \le i \le N$}
      \STATE Extract row vectors $\mtx b_i \in \mathbb{R}^{1 \times r}$, $\mtx c_i \in \mathbb{R}^{1 \times r}$, $\mtx v_i \in \mathbb{R}^{1 \times d}$ from $\mtx{B}, \mtx{C}, \mtx{V}$ respectively.
      \STATE Update $\mtx{U} \leftarrow \mtx{U} + \mtx c_i^T \mtx v_i$.
      \STATE Compute $\mtx o_i = \mtx b_i \mtx{U}$.
      \STATE Store $\mtx{O}_i = \mtx o_i$.
    \ENDFOR
    \STATE Return the output $\mtx{O}$.
  \end{algorithmic}
\end{algorithm}

\subsection{\texttt{Block-based} Algorithm}
\label{al:vq}
The row-by-row computation algorithm described in \Cref{equ:performer2} is considered to be inefficient. Transformer-VQ~\citep[Equation~(28)]{lingle2023transformer} proposed a block-by-block computation method 
designed for its specific low-rank matrix operations. 
We extend this method to a general low-rank matrix product $\tilde{\mtx A}=\mtx{B}\mtx{C}$.

Let the block size be denoted as $B_c$. The block slice $[i B_c:(i+1) B_c]$ is abbreviated as $[i]$. Let $\hat{\mtx K} \in \mathbb{R}^{N \times k}$ be the approximation of $\mtx K$ obtained through the low-rank method in Transformer-VQ or other algorithms. 
Let $\mtx{M} \in \{0,1\}^{B_c \times B_c}$ be a lower triangular causal mask, where $\mtx{M}_{ij}=1$ if $j \leq i$ and $\mtx{M}_{ij}=0$ otherwise.
Then the general computation method can present as follows:
\begin{align}
\mtx O_{[i]} &= (\exp(\mtx Q_{[i]}\hat{\mtx K}_{[i]}^T)\odot \mtx M)V_{[i]}+\sum_{j=1}^{i}\exp(\mtx Q_{[i]}\hat{\mtx K}_{[j]}^T)\mtx V_j\\
&= (\mtx B_{[i]}\mtx C_{[i]}^T \odot \mtx M) \mtx V_{[i]}+\sum_{j=1}^{i}\mtx B_{[i]}\mtx C_{[j]}^TV_j\\
&= (\mtx B_{[i]}\mtx C_{[i]}^T \odot \mtx M) \mtx V_{[i]}+\mtx B_{[i]}\sum_{j=1}^{i}\mtx C_{[j]}^T\mtx V_j
\end{align}
Let $\mtx U_{[i]} = \sum_{j=1}^{i}\mtx C_{[j]}^T\mtx V_{[j]} \in \mathbb{R}^{d \times d}$. Then, we obtain:
\begin{align}
\mtx O_{[i]} &= (\mtx B_{[i]}\mtx C_{[i]}^T \odot \mtx M)\mtx V_{[i]} + \mtx B_{[i]}\mtx U_{[i-1]}\\
\mtx U_{[i]} &= \mtx U_{[i-1]}+\mtx C_{[i]}^T\mtx V_{[i]}
\end{align}
The full block-based algorithm is described in Algorithm~\ref{al:block_based}.
The time complexity for processing each block $\mtx O_{[i]}$ is $\m O(B_c^2r+B_c^2d+B_crd)$; 
there are $\left\lceil\frac{N}{B_c} \right\rceil$ blocks, leading to a total time complexity of $\m O(NB_cr+NB_cd+Nrd)$. 
If we set $B_c = \m O(d)$, the time and space complexity are $\m O(Nrd)$ and $\m O(Nd+rd)$, respectively.

\begin{algorithm}[!t]
  \caption{\small\label{al:block_based} \texttt{block-based} Algorithm}
  \begin{algorithmic}[1]
    \REQUIRE Matrices $\mtx{B}, \mtx{C} \in \mathbb{R}^{N \times r}$, $\mtx{V} \in \mathbb{R}^{N \times d}$, block size $B_c$.
    \STATE Divide $\mtx{V}$ into $T_c = \left\lceil\frac{N}{B_c} \right\rceil$ blocks $\mtx{V}_{[1]}, \dots, \mtx{V}_{[T_c]}$ of size $B_c \times d$ each.

    \STATE Divide $\mtx{B}, \mtx{C}$ into $T_c$ blocks $\mtx{B}_{[1]}, \dots, \mtx{B}_{[T_c]}; \mtx{C}_{[1]}, \dots, \mtx{C}_{[T_c]};$ of size $B_c \times r$ each.

    \STATE Initialize $\mtx{U} = (\mtx 0)_{r \times d} \in \mathbb{R}^{r \times d}$,  $\mtx{O} = (\mtx 0)_{N \times d} \in \mathbb{R}^{N \times d}$.
    \STATE Let $\mtx{M} \in \{0,1\}^{B_c \times B_c}$ be a lower triangular causal mask.

    \FOR{$0 \le i < T_c$}
      \STATE Compute $\mtx o = (\mtx B_{[i]}\mtx C_{[i]}^T \odot \mtx{M})\mtx V_{[i]} + \mtx B_{[i]}\mtx{U}$.
      \STATE Update $\mtx{U} \leftarrow \mtx{U} + \mtx C_{[i]}^T\mtx V_{[i]}$.
      \STATE Compute and store $\mtx O_{[i]} = \mtx o$.
    \ENDFOR
    \STATE Return the output $\mtx{O}$.
  \end{algorithmic}
\end{algorithm}

\subsection{\texttt{Recursion} Algorithm}\label{al:recur}

HyperAttention~\citep[Algorithm~(4)]{han2023hyperattention} proposes a recursive method to compute causal attention. 
This approach starts with partitioning the matrices into two distinct parts: one is masked and the other remains unmasked. 
Following this initial division, the method further recursively partitions the masked part while concurrently applying computation method to the unmasked areas. 

We have extended the recursive approach to the general low-rank matrix form in \Cref{eq:BCMV}. We divide $\mtx B, \mtx C, \mtx V$ recursively to enable more efficient computation of the causal attention.
As shown in Figure~\ref{fig:hpyer}, the masked attention matrix $\tilde{\mtx A} \odot \mtx M$ can be decomposed into three distinct non-zero submatrices, each half the size of the original attention matrix. Notably, the block $\mtx B_{(2)}\mtx C_{(1)}$, located entirely below the diagonal is unmasked attention. We can efficiently compute this part of the result as $\mtx B_{(2)}(\mtx C_{(1)}\mtx V_{(1)})$, enabling linear computation through right multiplication. The two diagonal blocks $\mtx B_{(1)}\mtx C_{(1)}\odot \mtx M$ and $\mtx B_{(2)}\mtx C_{(2)} \odot \mtx M$ in Fig.~\ref{fig:hpyer} represent causal attentions with half the original size. To compute these, we recursively partition them into even smaller blocks and repeat such a decomposition procedure. The full recursion algorithm is described in 
Algorithm~\ref{al:recursion_0} and Algorithm~\ref{al:recursion}.



\begin{figure}[t]
    \centering
    \includegraphics[width=0.95\textwidth]{figs/recursion.pdf}
    \caption{Visualization of the \texttt{Recursion} algorithm. Causal attention matrix can be divided into three equal-sized non-zero sections: $\mtx B_{(1)}\mtx C_{(1)}\odot \mtx M$ and $\mtx B_{(2)}\mtx C_{(2)} \odot \mtx M$ are both masked attention score matrices and $\mtx B_{(2)} \mtx C_{(1)}$ is an unmasked attention score matrix.}
    \label{fig:hpyer} 
\end{figure}

\begin{algorithm*}[!t]
  \caption{\small\label{al:recursion_0} \texttt{recursion} Algorithm}
  \begin{algorithmic}[1]
    \REQUIRE  Matrices $\mtx{B}, \mtx{C}, \mtx{V}$.
    \IF{$\mathrm{len}(\mtx{B}) \leq \mathrm{termination~block~size}$}
      \STATE Return $(\mtx{M} \odot \mtx{B}\mtx{C}^T) \mtx{V}$
    \ELSE
        \STATE Split $\mtx{B}$, $\mtx{C}$, $\mtx{V}$ into equal sized sub-matrices: $\mtx{B}_1,\mtx{B}_2$; $\mtx{C}_1,\mtx{C}_2$; $\mtx{V}_1,\mtx{V}_2$.
        \STATE $\mtx{O}_1 \leftarrow \mathrm{Recursion}(\mtx{B}_1, \mtx{C}_1, \mtx{V}_1)$
      \STATE $\mtx{O}_2 \leftarrow \mathrm{Recursion}(\mtx{B}_2, \mtx{C}_2, \mtx{V}_2)$
      \STATE $\mtx{O}_3 \leftarrow \mtx{B}_2(\mtx{C}_1^T\mtx{V}_1)$
      \STATE Return $\begin{bmatrix}
 \mtx{O}_1 & \mtx 0\\
 \mtx{O}_3 & \mtx{O}_2
\end{bmatrix}$
    \ENDIF
  \end{algorithmic}
\end{algorithm*}


\begin{algorithm*}[!t]
  \caption{\small\label{al:recursion} \texttt{recursion} Algorithm with special mask}
  \begin{algorithmic}[1]
    \REQUIRE  Matrices $\mtx{B}, \mtx{C}, \mtx{V}$, $w$, left, right.
    \IF{$\mathrm{len}(\mtx{B}) \leq \mathrm{termination~block~size}$}
        \STATE $\mtx{M}_s$ = GetMask(right-left, $w$)
        \STATE Return $(\mtx{M}_s \odot \mtx{B}\mtx{C}^T) \mtx{V}$
    \ELSE
        \STATE Split $\mtx{B}$, $\mtx{C}$, $\mtx{V}$ into equal sized sub-matrices: $\mtx{B}_1,\mtx{B}_2$; $\mtx{C}_1,\mtx{C}_2$; $\mtx{V}_1,\mtx{V}_2$. mid = $\left \lfloor  \frac{\mathrm{left}+\mathrm{right}}{2} \right \rfloor $
        \STATE $\mtx{O}_1 \leftarrow \mathrm{Recursion}(\mtx{B}_1, \mtx{C}_1, \mtx{V}_1, w, \mathrm{left}, \mathrm{mid})$
      \STATE $\mtx{O}_2 \leftarrow \mathrm{Recursion}(\mtx{B}_2, \mtx{C}_2, \mtx{V}_2, w, \mathrm{mid}, \mathrm{right})$
      \STATE $\mtx{W}_1 = [1, w, w^2, ..., w^{\mathrm{right}-\mathrm{mid}-1}]$, $\mtx{W}_2 = [w^{\mathrm{mid}-\mathrm{left}}, w^{\mathrm{mid}-\mathrm{left}-1},..., w]$
      \STATE $\mtx{O}_3 \leftarrow (\mathrm{diag}(\mtx{W}_1)\mtx{B}_2)((\mathrm{diag}(\mtx{W}_2)\mtx{C}_1)^T\mtx{V}_1)$
      \STATE Return $\begin{bmatrix}
 \mtx{O}_1 & \mtx 0\\
 \mtx{O}_3 & \mtx{O}_2
\end{bmatrix}$
    \ENDIF
  \end{algorithmic}
\end{algorithm*}



