\end{adjustbox}
\caption{Comparison of experimental \( x_1 \) (red dotted) and simulated (SGD-calibrated simulation (blue)) with fixed \( T_{\text{v}} = 80.0 \,\text{k}\Omega \), \( T_{\text{con}} = 7.000 \), \( K = 0.050 \).}
\label{fig:sgd_fixed}
\end{figure}

\begin{figure}
\centering
