\section{Proofs and Derivations}
\label{app:sec:proof}

\subsection{Proof of \Cref{theory:sec:dpo}}
In this section, we provide a detailed proof of \Cref{theory:sec:dpo}, demonstrating that the objective of DPO corresponds to the forward KL divergence. Starting from \Cref{sec::method::pi_g} and \Cref{sec:method::dkl_g_r}, we extand the dpo loss $\mathcal{L}_{dpo}(K=2)$ from pair preference data to K samples selection, where the sigmoid needs to be replaced with softmax to present the soft distribution. Utilizing the definition of $\hat{p}_\theta(\rvx_{0:T})$ :
\[
\frac{\hat{p}_\theta(\rvx_{0:T} | \mathbf{c})}{p_{ref}(\rvx_{0:T}| \mathbf{c})}
\propto 
\left( \frac{p_\theta(\rvx_{0:T} | \mathbf{c})}{p_{ref}(\rvx_{0:T} | \mathbf{c})} \right)^{\beta}
\]

and by combining \Cref{eq:reward}, we can extend the dpo loss to: 
\begin{align}
\mathcal{L}_{\text{dpo}}(\theta) 
&= \mathbb{E}_{c \sim \mathcal{D}_c} \mathbb{E}_{p_{\text{ref}}(\{\rvx_{0:T}\}_{1:K} | c)} \left[
    - \sum_{i=1}^{K} \frac{e^{ r(c, \{\rvx_{0:T}\}_i)}}{\sum_{j=1}^{K} e^{ r(c, \{\rvx_{0:T}\}_j)}} 
    \log \left( \frac{e^{\beta \log \frac{p_\theta(\{\rvx_{0:T}\}_i | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_i | c)}}}
    {\sum_{j=1}^{K} e^{\beta \log \frac{p_\theta(\{\rvx_{0:T}\}_j | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_j | c)}}} \right)
\right] \notag \\
&= \mathbb{E}_{c \sim \mathcal{D}_c} \mathbb{E}_{p_{\text{ref}}(\{\rvx_{0:T}\}_{1:K} | c)} \left[
    - \sum_{i=1}^{K} \frac{e^{ r(c, \{\rvx_{0:T}\}_i)}}{\sum_{j=1}^{K} e^{ r(c, \{\rvx_{0:T}\}_j)}} 
    \log \left( \frac{\log \frac{p_\theta(\{\rvx_{0:T}\}_i | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_i | c)}^{\beta}}
                     {\sum_{j=1}^{K} \log \frac{p_\theta(\{\rvx_{0:T}\}_j | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_j | c)}^{\beta}} \right)
\right] \notag \\
&= \mathbb{E}_{c \sim \mathcal{D}_c} \mathbb{E}_{p_{\text{ref}}(\{\rvx_{0:T}\}_{1:K} | c)} \left[
    - \sum_{i=1}^{K} \frac{e^{ r(c, \{\rvx_{0:T}\}_i)}}{\sum_{j=1}^{K} e^{ r(c, \{\rvx_{0:T}\}_j)}} 
    \log \left( \frac{\frac{\hat{p}_\theta(\{\rvx_{0:T}\}_i | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_i | c)}}
                     {\sum_{j=1}^{K} \frac{\hat{p}_\theta(\{\rvx_{0:T}\}_j | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_j | c)}} \right)
\right]
\label{eq:dpo-rw}
\end{align}


When $K \rightarrow \infty$, for arbitrary function $g$, the estimate $\frac{1}{K} \sum_{i=1}^K g(\{\rvx_{0:T}\}_i)$ is unbiased since $\{\{\rvx_{0:T}\}_i\}_{i=1}^K$ are sampled from $p_{\text{ref}}(\cdot | c)$,, i.e.,
\[
\lim_{K \to \infty} \frac{1}{K} \sum_{i=1}^{K} g(\{\rvx_{0:T}\}_i) = \mathbb{E}_{p_{\text{ref}}(\rvx_{0:T} | c)}[g(\rvx_{0:T})].
\]
For $g$ is the relative  $g(c, \rvx_{0:T}) = \frac{\hat{p}_\theta(\rvx_{0:T} | c)}{p_{\text{ref}}(\rvx_{0:T} | c)}$, and $e^{ r(c, \{\rvx_{0:T}\}_j )}$, we have:

\begin{align*}
\sum_{j=1}^{K} \frac{\hat{p}_\theta(\{\rvx_{0:T}\}_j | c)}{p_{\text{ref}}(\{\rvx_{0:T}\}_j | c)}
&= K \mathbb{E}_{p_{\text{ref}}(\rvx_{0:T} | c)} \left[
\frac{\hat{p}_\theta(\rvx_{0:T} | c)}{p_{\text{ref}}(\rvx_{0:T} | c)}
\right] = K, \\
\sum_{j=1}^{K} e^{ r(c, \{\rvx_{0:T}\}_j )}
&= K \mathbb{E}_{p_{\text{ref}}(\rvx_{0:T} | c)} \left[
e^{ r(c, \rvx_{0:T})}
\right] = KZ(c) \\
\end{align*}

So that we can simplify the \Cref{eq:dpo-rw}:
\begin{align*}
\nabla_\theta \mathcal{L}_{\text{dpo}}(\theta) 
&= \nabla_\theta \mathbb{E}_{c \sim \mathcal{D}_c} \left[ 
    - \frac{1}{K} \sum_{i=1}^K \mathbb{E}_{p_{\text{ref}}(\{\rvx_{0:T}\}_i|c)} \left[ 
        \frac{e^{r(c, \{\rvx_{0:T}\}_i)}}{Z(c)} 
        \log \frac{\hat{p}_\theta(\{\rvx_{0:T}\}_i | c)}{\hat{p}^*(\{\rvx_{0:T}\}_i | c)}
    \right] 
\right] \\
&= \nabla_\theta \mathbb{E}_{c \sim \mathcal{D}_c} \left[ 
    - \mathbb{E}_{p_\text{ref}(\rvx_{0:T}|c)} \left[ 
        \frac{e^{r(c, \rvx_{0:T})}}{Z(c)} 
        \log \frac{\hat{p}_\theta(\rvx_{0:T} | c)}{\hat{p}^*(\rvx_{0:T} | c)}
    \right] 
\right] \\
&= \nabla_\theta \mathbb{E}_{c \sim \mathcal{D}_c} \left[ 
    - \sum_{\rvx_{0:T} \in \mathcal{D}} p_{ref}(\rvx_{0:T} | c) 
    \frac{e^{r(c, \rvx_{0:T})}}{Z(c)} 
    \log \frac{\hat{p}_\theta(\rvx_{0:T} | c)}{\hat{p}^*(\rvx_{0:T} | c)}
\right] \\
&= \nabla_\theta \mathbb{E}_{c \sim \mathcal{D}_c} \left[-\sum_{\rvx_{0:T} \in \mathcal{D}} \hat{p}^*(\rvx_{0:T} | c) 
    \log \frac{\hat{p}_\theta(\rvx_{0:T} | c)}{\hat{p}^*(\rvx_{0:T} | c)}
\right] \\
&= \nabla_\theta \mathbb{E}_{c \sim \mathcal{D}_c} \left[ 
    \mathbb{D}_{\text{KL}} \left( \hat{p}^*(\rvx_{0:T} | c) 
    \parallel \hat{p}_\theta(\rvx_{0:T} | c) \right)
\right],
\end{align*}




which completes the proof of \Cref{theory:sec:dpo}.


\subsection{Convexity of \Cref{eq:fu}}
We analyze the convexity by firstly computing the second derivative of \Cref{eq:fu}:
\begin{equation}
    f''(u) = \frac{e^u}{(1+e^{-u})^3}\left[-ue^u + (\log\frac{1-\alpha}{\alpha} + 1)e^u + u + 1-\log\frac{1-\alpha}{\alpha}\right].
\end{equation}
Let $g(u) = -ue^u + (\log\frac{1-\alpha}{\alpha} + 1)e^u + u + 1-\log\frac{1-\alpha}{\alpha}$, then the sign of $f(u)$ is determined by the sign of $g(u)$, i.e., $\operatorname{sgn}(f(u)) = \operatorname{sgn}(g(u)))$. 
We analyze the derivatives of \( g(u) \):
\begin{equation}
    g'(u) = e^u\left(\log\frac{1-\alpha}{\alpha} - u\right) + 1, \quad
    g''(u) = e^u\left(\log\frac{1-\alpha}{\alpha} - u - 1\right).
\end{equation}
Clearly, \( g''(u) = 0 \) when
$
u_0 = \log\frac{1-\alpha}{\alpha} - 1:
$
\begin{itemize}
    \item For \( u < u_0 \), we have \( g''(u) > 0 \);
    \item For \( u > u_0 \), we have \( g''(u) < 0 \).
\end{itemize}

Therefore, \( g'(u) \) attains its maximum at \( u = u_0 \). Moreover, we observe that:
\begin{align*}
    \lim_{u \to -\infty} g'(u) = 0^+, \quad
    \lim_{u \to +\infty} g'(u) = -\infty.
\end{align*}
Thus, by the intermediate value theorem, there exists a unique \( u_1 > u_0 \) such that \( g'(u_1) = 0 \). It follows that:
\begin{itemize}
    \item \( g'(u) > 0 \) for \( u < u_1 \),
    \item \( g'(u) < 0 \) for \( u > u_1 \).
\end{itemize}

Therefore, \( g(u) \) attains its global maximum at \( u = u_1 \). Since
$
g(u_0) = 2e^{u_0} > 0,
$
we have:
\[
g(u_1) > g(u_0)> 0.
\]
Furthermore, observe that \( g(0) \equiv 2 \), which is strictly positive.  
Additionally, we have:
\[
\lim_{u \to \pm\infty} g(u) = -\infty.
\]
Hence, by continuity and the monotonicity of \( g(u) \), we conclude that for any \( \alpha \in (0, 1) \), there exists an interval \( (h_1(\alpha), h_2(\alpha)) \) such that
\[
h_1(\alpha) < 0 < h_2(\alpha) \quad \text{and} \quad g(u) > 0 \quad \text{for all} \quad u \in (h_1(\alpha), h_2(\alpha)).
\]
This proves that \( f''(u) > 0 \) within this interval.

Moreover, consider the scenario where \( \alpha \) is small (e.g., \( \alpha \in (0, 0.1] \)), in this case, we can view the objective as a cross-entropy loss favoring the class with probability \( 1 - \alpha \). The corresponding optimal logit is
\[
u = \log\left(\frac{1 - \alpha}{\alpha}\right).
\]
Substituting this into \( g(u) \), we obtain
\[
g\left(\log\left(\frac{1 - \alpha}{\alpha}\right)\right) = \frac{1}{\alpha} > 0.
\]
This implies that, under this low-\( \alpha \) regime, the interval in which \( g(u) > 0 \) is not only guaranteed to exist but also sufficiently large to cover the optimizer's likely solution. Therefore, the curvature condition \( f''(u) > 0 \) holds throughout the practically relevant interval.


\subsection{Proof of \Cref{theory:sec:dmpo}}


We first start by rearranging $\mathcal{L}_{\text{RLHF}}(p_\theta)$ from \Cref{{sec::method::theory:2}} :

\begin{align*}
\mathcal{L}_{\text{RLHF}}(\theta) 
&= \mathbb{E}_{c \sim \mathcal{D}_c} \left( \mathbb{E}_{p_\theta(\rvx_{0:T} | c)} \left[ r(c, \rvx_{0:T}) \right]
- \beta \mathbb{D}_{\text{KL}} \left[ p_\theta(\rvx_{0:T} | c) \| p_{\text{ref}}(\rvx_{0:T} | c) \right] \right) \\
&= \mathbb{E}_{c \sim \mathcal{D}_c} \left( \mathbb{E}_{p_\theta(\rvx_{0:T}|c)} \left[ r(c, \rvx_{0:T}) \right]
- \beta \mathbb{E}_{p_\theta(\rvx_{0:T}| c)} \left[ \log \frac{p_\theta(\rvx_{0:T} | c)}{p_{\text{ref}}(\rvx_{0:T} | c)} \right] \right) \\
&= \mathbb{E}_{c \sim \mathcal{D}_c} \left( 
\beta \mathbb{E}_{\rvx_{0:T} \sim p_\theta(\cdot | c)} 
\left[ \log e^{ r(c, \rvx_{0:T})} \right]
- \beta \mathbb{E}_{\rvx_{0:T} \sim p_\theta(\cdot | c)} 
\left[ \log \frac{p_\theta(\rvx_{0:T} | c)}{p_{\text{ref}}(\rvx_{0:T} | c)} \right]
\right) \\
&= \mathbb{E}_{c \sim \mathcal{D}_c} \mathbb{E}_{\rvx_{0:T} \sim p_\theta(\cdot | c)} \left[
\beta \log \left( \frac{p_{\text{ref}}(\rvx_{0:T} | c) e^{r(c, \rvx_{0:T})}}{p_\theta(\rvx_{0:T} | c)} \right)
\right]
\end{align*}

Utilizing the definition of  $\hat{p}^*$ ,we substitute $p_{\text{ref}}(\rvx_{0:T}|  c) e^{ r(c, \rvx_{0:T})}$ into the expression of $\mathcal{L}_{\text{RLHF}}(\theta)$:
\begin{align*}
\mathcal{L}_{\text{RLHF}}(\theta) 
&= \mathbb{E}_{c \sim \mathcal{D}_c} \mathbb{E}_{\rvx_{0:T} \sim p_\theta(\cdot | c)} \left[
\beta \log \left( \frac{ H \cdot \hat{p}^*(\rvx_{0:T} | c)}{p_\theta(\rvx_{0:T} | c)} \right)
\right] \\
&= \beta \mathbb{E}_{c \sim \mathcal{D}_c} \left[
- \mathbb{D}_{\text{KL}} \left( p_\theta(\rvx_{0:T} | c) \| \hat{p}^*(\rvx_{0:T} | c) \right) + H
\right].
\end{align*}
where $H$ is a constant independent of $\theta$. Note that when $\beta$ = 1. $p_\theta$ can be also $\hat{p}_\theta$ as the definition. Hence when $\beta$ = 1, the final RLHF loss will be :
\begin{equation}
  \mathcal{L}_{\text{RLHF}}(\theta)  =  \mathbb{E}_{c \sim \mathcal{D}_c} \left[
- \mathbb{D}_{\text{KL}} \left( \hat{p_\theta}(\rvx_{0:T}| c) \| \hat{p}^*(\rvx_{0:T} | c) \right) + H
\right],
\end{equation}
Then we compute the gradient of above loss, as $H$ is a constant independent of $\theta$, finall the RLHF loss will be  
\begin{equation}
 \nabla_\theta \mathcal{L}_{\text{RLHF}}(\theta)  =  - \nabla_\theta \mathcal{L}_{\text{\method}}(\theta)
\end{equation}
so that we complete the proof of \Cref{theory:sec:dmpo}.

\section{Experimental Details}
\label{app:sec:details}
\subsection{Details of Evaluation}

\textbf{Reward Score}. For each generated or edited image \(I_{\text{1}}\) and its corresponding target prompt \(c\), we compute an automated \emph{reward score}:
\[
   R(I_{\text{1}}, c) \;=\; r\bigl(I_{\text{1}}, c\bigr),
\]
where \(r\) is a pretrained vision–language reward model that outputs a scalar alignment score. We directly report the mean reward score over the entire test set for \Cref{tab:score_15}, \Cref{app:tab:edit_score} and \Cref{tab:score_xl}:
\[
   \text{Reward Score}
   = \frac{1}{N} \sum_{i=1}^N R\bigl(I_{\text{1}}^{(i)}, p^{(i)}\bigr).
\]
\textbf{Win rate using Reward Score}.
Given a set of $N$ image–prompt pairs \(\{(I^{(i)}_{\text{1}}, I^{(i)}_{\text{2}}, p^{(i)})\}_{i=1}^N\), where \(I^{(i)}_{\text{1}}\) and \(I^{(i)}_{\text{2}}\) are the outputs from method 1 and 2 respectively for prompt \(p^{(i)}\), we compute the reward score for each image using a pretrained reward model \(r\):  
\[
R^{(i)}_{\text{1}} = r\bigl(I^{(i)}_{\text{1}}, p^{(i)}\bigr), \quad
R^{(i)}_{\text{2}} = r\bigl(I^{(i)}_{\text{2}}, p^{(i)}\bigr).
\]
We then assign a win to the method with the higher reward score on each instance:
\[
\delta_i =
\begin{cases}
1, & R^{(i)}_{\text{1}} > R^{(i)}_{\text{2}}, \\
0, & \text{otherwise}.
\end{cases}
\]
The overall reward-based win rate of method 1 over method 2 is calculated as:
\[
\text{WinRate}_{\text{1} > \text{2}} = \frac{1}{N} \sum_{i=1}^N \delta_i \times 100\%.
\]

\textbf{Details of user study}.

We randomly sampled a total of 100 prompts—equally drawn from the test set of Pick-a-Pic V2, HPS V2, and Parti-Prompt—and generated one image per prompt by different models for user study. These image–prompt pairs were then presented to human annotators via a custom web-based interface for blind evaluation.

Specifically, we include all baselines in our comparison. We pair the outputs generated by our DMPO-finetuned SD1.5 model with those from the following methods: Diffusion-DPO, Diffusion-KTO, DSPO, and SFT-finetuned SD1.5. This results in a total of 500 image pairs constructed from the 100 prompts.

Each comparison is evaluated by \textbf{2 to 3 human annotators}, yielding a total of \textbf{1500 judgments}. For each comparison, the annotator is shown a prompt and two images generated by different models, and is asked to answer the three evaluation questions outlined in \Cref{sec::setting}. We report the final win rates by aggregating the human preferences across all comparisons, as shown in \Cref{fig:img_study}.




\subsection{Details of Datasets}

\textbf{Pick-a-Pic~\citep{pickapic}}: This comprehensive dataset captures real user preferences from the Pick-a-Pic web platform, where users generate images from text prompts. The collection encompasses more than 500,000 preference examples derived from over 35,000 unique prompts. Each entry consists of a text prompt, two AI-generated images, and user feedback indicating their preferred image or marking cases where no clear preference exists. The dataset incorporates outputs from various generative models, including Stable Diffusion 2.1, Dreamlike Photoreal 2.05, and multiple Stable Diffusion XL configurations, utilizing different classifier-free guidance parameters during generation.

\textbf{Parti-Prompts~\citep{partiprompt}}: This benchmark dataset features more than 1,600 carefully crafted English prompts designed to evaluate text-to-image model capabilities. The prompts cover diverse categories and present varied challenges, enabling comprehensive assessment of model performance across multiple evaluation criteria.

\textbf{HPS V2~\citep{hpsv2}}: This preference-based collection contains 98,807 generated images sourced from 25,205 distinct prompts. The dataset structure allows for multiple image generations per prompt, with users selecting their preferred output while other variations serve as negative examples. The distribution includes 23,722 prompts with four associated images, 953 prompts with three images, and 530 prompts paired with two images.


\textbf{TEd-bench~\citep{ted}}: Textual Editing Benchmark is a text‐to‐image editing benchmark that provides pairs of real images and corresponding editing prompts. For example, given a source image of a dog running, the target prompt might be “A cat running on the grass”, in which case the model is expected to modify the original image so that it depicts the desired semantics. We evaluate both existing baselines and our proposed method on TEd-bench by applying an automated reward model to score each edited image, and report the average reward as our editing performance metric.

 \textbf{InstructPix2Pix~\citep{ip2p}}: This specialized collection focuses on instruction-based image editing capabilities. The dataset enables models to modify existing images according to natural language instructions, such as "make the clouds rainy." The system processes both the editing instruction and the original image to produce the desired modifications. Our experimental evaluation utilized 1,000 test samples from this dataset to assess instruction-following image editing performance. Note that although reward models such as CLIP~\citep{clip} may not comprehensively capture the semantics of instruction-style prompts when scoring edited images, we maintain that if the key terms from the instruction appear faithfully in the generated image, this constitutes a valid comparison.


\subsection{Pseudo code of DMPO}
\begin{nolinenumbers}
\begin{lstlisting}[language=Python,numbers=none]
def loss(model, ref_model, x_w, x_l, c, alpha, beta):
    """
        Calculate the DMPO loss for preferred image pair.
    model: Diffusion model with prompt and timestep conditioning.
    ref_model: Frozen reference model.
    x_w: Preferred latent.
    x_l: Less preferred latent.
    c: Conditioning input (e.g., caption text).
    alpha: smoothing coefficient.
    beta: Regularization strength.
    """
    t = torch.randint(0, 1000)
    noise = torch.randn_like(x_w)
    noisy_x_w = add_noise(x_w, noise, t)
    noisy_x_l = add_noise(x_l, noise, t)
    model_w_pred = model(noisy_x_w, c, t)
    model_l_pred = model(noisy_x_l, c, t)
    ref_w_pred = ref_model(noisy_x_w, c, t)
    ref_l_pred = ref_model(noisy_x_l, c, t)
    model_w_err = (model_w_pred - noise).norm().pow(2)
    model_l_err = (model_l_pred - noise).norm().pow(2)
    ref_w_err = (ref_w_pred - noise).norm().pow(2)
    ref_l_err = (ref_l_pred - noise).norm().pow(2)

    w_diff = model_w_err - ref_w_err
    l_diff = model_l_err - ref_l_err

    inside_term = -1 * beta * (w_diff - l_diff)
    loss_1 = torch.sigmoid(-inside_term) * (torch.logsigmoid(-inside_term) - torch.log(alpha))
    loss_2 = torch.sigmoid(inside_term) * (torch.logsigmoid(inside_term) - torch.log(1-alpha))
    loss = loss_1 + loss_2
    return loss
\end{lstlisting}
\end{nolinenumbers}


