\section{Derivations}

\subsection{Derivation of Equation~\ref{eqn:poisson-drv}}
\label{sec:poisson-derivation}
Note that, in our stylized example, $T_i$ is $\text{Poisson}(\lambda_j)$ conditional on $X_i = j$.  Therefore, its probability mass function is given by:
\begin{equation}
    P(T_i = t | X_i = j) = e^{-\lambda_j} \frac{\lambda_j^t}{t!}, t = 0, 1, 2, \ldots,
\end{equation}
and the conditional expectation of the causal derivative $\frac{1}{T_i + 1}$ given $X_i = j$ is:
\begin{equation}
    \sum_{t = 0}^\infty \frac{1}{t + 1} e^{-\lambda_j} \frac{\lambda_j^t}{t!} = \sum_{t = 0}^\infty e^{-\lambda_j} \frac{\lambda_j^t}{(t + 1)!}.
\end{equation}

Define $s := t + 1$.  Then we can rewrite the above as:
\begin{eqnarray}
\sum_{s = 1}^\infty e^{-\lambda_j} \frac{\lambda_j^{s - 1}}{s!} &=& \frac{e^{-\lambda_j}}{\lambda_j} \sum_{s = 1}^\infty \frac{\lambda_j^s}{s!} \\
&=& \frac{(e^{\lambda_j} - 1)}{\lambda_j e^{\lambda_j}} \\
&=& \frac{1 - e^{-\lambda_j}}{\lambda_j}.
\end{eqnarray}
where the second-to-last equality uses the identity $\sum_{s = 0}^\infty \frac{x^s}{s!} = e^x$.


\subsection{Derivation of $T_i^*$}

\label{sec:poisson-tstar-derivation}

Within a given stratum $X_i = j$, $h(X_i) = E[T_i | X_i] = \lambda_j$ by assumption.  We want to derive the point $T_i^*$ between $T_i$ and $\lambda_j$ at which we are evaluating the derivative $f'(t) = 1 / (t + 1)$.  We will condition on $X_i$ throughout.

By the mean value theorem, there is some $T_i^*$ between $T_i$ and $\lambda_j$ for which:
\[
    f(T_i) - f(\lambda_j) = f'(T_i^*) (T_i - \lambda_j).
\]

Plugging in the definition of $f$ and its derivative, we write this as:
\[
    \log(T_i + 1) - \log(\lambda_j + 1) = \frac{1}{T_i^* + 1} (T_i - \lambda_j).
\]
Solving for $T_i^*$ yields:
\[
    T_i^* = \frac{T_i - \lambda_j}{\log \frac{T_i + 1}{\lambda_j + 1}} - 1.
\]
Note that, when $T_i = \lambda_j$, this quantity is undefined (in which case we just set $T_i^* = T_i$).

In our simulations, we estimate the theoretical plim of RORR by taking many draws of $T_i$, plugging them into this formula, and using the resulting stratum means to estimate Equation \ref{eqn:rorr}

\section{Proof of Consistency of Coarsened AIPW}
\label{app:aipw}

We assume the PLM for continuous treatments, but introduce the potential outcomes notation:
\begin{eqnarray}
    Y_i(t) &=& f(t) + g(X_i) + e_i \\
    T_i &=& h(X_i) + u_i.
\end{eqnarray}
We assume that $f$ is continuously differentiable, $E[e_i | X_i] = 0$, $E[u_i | X_i] = 0$, and $E[e_i u_i | X_i] = 0$.  Note that the last of these assumptions implies that $Y_i(t)$ is conditionally independent of $T_i$ given $X_i$.  We further require positivity of treatment for all $x$ and $t$:
\begin{equation}
    p(t | x) \ge \epsilon > 0,
\end{equation}
where $p(t|x)$ is the continuous conditional density of $T_i$ given $X_i$. This is the continuous analog of the overlap assumption under binary or discrete treatments, which requires that every unit has a positive probability of treatment given covariates. 

Partition the domain of $T_i$ into $K$ equal-spaced segments, denoted by $S_k, k = 1, \ldots, K$, with $S_k = [t_{k}, t_{k+1})$ and $t_{k+1} - t_k = CK^{-1}$ for all $k$, where $C$ is some positive constant that spans the domain of $T_i$.  Define $p_k(X_i) = \Pr(T_i \in S_k | X_i)$ and $m_k(X_i) = E[Y_i | T_i \in S_k, X_i]$ and let one or both $\hat{p}_k$ and $\hat{m}_k$ be consistent estimators.

The coarsened AIPW estimator for a given segment $S_k$ is defined as:
\begin{equation}
    \hat{\psi}_k := \frac{1}{N} \sum_{i=1}^N \frac{1(T_i \in S_k)}{\hat{p}_k(X_i)} (Y_i - \hat{m}_k) + \hat{m}_k.
\end{equation}
Further define the approximate weights:
\begin{eqnarray}
    w_k = \begin{cases}
        \frac{\Pr(T_i \in S_k)}{\Pr(T_i \not\in S_K)} & \text{for } k < K\\
        0 & \text{for } k = K,
    \end{cases}
\end{eqnarray}
and denote the midpoint of bin $S_k$ by $\overline{t}_k = \frac{t_{k+1} - t_k}{2}$.  

Then coarsened AIPW estimator of the Average Causal Derivative is defined as \[
\hat{\psi} := \sum_{k=1}^{K-1} w_k \left(\frac{\hat{\psi}_{k + 1} - \hat{\psi}_k}{\overline{t}_{k + 1} - \overline{t}_k}\right).
\]

\begin{theorem}
    $\hat{\psi}$ converges in probability to the Average Causal Derivative $E[f'(T_i)]$ as both the number of observations $N$ and the number of segments $K$ $\to \infty$.
\end{theorem}

\begin{proof}
    By consistency of $\hat{p}_k$ or $\hat{m}_k$ and conditional independence of $Y_i(t)$ and $X_i$,
    \begin{eqnarray}
        \hat{\psi}_k \overset{p}{\to} \int \int Y_i(t) \frac{p(t | x) 1(t \in S_k)}{\Pr(t \in S_k | x)} p(x) dt dx.
    \end{eqnarray}

    Subtracting $\hat{\psi}_k$ from $\hat{\psi}_{k+1}$ and plugging in the definition of $Y_i$ yields:
    \begin{eqnarray}
        && \hat{\psi}_{k+1} - \hat{\psi}_{k} \\\nonumber
        && \quad \overset{p}{\to} \int \bigg(\int f(t) \frac{p(t | x) 1(t \in S_{k+1})}{\Pr(t \in S_{k+1} | x)} dt \\\nonumber
        && \qquad - \int f(t) \frac{p(t | x) 1(t \in S_k)}{\Pr(t \in S_k | x)} dt \bigg) p(x) dx \\
        && \qquad\quad := \Delta_k. \nonumber
    \end{eqnarray}

    $\Delta_k$ has a subtle interpretation: It is the ``effect'' of moving from segment $S_k$ to $S_{k+1}$ when units are treated according to the conditional treatment distribution in each segment.  We now show that $\Delta_k$ can be interpreted as a very specific ATE.  Given continuity of $f$, $p$, and positivity, the mean value theorem for integrals states that there exists a $\tilde{t}_k \in S_k$ such that
    \[
    \int f(t) \frac{p(t | x) 1(t \in S_k)}{\Pr(t \in S_k | x)} dt = f(\tilde{t}_k).
    \]
    Therefore, we can rewrite the above as:
    \begin{eqnarray}
        \Delta_k = \int (f(\tilde{t}_{k+1}) - f(\tilde{t}_k)) p(x) dx,
        \label{eqn:mvt-integral}
    \end{eqnarray}
    showing that $\Delta_k$ is the ATE of fixing $T_i$ to $\tilde{t}_{k+1}$ compared to $\tilde{t}_k$.

    By another application of the mean value theorem, there exists a $t_k^*$ between $\tilde{t}_k$ and $\tilde{t}_{k+1}$ such that:
    \begin{eqnarray}
        && \int (f(\tilde{t}_{k+1}) - f(\tilde{t}_k)) p(x) dx \\ \nonumber &=& \int f'(t_k^*) (\tilde{t}_{k+1} - \tilde{t}_k) p(x) dx \\
        &=& E[f'(t_k^*) (\tilde{t}_{k+1} - \tilde{t}_k)]. \nonumber
    \end{eqnarray}
    Note that the absolute difference between any of $\tilde{t}_k$, $t_k^*$, and $\overline{t}_k$ is bounded by $|2 C K^{-1}|$.  Therefore, as $K \to \infty$, these converge to the same point. Consequently:
    \begin{eqnarray}
        \sum_{k=1}^{K-1} w_k \left(\frac{\hat{\psi}_{k + 1} - \hat{\psi}_k}{\overline{t}_{k + 1} - \overline{t}_k}\right) \overset{p}{\to} \int f'(t) \frac{t_{k+1} - t_k}{t_{k+1} - t_k} p(t) dt = E[f'(t)].
    \end{eqnarray}
\end{proof}

\section{Choosing The Number of Segments}

Choosing the number of segments $K$ in which to bin the treatment involves the usual considerations of bias and variance.  In many practical applications, interpretability is also a goal.  In this section, we provide a semiformal justification, relying on many simplifying assumptions, for choosing $K = O(N^{1/7})$.  This implies fewer than ten bins for medium to large datasets (i.e., between 100,000 to 1,000,000 units).

In our practical work at Netflix, we find that a relatively small number of bins -- for example, dividing users into low, medium, and high usage segments -- is sufficient to detect meaningful heterogeneity in the dose-response function.  Although using a small number of bins increases bias, it reduces variance, adds robustness to slow nuisance estimation rates, and increases interpretability.

The MSE of the coarsened AIPW estimator is:
\begin{equation}
    MSE(\hat{\psi}) = \underbrace{(E[\hat{\psi}] - E[f'(t)])^2}_{\text{Bias}^2} + \operatorname{Var}(\hat\psi).
\end{equation}
We begin by decomposing the $\text{Bias}$ term into three components:
\begin{eqnarray}
    && E[\hat{\psi}] - E[f'(t)] \\ \nonumber && =
        \underbrace{E\left[\sum_{k=1}^{K-1} w_k \left(\frac{\hat{\psi}_{k + 1} - \hat{\psi}_k}{\overline{t}_{k + 1} - \overline{t}_k}\right)\right] - \sum_{k=1}^{K-1} w_k \left(\frac{\Delta_k}{\overline{t}_{k + 1} - \overline{t}_k}\right)}_{:= a} \\
        && \quad + \underbrace{\sum_{k=1}^{K-1} w_k \left(\frac{\Delta_k}{\overline{t}_{k + 1} - \overline{t}_k}\right) - \sum_{k=1}^{K-1} w_k f'(t_k)}_{:= b} \nonumber
        \\ && \qquad + \underbrace{\sum_{k=1}^{K-1} w_k f'(t_k) - E[f'(t)]}_{:= c}. \nonumber
\end{eqnarray}
In other words, $a$ is statistical estimation error, $b$ is the bias incurred by approximating $f$ by a piecewise linear function, and $c$ is the bias incurred by approximating an integral by a series of rectangles.

For simplicity, we will assume that $T_i$ is uniformly distributed, such that the number of units in each bin $N_k = N / K$, $\overline{t}_{k + 1} - \overline{t}_k$ is a constant $\ell \propto K^{-1}$, and $w_k = (K - 1)^{-1}$ for all $k$.  We will also assume that $f$ is at least thrice continuously differentiable.  Also for simplicity, we ignore cross-fitting and assume that the nuisance functions are estimated on a separate dataset of equal size (i.e., also consisting of $N$ units partitioned into $K$ bins).  We assume the estimated nuisances satisfy standard regularity conditions, specifically $\delta < \hat{p}(x) < 1 - \delta$ for some $\delta \in (0, 1)$ and $\hat{m}(x, k)^2 < \infty$ almost surely and that $Y_i^2 < \infty$, so that $\operatorname{Var}(\psi_i) = O(1)$.

Suppose that $\hat{\psi}_k - m_k = o_p\left((N/K)^{-1/2}\right)$.  Then, under mild regularity conditions, $a = \sum_{k=1}^K O\left((N/K)^{-1/2}\right) = O(K^{3/2}N^{-1/2})$.  The error of the midpoint approximation $b$ when $f$ is thrice continuously differentiable is known to be $O(\ell^2) = O(K^{-2})$ \cite[][p. 177]{burden1997numerical}.  The error of the Riemann sum approximation is also known to be $c = O(K^{-2})$ \cite[][p. 207]{burden1997numerical}.  Therefore, the error of the $\text{Bias}^2$ term is:
\begin{eqnarray}
    (a + b + c)^2 &=& O(K^{3}N^{-1}) + O(K^{-4}).
\end{eqnarray}

The variance is:
\begin{eqnarray}
    \operatorname{Var}(\hat\psi) &=& \operatorname{Var}\left(\sum_{k=1}^{K-1} w_k\left(\frac{\hat{\psi}_{k + 1} - \hat{\psi}_k}{b} \right)\right) \\ \nonumber &=& K \operatorname{Var}(\hat{\psi}_K - \hat{\psi}_1) \\ \nonumber
    &=& O(K^2 N^{-1}).
\end{eqnarray}
Putting these together, we obtain $$MSE(\hat{\psi}) = O(K^{3}N^{-1}) + O(K^{-4}) + O(K^2 N^{-1}).$$  The $K^*$ that minimizes this is $O(N^{1/7})$.

More generally, suppose that $\psi_k$ is $n^{-1/d}$ consistent for $d > 0$.  Then the $\text{Bias}^2$ term is $O(K^{2(d + 1)/d}N^{-2/d}) + O(K^{-4})$, while the variance remains $O(K^2 N^{-1})$.  If $d < 2$, the variance term dominates and the optimal $K^* = O\left(N^{1 / 6}\right)$.  If $d \ge 2$, the bias term dominates, and the optimal $K^* = O\left(N^{1/(3d + 1)}\right)$.

