\title{On Universality of Non-Separable Approximate Message Passing Algorithms}
\author{Max Lovig$^*$, Tianhao Wang$^\dagger$, Zhou Fan$^*$}
\email{max.lovig@yale.edu, tianhaowang@ucsd.edu, zhou.fan@yale.edu}
\address{$^*$Department of Statistics and Data Science, Yale University}
