\subsection{Gauge invariance for the diagram framings \texorpdfstring{$\frmR$}{} and \texorpdfstring{$\frmL$}{}}\label{subsec:gauge-Lnk}
\subsubsection{Gauge invariance of \texorpdfstring{$K(L(n,k), \frmR, H)$}{} for odd\texorpdfstring{$(n-k)$}{}}
In this subsection, we assume that $(n-k)$ is odd and prove the gauge invariance of the Kuperberg invariant $K(L(n,k), \frmR, H)$ based on the 2-combed Heegaard diagram in Figure \ref{fig:fR-detail}, which will be denoted by $D$. We will first show that $D$ is a framed Heegaard diagram, and give explicit descriptions of the permutation $\s_D$ and the sequence $\{s_i\}_{i=1}^{n}$ in the definition of the Kuperberg invariant (see \eqref{eq:PMDH}, \eqref{eq:sr-tr} and \eqref{eq:KInv}).

\begin{convention}\label{conv:k0}
For the rest of the paper, we adopt the following conventions.
\begin{itemize}
\item An interval of the form $[a, 0]$ with $a>0$ is understood as the empty set. 
\item In tensor components of the form $\bigotimes_{i=1}^{k_0}$, when $k_0 = 0$, the corresponding tensor component is understood as an empty tensor.  
\end{itemize}
\end{convention}

\begin{prop} \label{p:S-exponents}
Let $n > k > 0$ be a pair of coprime integers such that $(n-k)$ is odd, and denote $k_0 = \tfrac{n-k-1}{2}$. Then the 2-combed Heegaard diagram $D$ in Figure \ref{fig:fR-detail} is a framed Heegaard diagram of $L(n,k)$ with $\theta_\mu = \theta_\eta = \phi_\eta = \tfrac{1}{2}$ and $\phi_{\mu} = -\tfrac{1}{2}$. The permutation $\s_D$ is given by $\s_D(i)=\ol {k\cdot (i-1)}$ for $i \in \{1, \dots,  n\}$, where $\ol a$ is the positive residue of $a$ modulo $n$. Moreover, the sequence $\{s_i\}_{i=1}^{n}$ satisfies the following recursive relations with  $s_n=1$:
\begin{enumerate}[label=\rm{(\roman*)}] 
\item If $1\leq i\leq k_0$, then $s_{\ol{i+k}}=s_i+2$;
\item If $k_0 + 1\leq i \leq n-k-1$, then $s_{\ol{i+k}}=s_i-2$;
\item If $n-k \leq i \leq n$, then $s_{\ol{i+k}}=s_i$. 
\end{enumerate}
In particular, $s_n=s_{n-k}=s_k=1$, $s_i$ is an odd integer for all $1 \le i \le n$, and these recursive relations completely determine $\{s_i\}_{i=1}^{n}$. 
\end{prop}

\begin{proof}
By definition, to show that $D$ is a framed Heegaard diagram, it suffices to count the rotation numbers in Figure \ref{fig:fR-detail} and show that $\theta_\eta = \phi_\eta$ for the lower curve $\eta$ (green), and $\theta_\mu = -\phi_\mu$ for the upper curve $\mu$ (blue). 

We first analyze the rotation numbers of the lower curve $\eta$. Start from $\xi_1$ and go along $\eta$ to the right, it is easy to see that for $1 \le i \le n-1$, we have $\theta_{\eta}(p_i) = 0$, and $\theta_{\eta}(p_n) = \tfrac{1}{4}$. 
As we go through the handle and come back to $\xi_1$, the combing $b_1$ and $\eta$ are in opposite direction, so the total rotation number $\theta_\eta$ is equal to $\tfrac{1}{2}$. 
By design, there is no intersection between the twist front and $\eta$, and the direction of the twist front aligns with that of $\eta$ near $\xi_1$. Thus, we have $\phi_\eta = \tfrac{1}{2} = \theta_\eta$.

Now we study the rotation numbers of the upper curve $\mu$. We will compute $\theta_\mu(p_i)$ at the $I$-points, while finding patterns for $\s_D$ and $s_i = 2(\theta_\eta(p_i) - \theta_\mu(p_i))+\tfrac{1}{2}$. Reading directly from $D$, we find $p^1=p_n$ or $\s_D(1)=n$. Moreover, Observation \ref{obs:pts} implies that when traveling along $\mu$, we always go from $p_{i}$ to $p_{\overline{i+k}}$. Thus, $\s_D(i) = \ol{k\cdot (i-1)}$. At $p_n$, we have $\theta_{\mu}(p_n) = 0$. So we have 
\[s_n = 2(\theta_{\eta}(p_n) - \theta_{\mu}(p_n))+\frac{1}{2} = 2\cdot (\frac{1}{4}-0)+\frac{1}{2} = 1\,.\]
We have the following cases when computing $\theta_\mu(p_i)$ for $1 \le i \le n-1$. 

Starting from $p_n$, the next $I$-point we encounter is $p_{\ol{n+k}} = p_k$. The local picture is illustrated in Figure \ref{fig:fR-S-power-0} where only the relevant part of $\mu$ is drawn. 
We go downwards from $p_n$ and enter the handle at the attaching circle on the right, during which $\theta_\mu$ increases by $\tfrac{1}{2}$. Then we exit from the left attaching circle to reach $p_k$, and $\theta_\mu$ decreases by $\tfrac{3}{4}$. Therefore, $\theta_\mu(p_k) = \theta_{\mu}(p_n) + \tfrac{1}{2}-\tfrac{3}{4} = -\tfrac{1}{4}$, and we have 
\[s_{\ol{n+k}} = s_{k} = 2(\theta_\eta(p_k) - \theta_\mu(p_k)) + \frac{1}{2} = 2(0-(-\frac{1}{4})) + \frac{1}{2} = 1 = s_n\,.\]

\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fR-S-power-0.eps}
    \caption{$\theta_\mu(p_{k}) = -\tfrac{1}{4}$.}
    \label{fig:fR-S-power-0}
\end{figure}

For $n-k+1 \leq i \le n-1$, we have $\ol{i+k} = i+k-n$, and we can calculate the change of $\theta_\mu$ using the local configuration shown in Figure \ref{fig:fR-S-power-1}. Precisely, in Figure \ref{fig:fR-S-power-1}, we first go downwards from $p_i$, and then enter the attaching circle on the right. This process increases $\theta_\mu$ by $\tfrac{3}{4}$. Then we exit from the left attaching circle to reach $p_{i+k-n}$, and $\theta_\mu$ decreases by $\tfrac{3}{4}$ in this part of $\mu$. So in this case, we have $\theta_\mu(p_{\ol{i+k}}) = \theta_{\mu}(p_i)$, and $\theta_{\eta}(p_{\ol{i+k}}) = \theta_{\eta}(p_i) = 0$, which means $s_{\ol{i+k}} = s_{i}$. 
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fR-S-power-1.eps}
    \caption{For $n-k+1 \leq i \le n-1$, $\theta_\mu(p_{\ol{i+k}}) = \theta_{\mu}(p_i)$.}
    \label{fig:fR-S-power-1}
\end{figure}

Summarizing the above two cases, we have shown that if $n-k+1\leq i \le n$, then $s_{\ol{i+k}} = s_i$. In particular, if $k = n-1$ or $k_0=0$, then we have $s_n = s_{n-1} = 1$, and $s_{i-1} = s_i$ for all $2 \le i\le n-1$, which means  $s_i = 1$ for all $1 \le i \le n$. Therefore, we have finished the proof of the proposition for $k = n-1$. So for the rest of the proof, we assume that $n-k > 1$, i.e., $k_0 \ge 1$.

For $1\leq i \leq k_0$, we have $\ol{i+k} = i+k$, and we use Figure \ref{fig:fR-S-power-2} to analyze the change of $\theta_\mu$ from $p_i$ to $p_{i+k}$. Start from $p_i$, we go downwards to enter the left attaching circle, and $\theta_\mu$ decreases by $\tfrac{3}{4}$. Then we exit the right attaching circle from the left, and re-enter the handle from right, and $\theta_\mu$ increases by $\tfrac{1}{2}$ in this process. Finally, we exit the left attaching circle from the left to reach $p_{i+k}$, during which $\theta_\mu$ decreases by $\tfrac{3}{4}$. So in this case, we have $\theta_{\mu}(p_{i+k}) = \theta_{\mu}(p_i) -\tfrac{3}{4}+\tfrac{1}{2}-\tfrac{3}{4} = \theta_{\mu}(p_i) - 1$, which implies that 
\[s_{\ol{i+k}} = 2(0-\theta_{\mu}(p_{i+k})) +\frac{1}{2} =  2(0-(\theta_{\mu}(p_{i})-1)) +\frac{1}{2} = s_{i} + 2\,.\]
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fR-S-power-2.eps}
    \caption{For $1 \le i \le k_0$, $\theta_{\mu}(p_{i+k})= \theta_{\mu}(p_i) - 1$.}
    \label{fig:fR-S-power-2}
\end{figure}

For $k_0+1 \leq i \leq n-k-1$, $\ol{i+k} = i+k$, and the local configuration of $\mu$ is depicted in Figure \ref{fig:fR-S-power-3}, where we go downwards from $p_i$ to reach $p_{i+k}$. Using the similar argument as above, we can easily see that $\theta_\mu(p_{i+k}) = \theta_{\mu}(p_i) + 1$, and so $s_{\ol{i+k}}=s_{i}-2$. 
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fR-S-power-3.eps}
    \caption{For $k_{0}+1 \le i \le n-k-1$, $\theta_{\mu}(p_{i+k})= \theta_{\mu}(p_i)+1$.}
    \label{fig:fR-S-power-3}
\end{figure}

Now we compute $\theta_{\mu}(p_{n-k})$ and $s_{n-k}$. 
By the expression of $\s_D$, when we start from $p_n$ and travel along $\mu$, the last $I$-point we encounter (before we go back to $\xi_2$) is $p_{n-k}$, as $k$ is assumed to be coprime to $n$. Since $\{\{1, \dots, k_{0}\}, \{k_{0}+1, \dots, n-k-1\}, \{n-k+1, \dots, n\}\}$ is a partition of $\{1, \dots, n\}\setminus \{n-k\}$, the recursive relations above to completely determine $\theta_\mu(p_i)$ and  $s_i$ for all $i \ne n-k$. Consequently, we can compute $\theta_{\mu}(p_{n-k})$ inductively starting from $\theta_\mu(p_k) = -\tfrac{1}{4}$. More precisely, following $\mu$, we go from $p_k$ to $p_{\ol{2k}}$ and all the way to $p_{\ol{n+(n-1)k}} = p_{n-k}$. Note that in this process, there are exactly $k_{0}$ points at which $\theta_\mu$ increases by $1$, and $k_{0}$ points at which $\theta_\mu$ decreases by $1$, and at the rest of the points $\theta_\mu$ remains unchanged, so we can see that 
\[\theta_\mu(p_{n-k}) = \theta_{\mu}(p_k) = -\tfrac{1}{4}\,,\quad\text{and}\quad 
s_{n-k} = s_k = s_n = 1\,.\]
Therefore, the sequence $\{s_i\}_{i=1}^{n}$ satisfies the relations (i)-(iii) in the statement, and it is uniquely determined by these recursive relations.

\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fR-S-power-4.eps}
    \caption{The total rotation number $\theta_\mu = \tfrac{1}{2}$.}
    \label{fig:fR-S-power-4}
\end{figure}
Finally, we use the Figure \ref{fig:fR-S-power-4} to compute the total rotation $\theta_\mu$ when we return to the base point $\xi_2$ following $\mu$. Going from $p_{n-k}$ downwards, we can see that $\theta_\mu$ increases by $\tfrac{3}{4}$, and so $\theta_\mu = \theta_\mu(p_{n-k}) + \tfrac{3}{4} = \tfrac{1}{2}$. By design, there is no intersection between $\mu$ and the twist front, and the direction of the twist front is opposite to the orientation of $\mu$, so $\phi_\mu = -\tfrac{1}{2} = -\theta_\mu$, and we can conclude that $D$ is a framed Heegaard diagram of $L(n,k)$ in this case as desired.
\end{proof}

Recall that the diagram framing associated to the framed Heegaard diagram $D$ in Figure \ref{fig:fR-detail} is denoted by $\frmR$. We  now derive the expression of the Kuperberg invariant $K(L(n,k),\frmR,H)$ for any finite-dimensional Hopf algebra $H$.

\begin{definition}\label{d:cp} Let $n$ be a positive integer and $l$ an integer coprime to $n$. 
\begin{enumerate}
    \item[(a)] We define $\s_{(n,l)} \in \Sym_n$ by $\s_{(n,l)}(i)=\ol{il}$ for $i \in \{1, \dots, n\}$. Since $\s_{(n,l)}(n)=n$, we also consider $\s_{(n,l)} \in \Sym_{n-1}$ by restriction. 
\item[(b)] Let $H$ be a finite-dimensional Hopf algebra, and $n > k >0$ an integer with $(n-k)$ odd. We define the $\kk$-linear operator $P^{(n,-k)}: H \to H$ as 
\[
P^{(n,-k)} := m \circ \s_{(n,-k)}\circ \left(\bigotimes_{i=1}^{n-1}S^{2 c_i}\right)\circ\Delta^{n-1}
\]
where the sequence $\{c_i\}_{i=1}^{n}$ is determined by the following recursive relations with $c_n=0$:
\begin{enumerate}[label=\rm{(\roman*)}] 
    \item If $1\leq i\leq k_0$, then $c_{i+k}=c_i+1$ where $k_0=\frac{n-k-1}{2}$;
    \item If $k_0+1\leq i \leq 2k_0$, then $c_{i+k}=c_i-1$;
     \item If $2k_0+1 \leq i \leq n$, then $c_{\ol{i+k}}=c_i$.
\end{enumerate}
\item[(c)] Finally, we define $\delta(i):=c_{\ol{i+k}} -c_{i}$ for $i=1, \dots, n$.
\end{enumerate}
\end{definition}

\begin{remark}
For any coprime integers $n,k$ with $(n-k)$ odd, it is obvious that the sequences $\{c_i\}_{i=1}^{n}$ above and $\{s_i\}_{i=1}^{n}$ in Proposition \ref{p:S-exponents} are related by $s_i = 2 c_i+1$ for $i=1, \dots, n$. In particular, $c_n = c_{n-k} =0$.
\end{remark}

\begin{thm}\label{t:KInd}
Let $H$ be any finite-dimensional Hopf algebra. For any coprime integers $n>k>0$ such that $(n-k)$ is odd, we have
\begin{align*}
K(L(n, k), \frm_R, H)=\Tr(S \circ P^{(n,-k)})\,.
\end{align*}
\end{thm}
\begin{proof}
By \eqref{eq:KInv}, the Kuperberg invariant is given by
\begin{equation*}
   K(L(n, k), \frm_R, H)=\ld_{-\theta(\mu)}\left(m\circ \s_D\circ \left(\bigotimes_{i=1}^nS^{s_i}\right)\circ\Delta^{n}(\Ld_{\theta(\eta)})\right)
\end{equation*} 
where $\ld \in \int^r_{H^*}$ and $\Ld \in \int^l_{H}$ are a pair of normalized integrals. Recall \eqref{eq:twisted-ld} that $\ld_{-\frac{1}{2}}=\ld$ and $\Ld_{\frac{1}{2}}=\Ld$, by Proposition \ref{p:S-exponents}, we have  
\begin{equation}\label{eq:fR-form}
\begin{aligned}
&K(L(n, k), \frm_R, H)
=\ld_{-\frac{1}{2}} \left(m\circ \s_D\circ \left(\bigotimes_{i=1}^n S^{s_i}\right) \circ \Delta^{n}(\Ld_{\frac{1}{2}})\right) \\
=&\ld \left(m\circ \s_D\circ \left(\bigotimes_{i=1}^n S^{s_i}\right) \circ \Delta^{n}(\Ld)\right) 
=\ld\left(S^{s_n}(\Ld_{(n)})S^{s_{k}}(\Ld_{(k)}) \cdots  S^{s_{n-k}}(\Ld_{(n-k)})\right)\\
=&\ld\left( S(\Ld_{(n)}) S\left(S^{2c_{n-k}}(\Ld_{(n-k)}) S^{2c_{\ol{n-2k}}}(\Ld_{(\ol{n-2k})}) \cdots S^{2 c_k}(\Ld_{(k)})\right)\right)\\
=&\ld\left( S(\Ld_{(2)})\left(S \circ P^{(n,-k)}\right)(\Ld_{(1)})\right)
=\Tr(S \circ P^{(n,-k)})\,,
\end{aligned} 
\end{equation}
where the last equality follows from Theorem \ref{t:t2} (v).
\end{proof}

Now we are ready to prove the gauge invariance of $K(L(n,k),\frmR, H)$.

\begin{thm}\label{t:Lnk-fR}
Let $H$ be a finite-dimensional Hopf algebra over a field $\kk$, $F \in H \o H$ a 2-cocycle of $H$, and $H_F$ the Drinfeld twist of $H$. For any coprime integers $n >k> 0$ such that $(n-k)$ is odd, denote by $P_F^{(n,-k)}$ the $\kk$-linear operator for $H_F$ defined in Definition \ref{d:cp}. Then
\[
\Tr(S \circ  P^{(n,-k)}) = \Tr(S_F \circ  P^{(n,-k)}_F)\,.
\]
In particular, 
\[
K(L(n, k), \frm_R, H) =  K(L(n, k), \frm_R, H_F)\,.
\]
\end{thm}
\begin{proof}
Write $F = \ff{i}{1} \o \ff{i}{2} \in H\o H$. Note that $H = H_F$ as $\kk$-algebras, so $P^{(n,-k)}_F \in \End_\kk(H)$. 
Recall from \eqref{eq:S_F} that $S_F(h)=u S(h) u^{-1}$ where $u = \ff{i}{1}S(\ff{i}{2})$. Let  $Q=uS(u^{-1})$, and define $Q_0=1$, $Q_{s+1}=Q_{s}S^{2s}(Q)$ for $s\in \mathbb{Z}$. In particular, $Q_{-1}=S^{-2}(Q^{-1})$. One can show directly by induction on $s \ge 0$ and $s \le -1$ the equalities:
\begin{equation}\label{eq:Qs}
S_F^{2s}(x)=Q_sS^{2s }(x)Q_{s}^{-1}, \, Q_{s+1}^{-1} Q_s = S^{2s}(Q^{-1}),\,  Q_{s-1}^{-1}Q_s =S^{2s-2}(Q)\, \text{ and }\, Q_{s-1}=Q_{s}S^{2s}(Q_{-1})
\end{equation} 
for $s\in \mathbb{Z}$. Now, by the Radford trace formula (Theorem \ref{t:t2} (v)), 
\begin{equation}\label{eq:tr-fr}
\Tr(S_F \circ  P^{(n,-k)}_F) =  \ld\left(S(\Ld_{(2)})  S_F(P^{(n,-k)}_F(\Ld_{(1)})) \right) \\
\end{equation} 
where  the integrals $\ld \in \int^r_{H^*}$ and $\Ld \in \int_H^l$ are normalized, i.e., $\ld(\Ld)=1$. 

We will use Lemma \ref{l:t1}, which is an adaptation from \cite{KMN12}, to simplify the right hand side of \eqref{eq:tr-fr}. More precisely, let $l = n-k$. Applying Lemma \ref{l:t1} for $Y = m \circ \s_{(n,-k)} \circ \bigotimes_{p=1}^{n-1} S_F^{2 c_p}$, we have
\begin{align*}
\Tr(S_F \circ  P^{(n,-k)}_F) =&\ld \circ S\Biggl(\dd{i}{1} \biggl(\prod_{p=1}^{n-1}S_F^{2c_{\ol{lp}}}(\ff{j}{\ol{lp}}\Lda{\ol{lp}}\dd{i}{\ol{lp}+1})\biggl)\ff{j}{n}\Lda{n}\Biggl) \\ 
=&\ld \circ S\Biggl(\prod_{p=1}^{n}S_F^{2c_{\ol{lp}}}\left( S_F^{2\delta(\ol{lp})}(\dd{i}{\ol{l(p-1)+1}}) \ff{j}{\ol{lp}}\Lda{\ol{lp}}\right) \Biggl)
\end{align*}
which follows from $c_{\ol{l(p-1)}} = c_{\ol{lp+k}} = c_{\ol{lp}}+\delta(\ol{lp})$. Note that $\delta(n)=c_n = 0$, which explains the last term of the preceding expression. By Definition \ref{d:cp} and \eqref{eq:Qs}, we have 
\begin{itemize}
\item $\delta(p) = 1$ and $Q_{c_{p}}S^{2c_{p}}(Q) = Q_{c_{p} + 1} = Q_{c_{\ol{p+k}}}$ if $1 \le p \le k_0$;
\item $\delta(p) = -1$ and $Q_{c_{p}}S^{2c_{p}}(Q_{-1}) = Q_{c_{p} - 1} = Q_{c_{\ol{p+k}}}$ if $k_0+1 \le p \le 2k_0$;
\item $\delta(p) = 0$ and $Q_{c_{p}}S^{2c_p}(Q_0) = Q_{c_{p}} = Q_{c_{\ol{p+k}}}$ if $2k_0+1 \le p \le n$,
\end{itemize} 
where $k_0 = \tfrac{n-k-1}{2}$. Therefore, for all $1 \le p \le n$, we have $Q_{c_{p}}S^{2c_{p}}(Q_{\delta(p)}) = Q_{c_{\ol{p+k}}}$. Let $Y' := \ld \circ S \circ m \circ \s_{(n,-k)}$. Then we can rewrite $\Tr(S_F \circ  P^{(n,-k)}_F)$ as 
\begin{align*}
= &\  Y' \Biggl(\bigotimes_{p=1}^n 
S_F^{2c_{p}}\!\!\left(\! S_F^{2\delta(p)}(\dd{i}{\ol{p+k+1}}) \ff{j}{p}\Lda{p}\!\right)\!\!
\Biggl) =Y' \Biggl(\bigotimes_{p=1}^{n}
Q_{c_{p}} S^{2c_{p}}(Q_{\delta(p)}S^{2\delta(p)}(\dd{i}{\ol{p+k+1}}) Q^{-1}_{\delta(p)}\ff{j}{p}\Lda{p})Q_{c_p}^{-1} \!\!\Biggl)\\ 
=&\ Y' \Biggl(\bigotimes_{p=1}^{n}
Q_{c_{\ol{p+k}}} S^{2c_{p}}(S^{2\delta(p)}(\dd{i}{\ol{p+k+1}}) Q^{-1}_{\delta(p)}\ff{j}{p}\Lda{p})Q_{c_p}^{-1} \Biggl)\\
=&\ \ld S \Biggl(\prod_{p=1}^{n} Q_{c_{\ol{l(p-1)}}} S^{2c_{\ol{lp}}}(S^{2\delta(\ol{lp})}(\dd{i}{\ol{l(p-1)+1}}) Q^{-1}_{\delta(\ol{lp})}\ff{j}{\ol{lp}}\Lda{\ol{lp}})Q_{c_{\ol{lp}}}^{-1}\Biggl)\\
=&\ \ld S \Biggl(\prod_{p=1}^{n}  S^{2c_{\ol{lp}}}(S^{2\delta(\ol{lp})}(\dd{i}{\ol{l(p-1)+1}}) Q^{-1}_{\delta(\ol{lp})}\ff{j}{\ol{lp}}\Lda{\ol{lp}})\Biggl) \quad\text{since $Q_{c_{\ol{0}}} = Q_0 = 1$}\\
=&\ \ld S\Biggl(\dd{i}{1}\ff{j}{l}\Lda{l}\prod_{p=2}^{n} S^{2c_{\ol{lp}}}\left(S^{2\delta({\ol{lp}})}(\dd{i}{\ol{l(p-1)+1}}) Q^{-1}_{\delta({\ol{lp}})}\ff{j}{{\ol{lp}}}\Lda{{\ol{lp}}}\right)\Biggl)\,.
\end{align*}

Applying Theorem \ref{t:t2} (vi), the last expression becomes
\begin{align*}
&\ld S\Biggl(\Lda{l} \biggl(\prod_{p=2}^{n} S^{2 c_{\ol{l(p-1)}}}\left(S(\dd{i}{1}\ff{j}{l})_{(\ol{l(p-1)})}\right) S^{2c_{\ol{lp}}}\left(S^{2\delta({\ol{lp}})}(\dd{i}{\ol{l(p-1)+1}}) Q^{-1}_{\delta({\ol{lp}})}\ff{j}{{\ol{lp}}}\Lda{{\ol{lp}}}\right)\biggl) \Biggl)\\
=& \ \ld S\Biggl(\Lda{l} \cdot
\prod_{p=2}^{n} S^{2c_{\ol{lp}}}\left(S^{2 \delta(\ol{lp})}\bigl(S(\dd{i}{1}\ff{j}{l})_{(\ol{l(p-1)})}\dd{i}{\ol{l(p-1)+1}}\bigl) Q^{-1}_{\delta({\ol{lp}})}\ff{j}{{\ol{lp}}}\Lda{{\ol{lp}}}\right)
\Biggl)\\
% =&\  Y'\Biggl(
% \bigotimes_{p=1}^{l-1} S^{2c_{p}}\left(S^{2 \delta(p)}(S(\dd{i}{1}\ff{j}{l})_{(\ol{p+k})}\dd{i}{\ol{p+k+1}}) Q^{-1}_{\delta({p})}\ff{j}{{p}}\Lda{{p}}\right)
% \o \Lda{l} \\
% &\quad\quad \o \bigotimes_{p=l+1}^{n} S^{2c_{p}}\left(S(\dd{i}{1}\ff{j}{l})_{(\ol{p+k})}\dd{i}{\ol{p+k+1}} \ff{j}{{p}}\Lda{{p}}\right) 
% \Biggl)\\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{l-1} S^{2c_{p}}\left(S^{2 \delta(p)}(S(\dd{i}{1}\ff{j}{l})_{(p+k)}\dd{i}{p+k+1}) Q^{-1}_{\delta({p})}\ff{j}{{p}}\Lda{{p}}\right)
\o \Lda{l} \\
&\quad\quad \o \bigotimes_{q=1}^{k} S^{2c_{q+l}}\left(S(\dd{i}{1}\ff{j}{l})_{(q)}\dd{i}{q+1} \ff{j}{{l+q}}\Lda{{l+q}}\right) 
\Biggl)\,.
\end{align*}

By Lemma \ref{lem:trick-3} (i), we have 
\[F_n =  \left(\bigotimes_{p=1}^{l-1} \ff{j}{p}\right) \o (F_{k+1} \De^{k+1}(\ff{j}{l})) \text{ and } F_n^{-1} =  (\De^{k+1}(\dd{i}{1}) F_{k+1}^{-1}) \o \left(\bigotimes_{p=2}^{l}\dd{i}{p}\right)\,.\]
Moreover, since $c_p=c_{\ol{p+k}}$ for $n-k+1 \le p \le n$, $c_q=c_{q+l}$ for $1\le q \le k$ and $\Tr(S_F \circ  P^{(n,-k)}_F) $ equals to 
\begin{align*}
&\ Y'\Biggl(\biggl(\bigotimes_{p=1}^{l-1} S^{2c_{p}}\Bigl(S^{2 \delta(p)}\Bigl(S(\dd{i\,(1)}{1}\ff{j\, (1)}{l})_{(p+k)}\dd{i}{p+1}\Bigl) Q^{-1}_{\delta({p})}\ff{j}{{p}}\Lda{{p}}\biggl)
\o \Lda{l} \\
&\quad\quad \o \biggl(\bigotimes_{q=1}^{k} S^{2c_{q}}\Bigl(S(\dd{i\, (1)}{1}\ff{j\, (1)}{l})_{(q)}\dd{i\, (q+1)}{1}\ff{j\, (q+1)}{l}\Lda{q+l}\biggl) \Biggl) \\
=&\ Y'\Biggl(\biggl(\bigotimes_{p=1}^{l-1} S^{2c_{p}}\Bigl(S^{2 \delta(p)}\Bigl(S(\dd{i\,(l-p)}{1}\ff{j\, (l-p)}{l})\dd{i}{p+1}\Bigl) Q^{-1}_{\delta({p})}\ff{j}{{p}}\Lda{{p}}\biggl)
\o \Lda{l} \\
&\quad\quad \o \biggl(\bigotimes_{q=1}^{k} S^{2c_{q}}\Bigl(S(\dd{i\, (n-q)}{1}\ff{j\, (n-q)}{l})\dd{i\, (n-1+q)}{1}\ff{j\, (n-1+q)}{l}\Lda{l+q}\biggl) \Biggl) \\
= &\ Y'\Biggl(\biggl(\bigotimes_{p=1}^{l-1} S^{2c_{p}}(S^{2 \delta(p)}(S(\ff{j\, (l-p)}{l}) S(\dd{i\,(l-p)}{1})\dd{i}{p+1})
Q^{-1}_{\delta(p)} \ff{j}{p} \Lda{p})\biggl) \o \bigotimes_{p=l}^n S^{2 c_p}(\Lda{p}) \Biggl)\,,
\end{align*}
where the last equation follows from the antipode conditions and $(\id^{\o (n-1)} \o \e)(F_n)=F_{n-1}$. It follows from Lemma \ref{lem:trick-3} (v) that $\bigotimes_{p=1}^{l-1}S(\dd{i\,(l-p)}{1})\dd{i}{p+1}=\bigotimes_{p=1}^{l-1}S(\ff{t}{l-p}) u^{-1}$. Now the last expression equals
\begin{align*}
& Y'\Biggl(
\bigotimes_{p=1}^{l-1} S^{2c_{p}}
\left(S^{2 \delta(p)}(S(\ff{j\, (l-p)}{l}) S(\ff{t}{l-p}) u^{-1})
Q^{-1}_{\delta(p)} \ff{j}{p} \Lda{p}\right) \o 
\bigotimes_{p=l}^n S^{2 c_p}(\Lda{p})  
\Biggl)\\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{l-1} S^{2c_{p}}\left(S^{2 \delta(p)}(S(\ff{t}{l-p}\ff{j\, (l-p)}{l}) u^{-1}) Q^{-1}_{\delta(p)} \ff{j}{p} \Lda{p}\right)
\o 
\bigotimes_{p=l}^n S^{2 c_p}(\Lda{p})  
\Biggl)\\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{l-1} S^{2c_{p}}\left(S^{2 \delta(p)}(S(\ff{i}{2l-p-1})  u^{-1}) Q^{-1}_{\delta(p)} \ff{i}{p} \Lda{p}\right) \o 
\bigotimes_{p=l}^n S^{2 c_p}(\Lda{p}) \Biggl)\\
% \end{align*}
% \begin{align*}
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\left(S^3(\ff{i}{4k_0-p+1})S^2(u^{-1})Q^{-1} \ff{i}{p} \Lda{p}\right) 
\o \bigotimes_{p=k_0+1}^{2k_0} S^{2c_p}\left(S^{-1}(S(\ff{i}{p} )u^{-1} \ff{i}{4k_0-p+1})\Lda{p}\right)\\
&\quad\quad  \o \bigotimes_{p=l}^n S^{2 c_p}(\Lda{p})  \Biggl) 
\end{align*}
since $\delta(p)=1$ for $1 \le p \le k_0$,  $\delta(p)=-1$ for $k_0+1 \le p \le 2k_0$ and $Q_{-1}^{-1}=S^{-2}(Q)$. 
Repeatedly applying Lemma \ref{lem:trick-3} (iii) starting from $p=2k_0$ in the second term of the last expression, we find it equals to 
\begin{align*}
& Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\left(S^3(\ff{i}{2k_0-p+1})S^2(u^{-1})Q^{-1} \ff{i}{p} \Lda{p}\right) \o 
\bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p}) \Biggl)  \\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}} \left(S^3(\ff{j}{k_0-p+2})S^2(u^{-1})Q^{-1} \ff{i}{p}\ff{j\,(p)}{1} \Lda{p}\right) \o 
\bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p}) \Biggl) \text{ by Lemma \ref{lem:trick-3} (i)}\\
% & \qquad \text{ since }F_{2k_0} =F_{k_0}\De^{k_0}(\ff{j}{1})\o \ff{j}{2}\o \cdots \o \ff{j}{k_0+1} \text{ by Lemma \ref{lem:trick-3}(i)}\\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\left(S^2(\ff{j\,(p)}{1})S^3(\ff{j}{k_0-p+2})S^2(u^{-1})Q^{-1} \ff{i}{p} \Lda{p}\right) \o \bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p}) \Biggl) \text{ by Lemma \ref{l:t3}.}
\end{align*}
It follows from the second equality of \eqref{eq:u-f-Sf-3} in Lemma \ref{lem:trick-3} (iv), we have
\begin{align*}
& \Tr(S_F\circ P_F^{(n,-k)}) 
=  Y'\Biggl(\bigotimes_{p=1}^{k_0} S^{2c_{p}}\biggl(S^2(\dd{j}{p} u)S^2(u^{-1})Q^{-1} \ff{i}{p} \Lda{p}\biggl) \o \bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p})\Biggl) \\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\left(S^2(\dd{j}{p})Q^{-1} \ff{i}{p} \Lda{p}\right) \o \bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p}) \Biggl) \\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}(Q^{-1}_{(p)} \Lda{p}) \o \bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p}) 
\Biggl) \text{ by \eqref{eq:f-DQ-Q-Sf} of Lemma \ref{lem:trick-3} (v)}\\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\left(S(u)_{(p)} S(\dd{i}{1})_{(p)}\dd{i\,(p)}{2} \Lda{p}\right) \o 
\bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p})\Biggl) \text{ as $u^{-1} = S(\dd{i}{1})\dd{i}{2}$.}
\end{align*}
So by Lemma \ref{l:t3}, we have 
\begin{align*}
 &\Tr(S_F\circ P_F^{(n,-k)}) 
=\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\left(S^2(\dd{i\,(p)}{2})S(u)_{(p)} S(\dd{i}{1})_{(p)} \Lda{p}\right) \o 
\bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p})\Biggl) \\
=&\ Y'\Biggl(
\bigotimes_{p=1}^{k_0} S^{2c_{p}}\biggl(\Bigl(S^2(\dd{i}{2})S(u) S(\dd{i}{1})\Bigl)_{(p)} \Lda{p}\biggl) \o \bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p})\Biggl)  \text{ as $\dd{i}{1} u S(\dd{i}{2}) =1$}\\
=&\ Y'\Biggl(\bigotimes_{p=1}^{k_0} S^{2c_{p}}(\Lda{p}) \o \bigotimes_{p=k_0+1}^{n} S^{2c_p}(\Lda{p})\Biggl)\ = \Tr(S \circ P^{(n,-k)}) 
\end{align*}
This completes the proof of that $\Tr(S \circ P^{(n,-k)}) = K(L(n, k), \frm_R, H)$ is a gauge invariant. 
\end{proof}



\subsubsection{Gauge invariance of \texorpdfstring{$K(L(n,k), \frmL, H)$}{} for odd \texorpdfstring{$k$}{}} 
Let $n>k>0$ be coprime integers with $k$ odd. Similar to the previous subsection, we read the rotation numbers from the 2-combed Heegaard diagram in Figure \ref{fig:fL-detail}, show it is a framed Heegaard diagram, and study the gauge invariance of the associated Kuperberg invariants. 

We start with the rotation numbers $\theta$. For the lower curve $\eta$, it is easy to see that $\theta_\eta(p_1) = \tfrac{1}{4}$, $\theta_\eta(p_j) = \tfrac{1}{2}$ for all $2 \le j \le n$, and $\theta_\eta = \tfrac{1}{2}$.

We now obtain the change of rotation number from $p_i$ to the next $I$-point on the upper curve $\mu$. For $i = 1$,  we can see that $\theta_{\mu}(p_1) = 0$, and we have already had $\theta_{\eta} = \tfrac{1}{4}$, so $s_1 = 2(\tfrac{1}{4}-0)+\tfrac{1}{2} = 1$. As we go along $\mu$, the next $I$-point we encounter will be $p_{k+1}$. As is illustrated in Figure \ref{fig:fL-S-power-0}, we have $\theta_{\eta}(p_{k+1})=\tfrac{1}{2}$, and $\theta_{\mu}(p_{k+1})=\tfrac{1}{4}$, so $s_{k+1} = 2(\tfrac{1}{2}-\tfrac{1}{4})+\tfrac{1}{2}=1=s_1$. 
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fL-S-power-0.eps}
    \caption{$\theta_\mu(p_1) = 0$, $\theta_{\mu}(p_{k+1}) = \tfrac{1}{4}$.}
    \label{fig:fL-S-power-0}
\end{figure}

For $2\leq i\leq n-k$, the local picture is illustrated in Figure \ref{fig:fL-S-power-1}, and it is immediately seen that $\theta_{\eta}(p_i) = \theta_{\eta}(p_{i+k})$ and $\theta_\mu(p_i) = \theta_\mu(p_{i+k})$, and consequently, $s_{i+k}=s_{i}$. 
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fL-S-power-1.eps}
    \caption{For $1 \le i \le n-k$, $\theta_{\mu}(p_i) = \theta_{\mu}(p_{i+k})$.}
    \label{fig:fL-S-power-1}
\end{figure}
Recall that when $k=1$, there is no $I$-point between $\xi_1$ and the left attaching circle, and by direct computation, we have $\theta_{\mu}(p_{n}) = \tfrac{1}{4} = \theta_{\mu}(p_{i})$ for all $2 \le i \le n-1$, and $\theta_{\eta}(p_n) = \tfrac{1}{2}$. Moreover, the total rotation number of the upper curve is $\theta_\mu=\tfrac{1}{2}$, so in this case, $s_1 = \cdots = s_n$.

Now we assume that $k \ge 3$, and denote $k_1 := \tfrac{k-1}{2}$. For $n-k+2\leq i \leq n-k_1$, the local picture from $p_{i}$ to $p_{\ol{i+k}}$ along $\mu$ is given in Figure \ref{fig:fL-S-power-2}. Reading from the local picture, we have $\theta_{\mu}(p_{\ol{i+k}}) = \theta_{\mu}(p_i)-1$, and $\theta_{\eta}(p_{\ol{i+k}}) = \theta_{\eta}(p_i)$, which implies that $s_{\ol{i+k}}=s_{i}+2$. 
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fL-S-power-2.eps}
    \caption{For $n-k+2\leq i \leq n-k_1$, $\theta_{\mu}(p_{\ol{i+k}}) = \theta_{\mu}(p_i)-1$.}
    \label{fig:fL-S-power-2}
\end{figure}

For $n-k_1+1 \leq i \leq n$, the local picture from $p_{i}$ to $p_{\ol{i+k}}$ along $\mu$ is given in Figure \ref{fig:fL-S-power-3}. Reading from it, we have $\theta_{\mu}(p_{\ol{i+k}}) = \theta_{\mu}(p_i)+1$, and $\theta_{\eta}(p_{\ol{i+k}}) = \theta_{\eta}(p_i)$, which implies that $s_{\ol{i+k}}=s_{i}-2$. 
\begin{figure}[ht]
    \centering
    \includegraphics[width=280pt]{eps/fL-S-power-3.eps}
    \caption{For $n-k_1+1 \leq i \leq n$, $\theta_{\mu}(p_{\ol{i+k}}) = \theta_{\mu}(p_i)+1$.}
    \label{fig:fL-S-power-3}
\end{figure}

Now we are left with $p_{n-k+1}$, which is the last $I$-point we visit on $\mu$ before going back to the base point $\xi_2$. Note that $J = \{\{p_2, ..., p_{n-k}\}, \{p_{n-k+2}, ..., p_{n-k_1}\}, \{p_{n-k_1+1}, ..., n\}\}$ is a partition of $I \setminus \{p_1, p_{n-k+1}\}$. Starting from $p_{k+1}$, we will go  through every point in $J$ and finally reach $p_{n-k+1}$ without passing $p_1$.  Moreover, by the discussions above, upon reaching the next $I$-point, the $\theta_\mu$-value increases by 1 for $k_1$ of the points in $J$, decreases by 1 for $k_1$ of the points in $J$ and remains unchanged for the rest of the points in $J$ (the reason we exclude $p_1$ from $J$ is because it does not follow this pattern). 
Therefore, the total change of $\theta_\mu$-value of the $I$-points when we go from $p_{1+k}$ to $p_{n-k+1}$ is 0, which means $\theta_\mu(p_{n-k+1}) = \theta_{\mu}(p_{1+k}) = \tfrac{1}{4}$, and so $s_{n-k+1} = s_{k+1} = s_1 = 1$. 

After reaching $p_{n-k+1}$, we will follow $\mu$ to go into the right attaching circle, passing through the vertical axis of $\xi_1$ in Figure \ref{fig:fL-detail}, and go back to $\xi_2$. In this process, the $\theta_\mu$-value decreases by $\tfrac{3}{4}$, i.e., the total rotation number $\theta_\mu$ is equal to $-\tfrac{1}{2}$. 

Finally, by design, we have $\phi_\eta(p_i) = \phi_\mu(p_i) = 0$ for all $1 \le i \le n$, and $\phi_\eta = \tfrac{1}{2} = \phi_\mu$. So we can see that $\theta_{\mu} = -\phi_{\mu}$, and $\theta_{\eta} = \phi_{\eta}$. 

We summarize the above discussions in the following lemma:

\begin{lemma}\label{lem:fL-diag}
Let $n>k \ge 1$ be coprime integers such that $k$ is odd. Then the 2-combed Heegaard diagram in Figure \ref{fig:fL-detail} is a framed Heegaard diagram. Moreover, the exponent $s_i$'s are computed recursively with $s_1= 1$ as follows:
\begin{enumerate}[label=\rm{(\roman*)}] 
\item If $1\leq i\leq n-k+1$, then $s_{\ol{i+k}}=s_i$;
\item If $n-k+2\leq i \leq n-\tfrac{k-1}{2}$, then $s_{\ol{i+k}}=s_i+2$;
\item If $n-\tfrac{k-1}{2}+1 \leq i \leq n$, then $s_{\ol{i+k}}=s_i-2$. \qed
\end{enumerate}
\end{lemma}

Recall that the diagram framing associated to Figure \ref{fig:fL-detail} is denoted by $\frmL$.

\begin{prop} \label{p:duality}  
Let $n>k>0$ be  coprime integers such that  $k$ is odd. For any finite-dimensional Hopf algebra $H$, we have 
\[K(L(n, k),  \frm_L, H)=K(L(n, n-k),  \frm_R, H^{\op})\,.\]
\end{prop}
\begin{proof} 
Let $\ld \in \int_{H^*}^r$ and $\Ld \in \int_H^l$ be normalized integrals for $H$, and recall from \eqref{eq:twisted-ld} that $\ld_{\frac{1}{2}}=\ld\circ S^{-1}$ and $\Ld_{\frac{1}{2}}=\Ld$. By definition, the Kuperberg invariant of $L(n,k)$ for the framing $\frm_L$ as
\begin{align*}
	K(L(n, k), \frm_L, H)=\ld_{\frac{1}{2}}\left(m\circ \tau_{n,k}\circ (\otimes_{i=1}^nS^{s_i})\circ\Delta^{(n)}(\Ld_{\frac{1}{2}})\right)=\ld S^{-1}\left(m\circ \tau_{n,k}\circ (\otimes_{i=1}^nS^{s_i})\circ\Delta^{(n)}(\Ld)\right)
\end{align*}
where $\tau_{n,k}$ be the permutation $\tau_{n,k}(i)=\ol{1+(i-1)k}$ for $i \in \{1,\dots, n\}$.                     

Note that $S(\Ld)$ is the left integral of $H^{\op}$ such that $\ld \circ S(\Ld) =1$. Thus, $\ld$ and $S(\Ld)$ are normalized  integrals for $H^{\op}$, and we find
\begin{align*}
K(L(n, k),  \frm_L, H^{\op})
=&\ld S(m^{\op}\circ \tau_{n,k}\circ (\otimes_{i=1}^nS^{-s_i})\circ\Delta^{(n)}(S(\Ld)))\\
=&\ld S(m^{\op}\circ \tau_{n,k}\circ (\otimes_{i=1}^nS^{-s_i+1}(\Ld_{(n+1-i)})))\\
=&\ld S(S^{-s_{n+1-k}+1}(\Ld_{(k)})\cdots S^{-s_{1+k}+1}(\Ld_{(n-k)})S^{-s_1+1}(\Ld_{(n)}))
\end{align*}
Let $\tilde{k}=n-k$, $\tilde{k}_0 =\frac{n-\tilde{k}-1}{2} =\frac{k-1}{2}$, and $\tilde{c}_i=-s_{n+1-i}+1$ for $1\leq i \leq n$. Then $\tilde{c}_n=-s_1+1=0$ and $\tilde{c}_i$'s satisfy the following properties.
\begin{enumerate}[label=\rm{(\roman*)}] 
\item  If $1\leq i\leq \tilde{k}_0$, then $n-\tfrac{k-1}{2}+1 \leq n+1-i \leq n$ and $s_{n+1-i+k-n}=s_{n+1-i}-2$. Thus, we have $\tilde{c}_{i+\tilde{k}}=\tilde{c}_i+2$.

\item If $\tilde{k}_0+1\leq i \leq 2 \tilde{k}_0$, then $n-k+2\leq n+1-i \leq n-\tfrac{k-1}{2}$ and $s_{n+1-i+k-n}=s_{n+1-i}+2$. Thus, $\tilde{c}_{i+\tilde{k}}=\tilde{c}_i-2$.

\item  If $n-\tilde{k}+1 \leq i \leq n$, then $1\leq n+1-i\leq n-k$ and $s_{n+1-i+k}=s_{n+1-i}$. Thus, $\tilde{c}_{\overline{i+\tilde{k}}}=\tilde{c}_i$.
\end{enumerate}
Comparing to the recursive relation of the sequence $\{2c_i\mid 1 \le i \le n\}$ for the pair $(n, \tilde{k})$ in Definition \ref{d:cp}, we can see that $\{\tilde{c}_i\mid 1\le i \le n\}$ satisfies the same recursive relations and initial condition, so $\tilde{c}_i=2c_i$ for all $1 \le i\le n$. Hence, 
\begin{align*}
K(L(n, k),  \frm_L, H^{\op}) 
=& \ld S(S^{\tilde{c}_{n-\tilde{k}}}(\Ld_{(n-\tilde{k})})\cdots S^{\tilde{c}_{\tilde{k}}}(\Ld_{(\tilde{k})})S^{\tilde{c}_n}(\Ld_{(n)}))\\
=& \ld S(S^{2c_{n-\tilde{k}}}(\Ld_{(n-\tilde{k})})\cdots S^{2c_{\tilde{k}}}(\Ld_{(\tilde{k})})S^{2c_n}(\Ld_{(n)}))
= K(L(n,\tilde{k}), \frm_R, H)
\end{align*}
by the fourth equality of \eqref{eq:fR-form} in the proof of Theorem \ref{t:KInd}.
\end{proof}
 Since $K(L(n, n-k), \frm_R, H^{\op})$ is a gauge invariant by Theorem \ref{t:Lnk-fR}, so is $K(L(n, k), \frm_L, H)$.
\begin{thm}\label{t:Lnk-fL}
Let $n>k>0$ be coprime integers such that  $k$ is odd. Then for any finite-dimensional Hopf algebra $H$, the Kuperberg invariant $K(L(n, k), \frm_L, H)$ is a gauge invariant of $H$. \qed
\end{thm}

In \cite{Shi15}, the author used the extended Sweedler power to generalize the indicators defined in \cite{KMN12}:
\[
\nu_n(H) = \ld S(P^{(n)}(\Ld)) \text{ for $n \in \BZ$}\,,
\]
where $P^{(n)}$ is the $n$-th convolution power of the identity of $H$. In particular, for any positive integer $n$ and $x \in H$, $P^{(-n)}(x) = S(x_{(1)}) \cdots S(x_{(n)})$. We can view $\nu_n$ as special cases of the Kuperberg invariants in the following sense. Recall that for any nonnegative integer $n$, the lens space $L(n,n-1)$ is homeomorphic to $L(n,1)$ (cf. \eqref{eq:lens_iso}), then we can pull back $\frmR$ on $L(n,n-1)$ to obtain a framing on $L(n,1)$, denoted by $\frm_n$. When $n<0$, $L(n,1) \cong L(|n|, 1)$. By \cite{Kup96}, we can perform a spiral move to $\frmL$ and pull it back to from $L(|n|,1)$ to $L(n,1)$ to get another framing $\frm_n$ so that $K(L(n,1), \frm_n', H)=\alpha(g) K(L(|n|,1), \frmL, H)$ for all $H$. 

\begin{cor}\label{cor:Kup-and-nu}
For any integer $n$ and  finite-dimensional Hopf algebra $H$, we have 
\[
\nu_n(H) = K(L(n,1),\frm_n,H)=
\begin{cases}
K(L(n,n-1),\frmR,H) & \text{ if $n \ge 0$}\,,\\
\alpha(g) K(L(|n|,1),\frmL,H) & \text{ if $n < 0$}.
\end{cases}
\]
In particular, $\nu_n$ is a gauge invariant.
\end{cor}
\begin{proof}
Recall from \cite{Shi15} that $\nu_{-n}(H)=\alpha(g)\nu_n(H^{\op})$. The equalities follow from the fact that the Kuperberg invariant is an invariant of framed 3-manifolds up to homeomorphism (\cite[Thm.~4.1]{Kup96}), Theorems \ref{t:KInd}, \ref{t:Lnk-fR} and Proposition \ref{p:duality}.
\end{proof}





In view of Proposition \ref{p:duality}, Theorems \ref{t:Lnk-fL} and \ref{t:Lnk-fR}, we define the gauge invariant $\nu_{n,k}(H)$ for any finite-dimensional Hopf algebras $H$ and coprime integers $n > k >0$ as
\[
\nu_{n,k}(H):=\left\{\begin{array}{ll}
     K(L(n,n-k), \frm_R, H) & \text{if $k$ is odd;} \\
     K(L(n,n-k), \frm_L, H^{\op}) &  \text{if $k$ is even}.
\end{array}\right.
\]
Note that $\nu_{n,k}$ generalizes the $n$-th Frobenius-Schur indicator (see Corollary \ref{cor:Kup-and-nu}), namely, we have $\nu_n(H) = \nu_{n,1}(H)$. One could also define
\[\nu'_{n,k}(H):=\left\{\begin{array}{ll}
     K(L(n,k), \frm_L, H) & \text{if $k$ is odd;} \\
     K(L(n,k), \frm_R, H^{\op}) &  \text{if $k$ is even}.
\end{array}\right.\]
These gauge invariants satisfy the relation $\nu'_{n,k}(H) = \nu_{n,k}(H^{\op})$ for any coprime integers $n > k >0$ by Proposition \ref{p:duality}. When $H$ is defined over the complex number $\BC$, it is shown in \cite[Prop.\ 3.6]{Shi15} that $\ol{\nu_{n,1}(H)} = \nu_{n,1}(H^{\op}) = \nu'_{n,1}(H)$, and $\nu_{n,1}(H)$ is a cyclotomic integer. We do not know  whether similar properties hold for other pairs of coprime integers $n$, $k$. 
\begin{question}
Does the following  properties hold for any coprime positive integers $n,k$ for any 
finite-dimensional Hopf algebra $H$ over $\BC$?
\begin{enumerate}[label=\rm{(\roman*)}] 
\item $\ol{\nu_{n,k}(H)} = \nu_{n,k}(H^\op)$.
\item $\nu_{n,k}(H)$ is a cyclotomic integer.
\item $\nu_{n,k}(D(H)) = |\nu_{n,k}(H)|^2$.
\end{enumerate}
\end{question}
Note that (iii) follows from (i), cf.\ Corollary \ref{cor:DH}.

\subsection{Gauge invariance of \texorpdfstring{$K(L(n,k), \frm, H)$}{} with arbitrary framing \texorpdfstring{$\frm$}{}}\label{subsec:gen-frm}
In this subsection, we study the Kuperberg invariants of lens spaces with general framings and prove their gauge invariance. 
In order to do it, we start by giving a brief description of the homotopy classification of framings on a general 3-manifold $M$. 
Once a framing on $M$ is fixed, the set of framings up to homotopy can be identified with $[M, \SO(3)]$, the homotopy set of maps from $M$ to $\SO(3)$. Any map from $M$ to $\SO(3)$ can be viewed as an extension from the 0-skeleton $M^{0}$ of $M$ to $M = M^{3}$. By obstruction theory, up to homotopy, maps from $M^{1}$ to $\SO(3)$ which can be extended to $M^{2}$ are classified by $H^{1}(M, \pi_{1}\SO(3)) = H^{1}(M, \mathbb{Z}/2\mathbb{Z})$. Since $\pi_{2}\SO(3) = 0$, any of the extendable map above can be further extended to $M = M^{3}$, and up to homotopy, the extensions of such a map to the whole manifold $M$ are classified by $H^{3}(M, \pi_{3}\SO(3)) = H^{3}(M, \mathbb{Z})$. Therefore, each map from $M^2$ to $\SO(3)$ has $|H^{3}(M, \mathbb{Z})|$ extensions to $M$ up to homotopy, i.e., $[M, \SO(3)]=H^{1}(M, \mathbb{Z}/2\mathbb{Z}) \times H^{3}(M, \mathbb{Z})$. 
Relative to the fixed choice of framing, we call the $H^{1}(M, \mathbb{Z}/2\mathbb{Z})$-component of any framing its \emph{spin class}, and the $H^{3}(M, \mathbb{Z})$-component its \emph{degree}, see \cite[Sec.\ 2]{Kup96} for details.

Let $H$ be a finite-dimensional Hopf algebra. By \cite{Kup96}, when the degree of a framing $\frm$ of $M$ changes by +1, the corresponding Kuperberg invariant $K(M, \frm, H)$ gets a factor of $\alpha(g)$, which is a gauge invariant. Therefore, if $K(M, \frm, H)$ is a gauge invariant for some framing $\frm$, then $K(M, \frm', H)$ is also a gauge invariant for any framing $\frm'$ that has the same spin class as $\frm$. Consequently, in order to prove the gauge invariance of the Kuperberg invariant associated to an arbitrary framing on $M$, we only need to show that for any spin class, there is a framing $\frm$ on $M$ in that spin class such that $K(M, \frm, H)$ is a gauge invariant.

The spin class of the diagram framing $\frm$ of $M$ associated to a framed Heegaard diagram with combings $b_1$ and $b_2$ can be read from $b_1$ as follows. By the universal coefficient theorem and the Poincar\'e duality, we have the following split short exact sequence 
\[0 \to H^1(M, \BZ)\otimes \BZ/2\BZ \to H^1(M, \BZ/2\BZ) \to \Tor(H^2(M,\BZ), \BZ/2\BZ) \to 0\,,\]
and the spin class of $\frm$ is determined by its components in $H^1(M, \BZ)\ot \BZ/2\BZ$ and $\Tor(H^2(M,\BZ), \BZ/2\BZ)$ (``the torsion part''). In particular, if $M$ satisfies $H^{1}(M, \BZ) \cong H_{2}(M, \BZ) = 0$, then the spin class of $\frm$ is completely determined by its torsion part. In \cite{Kup96}, it is argued that the torsion part of $\frm$ is given by the characteristic class $c \in H^{2}(M, \BZ)$ of $b_1$ (by viewing $b_1$ as a map from $M$ to $S^{2}$). Moreover, the reason for $c \in \Tor(H^2(M,\BZ), \BZ/2\BZ)$ is that $2c$ is the obstruction of the extension of $b_1$ to $\frm$, which has to vanish. 

In this way, we are able to compare the spin classes of two diagram framings of a 3-manifold with vanishing second integral cohomology, and lens spaces can be easily shown to satisfy this condition (for example by the Mayer-Vietoris sequence associated to a genus 1 Heegaard diagram such as the one in Figure \ref{fig:HD-Lnk}). 
This enables us to obtain our main theorem on the gauge invariance of the Kuperberg invariants for lens spaces.

\begin{thm} \label{t:genus_1}
Let $n$, $k$ be coprime integers. For any framing $\frm$ of lens space $L(n, k)$, the Kuperberg invariant $K(L(n,k), \frm, H)$ is a gauge invariant of finite-dimensional Hopf algebras.
\end{thm}
\begin{proof}
Denote $L(n,k)$ by $\BL$ for short. Since $H^1(\BL, \BZ) = 0$, $H^1(\BL,\BZ/2\BZ) \cong \Tor(H^2(\BL,\BZ), \BZ/2\BZ) \cong \Tor(\BZ/n\BZ, \BZ/2\BZ)$ by Poincar\'e duality.  We have the following two cases.

When $n$ is odd, $H^1(\BL, \BZ/2\BZ) = 0$. Therefore, up to degree, any framing $\frm$ on $\BL$ is homotopic to either $\frm_L$ (when $k$ is odd) or $\frm_R$ (when $k$ is even). Thus, up to a power of $\alpha(g)$, $K(\BL, \frm, H)$ is equal to $K(\BL, \frm_L, H)$ or $K(\BL, \frm_R, H)$, and we are done by Theorems \ref{t:Lnk-fR} and \ref{t:Lnk-fL}.


When $n$ is even, then $k$ has to be odd, and $H^1(\BL, \BZ/2\BZ)\cong \BZ/2\BZ$. In light of the above discussions, by Theorems \ref{t:Lnk-fR} and \ref{t:Lnk-fL}, it suffices to show that $\frm_L$ and $\frm_R$ have different spin classes. Denote the 2 combings in the framed Heegaard diagram for $\frmL$ by $b_1$ and $b_2$, and those for $\frmR$ by $b_1'$ and $b_2'$ respectively. To compare the spin classes of $\frm_L$ and $\frm_R$, we only need to compare the characteristic classes $c$, $c' \in H^2(\BL, \BZ)$ of $b_1$ and $b_1'$ respectively. The relative characteristic class $c-c'$ can be presented by its Poincare dual $[C]\in H_1(\BL, \mathbb{Z})$. According to \cite[Lem.\ 2.14]{Les15}, this homology class is represented geometrically by a closed curve $C \subset \BL$ on which $b_1=-b'_1$. Apparently, if $[C] \ne 0$ in $H_1(\BL, \mathbb{Z})$, then $\frmL$ and $\frmR$ have different spin classes in $H^1(\BL, \BZ/2\BZ)$. 

To find the $C$, we compare the framed Heegaard diagrams $D$ (resp.\ $D'$) with combing $b_1$ (resp.\ $b_1'$) in Figure \ref{fig:fL-no-move} (resp.\ Figure \ref{fig:fR-no-move}) for $\frmL$ (resp.\ $\frmR$). Note that $D$ and $D'$ have identical underlying Heegaard diagram without combings. For the reader's convenience, we present the information relevant to our discussions here in Figure \ref{fig:compare} below. Note that by design, our combings $b_1$ and $b_1'$ are completely determined by the positions of the base points up to homotopy, so we only draw the combings near the base points in the figure.
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.7\linewidth]{eps/compare-fL-fR.eps}
    \caption{}
    \label{fig:compare}
\end{figure}
In Figure \ref{fig:compare}, we put $b_1$ and $b_1'$ in the same Heegaard diagram, and by construction, we place their left base points (labeled by $\xi_1$ in Figures \ref{fig:fL-no-move} and \ref{fig:fR-no-move}) at the same position, and we write $\xi_1=\xi_1'$ for the common left base point. 

Denote the right base point of $b_1$ by $\xi_2$ and that of $b_1'$ by $\xi_2'$. Then, by construction, there are $\tfrac{k-1}{2}$ $I$-points to the left of $\xi_2$ and $\tfrac{n-k-1}{2}$ $I$-points to the right of $\xi_2'$, which means there are $\tfrac{n}{2}$ $I$-points between $\xi_2$ and $\xi_2'$. Moreover, it can be immediately seen that along the segment of the lower curve $\eta$ connecting $\xi_2$ and $\xi_2'$ (colored in orange in Figure \ref{fig:compare}), $b_1$ is opposite to $b_1'$, so this part of $\eta$ is a segment $C_2$ of the \emph{anti-parallel locus} $C$. As is demonstrated in \cite{Kup96}, the other segment $C_1$ of $C$ lies in the disc $\mathbb{B}$ that the upper curve $\mu$ bounds in $\BL$. We can assume without loss of generality that $C_1$ is a segment in $\mathbb{B}$ connecting $\xi_2$ and $\xi_2'$. We then isotope $C_1$ to align with a segment of the upper curve $\mu$, and still denote that segment of $\mu$ by $C_1$. See the left part of Figure \ref{fig:euler} for an illustration of this situation. In this way, we get a closed curve $C_1 \cup C_2$ representing $[C] \in H_1(\BL, \BZ)$. See the right part of Figure \ref{fig:euler} for a picture in the Heegaard diagram of $\BL$.
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.2\linewidth]{eps/Euler-class-0.eps}
    \qquad
    \includegraphics[width=0.5\linewidth]{eps/Euler-class-1.eps}
    \caption{}
    \label{fig:euler}
\end{figure}

Now, to compute the homology class of $C$, we can perform an isotopy to $\BL$ so that $C_2$ is shrunk to a point that identifies $\xi_2$ and $\xi_2'$, and $C_1$ becomes a loop $\gamma$. Then we have $[C] = [\gamma] \in H_1(\BL,\BZ)$. Since $\mu$ bounds a disk in $\BL$, so $\gamma$ cannot bound a disk in $\BL$ because it is only a part of $\mu$. Therefore, $[C] = [\gamma] \ne 0 \in H_1(\BL,\BZ)$. In other words, the two framings $\frmL$ and $\frmR$ have different spin classes.
\end{proof}


\begin{cor}\label{cor:DH}
Let $H$ be a finite-dimensional Hopf algebra over a field $\kk$, and let $D(H)$ be the Drinfeld double of $H$. Let $n, k \in \BZ$ be a pair of coprime integers, and denote $L(n,k)$ by $\BL$.
\begin{enumerate}[label=\rm{(\roman*)}]
\item For any framing $\frm$ of $\BL$, $K(\BL, \frm, D(H)) = K(\BL, \frm, H) \cdot K(\BL, \frm, H^{\op})$.
\item The value $K(\BL, \frm, D(H))$ {is independent of the framing $\frm$ of $\BL$.}
% \item If in addition both $n$ and $k$ are odd, then $K(\BL, \frm, D(H))$ is a multiple of $K(\BL, \frm, H)^2$ by a root of unity. 
\end{enumerate}
\end{cor}
\begin{proof}
(i) By \cite{DT94}, $D(H)$ is gauge equivalent to $H \ot (H^*)^{\cop} \cong H \ot (H^{\op})^{*}$, so by Theorem \ref{t:genus_1} and the multiplicativity of the Kuperberg invariant \cite[Sec.~5]{Kup96}, we have 
\[K(\BL, \frm, D(H)) = K(\BL, \frm, H) \cdot K(\BL, \frm, (H^{\op})^*) = K(\BL, \frm, H) \cdot K(\BL, \frm, H^{\op})\,,\]
where the second equality follows from the invariance of the Kuperberg invariant under taking duals of Hopf algebras, which is argued in  \cite[Sec.~5]{Kup96}.

(ii) As is argued in \cite{Kup96}, when we fix the spin class of $\frm$ and change its Hopf degree, the resulting Kuperberg invariant differs only by a power of $\alpha(g)$ of $H$. {Since $D(H)$ is unimodular, the Kuperberg invariant is independent of the degree of the framing $\frm$. It remains to show that it is also independent of the spin class of $\frm$. Since $H^1(\BL, \BZ/2\BZ) = 0$ for odd $n$, the framings $\frm$, $\frmL$, $\frmR$ belong to the same spin class of $\BL$ whenever they are well-defined.  In particular, we have
\[
K(\BL, \frm, D(H))=\begin{cases}
    K(L(|n|,\ol{k}), \frmL, D(H)) & \text{if $\ol{k}$ is odd};\\
    K(L(|n|,\ol{k}), \frmR, D(H)) & \text{if $\ol{-k}$ is odd},
\end{cases}
\]
where $\ol{k}$ again denotes the least positive residue of $k$ modulo $n$. 

Now, we assume $n$ is even. Then both $\ol k$ and $\ol {-k}$ are odd. If $\frm$ has the same spin class as $\frmL$, then
\[
K(\BL, \frm, D(H))= K(L(|n|,\ol{k}), \frmL, D(H)) = K(L(|n|,\ol{k}), \frmL, H) K(L(|n|,\ol{-k}), \frmR, H)
\]
by Proposition \ref{p:duality}. On the other hand, if $\frm$ and $\frmR$ are in the same spin class, then 
\[
K(\BL, \frm, D(H))= K(L(|n|,\ol{-k}), \frmR, D(H)) = K(L(|n|,\ol{-k}), \frmR, H) K(L(|n|,\ol{k}), \frmL, H)\,.
\]
Therefore, $K(\BL, \frm, D(H))$ is also independent of the spin class of $\frm$.
}

% (iii) When both $n$ and $k$ are odd, $\BL$ has only one spin class, so by (i), (ii) and Proposition \ref{p:duality}, we have
% \[K(\BL, \frm, D(H)) = K(\BL, \frm_L, D(H)) = K(\BL, \frm_L, H) \cdot K(\BL, \frm_L, H^{\op}) = K(\BL, \frm_L, H) \cdot K(L(n,n-k), \frm_R, H)\,.\]
% Since $L(n,n-k) \simeq \BL$ as 3-manifolds, so (after identifying them by a homeomorphism), the framed 3-manifolds $(\BL, \frm_L)$ and $(L(n,n-k), \frm_R)$ are only different in their Hopf degrees. Therefore, again by Kuperberg's argument, we have $K(L(n,n-k), \frm_R, H) = K(\BL, \frm_L, H)\cdot \alpha(g)^x$ for some $x \in \BZ$. Now we are done because using the same argument, we have $K(\BL, \frm, H) = K(\BL, \frm_L, H) \cdot \alpha(g)^y$ for some $y \in \BZ$.
\end{proof}


\begin{exmp}
Let $n\ge 2$ be an integer. For any primitive $n$-th root of unity $\zeta \in \BC$, let $T(\zeta)$ be the Hopf algebra over $\BC$ with the algebra generated by $x, g$ subject to the relations:
\[
 x^n=0,\, g^n=1,\, gx=\zeta xg\,.
\]
The coalgebra structure and antipode of $T(\zeta)$ are given by
\[\begin{split}
&\De(g)=g\ot g, \,\quad \De(x)=x\ot g + 1 \ot x,\,  \\
&\e(g)=1,\,\, \e(x)=0,\,\, S(g)=g^{-1},\,\, S(x)=-xg^{-1}.
\end{split}\]
This Hopf algebra, known as the Taft algebra \cite{Taft1971}, has dimension $n^2$ and $\{x^i g^j \mid 0 \le i,j \le n-1 \}$ forms a basis for $T(\zeta)$. Moreover,
$\Ld=(\sum_{i=1}^{n} g^i)x^{n-1} \in \int^l_{T(\zeta)}$ and $\ld=\delta_{x^{n-1}} \in \int^r_{T(\zeta)^*}$ form a pair of normalized integral for $T(\zeta)$, i.e., $\ld(\Ld)=1$. 
\begin{enumerate} [label=\rm (\roman{*}), itemsep=3pt, leftmargin=*]
\item
Consider the lens spaces $L(7, 1)$ and $L(7, 2)$. As is explained in the proof of Theorem \ref{t:genus_1}, since $H^1(L(7,1),\BZ/2\BZ)=H^1(L(7,2),\BZ/2\BZ)=0$, the spin classes of all framings of $L(7,1)$ are equal, which means any two framings of $L(7,1)$ are different only by their Hopf degrees. The same is true for $L(7,2)$. In particular, for any finite-dimensional Hopf algebra $H$, the Kuperberg invariant for $L(7, 1)$ with any framing is equal to $K(L(7, 1), \frm_L, H)$ up to a root of unity, and the invariant for $L(7, 2)$ with any framing equals $K(L(7, 2), \frm_R, H)$ up to some root of unity. By Theorem \ref{t:KInd} and Proposition \ref{p:duality}, we have
\begin{align*}
K(L(7, 1), \frm_L, H)=&\lambda(\Lambda_{(7)}\Lambda_{(6)}\Lambda_{(5)}\Lambda_{4}\Lda{3}\Lda{2}\Lda{1})\,,\\
K(L(7, 2), \frm_R, H)=&\lambda S(\Lambda_{(5)}S^2(\Lda{3})\Lda{1}\Lambda_{(6)}S^2(\Lda{4})\Lda{2}\Lambda_{(7)})\,,
\end{align*}
where $\ld \in H^*$, $\Ld \in H$ is a pair of normalized integrals. With the help of the \texttt{GAP} algebra system, we obtain that $K(L(7, 1), \frm_L, T(\zeta_7))= -42\zeta_7-35\zeta_7^2-28\zeta_7^3-21\zeta_7^4-14\zeta_7^5-7\zeta_7^6$, while $K(L(7, 2), \frm_R, T(\zeta_7))=0$, where $\zeta_7$ is a primitive 7-th root of unity. Consequently, the Kuperberg invariants of $L(7, 1)$ and $L(7, 2)$ for any choices of framings cannot be equal to each other. Therefore, the Kuperberg invariant can distinguish $L(7, 1)$ and $L(7, 2)$ up to homeomorphism, although they are homotopic (see, for example, \cite{Rol76}). 
\item
Moreover, the Kuperberg invariant can also distinguish spin classes of framings of a manifold. For example, for any finite-dimensional Hopf algebra $H$, we have
\begin{align*}
&K(L(4, 1), \frmR, H)=\ld S(\Lda{3} S^2(\Lda{2}) \Lda{1}\Lda{4})\\
&K(L(4, 1), \frmL, H)=\ld (\Lda{4}\Lda{3}\Lda{2}\Lda{1})\,,
\end{align*}
where $\ld \in H^*$ and $\Ld \in H$ form a pair of normalized integrals. Let $H = T(i)$, where $i= \sqrt{-1}$. By direct computation, we have $K(L(4,1), \frmR, H)=0$ and $K(L(4,1), \frmL, H)=8(1-i)$. Consequently, $\frmR$ and $\frmL$ cannot be in the same spin class because otherwise, the corresponding Kuperberg invariant could only be different by a multiple of a root of unity. In particular, the discussion here is consistent with the proof of Theorem \ref{t:genus_1}, where we showed that the framings $\frmR$ and $\frmL$ of the lens space $L(n,k)$ have different spin classes for any positive even $n$.
\end{enumerate}
\end{exmp}

