\begin{lemma}\label{l:t3} 
Let $n > k >0$ be coprime integers such that $(n-k)$ is odd, and let $k_0 = \tfrac{n-k-1}{2}$. Let $Y' = \ls \circ m \circ \s_{(n,-k)}$, and $\{c_\ell\}$ the sequence defined in Definition \ref{d:cp}.  For $x, w_\ell\in H$ with $1\leq \ell \leq k_0$, we have 
\begin{equation*}
Y'\Biggl(\bigotimes_{\ell=1}^{k_0}S^{2c_\ell}(w_\ell x_{(\ell)}\Lda{\ell})\o \bigotimes_{\ell=k_0+1}^{n}S^{2c_\ell}(\Lda{\ell})\Biggl)
= Y' \Biggl(\bigotimes_{\ell=1}^{k_0}S^{2c_\ell}(S^2(x_{(\ell)})w_\ell\Lda{\ell}))\o \bigotimes_{\ell=k_0+1}^n S^{2c_\ell}(\Lda{\ell})\Biggl)\,.
\end{equation*}
\end{lemma}
\begin{proof}
Let $Z': H\sot{(n-2)} \to H$ be a $\kk$-linear map such that 
\[Y'(v) =\ld S\Biggl(v_i^{[n-k]} Z'\biggl(\bigotimes\limits_{\substack{\ell=1 \\ \ell \ne n-k}}^{n-1} v_i^{[\ell]}\biggl)v_i^{[n]}\Biggl) = \ld S\bigg(v_i^{[\ol{n-k}]}v_i^{[\ol{n-2k}]}\cdots v_i^{[\ol k]}v_i^{[\ol n]}\biggl)\] 
for all $v \in H\sot{n}$. Then, by Theorem \ref{t:t2} (iii), we have 
\begin{align*}
&Y'\Biggl(\bigotimes_{\ell=1}^{k_0}S^{2c_\ell}(w_\ell x_{(\ell)}\Lda{\ell})\o \bigotimes_{\ell=k_0+1}^{n}S^{2c_\ell}(\Lda{\ell})\Biggl)
\! =\! Y'\Biggl(\bigotimes_{\ell=1}^{k_0}S^{2c_\ell}(w_\ell\Lda{\ell})\o \!\bigotimes_{\ell=k_0+1}^{n}S^{2c_\ell}(S^{-1}(x)_{(\ell-k_0)}\Lda{\ell})\Biggl)\,.
\end{align*}
Since $c_n=c_{n-k}=0$, the right hand side of the preceding equation can be rewritten as follows:
\begin{align*}
&\ld S\Biggl(S^{-1}(x)_{(k_0+1)}\Lda{n-k}Z'\Biggl(\bigotimes_{\ell=1}^{k_0} S^{2 c_\ell}(w_\ell\Lda{\ell})\o\bigotimes_{\substack{\ell=k_0+1 \\ \ell\ne n-k}}^{n-1} S^{2 c_\ell}(S^{-1}(x)_{(\ell-k_0)}\Lda{\ell})\Biggl) S^{-1}(x)_{(n-k_0)}\Lda{n}\Biggl)\\
=&\ \ld S\Biggl(S^{-1}(x_{(k+1)})\Lda{n-k}Z'\Biggl(\bigotimes_{\ell=1}^{k_0} S^{2 c_\ell}(w_\ell\Lda{\ell})\o\bigotimes_{\substack{\ell=k_0+1 \\ \ell\ne n-k}}^{n-1} S^{2 c_\ell}(S^{-1}(x_{(n+1-\ell)})\Lda{\ell})\Biggl) S^{-1}(x_{(1)})\Lda{n}\Biggl)\\
=&\ \ld S  \Biggl(\Lda{n-k} (x_{(k+1)})_{(n-k)} Z'\Biggl(\bigotimes_{\ell=1}^{k_0} S^{2 c_\ell} (w_\ell\Lda{\ell}(x_{(k+1)})_{(\ell)})\o \\
&\qquad\qquad  \bigotimes_{\substack{\ell=k_0+1 \\ \ell\ne n-k}}^{n-1} S^{2 c_\ell}(S^{-1}(x_{(n+1-\ell)})\Lda{\ell} (x_{(k+1)})_{(\ell)})\Biggl)\cdot S^{-1}(x_{(1)})\Lda{n} \Biggl) \quad \text{by Theorem \ref{t:t2} (vi)}\\
% =&\ \ld S  \Biggl(\Lda{n-k} x_{(n)} Z'\Biggl(\bigotimes_{\ell=1}^{k_0} S^{2 c_\ell} (w_\ell\Lda{\ell}x_{(k+\ell)})\o  \bigotimes_{\substack{\ell=k_0+1 \\ \ell\ne n-k}}^{n-1} S^{2 c_\ell}(S^{-1}(x_{(n+1-\ell)})\Lda{\ell} x_{(k+\ell)}\Biggl)\cdot S^{-1}(x_{(1)})\Lda{n} \Biggl)\\
% =&\ Y'\Biggl( \bigotimes_{\ell=1}^{k_0} S^{2 c_\ell} (w_\ell\Lda{\ell}x_{(k+\ell)})\o  \Lda{n-k} x_{(n)}\o  \bigotimes_{\substack{\ell=k_0+1 \\ \ell\ne n-k}}^{n-1} S^{2 c_\ell}(S^{-1}(x_{(n+1-\ell)})\Lda{\ell} x_{(k+\ell)}\Biggl\o S^{-1}(x_{(1)})\Lda{n} \Biggl)\\
=&\ Y' \Biggl(\bigotimes_{\ell=1}^{k_0} S^{2 c_{\ol{\ell+k}}}((x_{(k+1)})_{(\ol{\ell+k})}) S^{2 c_\ell}(w_\ell\Lda{\ell})\o\! \bigotimes_{\ell=k_0+1}^{2k_0} S^{2 c_{\ol{\ell+k}}}((x_{(k+1)})_{(\ol{\ell+k})})S^{2c_\ell}(S^{-1}(x_{(n+1-\ell)})\Lda{\ell} )\\
&\ \o \Lda{n-k} \o \bigotimes_{\ell=2k_0+2}^{n} S^{2c_{\ol{\ell+k}}}((x_{(k+1)})_{(\ol{\ell+k})})S^{2c_{\ell}}(S^{-1}(x_{(n+1-\ell)})\Lda{\ell})  \Biggl)\\
=&\ Y' \Biggl(\bigotimes_{\ell=1}^{k_0} S^{2 c_\ell}\Big(S^{2}((x_{(k+1)})_{(\ol{\ell+k})})w_\ell\Lda{\ell}\Big)\o\! \bigotimes_{\ell=k_0+1}^{2k_0} S^{2c_\ell}\Big(S^{-2}\big((x_{(k+1)})_{(\ol{\ell+k})} S(x_{(n+1-\ell)})\big)\Lda{\ell} \Big) \\
&\qquad \o  \Lda{n-k} \o\!\bigotimes_{\ell=2k_0+2}^{n} S^{2c_\ell}((x_{(k+1)})_{(\ol{\ell+k})}S^{-1}(x_{(n+1-\ell)})\Lda{\ell})  \Biggl)\,.
\end{align*}
To complete the proof, it suffices to show
\[\De^{k_0}(x)  \o 1\sot{(n-k_0-1)} = 
\bigotimes_{\ell=1}^{k_0} (x_{(k+1)})_{(\ol{\ell+k})}   \o \bigotimes_{\substack{\ell=k_0+1\\ \ell \ne n-k}}^n (x_{(k+1)})_{(\ol{\ell+k})}S^{\w(\ell)}
(x_{(n+1-\ell)})\]
where $\w(\ell)=1$ if $k_0+1\le \ell \le 2k_0$ and $\w(\ell)=-1$ if $2k_0+2\le \ell \le n$.  One can rewrite the right hand side as
    \begin{align*}
     & \  \bigotimes_{\ell=k+1}^{k+k_0} (x_{(k+1)})_{(\ell)}  \o \bigotimes_{\ell=k+k_0+1}^{n-1} (x_{(k+1)})_{(\ell)}S(x_{(n+1+k-\ell)}) \o \bigotimes_{\ell=1}^k (x_{(k+1)})_{(\ell)}S^{-1}(x_{(k+1-\ell)}) \\
     =& \  \bigotimes_{\ell=k+1}^{k+k_0} (x_{(2)})_{(\ell)}  \o \bigotimes_{\ell=k+k_0+1}^{n-1} (x_{(2)})_{(\ell)}S(x_{(n+2-\ell)}) \o \bigotimes_{\ell=1}^k (x_{(2)})_{(\ell)}S^{-1}(x_{(1)})_{(\ell)} \\
     =& \  \bigotimes_{\ell=1}^{k_0} (x_{(2)})_{(\ell)}  \o \bigotimes_{\ell=k_0+1}^{n-k-1} (x_{(2)})_{(\ell)}S(x_{(n-k+2-\ell)}) \o \e(x_{(1)})\De^k(1)  \quad\text{ by the antipode condition} \\
     =& \ \De^{k_0} (x_{(1)})  \o \De^{n-k-k_0-1} (x_{(2)}S(x_{(3)})) \o \De^k(1) = \De^{k_0}(x) \o 1^{\o(n-k_0-1)}. 
    \end{align*}
    Here, the second last equality follows from the counit condition and Sweedler's notation, and the last equality is a 
    consequence of the  antipode condition.
\end{proof}


\subsection{Lemmas on 2-cocycles}
We state and prove lemmas on 2-cocycles that are relevant in this paper. Let $F=\ff{i}{1} \o \ff{i}{2}\in H\o H$ be a 2-cocycle. Then, by definition, $F^{-1} = \dd{i}{1} \o \dd{i}{2}  \in H^{\op} \o H^{\op}$ is a 2-cocycle of $H^{\op}$. Recall that $u = \ff{i}{1}S(\ff{i}{2})$ an invertible element in $H$ with $u^{-1} = S(\dd{i}{1})\dd{i}{2}$. The antipode of $H^{\op}$ is $S^{-1}$. Let $\bullet$ denote the multiplication of $H^{\op}$. Then
\begin{equation}\label{eq:op_trick}
    \dd{i}{1} \bullet S^{-1}(\dd{i}{2}) = S^{-1} (\dd{i}{2}) \dd{i}{1} = S^{-1}(u^{-1})\,.
\end{equation}
For elaboration of the properties of these 2-cocycles, we  continue to use these notations and introduce the reverse tensor  and insertion operators $(-)\rev$ and $I_j(-, -)$ as follows. Let $m, n \ge 1$ be integers. For $v= v^{[1]}_i \ot \cdots \ot v^{[n]}_i \in V\sot{n}$, $v\rev : =v^{[n]}_i \ot \cdots \ot v^{[1]}_i$. For  $w \in V^{\ot m}$, we define the $j$-th insertion operator of $w$, $I_j(w, -): V^{\ot n} \to V^{\ot (n+m)}$, as 
 \begin{equation}\label{eq:def-insert}I_j(w,v) := v^{[1]}_i \ot \cdots \ot v^{[j-1]}_i \ot w \ot v^{[j]}_i \ot \cdots \ot v^{[n]}_i \text{ for all $v \in V^{\ot n}$}\,.
 \end{equation}
The cases when $j=1$ or $n+1$ are simply the juxtapositions: $I_1(w,v) = w \ot v$, $I_{n+1}(w,v) = v \ot w$ for any $v \in V^{\ot n}$.


The following lemma is essential to the proof of the gauge invariance of the Kuperberg invariants discussed in the previous section, and its Statement (i) is a generalization of Lemma \ref{lem:F-n-plus-1}, which was proved in \cite{KMN12}. Recall the Convention \ref{conv:k0} and our definition of $F_n$ in \eqref{eq:F-n-plus-1}: $F_1= 1$, $F_2=F$, $F_{n+1}=(1\o F_n)(\id\o \Delta^{n})(F)$ for $n\geq 2$. 
\begin{lemma}\label{lem:trick-3}
Suppose $F_n = f^{[1]}_i  \o \cdots \o f_i^{[n]}$, $F_n^{-1} =  d^{[1]}_i \o \cdots \o d_i^{[n]}$, $u= f^{[1]}_i S(f^{[2]}_i)$, and $Q = u S(u^{-1})$. 
\begin{enumerate}[label={\rm (\roman*)}]
\item 
For any integers $m$, $n \ge 1$, we have
\begin{equation}\label{eq:insert}
F_{m+n} =  I_{j}(F_m, 1^{\ot n}) \cdot (\id^{\o (j-1)} \o \Delta^{m} \o \id^{\o (n+1-j)})(F_{n+1}) \quad \text{for all }j \in \{1, \dots, n+1\}.
\end{equation} 
Equivalently, we have $F^{-1}_{m+n} = (\id^{\o (j-1)} \o \Delta^{m} \o \id^{\o (n+1-j)})(F^{-1}_{n+1}) \cdot I_{j}(F^{-1}_m, 1^{\ot n})$ for all $j \in \{1, \dots, n+1\}$.

\item 
For any $m$, $n \ge 0$, we have $F_{m+n} = (F_m \o F_n)\cdot (\D^{m} \o \D^{n})(F)$. 

\item 
For any $n \ge 2$, and $n-1 \ge m \ge 1$, we have 
\begin{eqnarray}
I_{m}(1, F_{n-2})&=&\left(\bigotimes_{s=1}^{m-1} \ff{i}{s} \right) \o S (\ff{i}{m}) u^{-1} \ff{i}{m+1} \o \left(\bigotimes_{s=m+2}^{n} \ff{i}{s}\right) \,,\label{eq:reduce_f}\\
I_m(1, F^{-1}_{n-2})&=&\left(\bigotimes_{s=1}^{m-1} \dd{i}{s} \right) \o \dd{i}{m} u S(\dd{i}{m+1}) \o \left(\bigotimes_{s=m+2}^{n} \dd{i}{s}\right)\,.\label{eq:reduce_d}
\end{eqnarray}


\item 
For any $n \ge 1$, we have
  \begin{equation}
      1 \o u\sot{n}\! =\! \ff{i}{1} \o \bigotimes_{\ell=2}^{n+1} \ff{i}{\ell}S(\ff{i}{2n+3-\ell}) 
    \ =\  F_{n+1} \cdot(\ff{j (1)}{1} \o \bigotimes_{\ell=2}^{n+1} \ff{j (\ell)}{1} S(\ff{j}{n+3-\ell}))\,, \label{eq:u-f-Sf-1}
    \end{equation}
     \begin{equation}
     1 \o (S^{-1}(u^{-1}))\sot{n} = \dd{i}{1} \o \bigotimes_{\ell=2}^{n+1}S^{-1}(\dd{i}{2n+3-\ell})  \dd{i}{\ell}
    \ =\  (\dd{j (1)}{1} \o \bigotimes_{\ell=2}^{n+1} S^{-1}(\dd{j}{n+3-\ell})\dd{j (\ell)}{1} )F_{n+1}^{-1}\,,\label{eq:u-f-Sf-2}
  \end{equation} 
\begin{equation}
    u\sot{n} =  \bigotimes_{\ell=1}^n \ff{i}{\ell}S(\ff{i}{2n+1-\ell}) = F_n \Big(\bigotimes_{\ell=1}^{n} \ff{j (\ell)}{1} S(\ff{j}{n+2-\ell})\Big)  =\Big(\bigotimes_{\ell=1}^{n} \ff{j}{n+1-\ell} S(\ff{j\,(\ell)}{n+1})\Big) S\sot{n}(F_n)
   \,, \label{eq:u-f-Sf-3} 
\end{equation}
\begin{equation}  \label{eq:u-f-Sf-4}
    (u^{-1})\sot{n} \!= \! \bigotimes_{\ell=1}^n S(\dd{i}{\ell}) \dd{i}{2n+1-\ell} =  S\sot{n}(F_n^{-1})\Big(\!\bigotimes_{\ell=1}^{n}  S(\dd{j (\ell)}{1})\dd{j}{n+2-\ell} \Big)\!=\!\Big(\!\bigotimes_{\ell=1}^{n} S(\dd{j}{n+1-\ell}) \dd{j\,(\ell)}{n+1}\Big)F_n^{-1}.
\end{equation}
\item  For any $n \ge 1$, 
\begin{equation}\label{eq:f-Du-u-Sd}
\D^n(u) = F_n^{-1} \cdot u\sot{n} \cdot (S\sot{n} (F_n^{-1}))\rev\,.
\end{equation}
Consequently, we have 
\begin{equation}\label{eq:Sdd-vd}
\bigotimes_{\ell=1}^{n}S(d^{[1]}_{j\,(n+1-\ell)})d^{[\ell+1]}_{j}
 =\bigotimes_{\ell=1}^{n}S(\ff{j}{n+1-\ell})u^{-1}    
 =
\bigotimes_{\ell=1}^{n} u^{-1}_{(\ell)}d^{[\ell]}_j,
\end{equation}
\begin{equation}\label{eq:fSf-dv}
\bigotimes_{\ell=1}^{n}\ff{j\,(\ell)}{1}S(\ff{j}{n+2-\ell}) = \bigotimes_{\ell=1}^{n} \dd{j}{\ell} u = \bigotimes_{\ell=1}^{n} u_{(\ell)} S(\ff{j}{n+1-\ell}),
\end{equation}
\begin{equation}\label{eq:fSf-vSd}
\bigotimes_{\ell=1}^{n}\ff{j}{n+1-\ell}S(\ff{j\,(\ell)}{n+1}) = \bigotimes_{\ell=1}^{n} uS(\dd{j}{\ell}) = \bigotimes_{\ell=1}^{n} \ff{j}{n+1-\ell} u_{(n+1-\ell)}\,.
\end{equation}

and
\begin{equation}\label{eq:f-DQ-Q-Sf}
F_n \D^{(n)}(Q) = Q\sot{n} \cdot (S^2)\sot{n} (F_n),
\end{equation}
\end{enumerate}
\end{lemma}
 \begin{proof}
 (i) Fix $m \ge 1$. We proceed to prove the \eqref{eq:insert} by induction on $n$. For $n = 1$, and $j=1$ or $2$. When $j = 1$, \eqref{eq:insert} follows from Lemma \ref{lem:F-n-plus-1}, and when $j = 2$, \eqref{eq:insert} follows from the definition of $F_{m+1}$.

Suppose \eqref{eq:insert} holds for all positive integers $k\le n$. For any positive integer $j\le n+1$,  by Lemma \ref{lem:F-n-plus-1}, coassociativity of $\De$ and the induction hypothesis, we have
\begin{align*}
& F_{m+n+1} = (F_{m+n} \o 1) \cdot (\D^{m+n} \o \id)(F) \\
=& \left[\left((1^{\o (j-1)} \o F_m \o 1^{\o (n+1-j)}) \cdot (\id^{\o (j-1)} \o \D^{m} \o \id^{\o (n+1-j)})(F_{n+1})\right) \o 1\right] \cdot (\D^{m+n} \ot \id)(F)\\
=& (1^{\o (j-1)} \o F_m \o 1^{\o (n+2-j)}) \cdot (\id^{\o (j-1)} \o \D^{m} \o \id^{\o (n+2-j)})(F_{n+1} \ot 1) \\
\qquad & \cdot (\id^{\o (j-1)} \o \D^{m} \o \id^{\o (n+2-j)})(\D^{n+1} \ot \id)(F)\\
=& (1^{\o (j-1)} \o F_m \o 1^{\o (n+2-j)}) \cdot (\id^{\o (j-1)} \o \D^{m} \o \id^{\o (n+2-j)})[(F_{n+1} \ot 1) \cdot (\D^{n+1} \ot \id)(F)]\\
=& (1^{\o (j-1)} \o F_m \o 1^{\o (n+2-j)}) \cdot (\id^{\o (j-1)} \o \D^{m} \o \id^{\o (n+2-j)})(F_{n+2})  \,.
\end{align*}
For $j = n+2$, by definition and induction hypothesis, we can perform similar calculation as above
\begin{align*}
F_{m+n+1} =&\ (1 \o F_{m+n}) \cdot (\id \ot \D^{m+n})(F)\\
=&\ (1^{\o (n+1)} \o F_m) \cdot (\id^{\o (n+1)} \o \D^{m})(1\o F_{n+1}) \cdot (\id \o \D^{m+n})(F)\\
=&\ (1^{\o (n+1)} \o F_m) \cdot (\id^{\o (n+1)} \o \D^{m}) (F_{n+2}) \quad\text{by the coassociativity.}
\end{align*}
Therefore, \eqref{eq:insert} holds for $n+1$. 

Statement (ii) follows immediately from (i).

(iii) When $n=2$, $m$ can only be 1, and the statement follows from 
\begin{align*}
S(f_i^{[1]}) u^{-1} f_i^{[2]} 
= 
S(f_i^{[1]}) S(d_j^{[1]}) d_j^{[2]}f_i^{[2]} = m\circ (S \ot \id)(F^{-1} \cdot F) = 1\,.
\end{align*}

For any $x \in H$,  the term $F_0\D^{0}(x)$, if it appears in the following deductions, is considered as an empty tensorand. Now let $n\geq 3$ and apply (ii) repeatedly. Then we have 
\begin{align*}
F_{n}=&\ \Bigl(F_{m-1} \o 1^{\o 2} \o F_{n-m-1}\Bigl)\cdot (\D^{m-1} \o \id^{\o 2} \o \D^{n-m-1})(F_4)\\
=&\ \Bigl(F_{m-1} \o 1^{\o 2} \o F_{n-m-1}\Bigl)\cdot \Bigl((\D^{m-1} \o \id^{\o 2} \o \D^{n-m-1})(\ff{i}{1} \o \ff{j}{1} \ff{i\,(1)}{2} \o \ff{j}{2} \ff{i\,(2)}{2} \o \ff{i}{3})\Bigl)\\
=&\ \Bigl(F_{m-1} \cdot \D^{m-1}(\ff{i}{1})\Bigl) \o \Bigl( \ff{j}{1} \ff{i\,(1)}{2} \o \ff{j}{2} \ff{i\,(2)}{2} \Bigl) \o \Bigl(F_{n-m-1}\cdot \D^{n-m-1}(\ff{i}{3})\Bigl)\,.
\end{align*}
Therefore, 
\begin{align*}
&f_i^{[1]} \o \cdots \o S(f_i^{[m]})u^{-1}f_i^{[m+1]} \o \cdots \o f_i^{[n]}\\
=&\ \Bigl(F_{m-1} \cdot \D^{m-1}(f^{[1]}_i)\Bigl) \o S(\ff{i\,(1)}{2})\ff{i\,(2)}{2} \o \Bigl(F_{n-m-1}\cdot \D^{n-m-1}(\ff{i}{3})\Bigl) \quad\text{by the case $n=2$}\\
=&\ (F_{m-1} \cdot \D^{m-1}(f^{[1]}_i)) \o 1 \o (F_{n-m-1} \cdot \D^{n-m-1}(f^{[2]}_{i})) = I_m(1, F_{n-2})\,.
\end{align*}
The second equality can be proved similarly or using $H^\op$ in the beginning remark and \eqref{eq:op_trick}. 

(iv) We prove the first equality of \eqref{eq:u-f-Sf-1} by induction on $n$. For $n = 1$, by definition and (i), we have 
\[\ff{i}{1} \ot \ff{i}{2}S(\ff{i}{3}) 
= \ff{i}{1} \ot \ff{j}{1}\ff{i(1)}{2}S(\ff{j}{2}\ff{i(2)}{2}) = \ff{i}{1}\e(\ff{i}{2}) \o \ff{j}{1}S(\ff{j}{2}) = 1 \ot u\,.\]
Now assume  first equality of \eqref{eq:u-f-Sf-1} holds for any positive integer $n$. By a similar calculation as above, we have
\begin{align*}
\ff{i}{1} \o \left(\bigotimes_{\ell=2}^{n+2} \ff{i}{\ell}S(\ff{i}{2n+5-\ell})\right) = &\  \ff{i}{1} \o \left(\bigotimes_{\ell=2}^{n+1} \ff{i}{\ell}S(\ff{i}{2n+5-\ell})\right) \o \ff{i}{n+2}S(\ff{i}{n+3})\\
=\ \ff{i}{1} \o \left(\bigotimes_{\ell=2}^{n+1} \ff{i}{\ell}S(\ff{i}{2n+4-\ell})\right) & \o \ff{j}{1} \ff{i(1)}{n+2} S(\ff{j}{2}\ff{i(2)}{n+2}) \quad \text{ by (i)} \\
=\ \ff{i}{1} \o \left(\bigotimes_{\ell=2}^{n+1} \ff{i}{\ell}S(\ff{i}{2n+3-\ell})\right)  &\o u = 1 \o u\sot{n} \o u = 1 \o u^{\o (n+1)}
\end{align*}
by the induction hypothesis. The second equality above is a consequence of  the fact that $F_{2n+1}=(\id^{\o (n+1)} \o \e \o \id\sot{n})(F_{2n+2}) $ by the definition of $F_{2n+1}$ and (i).  The second equality of \eqref{eq:u-f-Sf-1} follows immediately from (ii) that $F_{2n+1} = (F_{n+1} \o 1\sot{n})\cdot (\D^{n+1} \o \id \sot{n})(F_{n+1})$. The first and the second equalities of \eqref{eq:u-f-Sf-3} are obtained by applying $\e \o \id\sot{n}$ to  \eqref{eq:u-f-Sf-1}. The third equality of \eqref{eq:u-f-Sf-3} follows from $F_{2n} = (1\sot{n} \o F_n)(\id\sot{n} \o \Delta^{n})(F_{n+1})$ and the first equality by reversing the tensor.

By the beginning remark of this subsection and \eqref{eq:op_trick}, \eqref{eq:u-f-Sf-3} implies
\begin{align*}
    (S^{-1}(u^{-1}))\sot{n} &=\  \bigotimes_{\ell=1}^{n}S^{-1}(\dd{i}{2n+1-\ell})  \dd{i}{\ell}
    \ =\  \bigg(\bigotimes_{\ell=1}^{n} S^{-1}(\dd{j}{n+2-\ell})\dd{j (\ell)}{1}\bigg) \cdot F_{n}^{-1}\\
    =&\ (S^{-1})^{\o n}(F_n^{-1}) \bigg(\bigotimes_{\ell=1}^n S^{-1}(\dd{j (\ell)}{n+1}) \dd{j}{n+1-\ell}\bigg)\,.
\end{align*}
Equation \eqref{eq:u-f-Sf-4} follows from applying $S\sot{n}$ to these equations.

(v) Note that $\D^n(u) = \bigotimes_{\ell=1}^n \ff{j\,(\ell)}{1}S(\ff{j\, (n+1-\ell)}{2})$. Thus, we have
\begin{align*}
    \D^n(u) \cdot  (S\sot{n}(F_n))\rev \ = &\ 
    \bigotimes_{\ell=1}^n \ff{j\,(\ell)}{1}S\Bigl(\ff{j\, (n+1-\ell)}{2}\Bigl) S\Bigl(\ff{i}{n+1-\ell}\Bigl)\ = \
    \bigotimes_{\ell=1}^n \ff{j\,(\ell)}{1}S\Bigl(\ff{i}{n+1-\ell}\ff{j\, (n+1-\ell)}{2}\Bigl) \\
    = &\ \bigotimes_{\ell=1}^n \ff{j\,(\ell)}{1}S\Bigl(\ff{j}{n+2-\ell}\Bigl) \quad \text{ since } F_{n+1} = (1 \o F_n)\cdot (\id \o \D^n)(F) \text{ by(i)} \\
    = &\ F_n^{-1} u^n \quad \text{ by \eqref{eq:u-f-Sf-3}}\,. 
\end{align*}
This implies \eqref{eq:f-Du-u-Sd}. Now, we take inverse of both sides of Equation \eqref{eq:f-Du-u-Sd} to obtain
\[\D^n(u^{-1}) F_n^{-1} = (S\sot{n}(F_n))\rev \cdot (u^{-1})\sot{n}\,,\]
which is the second equality of \eqref{eq:Sdd-vd}. Apply the reverse tensor operator to \eqref{eq:u-f-Sf-4}, we find
\[(u^{-1})\sot{n} = (S\sot{n}(F_n^{-1}))\rev \cdot \Biggl(\bigotimes_{\ell=1}^n S(\dd{j\ (n+1-\ell)}{1})\dd{j}{\ell+1}\Biggl)\,,\]
and the first equality of \eqref{eq:Sdd-vd} follows. The equations \eqref{eq:fSf-dv} and \eqref{eq:fSf-vSd} are obtained similarly from \eqref{eq:f-Du-u-Sd} and \eqref{eq:u-f-Sf-3}.


Finally, we show how to derive \eqref{eq:f-DQ-Q-Sf} from \eqref{eq:f-Du-u-Sd}. Since $Q = uS(u^{-1})$, we have 
\[\begin{split}
& F_n\cdot \D^{n}(Q) = F_n \cdot\D^{n}(u) \cdot \D^{n}(S(u^{-1})) = u\sot{n} \cdot \bigotimes_{\ell=1}^{n} S(\dd{i}{n+1-\ell}) \cdot \D^{n}(S(u^{-1}))\\ 
=&\ u\sot{n} \cdot S\sot{n} \left(u^{-1}_{(n)}\dd{i}{n} \ot \cdots \ot u^{-1}_{(1)}\dd{i}{1} \right) = u\sot{n} \cdot S\sot{n} \left(S\sot{n}(F_n) \cdot (u^{-1})\sot{n}\right) \\
=&\ Q\sot{n} \cdot (S^2)\sot{n}(F_n)\,,
\end{split}\]
where the second last equality is obtained from applying the reverse tensor operator on both sides of \eqref{eq:f-Du-u-Sd}, and last equality follows from that $S$ is an antihomomorphism of algebras.
\end{proof}

\begin{remark}
When $n = 2$, Equation \eqref{eq:f-Du-u-Sd} of (v) is well-known. See, for example, \cite[(2.17)]{Maj95}, \cite[(5)]{AEGN02} or \cite[Lem.~5.1]{KC17}.
\end{remark}



\begin{lemma}\label{l:t1}
Let $F \in H\sot{2}$ be a 2-cocycle of $H$. For any integer $n>0$ and any $\kk$-linear map $Y: H\sot{(n-1)} \to H$, we have
\begin{align*}
     \ld\left(S(\Ld_{(2)}) S_F\circ Y\circ \De_F^{n-1}(\Ld_{(1)})\right) & = \ld  S\left(m\circ (\id\o Y \o \id)\left((1\o F_n)(1 \o \De^n(\Ld))(F_n^{-1} \o 1) \right)\right) \\
      & = \ld  S\left(\dd{i}{1} Y\left(\ff{j}{1} \Ld_{(1)}\dd{i}{2}  \o \cdots \o (\ff{j}{n-1} \Ld_{(n-1)}\dd{i}{n})\right) \ff{j}{n}\Ld_{(n)}\right) \,.
\end{align*}
\end{lemma}
\begin{proof} Recall that $S_F(h) = u S(h) u^{-1}$ with $u=\ff{j}{1}S(\ff{j}{2})$ and $u^{-1}=S(\dd{i}{1})\dd{i}{2}$. Thus, we have
 \begin{equation*}
\begin{split}
& \ld \left(S(\Ld_{(2)}) S_F(Y\circ\Delta_F^{n-1}(\Ld_{(1)}))\right) = \ld \left(S(\Ld_{(2)}) u \cdot S(Y\circ\Delta_F^n(\Ld_{(1)}))\cdot  u^{-1}\right)\\
= & \ld \left(S(\Ld_{(2)}) \ff{j}{1}S(\ff{j}{2}) \cdot S(Y\circ\Delta_F^{n-1}(\Ld_{(1)})) \cdot S(\dd{i}{1})\dd{i}{2} \right)\\
= & \ls S\left( S^{-1}(\dd{i}{2}) \dd{i}{1} \cdot Y(\Delta_F^{n-1}(\Ld_{(1)})) \ff{j}{2} S^{-1}(\ff{j}{1})\Ld_{(2)} \right)\\
  = & \ld S \left( \dd{i}{1} \cdot Y(\Delta_F^{n-1}(\ff{j}{1}\Ld_{(1)}\dd{i}{2}))\ff{j}{2}\Ld_{(2)} \right)  \text{ by Theorem \ref{t:t2} (iii) and (vi).}
\end{split}
\end{equation*}
 By \eqref{eq:D_F(h)} and Lemma \ref{lem:trick-3} (i), we have 
\begin{equation*}
  \begin{split}
&\ \dd{i}{1} \ot (\Delta_F^{n-1}(\ff{j}{1}\Ld_{(1)}\dd{i}{2})) \ot \ff{j}{2} \Ld_{(2)} =  \dd{i}{1} \ot \biggl(\bigotimes_{m=1}^{n-1}\ff{p}{m} \ff{j\, (m)}{1}\Ld_{(m)} \dd{i\,(m)}{2}\dd{q}{m} \biggl)\ot \ff{j}{2}\Ld_{(n)}\\
= &\ \dd{i}{1} \ot \biggl(\bigotimes_{m=1}^{n-1}\ff{j}{m} \Ld_{(m)} \dd{i}{m+1} \biggl)\ot \ff{j}{n}\Ld_{(n)} = (1 \ot F_n) \left( 1 \ot \Delta^n(\Ld) \right)  \cdot (F_{n}^{-1} \ot 1) 
  \end{split}
\end{equation*}
by Lemma \ref{lem:F-n-plus-1}. The statement follows by applying $\ls\circ m\circ (\id\o Y \o \id)$ to these expressions.
\end{proof}







\section{Gauge invariance of \texorpdfstring{$\tilde\nu_{n, k}(H)$}{}}
In this section, we introduce another gauge invariant $\tilde\nu_{n,k}(H)$ for finite-dimensional Hopf algebras $H$, which are similar to $K(L(n,k), \frm, H)$, but not directly obtained from the Kuperberg invariants of $3$-manifolds. It is unclear whether or how   $\tilde\nu_{n,k}(H)$ and $\nu_{n,k}(H)$ are related. 

\begin{definition}\label{d:shifted_sp} 
Let $H$ be a  finite-dimensional Hopf algebra $H$. For any a coprime integers $n, k$ with $n > 1$, we define the ``shuffled'' Sweedler power 
\[\tP^{(n,k)} = m \circ \s_{(n,k)} \circ \D^{n-1}\,,\] 
and
\[\tnu_{n,k}(H) := \Tr(S \circ \tP^{(n, k)})\,.\]
\end{definition}
Note that 
\begin{align*}
	\tP^{(n,k)}(x)= \sum\limits_{(x)} x_{(\ol{k})}x_{(\ol{2k})}\cdots x_{(\ol{(n-1)k})} \quad\text{ for }x \in H\,.
\end{align*}
In particular, $\tP^{(n,1)} = P^{(n,1)}$, and so $\tnu_{n,1}(H) = \nu_{n,1}(H)$.

It follows from Radford's trace formula (Theorem \ref{t:t2} (v)) that  
\[\tnu_{n, k}(H)
=\sum \ld ( S(\Ld_{(2)}) S(\tP^{(n,k)}(\Ld_{(1)}))) = \sum \ld S(\Ld_{(\ol{k})}\Ld_{(\ol{2k})}\cdots \Ld_{(\ol{(n-1) k})} \Ld_{(n)})\]
for any normalized integrals $\ld \in \int_{H^*}^r$ and $\Ld \in \int_{H}^l$ for $H$. Thus, $\nu_{n,1}(H)=\tnu_{n,1}(H) = \Tr(S \circ P^{(n)})$, which is equal to the higher indicators $\nu^{\rm KMN}_n(H)$ defined in \cite{KMN12}. Therefore, both $\nu_{n,k}(H)$ and $\tnu_{n,k}(H)$ are generalizations of $\nu^{\rm KMN}_n(H)$. We will show that $\tnu_{n,k}(H)$ is also a gauge invariant of $H$  as follows.

\begin{thm}
Let $H$ be a finite-dimensional Hopf algebra over any field, and $F \in H \ot H$ a 2-cocycle of $H$. Then for any pair of coprime integers $n, k$ with $n>1$, we have
\[\tnu_{n,k}(H_F) = \tnu_{n,k}(H)\,.\]
\end{thm}
\begin{proof}
By definition, $\tnu_{n,k}(H) = \tnu_{n, \ol{k}}(H)$ for all $k$ coprime to $n$, and the gauge invariance of $\tnu_{n,1}$ is proved in \cite{KMN12}. Therefore, we assume without loss of generality that $2 \le k <n$.
It follows from Radford's trace formula (Theorem \ref{t:t2} (v)) that
\[\tnu_{n,k}(H_F) = \Tr(S_F \circ \tP^{(n,k)}_F) = \ld(S(\Ld_{(2)})(S_F\circ \tP^{(n,k)}_F(\Ld_{(1)}))) = \ld(S(\Ld_{(2)})(S_F\circ Y(\Delta_F^{n-1}\Ld_{(1)})))\]
for any normalized integrals $\ld \in \int^r_{H^*}$ and $\Ld \in \int^l_H$ for $H$, where $Y = m \circ \s_{(n,k)}$. Let  $F_n= f^{[1]}_j \ot \cdots \ot f^{[n]}_j$ and  $F_n^{-1}= d_i^{[1]} \o \cdots\o d^{[n]}_i$. By Lemma \ref{l:t1}, 
\begin{align*}
&\ \tnu_{n,k}(H_F) \ =\  \ls\Bigl(\dd{i}{1} Y\left(\ff{j}{1} \Ld_{(1)}\dd{i}{2}  \o \cdots \o \ff{j}{n-1} \Ld_{(n-1)}\dd{i}{n}\right) \ff{j}{n}\Ld_{(n)}\Bigl) \\
=&\ \ls  \biggl(\dd{i}{1}\ff{j}{k} \Lda{k} \prod_{p=2}^{n} d^{[\ol{1+(p-1)k}]}_i f^{[\ol{pk}]}_j \Ld_{\left(\ol{pk}\right)}\biggl)\stackrel{(\dagger)}{=}\  \ls \biggl( \Ld_{(k)} \, \prod_{p=2}^{n} S(d^{[1]}_i f^{[k]}_j)_{(\ol{(p-1)k})} d^{[\ol{1+(p-1)k}]}_i f^{[\ol{pk}]}_j \Ld_{(\ol{pk})} \biggl) \\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
=&\  \ls \circ Y\biggl(  \bigg(\bigotimes_{p=1}^{k-1} S(d^{[1]}_i f^{[k]}_j)_{(\ol{p-k})} \dd{i}{\ol{p-k}+1} \ff{j}{p} \Lda{p} \bigg)\o \Lda{k}\o \bigotimes_{p=k+1}^{n} S(d^{[1]}_i f^{[k]}_j)_{(p-k)} \dd{i}{p-k+1} \ff{j}{p} \Lda{p} \biggl)\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
=&\  \ls \circ  Y\biggl(\bigl(\bigotimes_{p=1}^{k-1} S(\ff{j\ (k-p)}{k}) S(\ff{i}{k-p})u^{-1} \ff{j}{p} \Lda{p} \bigl)\o \Lda{k}\o \bigotimes_{p=k+1}^{n} S(\ff{j\ (\ol{k-p})}{k}) S(\ff{i}{\ol{k-p}}) u^{-1} \ff{j}{p} \Lda{p}\biggl)
\end{align*}
where the third equality ($\dagger$) follows from Theorem \ref{t:t2} (vi), and the last equality is a consequence of \eqref{eq:Sdd-vd} of Lemma \ref{lem:trick-3} (v). Therefore, we have $\tnu_{n,k}(H_F)$ is equal to
\begin{align*}
&\  \ls \circ  Y\biggl(\bigl(\bigotimes_{p=1}^{k-1}  S(\ff{i}{k-p}\ff{j\ (k-p)}{k})u^{-1} \ff{j}{p} \Lda{p} \bigl)\o \Lda{k}\o \bigotimes_{p=k+1}^{n}  S(\ff{i}{\ol{k-p}}\ff{j\ (\ol{k-p})}{k}) u^{-1} \ff{j}{p} \Lda{p}\biggl) \\
=&\  \ls \circ  Y\biggl(\bigl(\bigotimes_{p=1}^{k-1}  S(\ff{j}{2k-p-1})u^{-1} \ff{j}{p} \Lda{p} \bigl)\o \Lda{k}\o \bigotimes_{p=k+1}^{n}  S(\ff{j}{n+2k-p-1}) u^{-1} \ff{j}{p+n-2} \Lda{p}\biggl)\,.
\end{align*}

Now, we apply \eqref{eq:reduce_f} of Lemma \ref{lem:trick-3} (iii) to the last expression repeatedly starting from $p=k+1$, and  obtain 
\begin{align*}
&\ \tnu_{n,k}(H_F)\  = \ \ls \circ  Y\biggl(\bigotimes_{p=1}^{k-1}  S(\ff{j}{2k-p-1})u^{-1} \ff{j}{p} \Lda{p}  \o \bigotimes_{p=k}^{n}  \Lda{p}\biggl) \\
=& \ \ls \circ  Y\biggl(\bigotimes_{p=1}^{k-1}  S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\ff{j\, (p)}{1} \Lda{p}  \o \bigotimes_{p=k}^{n}  \Lda{p}\biggl) \text{ by Lemma \ref{lem:trick-3} (i)} \\
=& \ \ls \circ  Y\biggl(\bigotimes_{p=1}^{k-1}  S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\Lda{p}  \o \bigotimes_{p=k}^{n}  S^{-1}(\ff{j\, (n+1-p)}{1})\Lda{p}\biggl)  \text{ by Theorem \ref{t:t2} (iii).}
\end{align*}
Let $Y': H^{\o (n-2)} \to H$ be the linear map $Y'(w) = Y(I_k(1,w) \o 1)$ for $w \in H\sot{n-2}$, then
\[Y\bigg(\bigotimes_{p=1}^{n} v^{[p]}\bigg) = v_i^{[k]}Y'\bigg(\bigotimes_{p=1}^{k-1} v_i^{[p]} \o \bigotimes_{p=k+1}^{n-1} v_i^{[p]}\bigg) v_i^{[n]}\] 
for all $v\in H\sot{n}$. Then  $\tnu_{n,k}(H_F)$ is equal to
\begin{align*}
&\ \ls \biggl(S^{-1}(\ff{j\,(\ol{1-k})}{1})\Lda{k}Y'\Bigl(\bigotimes_{p=1}^{k-1}  S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\Lda{p}  \o \bigotimes_{p=k+1}^{n-1}  S^{-1}(\ff{j\, (\ol{1-p})}{1})\Lda{p}\Bigl)S^{-1}(\ff{j\, (1)}{1})\Lda{n}\biggl) \\ 
=& \ \ls \biggl(\Lda{k} \ff{j\, (n)}{1}Y'\Bigl(\bigotimes_{p=1}^{k-1}  S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\Lda{p} \ff{j\, (n-k+p)}{1} \o \bigotimes_{p=k+1}^{n-1}  S^{-1}(\ff{j\, (\ol{1-p})}{1})\Lda{p}\ff{j\, (n-k+p)}{1}\Bigl)\\
& \qquad\qquad \cdot S^{-1}(\ff{j\, (1)}{1})\Lda{n}\biggl) \text{ by Theorem \ref{t:t2} (vi)}\\
=& \ {\ls\circ Y\biggl(\bigotimes_{p=1}^{k-1}  \ff{j\, (n-k+\ol{p-k})}{1}S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\Lda{p}  \o \Lda{k}\o \bigotimes_{p=k+1}^{n} \ff{j\,(n-k+\ol{p-k})}{1} S^{-1}(\ff{j\, (n+1-p)}{1})\Lda{p}\biggl)}\\
=& \ \ls\circ Y\biggl(\bigotimes_{p=1}^{k-1}  \ff{j\, (2n-2k+p)}{1}S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\Lda{p}  \o \Lda{k}\o \bigotimes_{p=k+1}^{n} \ff{j\,(n-2k+p)}{1} S^{-1}(\ff{j\, (n+1-p)}{1})\Lda{p}\biggl)\,.
\end{align*}
By repeatedly applying the antipode condition starting at $p=k+1$, we find
\begin{align*}
 \tnu_{n,k}(H_F) =& \ \ls\circ Y\biggl(\bigotimes_{p=1}^{k-1}  \ff{j\, (p)}{1}S(\ff{j}{k+1-p})u^{-1} \ff{i}{p}\Lda{p} \o \bigotimes_{p=k}^{n} \Lda{p}\biggl) \\
 =& \ \ls\circ Y\biggl(\bigotimes_{p=1}^{k-1}  \dd{j}{p} u u^{-1} \ff{i}{p}\Lda{p} \o \bigotimes_{p=k}^{n} \Lda{p}\biggl), \quad \text{ by \eqref{eq:u-f-Sf-3} of Lemma \ref{lem:trick-3} (iv),}\\
 =&\   \ \ls\circ Y\biggl(\bigotimes_{p=1}^{n}  \Lda{p} \biggl)\, = \,\tnu_{n,k}(H). \qedhere
\end{align*}
\end{proof}




\section{Kuperberg invariants of genus 2 framed 3-manifolds}\label{sec:Kmn}
So far we have been working with 3-manifolds of genus 1. It is then natural to ask whether there exist framed 3-manifolds of higher genera whose Kuperberg invariants are gauge invariant. In this section, we answer these questions by studying a family of 3-manifolds of genus 2, whose fundamental groups are certain central extensions of triangle groups studied by Milnor in his investigation of the Brieskorn manifolds \cite{Mil75}. 

We start with a brief review on the triangle groups. Let $p$, $q$, $r \ge 2$ be integers. The \emph{full (Schwarz) triangle group} $\Theta^{*}(p, q, r)$ admits the following presentation \cite[Thm.~2.2]{Mil75}
\[\Theta^{*}(p, q, r) \cong \langle a, b, c \mid a^{2} = b^{2} = c^{2} = (ab)^{p} = (bc)^{q} = (ca)^{r} = 1 \rangle\,.\]
Geometrically, $\Theta^{*}(p, q, r)$ is the group generated by reflections along the edges of the triangle with interior angles $\pi/p$, $\pi/q$ and $\pi/r$ in $\BP(p,q,r)$, the 2-dimensional simply-connected Riemannian manifold of constant Gauss curvature. Namely, 
\[\BP(p,q,r) = 
\begin{cases}
  \BS^{2} & \text{ if }\ p^{-1}+q^{-1}+r^{-1} > 1\,,\\
  \BH^{2} & \text{ if }\ p^{-1}+q^{-1}+r^{-1} < 1\,,\\
  \BR^{2} & \text{ if }\ p^{-1}+q^{-1}+r^{-1} = 1\,,
\end{cases}\]
where $\BS^{2}$, $\BH^{2}$ and $\BR^{2}$ stand for the unit sphere, the hyperbolic plane and the Euclidean plane respectively. For simplicity, we write $\BP$ for $\BP(p, q, r)$. By \cite[Cor.~2.5]{Mil75}, the index 2 subgroup $\Theta(p,q,r)$ of $\Theta^{*}(p,q,r)$ consisting of all orientation preserving elements of $\Theta^{*}(p,q,r)$ admits the following presentation  
\[\Theta(p, q,r) = \langle u, v, w \mid u^{p} = v^{q} = w^{r} = uvw = 1 \rangle\,. \]
Denote the connected Lie group of orientation preserving isometries of $\BP$ by $\Isom^{+}(\BP)$. Then we have
\[\Isom^{+}(\BP) = 
  \begin{cases}
    \SO(3) & \text{if }\ \BP = \BS^{2}\,,\\
    \PSL(2,\BR) & \text{if }\ \BP = \BH^{2}\,,\\
    \BR^{2} \rtimes \SO(2) & \text{if }\ \BP = \BR^{2}\,.
  \end{cases}
\]
As is listed in \cite[Tbl.~1]{RV81}, the quotient space $X(p,q,r): = \Theta(p,q,r)\backslash\Isom^{+}(\BP)$ is a compact 3-manifold whose fundamental group, called the \emph{centrally extended triangle group} in \cite{Mil75}, admits the following presentation \cite[Lem.~3.1]{Mil75}
\begin{equation}\label{eq:Gamma} 
\Gamma(p,q,r) := \pi_{1}(X(p,q,r)) \cong \langle x, y, z \mid x^{p} = y^{q} = z^{r} = xyz \rangle \,.
\end{equation}
If we denote the universal covering group of $\Isom^{+}(\BP)$ by $\widetilde{\Isom^{+}}(\BP)$, then we have  
\[X(p,q,r) = \Theta(p,q,r)\backslash \Isom^{+}(\BP) \cong \Gamma(p,q,r)\backslash\widetilde{\Isom^{+}}(\BP)\,,\]
and $\Gamma(p,q,r)$ is the inverse image of $\Theta(p,q,r)$ under the covering map $\widetilde{\Isom^{+}}(\BP) \to \Isom^{+}(\BP)$.

In this section, we study the Kuperberg invariant of 
\[\BM_{m,n} := X(2, m+1, n+1)\]
for any pairs of integers $m \ge 1$, $n \ge 1$. Such a manifold can be obtained by (Dehn) surgery on $\BS^3$ along framed links whose planar diagrams are depicted by either (a), (b), (c) or (d) in Figure \ref{fig:Mmn-link}, where the number near each strand represents the number of twists (or framing) on the corresponding strand. Note that since one can get the framed link diagram (b) by the Kirby (or the Fenn-Rourke) move \cite{Kir78, FR79} from (a), and similarly one can obtain (c) from (a) and (d) from (c), we indeed have framed link representations of the same manifold.
\begin{figure}
    \centering
    \includegraphics[width=0.9\linewidth]{eps/6-M-surgery.eps}
    \caption{Framed link presentations of $\BM_{m,n}$.}
    \label{fig:Mmn-link}
\end{figure}
\begin{remark}\label{rmk:Mmn}
For completeness, we provide the following remarks for the interested reader.
\begin{enumerate}[label=\rm (\roman{*}), itemsep=3pt, leftmargin=*]
\item 
For nonnegative integers $m$, $n$ such that $mn=0$, the framed link presentations in Figure \ref{fig:Mmn-link} are still valid, and the corresponding 3-manifold can be described as follows. Without loss of generality, assume $n=0$, then in Figure \ref{fig:Mmn-link}(a), the outer vertical $(n+1)$-framed unknot wraps around the 1-framed horizontal unknot, and the handle-slide move implies that we can delete the $(n+1)$-framed unknot and change the framing of the horizontal unknot to 0. Then the cutting property of the 0-framed unknot in Kirby calculus (see, for example, \cite{Kir78, MP94}) implies that we end up with a lens space $L(m+3,1)$. In fact, we can see that the group presentation in \eqref{eq:Gamma} can still be used in this case: Take $p = 2$, $q = m+1$ and $r = n+1 = 1$, then $z^r = xyz$ implies $xy = 1$, and $x^2 = y^{m+1}$ implies that 
\[\langle x, y, z \mid x^{p} = y^{q} = z^{r} = xyz \rangle \cong \langle y \mid y^{m+3} \rangle \cong \BZ/(m+3)\BZ \cong \pi_1(L(m+3,1))\,.\]

\item 
When $m = n = 1$, $\widetilde{\Isom^{+}}(\BP) \cong \SU(2)$, which is  simply the 3-sphere $\BS^3$ topologically. Using \eqref{eq:Gamma}, it is easy to see that $\BM_{1,1} \cong \BS^3/Q_8$, and Figure \ref{fig:Dn-local-3} indeed reduces to Figure \ref{fig:Q8}.

\item For any $m \ge 1$, $n \ge 1$, consider the framed link presentation of $\BM_{m,n}$ given by Figure \ref{fig:Mmn-link}(b). Since the Dehn surgery on $\BS^3$ along a 0-framed unknot results in $\BS^2\times \BS^1$ (see, for example, \cite{Rol76}), we can see that $\BM_{m,n}$ is a Seifert manifold over $\BS^2$ with $4$ singular fibers. Such a manifold is called a \emph{large Seifert manifold} \cite[Sec.~5.3]{Orl72}, and by Thm.~6 in loc.~cit., they are completely determined by their fundamental groups. 
\end{enumerate}    
\end{remark}

It is illustrated in \cite[Prop.\ 7]{Rol76} that one can convert a framed link diagram presentation of the Poincare homology sphere into a Heegaard diagram, and this can be generalized to arbitrary 3-manifolds. We  convert the link diagram Figure \ref{fig:Mmn-link}(d) into a Heegaard diagram of $\BM_{m,n}$, which is shown in Figure \ref{fig:Dn-local-3} (see also \cite{GH07}). 

As before, in Figure \ref{fig:Dn-local-3}, the four black circles are attaching circles indicating the positions of handles. The horizontal green and violet lines represent the lower curves, and the blue and red strands stand for the upper curves. For the discussions below, we also added combings and twist fronts on the Heegaard diagram, where the gray dashed arrows represent the combing $b_1$, and the four base points, colored in gray, are connected by the black twist fronts. This makes Figure \ref{fig:Dn-local-3} a 2-combed Heegaard diagram for $\BM_{m,n}$, denote by $D$.

By an abuse of notations, denote the fundamental group of the 3-manifold that $D$ represents be denoted by $\pi_1(D)$. We show that $\pi_1(D)$ is isomorphic to $\pi_1(\BM_{m,n}) \cong \Gamma(2, m+1, n+1)$, which, by the discussions above, provides an alternative argument that $D$ is indeed a Heegaard diagram of $\BM_{m,n}$. Start by choosing a base point, say, a point slightly below $p_1$ in Figure \ref{fig:Dn-local-3}. Then we choose two generators of $\pi_1(D)$ to be the loops at the base point that winds once around the upper right handle clockwise (denoted by $a$) and the lower right handle anticlockwise (denoted by $b$) respectively. By reading the homotopy class of the two upper curves in terms of these chosen generators,  we can write down the presentation of $\pi_1(D)$ as
\[\pi_1(D) = \langle a, b\mid aba^{-m}b=ab^{-n}ab=1 \rangle \cong \langle a, b\mid a^m = bab, b^n = aba \rangle\,.\]

Now we can compare the above presentation with the presentation in \eqref{eq:Gamma} when $p = 2$, $q = m+1$, and $r = n+1$. More precisely, in this case, we have 
\[\Gamma(2, m+1, n+1) = \langle x, y, z \mid x^2 = y^{m+1} = z^{n+1} = xyz \rangle\,. \]
Therefore, we have $x = yz$, which implies that $y^{m+1} = yzyz$, so $y^m=zyz$. Similarly, $z^{n+1} = yzyz$ implies $z^{n} = yzy$. Therefore, by assigning $y \mapsto a$ and $z \mapsto b$, we can establish an isomorphism of fundamental groups $\pi_1(D) \cong \Gamma(2, m+1, n+1) \cong \pi_1(\BM_{m,n})$ as desired.


