We can now state the main theorem of this section. Recall the Sweedler power $P^{(n)}$ of a Hopf algebra $H$ is $P^{(n, 1)}: H \to H$, $x \mapsto m\Delta^n(x)$.

\begin{thm}\label{t:genus_2}
Let $H$ be a finite-dimensional Hopf algebra over a field $\kk$. For any positive integers $m, n$, denote the diagram framing of $\BM_{m,n}$ associated to the framed Heegaard diagram in Figure \ref{fig:Dn-local-3} by $\frm_{m,n}$, then we have
\begin{equation}
\begin{split}
\label{eq:Kmn}
&K(\BM_{m,n}, \frm_{m,n}, H) =  \Tr\left((S \o S)\circ \Psi^{m,n}\right) \\
= &\lambda S\left(S^{-2}(\Lambda^2_{(4)})S^{-1}(\Lambda^1_{(2)})\Lambda^2_{(2)}P^{(m)}(\Lambda^1_{(4)})\right)\cdot 
\lambda S\left(P^{(n-1)}(\Lambda^2_{(1)})\Lambda^1_{(3)}S^{-1}(\Lambda^2_{(3)})S^{-2}(\Lambda^1_{(1)})\Lambda^2_{(5)}\right)
\end{split}
\end{equation}
where $\Psi^{m,n}: H^{\otimes 2} \to  H^{\otimes 2}$ is the $\kk$-linear operator defined by
\begin{equation} \label{eq:Psi}
    \Psi^{m, n}(x\otimes y)=S^{-2}(y_{(4)})S^{-1}(x_{(2)})y_{(2)}P^{(m-1)}(x_{(4)})\otimes P^{(n-1)}(y_{(1)})x_{(3)}S^{-1}(y_{(3)})S^{-2}(x_{(1)})
\end{equation}
for all $x$, $y \in H$.
Moreover, $K(\BM_{m,n}, \frm, H)$ above is a gauge invariant of $H$. 
\end{thm}
\begin{proof}
By Tables \ref{tbl:Mmn-1}, \ref{tbl:Mmn-2} and \ref{tbl:Mmn-3}, we can write down the formula for $K(\BM_{m,n}, \frm_{m,n}, H)$ as follows. As is indicated in the tables, by our choice of orientation, starting from their base points, $\mu_1$ passes $p_1$, $p_{m+3}$, ..., $p_5$, $q_{n+1}$, $p_3$, $q_{n+3}$ and $\mu_2$ passes $q_1$, $p_2$, $q_{n+2}$, $p_4$, $q_n$, ..., $q_2$ sequentially. Moreover, recall that in \eqref{eq:twisted-ld}, we have $\ld_{-\theta(\mu_1)}=\ld_{-\theta(\mu_2)}=\ld_{\tfrac{1}{2}}=\ld\circ S^{-1}$ {and $\Ld_{\frac{1}{2}} = \Ld$.} So 
\[
\begin{split}
&\, K(\BM_{m,n}, \frm_{m,n}, H) \\
=&\, \ld S^{-1}\left(S(\Lda{1}^{1}) S^3(\Lda{m+3}^{1}) \cdots S^3(\Lda{5}^{1}) S^3(\Lda{n+1}^{2}) S^2(\Lda{3}^{1}) S(\Lda{n+3}^{2})\right)\\
&\quad \cdot \ld S^{-1}\left(S(\Lda{1}^2) S(\Lda{2}^{1}) S^2(\Lda{n+2}^{2}) S^3(\Lda{4}^{1}) S^3(\Lda{n}^{2}) \cdots S^3(\Lda{2}^{2}) \right)\\
=&\, \ld \left(\Ld^{2}_{(5)} S(\Ld^{1}_{(3)}) S^{2}(\Ld^{2}_{(3)}) S^{2}(P^{m-1}(\Ld^{1}_{(5)})) \Ld^{1}_{(1)}\right)\cdot 
\ld \left(S^{2}(P^{n-1}(\Ld^{2}_{(2)})) S^{2}(\Ld^{1}_{(4)}) S(\Ld^{2}_{(4)}) \Ld^{1}_{(2)} \Ld^{2}_{(1)}  \right)\\
