\subsection{Analysis of the FPRAS}
We now conduct the analysis of {\approxMCNFA}. The hardest part to analyze is the core algorithm {\approxMCNFAcore} and to this we will first focus on the analysis of  $\approxMCNFAcore^*$, which, as discussed above, is $\approxMCNFAcore$ without the terminating condition of Line~c\ref{line:interrupt}, so the same algorithm but where $\sum_{r,q} |S^r(q)|$ can grow big. 

%

Recall that $\calA^\mathsf{u} = (\calQ^\mathsf{u},q_I,q_F,\calT^\mathsf{u})$ is an unrolled NFA for words in $\{0,1\}^n$, $\varepsilon > 0$ and $\kappa$, $n_s$, $n_t$ and $\theta$ are defined as in $\approxMCNFA$. The following lemmas provide bound on the correctness of $p(q)$ as well as the size of $S^r(q)$ for $\approxMCNFAcore^*$.  We defer their proofs to later subsections. 

\begin{lemma}\label{lemma:proba_p(q)}
	The probability that $\approxMCNFAcore^*(\calA^\mathsf{u},n,n_s,n_t,\theta)$ computes $p(q) \not\in (1 \pm \kappa)|\calL(q)|^{-1}$ for some $q \in \calQ^\mathsf{u}$ is at most $1/16$.
\end{lemma}

\begin{restatable}{lemma}{probaSq}\label{lemma:proba_S(q)}
	The probability that $\approxMCNFAcore^*(\calA^\mathsf{u},n,n_s,n_t,\theta)$ constructs sets $S^r(q)$ such that $\sum_{r \in [n_sn_t],q \in \calQ^\mathsf{u}} |S^r(q)| \geq \theta$ is at most $1/8$.
\end{restatable}

Combining the above lemmas, we can now state the correctness and runtime of {\approxMCNFA}.

\begin{restatable}{lemma}{mainResultCore}\label{lemma:main_result_core}
	Let $\calA^\mathsf{u} = (\calQ^\mathsf{u},q_I,q_F,\calT^\mathsf{u})$ be an unrolled NFA recognizing words in $\{0,1\}^n$. Let $m = \max_i |\calQ^i|$, $\varepsilon > 0$, and $\kappa$, $n_s$, $n_t$ and $\theta$ be defined as in $\approxMCNFA$, then $\approxMCNFAcore(\calA^\mathsf{u},n,n_s,n_t,\theta)$ runs in time $O(n^2m^3\log(nm)\varepsilon^{-2})$ and returns $\mathsf{est}$ with the guarantee
$
		\Pr\left[\mathsf{est}  \notin (1 \pm \varepsilon) |\calL(\calA^\mathsf{u})| \right] \leq \frac{1}{4}.
$
\end{restatable}
\begin{proof}
	\textcolor{black}{Let $\texttt{A}^{(\ast)} = \approxMCNFAcore^{(\ast)}(\calA^\mathsf{u},n,n_s,n_t,\theta)$.
		\[
		\begin{aligned}
			\Pr_{\texttt{A}}\left[\mathsf{est} \not\in (1 \pm \varepsilon)|\calL_n(\calA)|\right] 
			= \Pr_{\texttt{A}^*}\left[
			\sum_{r,q} |S^r(q)| \geq \theta
			\right] + \Pr_{\texttt{A}^*}\left[
			\sum_{r,q} |S^r(q)| < \theta \text{ and } \mathsf{est} \not\in (1 \pm \varepsilon)|\calL_n(\calA)|
			\right] 
			\\
			\leq \Pr_{\texttt{A}^*}\left[
			\sum_{r,q} |S^r(q)| \geq \theta
			\right] + \Pr_{\texttt{A}^*}\left[
			\mathsf{est} \not\in (1 \pm \varepsilon)|\calL_n(\calA)|
			\right]  
			\leq \Pr_{\texttt{A}^*}\left[
			\sum_{r,q} |S^r(q)| \geq \theta
			\right] + \Pr_{\texttt{A}^*}\left[
			\bigcup_{q}
			p(q) \not\in \frac{(1 \pm \varepsilon)^{-1}}{|\calL(q)|} 
			\right]
		\end{aligned}
		\]
		where $q$ ranges over $\calQ^\mathsf{u}$ and $r$ ranges over $[n_sn_t]$. The number $\kappa$ has been set so that $p(q) \not\in \frac{1 \pm \kappa}{|\calL(q)|}$ implies $p(q) \not\in \frac{(1 \pm \varepsilon)^{-1}}{|\calL(q)|}$ so, using Lemmas~\ref{lemma:proba_p(q)} and~\ref{lemma:proba_S(q)}: 
		\[
		\Pr_{\texttt{A}}\left[\mathsf{est} \not\in (1 \pm \varepsilon)|\calL_n(\calA)|\right] 
		\leq \Pr_{\texttt{A}^*}\left[
		\sum_{r,q} |S^r(q)| \geq \theta
		\right] + \Pr_{\texttt{A}^*}\left[
		\bigcup_{q}
		p(q) \not\in \frac{1 \pm \kappa}{|\calL(q)|} 
		\right] \leq \frac{1}{4} 
		\]
		To analyse the running time, we assume one of the caching strategy is used.} 
	\begin{enumerate}[leftmargin=*]
		\item[•] \textcolor{black}{The cost of $\computeCache{i}$ is twice the cost of multiplying a $|\calS^{i-1}| \times |\calQ^{i-1}|$ matrix with a $|\calQ^{i-1}|\times|\calQ^i|$ matrix, so it is in $O(\max(\frac{|\calS^{i-1}|}{m},1)\cdot m^\omega) = O(\max(|\calS^{i-1}|\cdot  m^{\omega-1}, m^{\omega}))$ where $m = \max_{i} |\calQ^i|$ and $\omega \leq 3$ is the matrix product constant over $\mathbb{N}$. The cost of $\updateCache{i}$ is $O(|\calS^i|\cdot |\calQ^i|)$. So the total cost for caching when the number of samples stays below $\theta$ is at most $O(n\cdot m^{\omega} + \theta\cdot  m^{\omega-1}) = O(\theta\cdot  m^{\omega-1})$ (because $\theta \geq n|\calQ| \geq nm$). We have that $\omega \leq 3$ and $\theta = O(n_sn_t|\calQ^\mathsf{u}|) = O(n_sn_tnm)$ so the cost is in $O(n_sn_tn m^3)$.}

		\item[•] \textcolor{black}{For the $\reduce$, each sample $w \in S^r(q)$ with $q \in \calQ^i$ is tested only in $\reduce$ operations triggered by $\estimateAndSample$ when called on states in $\calQ^{i+1}$. So each $w$ can be tested in at most $m$ $\reduce$ operations and therefore the cumulated cost of all $\reduce$ is in $O(\theta  m) = O(n_sn_tn m^2)$.}

		\item[•] \textcolor{black}{For the median of means, at most $|\calQ^\mathsf{u}| n_t$ means of $n_s$ integers are computed and at most $|\calQ^\mathsf{u}|$ medians of $n_t$ integers are computed so the cumulated cost of all median of means computations is $O((n_sn_t + n_t\log(n_t))|\calQ^\mathsf{u}|) \leq O(nm(n_sn_t + n_t\log(n_t)))$. $n_t$ is in $O(\log|\calQ^\mathsf{u}|) = O(\log(nm))$ so this sums up to a cost in $O(n_sn_tnm + n_tnm\log\log(nm))$}

		\item[•] \textcolor{black}{For the $\union$, with caching it takes $O(m)$-time to determine for $\pred(q) = (q_1,\dots,q_k)$ and $w \in \calL(q_\ell)$ whether $w \in  \calL(q_j)$ for any $j < \ell$. For every a single sample $w$, this query is done only for states $q$ belonging to a same layer $\calQ^i$. So, when the number of samples stays below $\theta$, at most $\theta\cdot m$ queries occur, resulting in a cost in $O(\theta  m^2) = O(n_sn_tn m^3)$.}
	\end{enumerate}
	\textcolor{black}{Thus the overall running time is in $O(n_sn_tnm^3) = O(n^2m^3\varepsilon^{-2}\log(nm))$.}
\end{proof}


\noindent The value $1/4$ is decreased down to any $\delta > 0$ with the median technique, hence our main result.

\mainResult*
\begin{proof}
\textcolor{black}{Let $\mathsf{est}_1,\dots,\mathsf{est}_m$ be the outputs of $n_u$ independent calls to $\approxMCNFAcore$. Let $X_i$ be the indicator variable that takes value $1$ if and only if $\mathsf{est}_i \not\in (1\pm \varepsilon)|\calL_n(\calA)|$, and define $\bar X = X_1 + \dots + X_{n_u}$. By Lemma~\ref{lemma:main_result_core}, $\Ex[\bar X] \leq n_u/4$. Hoeffding bound gives
\[
\Pr\Big[\median(X_1,\dots,X_{n_u}) \not\in (1 \pm \varepsilon)|\calL_n(\calA)|\Big] = \Pr\left[\bar X > \frac{n_u}{2}\right] \leq \Pr\left[\bar X - \Ex[\bar X] > \frac{n_u}{4}\right] \leq e^{-n_u/8} \leq \delta.
\]
The running time is $O(|\log(\frac{1}{\delta})|)$ times that of $\approxMCNFAcore$ (using $n_u \leq |\calQ|$). }
\end{proof}




\subsection{Proof of Lemma~\ref{lemma:proba_p(q)}}

Let $\Delta(q)$ be the interval $\frac{1 \pm \kappa}{|\calL(q)|}$ and $\nabla(q)$ be the interval $\frac{|\calL(q)|}{1 \pm \kappa}$. The probability to bound is  
$$
P_1 := \Pr\left[\bigcup_{q \in \calQ^\mathsf{u}}	p(q) \not\in \Delta(q)\right].
$$ 
The key component for proving Lemma~\ref{lemma:proba_p(q)}, is a variance upper bound on the size of the sample sets. Before that, some work on $P_1$ is needed. The first important idea is that we focus on the probability of the first occurence of $p(q) \not\in \Delta(q)$, that is, when $p(q') \in \Delta(q')$ holds for all ancestors of $q$.

%
%
%
%
%
%
\begin{claim}\label{claim:first_error}
\textcolor{black}{$
p(q) \not\in \Delta(q)
$
occurs for some $q \in \calQ^\mathsf{u}$ if and only if, for some $q' \in \calQ^{> 0}$ we have that 
$p(q') \not\in \Delta(q')$ and for all $q'' \in \ancestors(q')$ we have $p(q'') \in \Delta(q'')$.}
\end{claim}
\begin{proof}
\textcolor{black}{The ``if'' direction is trivial. For the other direction, suppose that $p(q) \not\in \Delta(q)$ holds for some $q$. Let $i$ be the smallest integer such that there is $q \in \calQ^i$ and $p(q) \not\in \Delta(q)$. $i$ cannot be $0$ because the only state in $\calQ^0$ is $q_I$ and $p(q_I) = 1 = |\calL(q_I)|^{-1} \in \Delta(q_I)$. So $q \in \calQ^{> 0}$ and, by minimality of $i$, we have that $p(q'') \in \Delta(q'')$ for all $q'' \in \ancestors(q)$.}
\end{proof}
\textcolor{black}{\begin{align*}
P_1 =
\Pr\left[
		\bigcup_{q \in \calQ^{> 0}}
			p(q) \not\in \Delta(q) 
			\text{ and } \forall q' \in
			 \ancestors(q),\, p(q') \in
			  \Delta(q') 
\right] \tag{Claim~\ref{claim:first_error}}
\\
\leq
\sum_{q \in \calQ^{> 0}}\underbrace{\Pr\left[
			p(q) \not\in \Delta(q) 
			\text{ and } \forall q' \in \ancestors(q),\, p(q') \in
			  \Delta(q')
\right]}_{P_1(q)}
\end{align*}
We introduce the history of $q$ in $P_1(q)$. Consider the set $\calH_q$ of realizable histories for $q$ and denote by $H(q) = h$ the event that the history $h$ occurs for $q$, that is, the event that the algorithm sets $p(q')$ to $h(q')$ for all $q' \in \ancestors(q)$.
\begin{align*}
P_1(q) &= \sum_{h \in \calH_q} \Pr\left[H(q)=h \text{ and }
				p(q) \not\in \Delta(q) 
				\text{ and for all } q' \in
				 \ancestors(q),\, p(q') \in
				  \Delta(q')
		\right].
\end{align*}
The summand probabilities are zero when $h(q')$ is not in $\Delta(q')$ for any ancestor of $q$. Let $\calH^*_q$ be the subset of $\calH_q$ where $h(q') \in \Delta(q')$ holds for every $q' \in \ancestors(q)$. Then
\begin{equation*}
\begin{aligned}
P_1(q) &= \sum_{h \in \calH^*_q} \Pr\left[H(q)=h \text{ and }
				p(q) \not\in \Delta(q) 
				\text{ and for all } q' \in
				 \ancestors(q),\, p(q') \in
				  \Delta(q')
		\right]
\\
	&= \sum_{h \in \calH^*_q} \Pr\left[H(q)=h \text{ and }
				p(q) \not\in \Delta(q)
		\right]
\end{aligned} 
\end{equation*}
Let $R_j$ be the interval $\{n_s(j-1) + 1,\dots,n_sj\}$. Recall that $\rho(q) = \min(p(q_1),\dots,p(q_k))$ and $M^j(q) = (n_s\rho(q))^{-1}\sum_{r \in R_j}|\hat{S}^{r}(q)|$. Let $\rho_h(q) = \min(h(q_1),\dots,h(q_k))$ and $M^j_h(q) = (n_s\rho_h(q))^{-1}\sum_{r \in R_j}|\hat{S}^{r}(q)|$. Note that $\rho_h(q)$ is a constant. Under the event $H(q) = h$, $\estimateAndSample(q)$ sets $p(q)$ to $\min(\rho_h(q),\hat \rho_h(q))$ where $\hat \rho_h(q) = \underset{0 \leq j < n_t}{\median}(M^j_h(q))^{-1}$. We show that it is enough to focus on $\hat \rho_h(q)$.}

\begin{claim}\label{claim:hat_rho}
\textcolor{black}{When $H(q) = h$ occurs, $\hat \rho_h(q) \in \Delta(q)$ implies that $p(q) \in \Delta(q)$.}
\end{claim}
\begin{proof}
\textcolor{black}{If $p(q) = \hat \rho_h(q)$ then, trivially, $\hat \rho_h(q) \in \Delta(q)$ implies $p(q) \in \Delta(q)$. Otherwise if $p(q) = \rho_h(q)$ then $\hat \rho_h(q) \in \Delta(q)$ implies that $p(q) \leq \hat \rho_h(q) \leq (1 + \kappa)/|\calL(q)|$ and, since $h \in \calH^*_q$ guarantees that $\rho_h(q) \geq (1-\kappa)/\max_{j \in [k]} |\calL(q_j)| \geq (1-\kappa)/|\calL(q)|$, we have that $p(q) \in \Delta(q)$.}
\end{proof}
\textcolor{black}{
\begin{align*}
\Pr\left[H(q)=h \text{ and }  p(q) \not\in \Delta(q) \right]
\leq
\Pr\left[H(q)=h \text{ and }  p(q) \not\in \Delta(q) \text{ and } \hat \rho_h(q \not\in \Delta(q) \right] \tag{Claim~\ref{claim:hat_rho}}
\\
=
\Pr\left[H(q)=h \text{ and }  p(q) \not\in \Delta(q) \text{ and } \underset{1 \leq j \leq n_t}{\median}(M^j_h(q)) \not\in \nabla(q) \right] 
\\
\leq 
\Pr\left[H(q)=h \text{ and } \underset{1 \leq j \leq n_t}{\median}(M^j_h(q)) \not\in \nabla(q) \right] 
\end{align*}}
%

Next, let $\mathfrak{M}^j_h(q) = (\rho_h(q)n_s)^{-1}\sum_{r \in R_j}|\vZ{r}{h}{q}|$ be the counterpart of $M^j_h(q)$ in the random process.  Because $M^j_h(q)$ and $\mathfrak{M}^j_h(q)$ are constructed analogously from $(\hat{S}^{r}(q))_r$ and $(\vZ{r}{h}{q}|)_r$, respectively, Lemma~\ref{lemma:not_so_black_magic} implies that $(H(q), \median_{j \in [n_t]}(M^j_{H(q)}(q)))$ and $(H(q), \median_{j \in [n_t]}(\mathfrak{M}^j_{H(q)}(q)))$ have equal distribution. So we replace $M^j_h(q)$ by $\mathfrak{M}^j_h(q)$ and use the independence of $\mathfrak{M}^j_h$ with $H(q)$ (Fact~\ref{fact:independence}).
\begin{align*}
\Pr\Big[H(q)=h \text{ and }  \underset{0 \leq j < n_t}{\median}(M^j_h(q)) \not\in \nabla(q) \Big]
\leq \Pr[H(q) = h] \Pr\Big[\underset{0 \leq j < n_t}{\median}(\mathfrak{M}^j_h(q)) \not\in \nabla(q)\Big]
\end{align*}
We bound $\Pr[\median_{j \in [n_t]}(\mathfrak{M}^j_h(q)) \not\in \nabla(q)]$
using Chebyshev's inequality followed by Hoeffding bound. For that, we need a bound on the variance of the variables $|\vZ{r}{h}{q}|$. By Lemma~\ref{lemma:proba_first_order}, the expected value of $|\vZ{r}{h}{q}|$ is $\mu := \rho_h(q)|\calL(q)|$. Now for the variance,
\begin{align*}
\Va\left[|\vZ{r}{h}{q}| \right] \leq \Ex\left[|\vZ{r}{h}{q}|^2 \right] = \mu + \sum_{w \in \calL(q)}\sum_{\substack{w' \in \calL(q) \\ w \neq w'}} \Pr\left[w \in \vZ{r}{h}{q} \text{ and } w' \in \vZ{r}{h}{q}\right]
\\
\leq \mu + \sum_{w \in \calL(q)}\sum_{\substack{w' \in \calL(q) \\ w \neq w'}} \frac{\rho_h(q)^2}{h(\lcpn(\paths(q,w),\paths(q,w'))} \tag{Lemma~\ref{lemma:proba_second_order}}
\end{align*}
Let $R = \paths(w,q) = (q^0_w,q^1_w,q^2_w,\dots,q^{i-1}_w,q)$, with $q^0_w = q_F$. Let $R' = \paths(w',q)$ for any $w' \in \calL(q)$ distinct from $w$. Then $\lcpn(R,R')$ is one of the $q^j_w$. Recall that $I(w,q,j)$ is the set of $w' \in \calL(q)$ such that $\lcpn(R,R') = q^j_w$.
\begin{align*}
\sum_{\substack{w' \in \calL(q) \\ w \neq w'}} &\frac{\rho_h^2}{h(\lcpn(\paths(q,w),\paths(q,w'))} = \sum_{j = 0}^{i-1} |I(w,q,j)|\frac{\rho_h(q)^2}{h(q^j_w)} 
\leq \sum_{j = 0}^{i-1} \frac{\rho_h(q)^2 |\calL(q)|}{h(q^j_w)|\calL(q^j_w)|}
\tag{Lemma~\ref{lemma:derivation_path}}
\end{align*}
Since $h \in \calH^*_q$, it holds that $h(q^j_w) \in \Delta(q^j_w)$. This implies $h(q^j_w) \geq (1 - \kappa)/|\calL(q^j_w)|$ and therefore 
$$
\Va\left[|\vZ{r}{h}{q}| \right] \leq
\mu + \sum_{w \in \calL(q)} \sum_{j = 0}^{i-1} |\calL(q)| \leq \mu + \frac{\rho_h(q)^2n}{1 - \kappa}\sum_{w \in \calL(q)} |\calL(q)| = \mu + \frac{\mu^2n}{1 - \kappa}
$$
Now, back to the median of means, we have that $\Ex[\mathfrak{M}^j_h] = \mu/\rho_h(q) = |\calL(q)|$ and, by independence of the variables $\{\vZ{r}{h}{q}\}_{r \in [n_sn_t]}$, the variance is 
\begin{align*}
\Va[\mathfrak{M}^j_h(q)] = \frac{1}{\rho_h(q)^2n_s^2}\sum_{r = j\cdot n_s+1}^{(j+1)n_s} \Va[|\vZ{r}{h}{q}|]\leq \frac{1}{\rho_h(q)^2n_s} \left( \mu + \frac{\mu^2n}{1 - \kappa}\right) =   \frac{1}{n_s}\left(\frac{|\calL(q)|}{\rho_h(q)} + \frac{n |\calL(q)|^2}{1-\kappa}\right).
\end{align*}
Next, $\mathfrak{M}^j_h(q) \in \nabla(q) = \frac{|\calL(q)|}{1 \pm \kappa}$ occurs if and only if $\frac{-\kappa|\calL(q)|}{1 + \kappa} \leq \mathfrak{M}^j_h(q) - |\calL(q)| \leq \frac{\kappa|\calL(q)|}{1 - \kappa}$, which is subsumed by $|\mathfrak{M}^j_h(q) - |\calL(q)|| \leq \frac{\kappa|\calL(q)|}{1+\kappa}$. So Chebyshev's inequality gives 
\begin{align*}
&\Pr\left[\mathfrak{M}^j_h(q) \notin \nabla(q)\right] \leq \Pr\left[\big|\mathfrak{M}^j_h(q) - |\calL(q)|\big| > \frac{\kappa|\calL(q)|}{1+\kappa}\right] \leq \frac{(1+\kappa)^2}{\kappa^2 |\calL(q)|^2} \Va\left[\mathfrak{M}^j_h(q)\right]
\\
&\leq \frac{(1+\kappa)^2}{\kappa^2n_s}\left(\frac{1}{\rho_h(q)|\calL(q)|} + \frac{n}{1-\kappa}\right)
\leq \frac{(1+\kappa)^2}{\kappa^2n_s}\left(\frac{1}{1 - \kappa} + \frac{n}{1-\kappa}\right) \tag{$\rho_h(q) \geq \frac{1- \kappa}{\max_{j}|\calL(q_j)|} \geq \frac{1- \kappa}{|\calL(q)|}$}
\\
&\leq \frac{1}{4} \tag{$n_s \geq \frac{4(n+1)(1+\kappa)^2}{\kappa^2(1-\kappa)}$}
\end{align*}
By taking the median of the $\mathfrak{M}^j_h(q)$'s, we decrease the $1/4$ upper bound. Let $E_j$ be the indicator variable taking value~$1$ if and only if $\mathfrak{M}^j_h(q) \not\in \nabla(q)$ and let $\bar E = \sum_{j = 0}^{n_t - 1} E_j$. We have $\Ex[\bar E] \leq n_t/4$ so Hoeffding bound gives
\begin{align*}
\Pr\left[ \underset{0 \leq j < n_t}{\median}(\mathfrak{M}^j_h(q)) \not\in \nabla(q) \right] 
= 
\Pr\left[ \bar E > \frac{n_t}{2}\right] 
\leq 
\Pr\left[ \bar E - \Ex(\bar E) \geq \frac{n_t}{4}\right] 
\leq e^{-n_t/8} \leq \frac{1}{16|\calQ^\mathsf{u}|}
\end{align*}
where the last inequality comes from $n_t \geq 8\ln(16|\calQ^\mathsf{u}|)$. Putting everything together, we have that 
$$
P_1 \leq \sum_{q \in \calQ^{> 0}}\sum_{h \in \calH^*_q} \frac{1}{16|\calQ^\mathsf{u}|}\Pr[H(q) = h] \leq  \frac{1}{16}.
$$

\subsection*{Proof of Lemma~\ref{lemma:proba_S(q)}}

\textcolor{black}{We reuse the $\Delta(q)$ notation from before.
\begin{align*}
\Pr\left[\sum_{r,q} |S^r(q)| \geq \theta\right] \leq \underbrace{\Pr\left[\sum_{r,q} |S^r(q)| \geq \theta \text{ and } \bigcap_{q' \in \calQ^\mathsf{u}} p(q') \in \Delta(q') \right]}_{P_2} + \underbrace{\Pr\left[\bigcup_{q \in \calQ^\mathsf{u}} p(q) \not\in \Delta(q) \right]}_{P_1}
\end{align*}
Lemma~\ref{lemma:proba_p(q)} gives a $1/16$ upper bound on $P_1$. We focus on $P_2$. We start with Markov's inequality.
\begin{align*}
P_2 &= 
\Pr\left[\sum_{r,q}\bigg(|S^r(q)| \prod_{q' \in \calQ^\mathsf{u}}\mathbbm{1}\left(p(q') \in \Delta(q')\right)\bigg) \geq \theta \right] 
\leq 
\frac{1}{\theta} \cdot \Ex\left[\sum_{r,q}\bigg(|S^r(q)|\prod_{q' \in \calQ^\mathsf{u}}\mathbbm{1}\left(p(q') \in \Delta(q')\right)\bigg)\right] 
\\
&=
\frac{1}{\theta}\cdot \sum_{r,q} \Ex\left[|S^r(q)|\cdot \prod_{q' \in \calQ^\mathsf{u}}\mathbbm{1}\left(p(q') \in \Delta(q')\right)\right] 
\leq
\frac{1}{\theta}\cdot \sum_{r,q} \underbrace{\Ex\left[|S^r(q)|\cdot \mathbbm{1}\left(p(q) \in \Delta(q)\right)\right]}_{E(r,q)}
\end{align*}
To bound $E(r,q)$ we introduce the history of $q$.
\begin{align*}
E(r,q) &= \sum_{t \in \Delta(q)} \Ex\left[|S^r(q)|\cdot \mathbbm{1}(p(q) = t)\right]
= \sum_{h \in \calH_q} \sum_{t \in \Delta(q)} \Ex\left[|S^r(q)|\cdot \mathbbm{1}(p(q) = t)\cdot \mathbbm{1}(H(q) = h)\right]
\\
&= \sum_{h \in \calH_q} \sum_{t \in \Delta(q)} \Ex\left[|\vY{r}{h}{t}{q}|\cdot \mathbbm{1}(p(q) = t)\cdot \mathbbm{1}(H(q) = h)\right] \tag{Lemma~\ref{lemma:not_so_black_magic}}
\\
&= \sum_{h \in \calH_q} \sum_{t \in \Delta(q)} \Ex\left[|\vY{r}{h}{t}{q}| \right]\cdot \Pr[p(q) = t \text{ and }H(q) = h] \tag{Fact~\ref{fact:independence}}
\\
&= \sum_{h \in \calH_q} \sum_{t \in \Delta(q)} t\cdot |\calL(q)|\cdot \Pr[p(q) = t \text{ and } H(q) = h] \tag{Lemma~\ref{lemma:proba_first_order}}
\\
&\leq \sum_{h \in \calH_q} \sum_{t \in \Delta(q)} (1+\kappa)\cdot \Pr[p(q) = t \text{ and } H(q) = h] \leq 1+\kappa \tag{$t \leq (1 + \kappa)/|\calL(q)|$}
\end{align*}
Since $\theta \geq 16(1+\kappa)n_sn_t|\calQ^\mathsf{u}|$, we have $
P_2 \leq (1+\kappa)n_sn_t|\calQ^\mathsf{u}|\theta^{-1} \leq 1/16$ and $\Pr\left[\sum_{r,q} |S^r(q)| \geq \theta\right] \leq P_1 + P_2 \leq 1/8$.}

