\section*{Appendix}



\subsection*{Proof of Lemmas~\ref{lemma:proba_first_order} and~\ref{lemma:proba_second_order}}

\probaFirstOrder*
\begin{proof}
Let $q \in \calQ^i$. We proceed by induction on $i$. The base case $i = 0$ is immediate since $\vY{r}{h_\emptyset}{1}{q_I} = \{\lambda\} = \calL(q_I)$ and these are the only variables for states in $\calQ^0$. Now let $i > 0$, $q \in \calQ^i$, $\pred(q) = (q_1,\dots,q_k)$ and suppose that $\Pr[w' \in \vY{r}{h'}{t'}{q'}] = t'$ holds for all $\vY{r}{h'}{t'}{q'}$ and $w' \in \calL(q')$ with $q' \in \calQ^{< i}$. Let $t_{\min} = \min(h(q_1),\dots,h(q_k))$ and $w = w' \cdot b$. We have  
\begin{align*}
\Pr\left[w \in \vY{r}{h}{t}{q}\right] 
= \Pr\left[w \in \reduce\left(\vZ{r}{h}{q}, \frac{t}{t_{\min}}\right) \mid w \in Z^r_{q,h}\right]\Pr\left[w \in \vZ{r}{h}{q}\right] 
\\
= \frac{t}{t_{\min}}\Pr\left[w \in \vZ{r}{h}{q}\right]
\end{align*}
Let $t_j = h(q_j)$ and let $h_j$ be the restriction of $h$ to $q_j$'s ancestors. The event $w \in \vZ{r}{h}{q}$ occurs if and only if $w' \in \vY{r}{h_j}{t_j}{q_j}$ for $q_j$ the first $b$-predecessor of $q$ (first with respect to $\prec$) such that $w \in \reduce(\vY{r}{h_j}{t_j}{q_j},\frac{t_{\min}}{t_j})$. So by induction
\begin{align*}
\Pr\left[w \in \vZ{r}{h}{q}\right] = \Pr\left[w \in \reduce\left(\vY{r}{h_j}{t_j}{q_j}, \frac{t_{\min}}{t_j}\right) \mid w' \in \vY{r}{h_j}{t_j}{q_j}\right]\Pr\left[w' \in \vY{r}{h_j}{t_j}{q_j}\right] 
\\
= \frac{t_{\min}}{t_j}\Pr\left[w' \in \vY{r}{h_j}{t_j}{q_j}\right] = t_{\min}
\end{align*}
It follows that $\Pr[w \in \vY{r}{h}{t}{q}] = t$.
\end{proof}

\probaSecondOrder*
\begin{proof}
We prove a stronger statement, namely, that for every $i$, for every $q$ and $q'$ two states (potentially $q = q'$) in $\calQ^i$ and every $t$ and $t'$ such that $t = t'$ when $q = q'$,  and every $w \in \calL(q)$ and $w' \in \calL(q')$, and $h$ and $h'$ two compatible histories for $q$ and $q'$, respectively, we have that 
\begin{equation}\label{equation:stronger_statement}
\Pr\left[w \in \vY{r}{h}{t}{q} \text{ and } w' \in \vY{r}{h'}{t'}{q'}\right] \leq \frac{tt'}{t^*}
\end{equation}
where $t^* = t$ if $q = q'$ and $w = w'$, and $t^* = h(\lcpn(\paths(w,q),\paths(w',q'))$ otherwise.

Inequality (\ref{equation:stronger_statement}) is straightforward when $(q,w) = (q',w')$ because then $t = t' = t^*$ and we use Lemma~\ref{lemma:proba_first_order}. In particular~(\ref{equation:stronger_statement}) holds true when $q = q' = q_I$. Now we assume $(w, q) \neq (w',q')$ and proceed by induction on $i$. The base case $i = 0$ holds true by the previous remark. 

Let $b,b' \in \{0,1\}$ such that $w = \omega \cdot b$ and $w' = \omega' \cdot b'$ (potentially $\omega = \omega' = \lambda$). Let $t_{\min}$ (resp. $t'_{\min}$) be the minimum $h(q'')$ (resp. $h'(q'')$) for $q'' \in \pred(q)$ (resp. $q'' \in  \pred(q')$). We have that 
\begin{align*}
&\Pr\left[w \in \vY{r}{h}{t}{q} \text{ and } w' \in \vY{r}{h'}{t'}{q'}\right] = \Pr\left[w \in \vZ{r}{h}{q} \text{ and } w' \in \vZ{r}{h'}{q'}\right]\\
 \times&\Pr\left[w \in \reduce\left(\vZ{r}{h}{q},\frac{t}{t_{\min}}\right) \text{, } w' \in \reduce\left(\vZ{r}{h'}{q'},\frac{t'}{t'_{\min}}\right) \,\Big|\, w \in \vZ{r}{h}{q} \text{, } w' \in \vZ{r}{h'}{q'}\right] 
\end{align*}
We have that 
$\Pr[w \in \reduce(\vZ{r}{h}{q},\frac{t}{t_{\min}}) \text{ and } w' \in \reduce (\vZ{r}{h'}{q'},\frac{t'}{t'_{\min}}) \mid w \in \vZ{r}{h}{q} \text{ and }  w' \in \vZ{r}{h'}{q'}]$ equals $\Pr[w \in \reduce(\vZ{r}{h}{q},\frac{t}{t_{\min}}) \mid w \in \vZ{r}{h}{q}]\Pr[ w' \in \reduce (\vZ{r}{h'}{q'},\frac{t'}{t'_{\min}}) \mid w' \in \vZ{r}{h'}{q'}] = \frac{tt'}{t_{\min}t'_{\min}}$ by the independence of the $\reduce$ events. So
\begin{equation}\label{equation:vZ_connection}
\Pr\left[w \in \vY{r}{h}{t}{q} \text{ and } w' \in \vY{r}{h'}{t'}{q'}\right] = \frac{tt'}{t_{\min}t'_{\min}} \Pr\left[w \in \vZ{r}{h}{q} \text{ and } w' \in \vZ{r}{h'}{q'}\right]
\end{equation}
There is a unique $b\textit{-}$predecessor $q_j$ of $q$ and a unique $b'$-predecessor $q'_l$ of $q'$ such that $\Pr[w \in \vZ{r}{h}{q} \text{ and } w' \in \vZ{r}{h'}{q'}]$ equals
\begin{align*}
&\Pr\left[\omega \in \reduce\left(\vY{r}{h_j}{t_j}{q_j},\frac{t_{\min}}{t_j}\right), \omega' \in \reduce\left(\vY{r}{h'_l}{t'_l}{q'_l},\frac{t'_{\min}}{t'_l}\right) \,\Big|\, \omega \in \vY{r}{h_j}{t_j}{q_j} \text{, } \omega' \in \vY{r}{h'_l}{t'_l}{q'_l}\right] 
\\ \times & \Pr\left[\omega \in \vY{r}{h_j}{t_j}{q_j}  \text{ and } \omega' \in \vY{r}{h'_l}{t'_l}{q'_l}\right]
\end{align*}
where $h_j$ denotes the restriction of $h$ to $\ancestors(q_j)$, $h'_l$ denotes the restriction of $h'$ to $\ancestors(q'_l)$, $t_j = h(q_j)$ and $t'_l = h'(q'_l)$.
By independence of the $\reduce$ events, the first probability equals $\frac{t_{\min}t'_{\min}}{t_jt'_l}$. The states $q_j$ and $q'_l$ are in $\calQ^{i-1}$ so, by induction, $\Pr[\omega \in \vY{r}{h_j}{t_j}{q_j}  \text{ and } \omega' \in \vY{r}{h'_l}{t'_l}{q'_l}]$ is bounded from above by $\frac{t_jt'_l}{\tau}$ where $\tau = t_j$ if $(q_j,t_j,\omega) = (q'_l,t'_l,\omega')$ and $\tau = h(\lcpn(\paths(\omega,q_j),(\omega',q'_l)))$ otherwise. So 
$$
\Pr[w \in \vZ{r}{h}{q} \text{ and } w' \in \vZ{r}{h'}{q'}] \leq \frac{t_{\min}t'_{\min}}{\tau}.
$$
If $(q_j,t_j,\omega) = (q'_l,t'_l,\omega')$ then $q \neq q'$ for otherwise we would have $b = b'$ and $(q,w) = (q',w')$. So $\lcpn(\paths(w,q),\paths(w',q')) = q_j = q'_l$ and $t^* = h(q_j) = h(q'_l) = t'_l = t_j = \tau$. If instead $(q_j,t_j,\omega) \neq (q'_l,t'_l,\omega')$ then $\lcpn(\paths(w,q),\paths(w',q')) = \lcpn(\paths(\omega,q_j),\paths(\omega',q'_l))$ and, again $t^* = \tau$. It follows that $\Pr[w \in \vZ{r}{h}{q} \text{ and } w' \in \vZ{r}{h'}{q'}] \leq \frac{t_{\min}t'_{\min}}{t^*}$ and thus $\Pr[w \in \vY{r}{h}{t}{q} \text{ and } w' \in \vY{r}{h'}{t'}{q'}] \leq \frac{tt'}{t^*}$. The matching inequality for the $\vZ{r}{h}{q}$ variables follows from (\ref{equation:vZ_connection}).
\end{proof}


\notSoBlackMagic*


We make a sequence of modifications to $\approxMCNFAcore^*$ to transform it into the random process. The modifications are on $\estimateAndSample$. Initially the procedure is as follows:

\renewcommand{\thealgocf}{}

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r(q)$ for all $r$ using $\{ S^r(q') \mid q' \in \pred(q)\}$\\
compute $p(q)$ using $\{\hat{S}^r(q)\}_r$\\
compute $S^r(q)$ for all $r$ using $p(q)$ and $\hat{S}^r(q)$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}

\paragraph*{Recording histories.} For every state $q$, we keep the history for the ancestors of $q$. Formally, we maintain a variable $H(q)$ for every state $q$. Initially $H(q)$ is empty for all $q$. After the value $p(q)$ is computed the variable $H(q')$ is updated for all descendants $q'$ of $q$ as follow: $H(q') = H(q') \cup (p \mapsto p(q))$. Thus, just before processing $q'$, $H(q')$ is the history for $q'$. Clearly, keeping unused additional variables does not modify the output of the algorithm. The procedure $\estimateAndSample$ now is as follow:

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r(q)$ for all $r$ using $\{ S^r(q') \mid q' \in \pred(q)\}$\\
compute $p(q)$ using $\{\hat{S}^r(q)\}_r$ \textcolor{red}{and update $H$}\\
compute $S^r(q)$ for all $r$ using $p(q)$ and $\hat{S}^r(q)$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}


\paragraph*{Introducing clone variables.} For every realizable history $h$ for $q$, and every $r \in [n_sn_t]$, the algorithm now has a variable $\hat{S}^r_h(q)$ and for every $t$ that is a possible candidate for $p(q)$, it also has a variable $S^r_{h,t}(q)$. Initially all $\hat{S}^r_{h}(q)$ and $S^r_{h,t}(q)$ are empty. When the algorithm computes the value for $p(q)$, $H(q)$ has already been set. Once $\hat{S}^r(q)$ is computed we copy its content in $\hat{S}^r_{H(q)}(q)$ and once $S^r(q)$ is computed we copy its content in $S^r_{H(q),p(q)}(q)$. All these steps are superfluous since we are just assigning variables that, so far, are not used. Note that
\begin{align*}
(H(q),\hat S^r(q)) = (H(q),\hat S^r_{H(q)}(q)) \quad  \text{ and } \quad (H(q),p(q), S^r(q)) = (H(q),p(q),S^r_{H(q),p(q)}(q)).
\end{align*}

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r(q)$ for all $r$ using $\{ S^r(q') \mid q' \in \pred(q)\}$\\
\textcolor{red}{copy $\hat{S}^r(q)$ to $\hat{S}^r_{H(q)}(q)$ for all $r$}\\
compute $p(q)$ using $\{\hat{S}^r(q)\}_r$ and update $H$\\
compute $S^r(q)$ for all $r$ using $p(q)$ and $\hat{S}^r(q)$\\
\textcolor{red}{copy $S^r(q)$ to $S^r_{H(q),p(q)}(q)$ for all $r$}
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}

\paragraph*{Working with the clone variables.}
For a fixed $q$, to compute $p(q)$, $\{\hat S^r(q)\}_r$ and $\{S^r(q)\}_r$, the algorithm uses $\{p(q')\}_{q' \in \pred(q)}$ and $\{\{S^r(q')\}_r\}_{q' \in \pred(q)}$. By the equalities above, we can use the $S^r_{h,t}(q)$ instead of the $S^r(q)$ to do the computation.  We just need to retrieve the correct sets using $H(q)$.

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r(q)$ for all $r$ using $\{\textcolor{red}{S^r_{H(q'),p(q')}(q')} \mid q' \in \pred(q)\}$\\
copy $\hat{S}^r(q)$ to $\hat{S}^r_{H(q)}(q)$ for all $r$\\
compute $p(q)$ using $\{\textcolor{red}{\hat{S}^r_{H(q)}(q)}\}_r$ and update $H$\\
compute $S^r(q)$ for all $r$ using $p(q)$ and \textcolor{red}{$\hat{S}_{H(q)}^r(q)$}\\
copy $S^r(q)$ to $S^r_{H(q),p(q)}(q)$ for all $r$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}
\medskip

\noindent But then we might as well compute $\hat{S}^r_{H(q)}(q)$ and $S^r_{H(q),p(q)}(q)$ directly and then copy their content to $S^r(q)$ and $\hat{S}^r(q)$.

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute \textcolor{red}{$\hat{S}^r_{H(q)}(q)$} for all $r$ using $\{S^r_{H(q'),p(q')}(q') \mid q' \in \pred(q)\}$\\
compute $p(q)$ using $\{\hat{S}^r_{H(q)}(q)\}_r$ and update $H$\\
compute \textcolor{red}{$S^r_{H(q),p(q)}(q)$} for all $r$ using $\hat{S}^r_{H(q)}(q)$\\
copy \textcolor{red}{$S^r_{H(q),p(q)}(q)$ to $S^r(q)$} for all $r$\\
copy \textcolor{red}{$\hat{S}^r_{H(q)}(q)$ to $\hat{S}^r(q)$} for all $r$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}
\medskip

\noindent We still have $(H(q),\hat S^r(q)) = (H(q),\hat S^r_{H(q)}(q))$ and $(H(q),p(q), S^r(q)) = (H(q),p(q),S^r_{H(q),p(q)}(q))$.

\paragraph*{Filling unused clone variables.} When processing a state $q$ given $H(q)$ we know the sets $\hat{S}^r_{h}(q)$ for $h \neq H(q)$ will not be filled and will not be used to compute the output of the algorithm. Similarly once $p(q)$ is found, we know the sets $S^r_{h,t}(q)$ for $(h,t) \neq (H(q),p(q))$ will not be filled nor used to compute the output of the algorithm. So additional work can be done to decide the content of these $\hat{S}^r_{h}(q)$ and $S^r_{h,t}(q)$. In particular, if $\pred(q) = (q_1,\dots,q_k)$ then we can set $\rho_h(q) = \min(h(q_1),\dots,h(q_k)$ and $\hat{S}^r_{h}(q) = \union(q,\reduce(S^r_{h_1,h(q_1)}(q_1),\rho^{h}/h(q_1)),\dots,\reduce(S^r_{h_k,h(q_k)}(q_k),\rho^{h}/h(q_k)))$ and $S^r_{h,t}(q) = \reduce(\hat{S}^r_{h}(q),t/\rho)$, where $h_i$ denote the restriction of $h$ to the ancestors of $q_i$.

\begin{minipage}{0.9\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r_{H(q)}(q)$ for all $r$ using $\{ S^r_{H(q'),p(q')}(q') \mid q' \in \pred(q)\}$\\
\textcolor{red}{compute $\hat{S}^r_{h}(q)$ for all $r$ and $h$ using $\{ \{S^r_{h,t}(q') \}_{r,h,t} \mid q' \in \pred(q)\}$}\\
compute $p(q)$ using $\{\hat{S}^r_{H(q)}(q)\}_r$ and update $H$\\
compute $S^r_{H(q),p(q)}(q)$ for all $r$ using $\hat{S}^r_{H(q)}(q)$\\
\textcolor{red}{compute $S^r_{h,t}(q)$ for all $r$ and $h \neq H(q)$ using $\{\hat{S}^r_{h}(q)\}_h$}\\
copy $S^r_{H(q),p(q)}(q)$ to $S^r(q)$ for all $r$\\
copy $\hat{S}^r_{H(q)}(q)$ to $\hat{S}^r(q)$ for all $r$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}
\medskip

\noindent But then the computation of $\hat S^r_h$ and $S^r_{h,t}$ is no different from what is done to compute $\hat{S}^r_{H(q)}(q)$ and $S^{r}_{H(q),p(q)}(q)$ so the procedure is equivalent to 

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r_{h}(q)$ for all $r$ \textcolor{red}{and all $h$ (including $h= H(q)$)} using $\{ S^r_{h',p(q')}(q')\}_{h',q' \in \pred(q)}$\\
compute $p(q)$ using $\{\hat{S}^r_{H(q)}(q)\}_r$ and update $H$\\
compute $S^r_{h,t}(q)$ for all $r$, \textcolor{red}{and all $h$ and $t$ (including $h = H(q)$ and $t = p(q)$)} using $\{\hat{S}^r_{h}(q)\}_h$\\
copy $S^r_{H(q),p(q)}(q)$ to $S^r(q)$ for all $r$\\
copy $\hat{S}^r_{H(q)}(q)$ to $\hat{S}^r(q)$ for all $r$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}
\medskip

which is equivalent to

\begin{minipage}{\textwidth}
\begin{algorithm}[H]
compute $\hat{S}^r_{h}(q)$ for all $r$ and all $h$ (including $h= H(q)$) using $\{ S^r_{h',p(q')}(q')\}_{h',q' \in \pred(q)}$\\
compute $S^r_{h,t}(q)$ for all $r$, $h$ and $t$ (including $h = H(q)$ and $t = p(q)$) using $\{\hat{S}^r_{h}(q)\}_h$\\
compute $p(q)$ using $\{\hat{S}^r_{H(q)}(q)\}_r$ and update $H$\\
copy $S^r_{H(q),p(q)}(q)$ to $S^r(q)$ for all $r$\\
copy $\hat{S}^r_{H(q)}(q)$ to $\hat{S}^r(q)$ for all $r$
\caption*{$\estimateAndSample(q)$}
\end{algorithm}
\end{minipage}
\medskip

Now the computation of $p(q)$ and $H$ is not needed to compute $\hat{S}^r_{h}(q)$ and $S^r_{h,t}(q)$. So we have transformed the algorithm into the random process with $\hat{S}^r_h(q) =  \vZ{r}{h}{q}$ and $S^r_{h,t}(q) = \vY{r}{h}{t}{q}$ (the first two lines of $\estimateAndSample(q)$). The variables $H(q)$ and $p(q)$ do the bookkeeping and allow us to retrieve $S^r(q)$ as $S^r_{H(q),p(q)}(q)$ and $\hat S^r(q)$ has $\hat S^r_{H(q)}(q)$ for every $q$. So we indeed have that 
$$
(H(q),\hat S^r(q)) = (H(q),\hat S^r_{H(q)}(q)) = (H(q),\vZ{r}{H(q)}{q})
$$
and
$$
(H(q),p(q),S^r(q)) = (H(q),p(q),S^r_{H(q),p(q)}(q)) = (H(q),p(q),\vY{r}{H(q)}{p(q)}{q}).
$$


