	Due to the arbitrariness of \(x\) and \(y\) in the above equation, we set the coefficients of $y^2$, \(xy\), $x$, $y$, and the constant terms to zero, thereby obtaining five equations for \(C, D, E, F, I\), respectively. Hence, we deduce the expressions of \(C, D, E, F, I\) as follows: \begin{align}
		C &=(2r-\lambda)^{-1}[\lambda\gamma(c+\phi)-\frac{\rho}{2}\gamma \tilde{a}q^2], \label{eq:C1} \\
		D &=(2r-\lambda)^{-1}[\mu_1 cr-\gamma  \tilde{a}\rho pq+2\gamma \lambda(a-{\varphi}_{n})(c+\phi)+\lambda\mu_1\phi], \label{eq:D1} \\
		E &=(r-\lambda)^{-1}[\mu_1\alpha r-D\widehat{\underline{br}\hat{\pi}}-\rho\gamma  \tilde{a}\varrho p+2\gamma\lambda \alpha (a-{\varphi}_{n})-\mu_2\lambda \varp_n],\label{eq:E1} \\
		F &=(r-\lambda)^{-1}[ 2\lambda\gamma \alpha(c+\phi)+\lambda\mu_2\phi-\rho\gamma \tilde{a}\varrho   q-2C\widehat{\underline{br}\hat{\pi}}], \label{eq:F1} \\
		I &=\lambda^{-1}\Big[(C-\gamma c^2)\Big(\widehat{\xi\hat{\pi}}^2+\widehat{\sigma\hat{\pi}}^2\Big)-\lambda \gamma \alpha^2+\frac{\rho}{2}\gamma \tilde{a}\varrho^2+F\widehat{\underline{br}\hat{\pi}}\Big]. \label{eq:I1}
	\end{align}
	By substituting \eqref{eq:bara}, \eqref{eq:c1}, and \eqref{eq:D1} into \eqref{eq:q1} and simplifying the expressions, we obtain the equation of \(q\):
	\begin{align}\label{eq:q2}
		\{\gamma \tilde{a}(\lambda-r)[2r-\lambda+(b-r)\rho p]-[2\gamma\lambda(a-\varphi_n)+\mu_1(\lambda-r)]a\rho(b-r)^2\}q=-2\gamma\lambda\phi r(a-\varphi_n)(b-r).
	\end{align}
	Finally, by substituting \eqref{eq:bara}, \eqref{eq:A}, \eqref{eq:a1}, \eqref{eq:e1}, \eqref{eq:D1}, and \eqref{eq:E1} into \eqref{eq:k}, we derive the expression of \(\varrho\).

	Because the \(i\)-th agent's investment strategy \(\widehat{\pi}_i\) in \eqref{eq:NE} is combined with other competitors' equilibrium  feedback  strategy \(\widehat{\pi}_j\) (for \(j\neq i\)), we still need to find the closed-form expression of \(\widehat{\pi}_i\) for \(i=1,\ldots,n\). Define
	\begin{align}\label{eq:Qi}
	Q_i :=\gamma_i \tilde{a}_i[r-\lambda+\rho_ip_i(b_i-r)]-a_i\rho_i(b_i-r)^2[2\gamma_i(a_i-1+\phi_i/n)+\mu_{i1}],
	\end{align}
	and assume that \(Q_i \neq 0\). By using \(\varrho_i\) in \eqref{eq:k}, we can rewrite \(\widehat{\pi}_i(x_i, y_{\smn i})\) in \eqref{eq:NE}  as follows
	\begin{align}\label{eq:pifinal}
		\widehat{\pi}_i(x_i, y_{\smn i})
		:= \rho_i p_i x_i + \rho_i q_i y_{\smn i} + k_{i1} \widehat{\sigma\hat{\pi}} + k_{i2}\widehat{\underline{br}\hat{\pi}}+k_{i3},
	\end{align}
	in which
	\begin{align}	
k_{i1}&=Q^{-1}_i\rho_i\sigma_i(r-\lambda)(D_i-\mu_{i1}c_i-2\gamma_ia_ic_i),\label{eq:k1}\\	k_{i2}&=Q^{-1}_i\rho_i(b_i-r)[2\gamma_i(a_i-1+\phi_i/n)c_i+\mu_{i1}c_i-D_i],\label{eq:k2}\\
		k_{i3}&=-Q^{-1}_i\mu_{i2}\rho_i\lambda(1-\phi_i/n)(b_i-r).\label{eq:k3}
	\end{align}


	From \eqref{eq:q2} and \eqref{eq:c1}, we observe that \(q_i\) and \(c_i\) are proportional to the competitive parameter \(\phi_i\). Moreover, from \eqref{eq:D1}, we know that \(D_i\) is also proportional to \(\phi_i\). Hence, \(k_{ij}\) (for \(j=1,2\)) given in \eqref{eq:k1} and\eqref{eq:k2} are proportional to \(\phi_i\). In view of this, the equilibrium  feedback  strategy given in \eqref{eq:pifinal} can be divided into two parts: One part is \(\rho_i p_i x_i+k_{i3}\), which is independent of the competition parameter \(\phi_i\); the other part is $ \rho_i q_i y_{\smn i} + k_{i1} \widehat{\sigma\hat{\pi}} + k_{i2}\widehat{\underline{br}\hat{\pi}}$, proportional to \(\phi_i\).

	Based on the above analysis and \eqref{eq:pifinal}, we derive the following \(n\)-dimensional linear system of equations for \(\widehat{\pi} = (\widehat{\pi}_1,\ldots,\widehat{\pi}_n)\),
	\begin{align}
		\big[\bm{N}-(\bm{k}_1,\bm{k}_2)\cdot (\bm{\sigma} ,\bm{b-r})^\top\big]\widehat{\pi}^\top=\bm{k}_3^\top+\diag{\rho_1p_{1},\ldots,\rho_np_n}\bm{x}^\top+\diag{\rho_1q_1,\ldots,\rho_nq_n}\bm{y}^\top,\\
		\label{eq:systempi}
	\end{align}
	in which \(\bm{N}=\diag{N_1,\ldots,N_n}\) with
\begin{align}\label{eq:Ni}
N_i=(k_{i2}(b_i-r)+k_{i1}\sigma_i+n)/{n},
\end{align}
 for \(i= 1,\ldots,n \),
 and \(\bm{k}_j=(k_{1j}, \ldots,k_{nj})^\top\), for \(j= 1,2,3 \),  \(\bm{\sigma}=\big(\sigma_1/n,\ldots,\sigma_n/n\big)^\top\), \(\bm{b-r}=\big((b_1-r)/n,\ldots,(b_n-r)/n\big)^\top\), \(\bm{x}=(x_1,\ldots,x_n)^\top\), and \(\bm{y}=(y_{\smn 1},\ldots,y_{\smn n})^\top\). Thus, if the coefficient matrix of \(\widehat{\pi}\) is invertible, namely, \(\bm{N}-(\bm{k}_1,\bm{k}_2)\cdot (\bm{\sigma} ,\bm{b-r})^\top\) is invertible, then the equilibrium  feedback  strategy for the \(n\)-agent game exists and is unique.

	Next,  we restrict our attention to derive the closed form of \(\bm{\widehat{\pi}}\) when \(\diag{N_1,\ldots,N_n}\neq \bm{0}_{n\times n}\).
	Define
    \[\overline{\sigma\hat{\pi}}^{(n)}:=\frac{1}{n}\sum_{i = 1}^n\sigma_i\widehat{\pi}_i \quad  \text{and} \quad \overline{\underline{br}\hat{\pi}}^{(n)}:=\frac{1}{n}\sum_{i = 1}^n(b_i - r)\widehat{\pi}_i.
    \]
    Then, we can rewrite the linear system of equations \eqref{eq:systempi} as follows:
	\begin{align}\label{eq:average}
		\widehat{\pi}_i( x_i,y_{\smn i})=N_i^{-1}\big[\rho_i p_ix_i+\rho_i q_iy_{\smn i}+k_{i1}\overline{\sigma\hat{\pi}}^{(n)}+k_{i2}\overline{\underline{br}\hat{\pi}}^{(n)}+k_{i3}\big],~~\text{for}~ i=1,\cdots,n.
	\end{align}
	We now derive the closed forms of \(\overline{\sigma\hat{\pi}}^{(n)}\) and \(\overline{\underline{br}\hat{\pi}}^{(n)}\).  Through straightforward calculations, we obtain two equations for \(\overline{\sigma\hat{\pi}}^{(n)}\) and \(\overline{\underline{br}\hat{\pi}}^{(n)}\):
	\begin{align}
		&\overline{\sigma\rho px}^{(n)}+\overline{\sigma\rho qy}^{(n)}+\big(\overline{\sigma k_1}^{(n)}-1\big)\overline{\sigma\hat{\pi}}^{(n)}+\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}\hat{\pi}}^{(n)}+\overline{\sigma k_3}^{(n)}=0,\label{eq:system1}\\
		& \overline{\underline{br}\rho px}^{(n)}+\overline{\underline{br}\rho qy}^{(n)}+\overline{\underline{br}k_1}^{(n)}\overline{\sigma\hat{\pi}}^{(n)}+\big(\overline{\underline{br}k_2}^{(n)}-1\big)\overline{\underline{br}\hat{\pi}}^{(n)}+\overline{\underline{br}k_3}^{(n)}=0,\label{eq:system2}
	\end{align}
	in which
	\begin{align}
		\overline{\sigma\rho px}^{(n)}&=\sum_{i=1}^n\frac{\sigma_i\rho_i p_ix_i}{nN_i},&\quad\quad \overline{\sigma\rho qy}^{(n)}&=\sum_{i=1}^n \frac{\sigma_i\rho_i q_iy_{-i}}{nN_i},\label{eq:coeff1}\\
		\overline{\underline{br}\rho px}^{(n)}&=\sum_{i=1}^n\frac{(b_i-r)\rho_i p_ix_i}{nN_i},&\quad\quad \overline{\underline{br}\rho qy}^{(n)}&=\sum_{i=1}^n \frac{(b_i-r)\rho_i q_iy_{-i}}{nN_i},\label{eq:coeff2}\\
		\overline{\sigma k_j}^{(n)}&=\sum_{i=1}^n \frac{\sigma_ik_{ij}}{nN_i},&\quad\quad \overline{\underline{br}k_j}^{(n)}&=\sum_{i=1}^n \frac{(b_i-r)k_{ij}}{nN_i},\label{eq:coeff3}
	\end{align}
	for \(j=1,2,3\).

	By further computations, we derive that if \(\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)} \neq 0\), the closed forms of \(	\overline{\sigma\hat{\pi}}^{(n)}\) and \(	\overline{\underline{br}\hat{\pi}}^{(n)}\) are given by
		\begin{align}
		&\overline{\sigma\hat{\pi}}^{(n)} =\frac{\big(1-\overline{\underline{br}k_2}^{(n)}\big)\big(\overline{\sigma\rho px}^{(n)}+\overline{\sigma\rho qy}^{(n)}+\overline{\sigma k_3}^{(n)}\big)+\overline{\sigma k_2}^{(n)}\big(\overline{\underline{br}\rho px}^{(n)}+\overline{\underline{br}\rho qy}^{(n)}+\overline{\underline{br} k_3}^{(n)}\big)}{\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)}},\\
        \label{eq:overpisigma} \\
		&\overline{\underline{br}\hat{\pi}}^{(n)}=\frac{\big(1-\overline{\sigma k_1}^{(n)}\big)\big(\overline{\underline{br} \rho px}^{(n)}+\overline{\underline{br}\rho qy}^{(n)}+\overline{\underline{br} k_3}^{(n)}\big)+\overline{\underline{br}k_1}^{(n)}\big(\overline{\sigma\rho px}^{(n)}+\overline{\sigma\rho qy}^{(n)}+\overline{\sigma k_3}^{(n)}\big)}{\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)}}.\\ \label{eq:overpibr}
	\end{align}

\noindent By plugging \eqref{eq:overpisigma} and \eqref{eq:overpibr} into \eqref{eq:average}, we obtain the ``unique'' equilibrium feedback strategy \footnote{Here, the ``unique'' means the values of $\overline{\sigma\hat{\pi}}^{(n)}$ and $\overline{\underline{br}\hat{\pi}}^{(n)}$ are unique, while the value of the equilibrium feedback strategy $\widehat{\bf{\pi}}$ is not unique, see the item 1 in Remark \ref{remark:2.5}. }.

	\noindent If \(\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)} = 0\), the linear equations \eqref{eq:system1} and \eqref{eq:system2} are solvable if and only if there exists a constant \(\kappa\) such that
	\begin{align}
		&\overline{\sigma\rho px}^{(n)}+\overline{\sigma \rho qy}^{(n)}+\overline{\sigma k_3}^{(n)}=\kappa\left[\overline{\underline{br} \rho px}^{(n)}+\overline{\underline{br} \rho qy}^{(n)}+\overline{\underline{br}k_3}^{(n)}\right],\label{eq:kappa1}\\
		&\overline{\sigma k_1}^{(n)}-1=\kappa\overline{\underline{br} k_1}^{(n)},\quad\quad
		\overline{\sigma k_2}^{(n)}=\kappa\left(\overline{\underline{br} k_2}^{(n)}-1\right). \label{eq:kappa2}
	\end{align}






	%The constant \(\kappa\) is independent with \(\lambda\) while other expressions in the above equation are related to \(\lambda\). Then, by taking \(\lambda\to\infty\) for the above equations, we can get that
	%\begin{align}
	%	\lim_{\lambda\to\infty}	\overline{\sigma\rho px}&=\kappa 	\lim_{\lambda\to\infty}\overline{br \rho px},  	\lim_{\lambda\to\infty}\overline{\sigma k_1}-1=\kappa	\lim_{\lambda\to\infty}\overline{br k_1},
	%	\lim_{\lambda\to\infty} \overline{\sigma k_3}=\kappa 	\lim_{\lambda\to\infty}\overline{brk_3}.
	%\end{align}
	%Since \(\lim_{\lambda\to\infty}	\overline{\sigma\rho px}\geq 0\) and \(\lim_{\lambda\to\infty}\overline{br \rho px}\geq 0\), we can obtain \(\kappa\geq 0\). However, \(\lim_{\lambda\to\infty}\overline{\sigma k_1}\leq 1\) and \(\lim_{\lambda\to\infty}\overline{br k_1}\geq 0\) , which implies \(\kappa\leq 0\). However, if we assume \(\kappa=0\), we obtain that both \(\overline{\sigma\rho px}\), \(\overline{\sigma\rho qy}\) and \(\overline{\sigma \rho k_3}\) are equal to zero. These lead to \(\sigma_i=0\) for all \(i=1,\cdots,n\), which implies that \(\lim_{\lambda\to\infty}\overline{brk_2}=1\). This gives rise to a contradiction. Therefore, if \(\big(\overline{brk_2}-1\big)\big(\overline{\sigma k_1}-1\big)-\overline{\sigma k_2}\cdot\overline{brk_1} = 0\), the equilibrium  feedback  strategy does not exist.


	We summarize the above analysis in the following theorem, which presents the equilibrium  feedback  strategy and the value function for the mean-variance problem when \(\diag{N_1,\ldots,N_n}\neq \bm{0}_{n\times n}\).

	\begin{theorem}\label{th:main}
		Let \(\lambda\neq r\), \(\lambda\neq 2r\)\footnote{When \(\lambda = r\) or \(\lambda = 2r\), the methodology for deriving the equilibrium  feedback  strategy and the value function is analogous to that presented in this paper. Thus, we omit the detailed analysis of these two cases in this paper.}, \(Q_i\neq 0\), and \(N_i\neq 0\), for $i=1,\ldots,n.$ Then, for the mean-variance problem,
		\begin{itemize}
			\item[$(1)$]  when \(\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)}\neq 0\), the expression for \(\widehat{\pi}_i(x_i,y_{\smn i})\) is given by \eqref{eq:average}, in which \(\rho_i\) is defined in \eqref{eq:rho}, and \(p_i=z_i/[\rho_i(b_i-r)]\), with \(z_i\) solving \eqref{eq:p1}, and $p_i$ satisfying \eqref{eq:conditionP}. Meanwhile, \(q_i\) solves \eqref{eq:q2}, and \(k_{ij}\), for \(j=1,2,3\), is given in \(\eqref{eq:k1}-\eqref{eq:k3}\).
			The expressions for \(\overline{\sigma\hat{\pi}}^{(n)}\) and \(\overline{\underline{br} \hat{\pi}}^{(n)}\) are presented in \eqref{eq:overpisigma} and \eqref{eq:overpibr}, respectively. Moreover, the corresponding equilibrium value function is given by
			\begin{align}\label{eq:VV}
				V_i( x_i,y_{\smn i})=A_i x_i^2+C_i y_{\smn i}^2+D_i x_iy_{\smn i}+E_i x_i+F_i y_{\smn i}+I_i,
			\end{align}
			in which the functions $A_i $, $C_i $,\ $D_i$,\ $E_i $, \(F_i\),\ and $I_i $ are given in \eqref{eq:A},\ \eqref{eq:C1},\ \eqref{eq:D1},\ \eqref{eq:E1},\ \eqref{eq:F1}, and \eqref{eq:I1}\ respectively.

			\item[$(2)$]  when \(\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)}= 0\),
			\begin{itemize}
				\item[$(a)$] if there exist a constant \(\kappa\) such that \eqref{eq:kappa1} and \eqref{eq:kappa2} hold, the equilibrium feedback strategy exists, and the equilibrium feedback strategy \(\hat{\pi}_i\) (for \(i=1,\ldots,n\)) satisfies the equation \eqref{eq:system1} or \eqref{eq:system2}.

					\item[$(b)$]  if no such constant \(\kappa\) exists, the equilibrium feedback strategy does not exist.
			\end{itemize}

		\end{itemize}
	\end{theorem}

