	\section{The mean-field game (MFG)}\label{sec:MF}
	In this section, we study the equilibrium feedback strategy for the game as the number of agents \(n\) tends to infinity. In this case,  the \(n\)-agent game converges to a mean-field game with a continuum of agents. In Subsection \(\ref{subsec:MF-model}\), we introduce the type space, the objective, and the definition of the mean-field equilibrium (MFE) feedback strategy. In Subsection \(\ref{subsec:MF-VT}\), we first present a general verification theorem. Then, we use it to find the solutions of the mean-field game when the hazard rate of the random horizon is constant. Finally, we derive the relationship between the equilibrium feedback strategy in the \(n\)-agent game and the MFE in the mean-field game in Subsection \ref{subsec:rela}.



	\subsection{Model formulation}\label{subsec:MF-model}
	We start by defining the type vector and the type space. For the \(n \)-agent game, we denote the parameters of the \(i\)-th agent by the following type vector
	\begin{align}
		\eta_i := (x_i, b_i, \xi_i, \sigma_i, \phi_i, \gamma_i, \mu_{1i}, \mu_{2i}), \qquad \text{for}~~i=1,\ldots,n.
	\end{align}
	We allow these parameters to depend on \(n\), but for simplicity, we will not add an index \(n\) to the  type vector \(\eta_i\). These type vectors induce an empirical measure \(m_n\), called the type distribution, which is a probability measure on the type space
	\begin{align*}
		\mathcal{Z}^e:=\mathbb{R}\times [0,\infty)^3\times[0,1]\times\mathbb{R}^+\times[0,\infty)^2,
	\end{align*}
	given by
	\begin{align}
		m_n(A) = \frac{1}{n} \sum_{i=1}^{n} {\bf{1}}_A(\eta_i) \quad \text{for Borel sets } A \subset \mathcal{Z}^e. \label{eq:mn}
	\end{align}

	We then find that the equilibrium strategy \(\widehat{\pi}_i\) computed in Theorem \ref{th:main} depends only on the $i$-th agent's own type vector \(\eta_i\) and the type distribution \(m_n\) of all type vectors. Now, we assume that the empirical measure \(m_n\) converges weakly to a limit measure \(m\) on the space \(\mathcal{Z}^e\) in the sense that
	\begin{align}
		\int_{\mathcal{Z}^e} f \, \drm m_n \to \int_{\mathcal{Z}^e} f \, \drm m,  \label{eq:weak_converge}
	\end{align}
	for any bounded continuous function \(f\) on \(\mathcal{Z}^e\) when the number of agents tend to infinity, that is \(n\to\infty\). We define \(\eta = (x, b, \xi, \sigma, \phi, \gamma, \mu_1, \mu_2)\) as a random variable with this limiting distribution \(m\) on the space \(\mathcal{Z}^e\). The distribution of this random type vector reflects the law of type vectors of a continuum of agents, where a single realization of the random type vector represents the type assigned to a single representative agent.

	We start to formulate the MFG, and then derive the expression of the equilibrium feedback strategy for the MFG. Let \((\Omega, \mathcal{F},\mathbb{F}=\{\mathcal{F}_t\}_{t\geq 0}, \mathbb{P})\) be a filtered complete probability space satisfying the usual conditions, which supports a two-dimensional Brownian motion \((W, B)\) and a random type vector \(\eta = (x, b, \xi, \sigma, \phi, \gamma, \mu_1, \mu_2)\). Here, \(\eta\)  is measurable with respect to the filtration \(\mathcal{F}_0\) and is independent of both \(W\) and \(B\). Let \(\mathbb{F}^B = \{\mathcal{F}_t^B\}_{t \geq 0}\) denote the natural filtration generated by the Brownian motion \(B\).

	%Similar to the \(n\)-agent game,
	%

	We assume that the financial market is the same as that considered in Subsection \ref{subsec:model} except that the idiosyncratic risk factors for the stocks are replaced by \(W=\{W(t)\}_{t\geq 0}\). Furthermore, we assume that the risk-free interest rate \(r\) is identical for all agents. Let $\pi(t)$ represent the amount of money that the representative agent invests in the risky stock. Then, the dynamic of the representative agent's wealth process $X^{\boldsymbol{\pi}}=\{X^{{\boldsymbol{\pi}}}(t)\}_{t\geq 0}$ under strategy ${\boldsymbol{\pi}} = \{\pi(t)\}_{t \ge 0}$ satisfies the following SDE:
	\begin{align}\label{eq:MFX}
		\drm X^{\bpi}(t)&= [rX^{\bpi}(t)  +(b-r)\pi(t)]\drm t+\xi\pi(t)\drm W(t)+\sigma\pi(t)\drm B(t).
	\end{align}

In order to solve the mean-field game, we restrict our attention to the average wealth of the continuum of agents, which is represented by the stochastic process $\{\bar{X}^{\bpi}(t)\}_{t\geq 0}$ of the form $\bar{X}^{\bpi}(t)=\mathbb{E}[X^{\bpi}(t)|\mathcal{F}_t^B]$ for all \(t\geq 0\). By taking the conditional expectation $\mathbb{E}[\cdot|\mathcal{F}^B_t]$ on both sides of (\ref{eq:MFX}), we obtain the SDE of $\bar{X}^{\bpi}(t)$ as follows
	\begin{align}
		\label{eq:MFbarX}
		\drm \bar{X}^{\bpi}(t)=[r\bar{X}^{\bpi}(t)+\overline{\underline{br}\pi}(t)]\drm t+\overline{\sigma\pi}(t)\drm B(t),~~\text{for all}~~t\geq 0,
	\end{align}
{where \(\overline{\underline{br}\pi}(t)=\mathbb{E}[(b-r)\pi(t)]\), and \(\overline{\sigma\pi}(t)=\mathbb{E}[\sigma\pi(t)]\).}

	\begin{definition}[Admissible Strategy]\label{def:mf_admissible}
		A feedback strategy \(\bm{\pi} = \{\pi(t, X^{\bpi}(t), \bar{X}^{\bpi}(t))\}_{t\geq 0}\) is called admissible if it satisfies the following conditions:
		\begin{itemize}
          %  \item[$(1)$] \(\bm{\pi}\) is an \(\mathbb{F}\)-progressively measurable real-valued process.
			\item[$(1)$] \( \int_0^t |\pi(s,X^{\bpi}(s),\bar{X}^{\bpi}(s))|^2\, \drm s\Big]<\infty\) almost surely for all \( t \geq 0 \).
			\item[$(2)$] The SDE \eqref{eq:MFX} has a unique strong solution for any \( X^{\bpi}(0) = x \in \mathbb{R} \).
		\end{itemize}
		We use \( \boldsymbol{\Pi}^m \) to denote the set of the representative agent's all admissible feedback strategies.
	\end{definition}
	We also assume the time horizon is random. Let \(\tau\) be a random variable defined in the above probability space, which is independent of the Brownian motion \((W,B)\) and the type vector \(\eta\), and we use \(\lambda(t)\)  to denote the time-dependent hazard rate function of \(\tau\) such that
	\begin{align*}
		\mathbb{P}(\tau>t)=\exp \Big(-\int_0^t \lambda(s)\drm s\Big).
	\end{align*}


	In the MFG framework, we assume that the representative agent has a mean-variance investment preference with a state-dependent risk aversion, concerning about the average wealth \(\bar{X}^{\bpi}(t)\). Thus, the objective for the representative agent is to  maximize
	\begin{align}	\label{eq:MFMFJ}
	J(t, x, \bar{x}; {\bm{\pi}}) = (\mu_1 x+\mu_2)\mathbb{E}_{t,x,\bar{x},t+}[X^{\bpi}(\tau)-\phi\bar{X}^{\bpi}(\tau)]-\gamma Var_{t,x,\bar{x},t+}[X^{\bpi}(\tau)-\phi\bar{X}^{\bpi}(\tau)],
	\end{align}
	in which \(\mathbb{E}_{t,x,\bar{x},t+}[\cdot]:=\mathbb{E}[\cdot|{X}^{\bpi}(t)={x}, \bar{X}^{\bpi}(t)=\bar{x}, \tau > t]\).


	Now, we give the definition of a time-consistent mean-field equilibrium feedback strategy in the MFG framework.

\begin{definition}[Time-consistent mean-field equilibrium feedback strategy]\label{def:MFE}
For an admissible feedback strategy \(\widehat{\bm{\pi}}=\{\widehat{\pi}(t,X^{\widehat{\bpi}}(t),\bar{X}^{\widehat{\bpi}}(t))\}_{t\geq 0}\), any fixed \((t, x, \bar{x}) \in [0,\infty) \times \mathbb{R} \times \mathbb{R}\), a fixed number \(\epsilon > 0\), and a real number $\pi$, define a feedback strategy $\bpi^{\eps}$ by
		\[
		\pi^{\eps}(s, x, \bar{x}) =
		\begin{cases}
			\pi, & \text{for } ~~   {t \leq s < (t+\epsilon) \wedge \tau,} \\
			\widehat{\pi}(s, x, \bar{x}), & \text{for }~~ (t+\epsilon) \wedge \tau \leq s \leq \tau.
		\end{cases}
		\]		
		If for all \((t, x, \bar{x}) \in [0,\infty) \times \mathbb{R} \times \mathbb{R}\),
		\begin{align}
		\liminf_{\epsilon \to 0^+} \frac{J(t, x, \bar{x}; \widehat{\bm{\pi}}) - J(t, x, \bar{x}; {\bm{\pi}^{\eps}})}{\epsilon} \geq 0,
		\end{align}
		then $\widehat{\bpi}$ is a time-consistent mean-field equilibrium (MFE) feedback strategy,
		and  the corresponding equilibrium value function is given by
		\[
		V(t, x, \bar{x}) = J(t, x, \bar{x}; \widehat{\bm{\pi}}),
		\]
with \(\bar{X}^{\widehat{\bm{\pi}}}(t)=\mathbb{E}[X^{\widehat{\bm{\pi}}}(t)|\mathcal{F}_t^B]\) for all \(t \geq 0\).
	\end{definition}


	\subsection{Solution to the MFG}\label{subsec:MF-VT}
	In this subsection, we first present a verification theorem for the MFG problem proposed in Section \ref{sec:ngame}, whose proof is the same as that of Theorem \ref{th:verification}, so we omit it. Then, we use this theorem to derive the MFE for the MFG problem when the hazard rate of the random horizon is a positive constant.

	First, for any real number $\pi$, and a function $g(t,x,\bar{x}) \in C^{1,2,2}([0,\infty) \times \mathbb{R} \times \mathbb{R})$, define the infinitesimal generator  $\mathcal{L}_{\scriptscriptstyle m}^{{\pi}}$ by
	\begin{align}
		\mathcal{L}_{\scriptscriptstyle m}^{{\pi}} g(t,x,\bar{x}) = & g_t + g_x[rx + (b - r)\pi] + g_{\bar{x}}[r\bar{x} + \overline{\underline{br} \pi}(t)] \\
		& + \frac{1}{2}g_{xx}[\xi^2\pi^2 + \sigma^2 \pi^2] + \frac{1}{2}g_{\bar{x}\bar{x}}\overline{\sigma \pi}(t)^2 + g_{x\bar{x}}\sigma \pi \overline{\sigma \pi}(t).
	\end{align}
	Define a function \(f \in C^{1,2,2,2,2}([0,\infty) \times \mathbb{R}^4)\) by
	\begin{align}
		f(t, x, y, u, v) = (\mu_{1} x + \mu_{2}) u - \gamma (v - u^2),
	\end{align}
  where $u$ and $v$ are two functions depending on $(t,x,y)$.
	\begin{theorem}[Verification Theorem]\label{th:MF-verification}
		Suppose that the hazard rate \(\lambda(t)\) has support on all of \(\mathbb{R}^+\) and suppose that there exist three real-valued functions $V^{\scriptscriptstyle m}(t,x,\bar{x})$, $G^{\scriptscriptstyle m}(t,x,\bar{x})$, $H^{\scriptscriptstyle m}(t,x,\bar{x})\in C^{1,2,2}({[0,\infty)}\times\mathbb{R}\times\mathbb{R})$ satisfying the following conditions:
		\begin{itemize}
			\item[$(1)$] For all \( (t,x,\bar{x})\in {[0,\infty)}\times \mathbb{R}\times \mathbb{R}\),
			\begin{align}				
				&\lambda(t)\left\{V^{\scriptscriptstyle m}(t,x,\bar{x})-(\mu_{1}x+\mu_{2})\big(x-\phi\bar{x}\big)+\gamma \left[G^{\scriptscriptstyle m}(t,x,\bar{x})-(x-\phi\bar{x})\right]^2\right\}\\	&=\sup_{{\pi}\in\boldsymbol{\Pi}^{\scriptscriptstyle m}}\left\{\mathcal{L}^{{\pi}}_{\scriptscriptstyle m}V^{\scriptscriptstyle m}(t,x,\bar{x})-\mathcal{L}^{{\pi}}_{\scriptscriptstyle m}f(t,x,\bar{x},G^{\scriptscriptstyle m},H^{\scriptscriptstyle m})+f_G(t,x,\bar{x},G^{\scriptscriptstyle m},H^{\scriptscriptstyle m})\mathcal{L}^{{\pi}}_{\scriptscriptstyle m} G^{\scriptscriptstyle m}(t,x,\bar{x})\right.\\
				&\left.\quad\quad\quad\quad+f_H(t,x,\bar{x},G^{\scriptscriptstyle m},H^{\scriptscriptstyle m})\mathcal{L}^{{\pi}}_{\scriptscriptstyle m}H^{\scriptscriptstyle m}(t,x,\bar{x})\right\}. \label{eq:MF-HJB}
			\end{align}
			Let $\widehat{\pi}$ denote the function of $(t, x, \bar{x})$ that attains the supremum in \eqref{eq:MF-HJB}.		
			\item[$(2)$] For all \( (t,x,\bar{x})\in {[0,\infty)}\times \mathbb{R}\times \mathbb{R}\),
			\begin{align}\label{eq:MF-LG}
				\lambda(t)\left( G^{\scriptscriptstyle m}(t,x,\bar{x})-(x-\phi \bar{x})\right)=\mathcal{L}^{\widehat{{\pi}}}_{\scriptscriptstyle m}G^{\scriptscriptstyle m}(t,x,\bar{x}).
			\end{align}

			\item[$(3)$] For all \( (t,x,\bar{x})\in {[0,\infty)}\times \mathbb{R}\times \mathbb{R}\),
			\begin{align}\label{eq:MF-LH}
				\lambda(t)\left[H^{\scriptscriptstyle m}(t,x,\bar{x})-\big(x-\phi \bar{x}\big)^2\right]=\mathcal{L}_{\scriptscriptstyle m}^{{\widehat{\pi}}}H^{\scriptscriptstyle m}(t,x,\bar{x}).
			\end{align}

			\item[$(4)$] A transversality condition holds. Specifically, for all \( (t,x,
			\bar{x})\in {[0,\infty)}\times \mathbb{R}\times \mathbb{R}\),
			\begin{align}\label{eq:MF-T}
				\lim_{s\to \infty}\mathbb{E}_{t,x,\bar{x}}\Big[e^{-\int_t^s \lambda(v)\drm v} j(s,X^{\bm{\widehat{\pi}}}(s),\bar{X}^{\bm{\widehat{\pi}}}(s))\Big]=0,
			\end{align}
			for \(j=G^{\scriptscriptstyle m}\), \(H^{\scriptscriptstyle m}\), \(V^{\scriptscriptstyle m}\), and \(f\).
		\end{itemize}


		Then
		\begin{align*}
			V^{\scriptscriptstyle m}(t,x,\bar{x})&=	(\mu_1 x+\mu_2)\mathbb{E}_{t,x,\bar{x},t+}[X^{\widehat{\bm{\pi}}}(\tau)-\phi\bar{X}^{\bm{\widehat{\pi}}}(\tau)]-\gamma Var_{t,x,\bar{x},t+}[X^{\widehat{\bm{\pi}}}(\tau)-\phi\bar{X}^{\bm{\widehat{\pi}}}(\tau)],\\
			G^{\scriptscriptstyle m}(t,x,\bar{x})&=\mathbb{E}_{t,x,\bar{x},t+}[X^{\widehat{\bm{\pi}}}(\tau)-\phi \bar{X}^{\bm{\widehat{\pi}}}(\tau)],\\
			H^{\scriptscriptstyle m}(t,x,\bar{x})&=\mathbb{E}_{t,x,\bar{x},t+}\left[\big(X^{\widehat{\bm{\pi}}}(\tau)-\phi \bar{X}^{\bm{\widehat{\pi}}}(\tau)\big)^2\right],
		\end{align*}
		in which $X^{\widehat{\bm{\pi}}}$ is the representative agent's wealth process  under the MFE strategy $\widehat{\bm{\pi}}$.
	\end{theorem}

	Similar to Subsection \ref{subsec:verif}, we assume that $\lambda(t)$ is a positive constant, that is, $\lambda(t) \equiv \lambda$. Under this assumption, we apply Theorem \ref{th:MF-verification} to derive the MFE and the corresponding value function for the MFG.
	Define
	\[Q_{\scriptscriptstyle m}:=\gamma \tilde{a}_{\scriptscriptstyle m}[r-\lambda+\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}(b-r)]-a_{\scriptscriptstyle m}\rho_{\scriptscriptstyle m}(b-r)^2[2\gamma(a_{\scriptscriptstyle m}-1)+\mu_{1}]\neq 0,\]
	in which
	\begin{align}
