		&+\{\rho_{\scriptscriptstyle m}(b-r)^2[\mu_{1}(3\lambda-4r)+4r\gamma]+\gamma(\lambda-r)^2\}z_{\scriptscriptstyle m}+\rho_{\scriptscriptstyle m}(b-r)^2[2\gamma r^2-\mu_{1}(\lambda-r)(\lambda-2r)]=0.\\\label{eq:MF-p1}
	\end{align}	
	Define
	\begin{align}
