				\widehat{\pi}( x,\bar{x})=\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m} x+\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m} \bar{x}+k_{1}\overline{\sigma\hat{\pi}}+k_{2}\overline{\underline{br}\widehat{\pi}}+k_3,
			\end{align}
			in which \(\rho_{\scriptscriptstyle m}\) is given in \eqref{eq:MFrho},  \(p_{\scriptscriptstyle m}=z_{\scriptscriptstyle m}/[\rho_{\scriptscriptstyle m}(b-r)]\), with \(z_{\scriptscriptstyle m}\) solving  \eqref{eq:MF-p1},
			and \(p_{\scriptscriptstyle m}\) satisfying \(\lambda>2r+2\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}(b-r)+\frac{1}{2}\rho_{\scriptscriptstyle m} {p^2_{\scriptscriptstyle m}}\). Meanwhile, \(q_{\scriptscriptstyle m}\) is the solution of \eqref{eq:MFq2}, and
			\(k_j\) (for \(j=1,2,3\)) is given in \eqref{eq:MFk1}, \eqref{eq:MFk2}, and \eqref{eq:MFk3}, respectively. And
			{
			\begin{align}
				\nonumber	\overline{\sigma\hat{\pi}}&= \frac{\big(1-\overline{\underline{br}k_2}\big)\big(\overline{\sigma\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\sigma\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\sigma k_3}\big)+\overline{\sigma k_2}\big(\overline{\underline{br}\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\underline{br}\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\underline{br} k_3}\big)}{\big(\overline{\underline{br}k_2}-1\big)\big(\overline{\sigma k_1}-1\big)-\overline{\sigma k_2}\cdot\overline{\underline{br}k_1}},\\
				\overline{\underline{br}\widehat{\pi}}&=\frac{\big(1-\overline{\sigma k_1}\big)\big(\overline{\underline{br} \rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\underline{br}\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\underline{br} k_3}\big)+\overline{\underline{br}k_1}\big(\overline{\sigma\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\sigma\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\sigma k_3}\big)}{\big(\overline{\underline{br}k_2}-1\big)\big(\overline{\sigma k_1}-1\big)-\overline{\sigma k_2}\cdot\overline{\underline{br}k_1}},\label{eq:MF-ops}
			\end{align}}
			Moreover, the corresponding equilibrium value function is given by
			\begin{align}\label{eq:MF-VV}
				V(x,\bar{x})=A_{\scriptscriptstyle m} x^2+C_{\scriptscriptstyle m} \bar{x}^2+D_{\scriptscriptstyle m} x\bar{x}+E_{\scriptscriptstyle m} x+F_{\scriptscriptstyle m} \bar{x}+I_{\scriptscriptstyle m},
			\end{align}
			in which
			\begin{align}
				A_{\scriptscriptstyle m}&=\mu_1 a_{\scriptscriptstyle m}+\gamma {a^2_{\scriptscriptstyle m}}{-\gamma  \tilde{a}_{\scriptscriptstyle m},}\\
				C_{\scriptscriptstyle m}&=\frac{\lambda\gamma(c_{\scriptscriptstyle m}+\phi)-\frac{\rho_{\scriptscriptstyle m}}{2}\gamma \tilde{a}_{\scriptscriptstyle m}{q^2_{\scriptscriptstyle m}}}{2r-\lambda},\\
				E_{\scriptscriptstyle m}&=\frac{\mu_1\alpha_{\scriptscriptstyle m}r-D_{\scriptscriptstyle m}\overline{\underline{br}\widehat{\pi}}-\rho_{\scriptscriptstyle m}\gamma  \tilde{a}_{\scriptscriptstyle m}\varrho_{\scriptscriptstyle m}p_{\scriptscriptstyle m}+2(a_{\scriptscriptstyle m}-1)\gamma\lambda \alpha_{\scriptscriptstyle m}-\mu_2\lambda}{r-\lambda},\\
				F_{\scriptscriptstyle m}&=\frac{2\lambda\gamma \alpha_{\scriptscriptstyle m}(c_{\scriptscriptstyle m}+\phi)+\lambda\mu_2\phi-\rho_{\scriptscriptstyle m}\gamma \tilde{a}_{\scriptscriptstyle m}\varrho_{\scriptscriptstyle m}q_{\scriptscriptstyle m}-2C_{\scriptscriptstyle m}\overline{\underline{br}\widehat{\pi}}}{r-\lambda},\\
				I_{\scriptscriptstyle m}&=\frac{(C_{\scriptscriptstyle m}-\gamma {c^2_{\scriptscriptstyle m}})\overline{\sigma\hat{\pi}}^2-\lambda \gamma {\alpha^2_{\scriptscriptstyle m}}+{\frac{\rho_{\scriptscriptstyle m}}{2}\gamma \tilde{a}_{\scriptscriptstyle m}\varrho^2_{\scriptscriptstyle m}}+F_{\scriptscriptstyle m}\overline{\underline{br}\widehat{\pi}}}{\lambda},
			\end{align}
			with
			\begin{align}
				\alpha_{\scriptscriptstyle m}&=\la^{-1}\big({c_{\scriptscriptstyle m}\overline{\underline{br}\widehat{\pi}}+a_{\scriptscriptstyle m}\rho_{\scriptscriptstyle m} \varrho_{\scriptscriptstyle m}(b-r)}\big), \label{eq:MFe1}\\
				\varrho_{\scriptscriptstyle m}&={\left[k_1\overline{\sigma\hat{\pi}}+k_2\overline{\underline{br}\widehat{\pi}}+k_3\right]/\rho_{\scriptscriptstyle m}}.
			\end{align}

			\item[$(2)$] if \(\big(\overline{\underline{br}k_2}-1\big)\big(\overline{\sigma k_1} -1\big)-\overline{\sigma k_2}\cdot\overline{\underline{br}k_1} =0\),
			\begin{itemize}
				\item[$(a)$] if there  exists a constant \(\kappa\) such that
				\begin{align}
					&\overline{\sigma\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\sigma \rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\sigma k_3}=\kappa[\overline{\underline{br} \rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\underline{br} \rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\underline{br}k_3}], \label{eq:MF-kappa}
					\\ &\overline{\sigma k_1}-1=\kappa\overline{\underline{br} k_1},\quad\quad \overline{\sigma k_2}=\kappa(\overline{\underline{br} k_2}-1). \label{eq:MF-kappa1}
				\end{align}
				hold, then the MFE exists, and the equilibrium  feedback  strategy \(\widehat{\pi}\) satisfies both of the following equations
				\begin{align}
					&\overline{\sigma\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\sigma\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\big(\overline{\sigma k_1}-1\big)\overline{\sigma\hat{\pi}}+\overline{\sigma k_2}\cdot\overline{\underline{br}\widehat{\pi}}+\overline{\sigma k_3}=0, \label{eq:MFsystem1}
				\end{align}
				and
				\begin{align}
					& \overline{\underline{br}\rho_{\scriptscriptstyle m} p_{\scriptscriptstyle m}x}+\overline{\underline{br}\rho_{\scriptscriptstyle m} q_{\scriptscriptstyle m}\bar{x}}+\overline{\underline{br}k_1}\cdot\overline{\sigma\hat{\pi}}+\big(\overline{\underline{br}k_2}-1\big)\overline{\underline{br}\widehat{\pi}}+\overline{\underline{br}k_3}=0.\label{eq:MFsystem2}
				\end{align}

				\item[$(b)$] if no such constant \(\kappa\) exists, the MFE does not exist.
			\end{itemize}
		\end{itemize}
	\end{theorem}

