	Define
	\begin{align}\label{eq:MFPsi}
		\Psi=\mathbb{E}\Big[\frac{\phi\sigma^2}{\xi^2+\sigma^2}\Big] \le 1, \quad \quad \Upsilon=\mathbb{E}\left[\frac{\mu_{1}\sigma x(b-r)}{2\gamma(\xi^2+\sigma^2)}\right],
	\end{align}
	and
	\begin{align}\label{eq:MFPhi}
		\Phi=\mathbb{E}\Big[\frac{\mu_2\sigma(b-r)}{2\gamma(\xi^2+\sigma^2)}\Big],\quad\quad {\Phi_0=\mathbb{E}\Big[\frac{\sigma b}{\gamma(\xi^2+\sigma^2)}\Big]}.
	\end{align}

	In the following corollary, we analyze the unique limiting MFE as \(\lambda\to\infty\).
	\begin{corollary}\label{coro:MF-1.8}
	As \(\lambda \to \infty\),  Then, the limiting MFE is given by
		\begin{itemize}
			\item[$(1)$] If \(\Psi < 1\), then
			\begin{align}
				\widehat{\pi}(x)=\frac{\mu_{1}(b-r)}{2\gamma(\xi^2+\sigma^2)}x+\frac{\phi\sigma}{\xi^2+\sigma^2} \cdot\frac{\Upsilon+\Phi}{1-\Psi} + \frac{\mu_{2}(b-r)}{2\gamma(\xi^2+\sigma^2) },
			\end{align}
			in which \(\Psi\), $\Upsilon$, and \(\Phi\) are given in \eqref{eq:MFPsi} and \eqref{eq:MFPhi}.
			Moreover, the corresponding equilibrium value function equals
			\begin{align}\label{eq:MFvalue1.8}
				V^{\scriptscriptstyle m}(x,\bar{x})=\mu_{1}x^2-\mu_{1}\phi x\bar{x}+\mu_{2}x-\mu_{2}\phi \bar{x}.
			\end{align}

			\item[$(2)$] If \(\Psi=1\), then
\begin{itemize}
\item[$(a)$] if \(\Upsilon+\Phi=0\), there are infinitely many MFEs, and the MFE is given by
    \begin{align}\label{eq:MFpicor1.80}
    \widehat{\pi}(x)=\frac{\mu_{1}(b-r)}{2\gamma(\xi^2+\sigma^2)}x+\frac{\phi\sigma}{\xi^2+\sigma^2} \overline{\sigma\hat{\pi}}+ \frac{\mu_{2}(b-r)}{2\gamma(\xi^2+\sigma^2) },
    \end{align}
    where \(\overline{\sigma\hat{\pi}} \) is an arbitrary real number.
    Furthermore, the corresponding equilibrium value function is given in \eqref{eq:MFvalue1.8}.

    \item[$(b)$] if \(\Upsilon+\Phi\neq0\) , then the MFE does not exist.
\end{itemize}
		\end{itemize}
	\end{corollary}

	The following corollary states the MFE and the value function when the risk aversion function is state-independent and the risk-free interest rate equals zero, that is, \blue{\(\mu_{1}=0\)}, \(\mu_{2}=2\), and \(r = 0\).
	\begin{corollary}\label{cor:MF-020}
		Suppose that \(\mu_{1}=0\), \(\mu_{2}=2\), and \(r=0\),
		and then for the mean-variance problem in the mean-field game with a state-independent risk aversion function,
		\begin{itemize}
			\item[$(1)$] if \(\Psi<1\), the MFE is a constant, given by
			\begin{align}\label{eq:MF-01pi}
				\widehat{\pi}=\frac{\phi\sigma}{\xi^2+\sigma^2}\cdot \frac{\Phi_0}{1-\Psi}+\frac{b}{\gamma(\xi^2+\sigma^2)},
			\end{align}		
			where \(\Psi\) and \(\Phi_0\) are given in \eqref{eq:MFPsi} and \eqref{eq:MFPhi}.
			Moreover, the corresponding value function of the representative agent is given by
			\begin{align*}
				V(x,\bar{x})=x-\phi \bar{x}+I_{\scriptscriptstyle m},
			\end{align*}
			in which
			\begin{align*}
				I_{\scriptscriptstyle m}&=\frac{-\gamma \phi^2 \overline{\sigma\hat{\pi}}^2+\gamma\frac{\rho_{\scriptscriptstyle m}}{2}{\varrho^2_{\scriptscriptstyle m}}-\phi\mathbb{E}[b\widehat{\pi}]-\lambda \gamma {\alpha^2_{\scriptscriptstyle m}}}{\lambda}, \\
				\alpha_{\scriptscriptstyle m}&=\frac{-\phi\mathbb{E}[b\widehat{\pi}]+\varrho_{\scriptscriptstyle m}b\widehat{\pi}}{\lambda},\\
				\varrho_{\scriptscriptstyle m}&=\frac{\gamma\phi\sigma\overline{\sigma\hat{\pi}}+b}{2\gamma(\xi^2+\sigma^2)^2}.
			\end{align*}

			\item[$(2)$] if  \(\Psi=1\), the MFE does not exist.
		\end{itemize}
	\end{corollary}
	\begin{remark}
		In this remark, we consider the relative performance investment problem for a continuum of agents with CARA preferences. We assume that the financial market is the same as that in Subsection  \ref{subsec:MF-model} except that the interest rate \(r = 0\), and the value function is given by
		\begin{align}
			\sup_{\bpi\in\bm{\Pi}^{\scriptscriptstyle m}}\mathbb{E}\Bigg[-\exp\Bigg(-\frac{1}{\gamma}\Big(X^{\bpi}(\tau)-\phi\bar{X}^{\bpi}(\tau)\Big)\Bigg)\Bigg],
		\end{align}
		in which the definition of the admissible set $\bm{\Pi}^m$ is the same as that in Subsection \ref{subsec:MF-model}.
		Then, one can show that the equilibrium investment strategy for this problem is also given by \eqref{eq:MF-01pi}.
		Thus, as the $n$-agent game scenario, we also obtain that when the risk-free interest rate $r=0$, the equilibrium investment strategy under CARA preferences is the same as that of the mean-variance problem with a state-independent risk-aversion within MFG framework.
	\end{remark}


	\subsection{The relationship between \(n\)-agent game and the MFG}\label{subsec:rela}

	In this subsection, we explore the relationship between the equilibrium feedback strategy in the \(n\)-agent game and the MFE of the MFG.
	We show that the time-consistent equilibrium of the \( n \)-agent game converges to the equilibrium of the MFG as $n \to \infty$.

	For each \(i \in \{1, \ldots, n\}\), let the type vector of the $i$-th agent be
	\( \eta_i = (x_i, b_i, \xi_i, \sigma_i, \phi_i, \gamma_i, \mu_{i1}, \mu_{i2}) \in \mathcal{Z}^e, \)
	and	the empirical measure \(m_n\) associated with the type vector \(\eta_i\) is defined in \eqref{eq:mn}. Moreover, we assume that the sequence of empirical measures \(\{m_n\}_{n\geq 1}\) converges weakly to a probability measure \(m\) in the sense of \eqref{eq:weak_converge} as \(n \to \infty\). Let random variable \(\eta = (x, b, \xi, \sigma, \phi, \gamma, \mu_1, \mu_2)\in\mathcal{Z}^e\) be the type vector assigned with the limiting distribution $m$.

	Recall that the notations of \(N_i\), \(\overline{\underline{br}k_2}^{(n)}\), \(\overline{\sigma k_1}^{(n)}\), \(\overline{\sigma k_2}^{(n)}\),  \(\overline{\underline{br}k_1}^{(n)}\),  and \(Q_i\) are given in Subsection \ref{subsec:verif}, and \(\overline{\underline{br}k_2}\), \(\overline{\sigma k_1}\), \(\overline{\sigma k_2}\),  \(\overline{\underline{br}k_1}\), and \(Q_{\scriptscriptstyle m}\) are given in Subsection \ref{subsec:MF-VT}. Then, using these notations, we obtain the following theorem.
	\begin{theorem}\label{th:relationship}
		Let the sequence of type vectors \((\eta_i)_{i\in\mathbb{N}}\) be independent and identically distributed $($i.i.d.$)$ samples  from the law \(m_n\), and let \(\eta = (x, b, \xi, \sigma, \phi, \gamma, \mu_1, \mu_2) \in \mathcal{Z}^e\) be a random variable on the probability space \((\Omega, \mathcal{F},\mathbb{F}, \mathbb{P})\) with the limiting distribution \(m\).
		Moreover, assume \(b_i\), \(\xi_i\), \(\sigma_i\), \(\phi_i\), \(\gamma_i\), \(\mu_{1i}\), and \(\mu_{2i}\) are finite. Then, if
		\(N_i\neq 0\), \(Q_i\neq 0\), \(Q_{\scriptscriptstyle m}\neq 0\), \(\big(\overline{\underline{br}k_2}^{(n)}-1\big)\big(\overline{\sigma k_1}^{(n)}-1\big)-\overline{\sigma k_2}^{(n)}\cdot\overline{\underline{br}k_1}^{(n)}\neq 0\), and \(\big(\overline{\underline{br}k_2}-1\big)\big(\overline{\sigma k_1}-1\big)-\overline{\sigma k_2}\cdot\overline{\underline{br}k_1} \neq 0\), we have
		\begin{align}
			\widehat{\pi}_i\to\widehat{\pi},~~{\rm{ a.s.}} ~~\text{as}~~ n\to\infty. \label{eq:limit_pi}
		\end{align}

	\end{theorem}
\begin{proof}
 See Appendix \ref {app:C}.
\end{proof}	





