\section{Proof of Theorem \ref{th:relationship}}\label{app:C}
\setcounter{equation}{0}
	\renewcommand{\theequation}{C.\arabic{equation}}
	\begin{proof}
		As \(n\to\infty\), the \(i\)-th agent in the \(n\)-agent game can be viewed as a representative agent in the MFG, and the arithmetic mean can be interpreted as the expected value in the limit. Thus, as \( n\to \infty\),
		\begin{align}
			\overline{\sigma\hat{\pi}}^{(n)}\to\overline{\sigma\hat{\pi}},~~\text{ a.s. }\\
			\overline{\underline{br}\hat{\pi}}^{(n)}\to\overline{\underline{br}\widehat{\pi}},~~\text{ a.s. }
		\end{align}
		Moreover, by recalling the expressions of \(p_i\), \(q_i\), and \(k_i\) given in  Subsection \ref{subsec:verif}, as well as the expressions of \(p_{\scriptscriptstyle m}\), \(q_{\scriptscriptstyle m}\), and \(k_{\scriptscriptstyle m}\) given in Subsection \ref{subsec:MF-VT}, and letting \(n\to\infty\), we obtain
		\begin{align*}
			&\rho_i\to\rho_{\scriptscriptstyle m}, \quad \text{a.s.} \\
			& p_i\rightarrow p_{\scriptscriptstyle m}, \quad \text{a.s.}\\
			& q_i \rightarrow q_{\scriptscriptstyle m}, \quad \text{a.s.}\\
			& k_{ij}\rightarrow k_j, \quad \text{a.s.}\\
		& 	{N_i\rightarrow 1,\quad\text{a.s.}}
		\end{align*}
		for \(i=1,\ldots,n,~ j=1,2,3.\)

		Since the equilibrium feedback strategy of the \(n\)-agent game is given by
		\[\widehat{\pi}_i=N_i^{-1}\left[\rho_ip_ix_i+\rho_iq_iy_{\smn i} +k_{i1}\overline{\sigma\hat{\pi}}^{(n)}+k_{i2}\overline{\underline{br}\hat{\pi}}^{(n)}+k_{i3}\right],\]
		and the MFE of the MFG equals
	\[\widehat{\pi}_{\scriptscriptstyle m}=\rho_{\scriptscriptstyle m}p_{\scriptscriptstyle m}x+\rho_{\scriptscriptstyle m}q_{\scriptscriptstyle m}\bar{x}+k_1\overline{\sigma\hat{\pi}}+k_2\overline{\underline{br}\widehat{\pi}}+k_3,\]
		thus, \eqref{eq:limit_pi} holds true.
	\end{proof}

