        \mathbf{A}^1&=
\left(
\begin{array}{ccccc}
 \frac{5-\sqrt{5}}{10} & \frac{\sqrt{5}}{5} & \frac{5-\sqrt{5}}{10} & 0 & 0 \\
 0 & \frac{5-\sqrt{5}}{10} & \frac{\sqrt{5}}{5} & \frac{5-\sqrt{5}}{10} & 0 \\
