\section{M step details}
\label{Appen:Mstepdetails}
The observed data likelihood for subject $i$ is defined in (\ref{likelihood}). Since we seek to obtain $\hat{\Psi}$ via SMLE, we present the complete data log-likelihood $l_i (\Ybf_i, T_i, D_i \mid \Psi)$ required by the E-step in (\ref{MstepFunction}), i.e.
{\small
\begin{eqnarray}
\label{complikelihood}
 l_i (\Ybf_i, T_i, D_i \mid \Psi) &=& \sum_{i=1}^n \left[\left\{ \sum_{g=1}^G \log f(\Ybf_{ig} \mid \bbf_i, \Psi) \right\} + \log f(T_i, D_i \mid \bbf_i, \Psi) + \log f(\bbf_i \mid \Psi)\right].
\end{eqnarray}
}
Note that each of these terms in (\ref{complikelihood}) involves a disjoint set of parameters; thus, to maximize (\ref{complikelihood}), we can maximize the expectation of each term separately. In the following, we describe the normal approximation algorithm used to update the parameters from iteration $(m)$ to iteration $(m +1)$.

\subsection{Update for \texorpdfstring{$\bm{\beta}$}{beta}}
We first set the log-likelihood $l_i (\Ybf_i, T_i, D_i \mid \Psi)$ with respect to $\beta$,
\begin{eqnarray*}
    l_i(\bm \beta) \propto -\frac{1}{2} (\Ybf_i - \Xbf_i^{\top}\bm \beta - \Zbf_i^{\top} \bbf_i)^{\top} V_i^{-1} (\Ybf_i - \Xbf_i^{\top}\beta - \Zbf_i^{\top} \bbf_i),
\end{eqnarray*}
where $\Xbf_i = \bigoplus_{g=1}^G X_{ig}$, $\Zbf_i = \bigoplus_{g=1}^G Z_{ig}$, and $V_i = \bigoplus_{g=1}^G \sigma_g^2 I_{n_{ig}}$, with $\bigoplus$ denoting the direct matrix sum and $I_x$ denoting an $x \times x$ identity matrix.

Now We need to compute the expectation of the above log-likelihood with respect to the posterior distribution of $\mathbf{b}_i$.

\[
E_i[l_i(\bm \beta)] = E_i \left[ -\frac{1}{2} (\Ybf_i - \Xbf_i^{\top} \bm \beta - \Zbf_i^{\top} \bbf_i)^{\top} \mathbf{V}_i^{-1} (\Ybf_i - \Xbf_i^{\top} \bm \beta - \Zbf_i^{\top} \bbf_i) \right]
\]
The random variable is \( \bbf_i \), and the fixed parameter is \( \bm \beta \). Using the approximation (\ref{biappro}), we have the conditional distribution of \( \bbf_i \) given the observed data is:
\[
\bbf_i \mid \Ybf_i, T_i, D_i, \Psi^{(m)} \sim N(\hat{\bbf}_i, \hat{\Sigma}_i),
\]
where \( \hat{\bbf}_i \) is the posterior mean, and \( \hat{\Sigma}_i \) is the posterior covariance of \( \bbf_i \). Therefore,

\[\Ybf_i - \Xbf_i^{\top} \bm \beta - \Zbf_i^{\top} \bbf_i \mid \Ybf_i, T_i, D_i, \Psi^{(m)} \sim N(\Ybf_i - \Xbf_i^{\top} \bm \beta -\Zbf_i^{\top}  \hat{\bbf}_i, \Zbf_i^{\top}\hat{\Sigma}_i\Zbf_i),
\]
Then we have 
\begin{eqnarray*}
E_i[l_i(\bm \beta)] &=& -\frac{1}{2} \left[ 
\text{Tr}\{\mathbf{V}_i^{-1}\Zbf_i^{\top}\hat{\Sigma}_i\Zbf_i\}+(\Ybf_i - \Xbf_i^{\top} \bm \beta -\Zbf_i^{\top}  \hat{\bbf}_i)^{\top}\mathbf{V}_i^{-1}(\Ybf_i - \Xbf_i^{\top} \bm \beta -\Zbf_i^{\top}  \hat{\bbf}_i)\right]
\end{eqnarray*}
To find the estimator for $\bm{\beta}$, we take the derivative of the log-likelihood with respect to $\bm{\beta}$:
{\small
\begin{eqnarray*}
   \frac{\partial E_i[l_i(\bm \beta)]}{\partial \bm \beta} &=&-\frac{1}{2}\frac{\partial}{\partial \bm \beta}(\Ybf_i - \Xbf_i^{\top} \bm \beta - \Zbf_i^{\top} \hat{\bbf}_i)^{\top} \mathbf{V}_i^{-1} (\Ybf_i - \Xbf_i^{\top} \bm \beta - \Zbf_i^{\top} \hat{\bbf}_i)\\
 &=&  -\frac{1}{2}\frac{\partial}{\partial \bm \beta}\left\{(\Ybf_i - \Zbf_i^{\top} \hat{\bbf}_i)^{\top} \mathbf{V}_i^{-1} (\Ybf_i - \Zbf_i^{\top} \hat{\bbf}_i)-2 (\bm{\beta}^{\top}\Xbf_i)\mathbf{V}_i^{-1}(\Ybf_i - \Zbf_i^{\top} \hat{\bbf}_i)+ (\bm{\beta}^{\top} \Xbf_i)\mathbf{V}_i^{-1} (\Xbf_i^{\top} \bm{\beta})\right\} \\
&=&\frac{\partial}{\partial \bm{\beta}} \left[ -\frac{1}{2} (\bm{\beta}^{\top}\mathbf{X}_i) \mathbf{V}_i^{-1} ( \mathbf{X}_i^{\top} \bm{\beta}) - \frac{1}{2} \cdot (-2) (\bm{\beta}^{\top}\mathbf{X}_i)\mathbf{V}_i^{-1}(\Ybf_i - \Zbf_i^{\top} \hat{\bbf}_i) \right] \\
&=& \mathbf{X}_i  \mathbf{V}_i^{-1} (\mathbf{Y}_i- \mathbf{Z}_i^{\top} \hat{\mathbf{b}}_i-\mathbf{X}_i^{\top} \bm{\beta})
\end{eqnarray*}
}
Setting the derivative to zero:
\begin{eqnarray*}
\mathbf{X}_i \mathbf{V}_i^{-1} (\mathbf{Y}_i -\mathbf{Z}_i^{\top} \hat{\mathbf{b}}_i) &=& \mathbf{X}_i \mathbf{V}_i^{-1}\mathbf{X}_i^{\top}\bm{\beta}
\end{eqnarray*}

%Thus, the estimator for $\bm{\beta}$ is:

%\begin{equation*}
%\hat{\bm{\beta}} = \left( \mathbf{X}_i %\mathbf{V}_i^{-1} \mathbf{X}_i^{\top} \right)^{-1} \left( %\mathbf{X}_i \mathbf{V}_i^{-1} \mathbf{Y}_i - %\mathbf{X}_i \mathbf{V}_i^{-1} \mathbf{Z}_i^{\top} %\hat{\mathbf{b}}_i \right).
%\end{equation*}



To derive the estimator for \(\bm{\beta}\), we sum this equation over all subjects \(i\) from 1 to \(n\). Thus:

\[
\sum_{i=1}^n \mathbf{X}_i \mathbf{V}_i^{-1} (\mathbf{Y}_i - \mathbf{Z}_i^{\top} \hat{\mathbf{b}}_i) = \sum_{i=1}^n \mathbf{X}_i \mathbf{V}_i^{-1} \mathbf{X}_i^{\top} \bm{\beta}
\]



Solving for $\bm{\beta}$ gives:

\[
\hat{\bm{\beta}} = \left(\sum_{i=1}^n \mathbf{X}_i \mathbf{V}_i^{-1} \mathbf{X}_i^{\top}\right)^{-1} \left\{\sum_{i=1}^n \mathbf{X}_i \mathbf{V}_i^{-1} \left(\mathbf{Y}_i - \mathbf{Z}_i^{\top} \hat{\mathbf{b}}_i\right)\right\}
\]



\subsection{\texorpdfstring{Update for $\sigma_g^2$}{Update for sigma\_g²}}
We set the log-likelihood w.r.t. $\sigma_g^2$,
\begin{eqnarray*}
    l_i(\sigma_g^2) \propto -\frac{n_{ig}}{2} \log \sigma_g^2 - \sum_{j=1}^{n_{ig}}\frac{1}{2\sigma_g^2} \left\{Y_{ig}(t_{ijg}) - X_{ig}^{\top}(t_{ijg}) \beta_g - Z_{ig}^{\top}(t_{ijg}) b_{ig}\right\}^2.
\end{eqnarray*}
Define $r_{ig}(t_{ijg}) = Y_{ig}(t_{ijg}) - X_{ig}^{\top}(t_{ijg}) \beta_g$. Then the expected value 
{\small
\begin{eqnarray*}
    E_i [l_i(\sigma_g^2)] &=& -\frac{n_{ig}}{2} \log \sigma_g^2 - \sum_{j=1}^{n_{ig}}\frac{1}{2\sigma_g^2} E_i \left\{r_{ig}(t_{ijg}) - Z_{ig}^{\top}(t_{ijg}) b_{ig}\right\}^2, \\
    &=& -\frac{n_{ig}}{2} \log \sigma_g^2 - \sum_{j=1}^{n_{ig}}\frac{1}{2\sigma_g^2} \left[r_{ig}^2(t_{ijg}) -  2 r_{ig}(t_{ijg}) Z_{ig}^{\top}(t_{ijg}) E_i(b_{ig}) + \text{Tr}\left\{Z_{ig}(t_{ijg})Z_{ig}^{\top}(t_{ijg}) E_i(b_{ig} b_{ig}^{\top})\right\}\right]
\end{eqnarray*}
}
The first derivative w.r.t. $\sigma_g^2$ is
\begin{eqnarray*}
\frac{\partial E_i [l_i(\sigma_g^2)]}{\partial \sigma_g^2} &=&
 -\frac{n_{ig}}{2\sigma_g^2} + \frac{1}{2\sigma_g^4} \sum_{j=1}^{n_{ig}} \left[r_{ig}^2(t_{ijg}) - 2 r_{ig}(t_{ijg}) Z_{ig}^{\top}(t_{ijg}) E_i(b_{ig}) +  \text{Tr}\left\{Z_{ig}(t_{ijg})Z_{ig}^{\top}(t_{ijg}) E_i(b_{ig} b_{ig}^{\top})\right\}\right].
\end{eqnarray*}
Equating the above equation to be 0 and solve for $\sigma_g^2$ for all $i=1,\ldots,n$, we obtain the close-form update
\begin{eqnarray*}
    \hat{\sigma}_g^2 =\frac{\sum_{i=1}^n \sum_{j=1}^{n_{ig}} \left[r_{ig}^2(t_{ijg}) -  2 r_{ig}(t_{ijg}) Z_{ig}^{\top}(t_{ijg}) E_i(b_{ig}) +  \text{Tr}\left\{Z_{ig}(t_{ijg})Z_{ig}^{\top}(t_{ijg}) E_i(b_{ig} b_{ig}^{\top})\right\}\right]}{\sum_{i=1}^n n_{ig}}. 
\end{eqnarray*}
Using the approximation (\ref{biappro}), we have $E_i(b_{ig}) = \hat{b}_{ig}$ and $Var(\bbf_i) = \hat{\Sigma}_{ig}$, where $\hat{b}_{ig}$ is the posterior mode w.r.t. $b_{ig}$, i.e., the random effects for the $g^{th}$ longitudinal response, and $\hat{\Sigma}_{ig}$ is the $(g,g)^{th}$ block matrix of $\hat{\Sigma}_i$.  This results in
\begin{eqnarray*}
    E_i(b_{ig} b_{ig}^{\top}) &=& Var(b_{ig}) + E_i(b_{ig}) E_i(b_{ig})^{\top} \\
    &=& \hat{\Sigma}_{ig} + \hat{b}_{ig} \hat{b}_{ig}^{\top}.
\end{eqnarray*}
Therefore, we have 
\begin{eqnarray*}
    \hat{\sigma}_g^2 =\frac{\sum_{i=1}^n \sum_{j=1}^{n_{ig}} \left[r_{ig}^2(t_{ijg}) -  2 r_{ig}(t_{ijg}) Z_{ig}^{\top}(t_{ijg}) \hat{b}_{ig} +  \text{Tr}\left\{Z_{ig}(t_{ijg})Z_{ig}^{\top}(t_{ijg}) (\hat{\Sigma}_{ig} + \hat{b}_{ig} \hat{b}_{ig}^{\top})\right\}\right]}{\sum_{i=1}^n n_{ig}}. 
\end{eqnarray*}

\subsection{\texorpdfstring{Update for $\Sigma$}{Update for Sigma}}
We have
\begin{eqnarray*}
    E_i [\log f(\bbf_i \mid \Sigma)] &=& E_i \left[-\frac{q}{2} \log(2\pi) - \frac{1}{2}\log \mid\Sigma\mid - \frac{1}{2}\bbf_i^{\top} \Sigma^{-1} \bbf_i\right] \\
    &=& -\frac{q}{2} \log(2\pi) + \frac{1}{2} \log\mid\Sigma^{-1}\mid - \frac{1}{2}\text{Tr}\left\{\Sigma^{-1} E_i(\bbf_i \bbf_i^{\top})\right\}.
\end{eqnarray*}
The first derivative of $E_i [\log f(\bbf_i \mid \Sigma)]$ w.r.t. $\Sigma$ is
\begin{eqnarray*}
    \frac{\partial E_i [\log f(\bbf_i \mid \Sigma)]}{\partial \Sigma} = -\frac{1}{2}\Sigma + \frac{1}{2} E_i(\bbf_i \bbf_i^{\top}).
\end{eqnarray*}
Equating the above equation to be 0, we obtain the close-form update
\begin{eqnarray*}
    \hat{\Sigma} = E_i(\bbf_i \bbf_i^{\top}).
\end{eqnarray*}
Using the approximation (\ref{biappro}), we have $E_i(\bbf_i) = \hat{\bbf}_i$ and $Var(\bbf_i) = \hat{\Sigma}_i$. This results in
\begin{eqnarray*}
    E_i(\bbf_i \bbf_i^{\top}) &=& Var(\bbf_i) + E_i(\bbf_i) E_i(\bbf_i)^{\top} \\
    &=& \hat{\Sigma}_i + \hat{\bbf}_i \hat{\bbf}_i^{\top}.
\end{eqnarray*}
Finally, we solve for $\Sigma$ for all $i=1,\ldots,n$
\begin{eqnarray*}
    \hat{\Sigma} = \frac{\sum_{i=1}^n (\hat{\Sigma}_i + \hat{\bbf}_i \hat{\bbf}_i^{\top})}{n}.
\end{eqnarray*}

\subsection{\texorpdfstring{Update for $\Lambda_{0k}(.)$}{Update for Lambda\_0k(.)}}
We have
\begin{eqnarray*}
  \log  f(T_i, D_i \mid \bbf_i, \Psi) &=& \sum_{k=1}^K \left[I(D_i=k)\left\{\log \Delta \Lambda_{0k}(T_i) + W_i^{\top} \gamma_k + \sum_{g=1}^G \alpha_{kg}^{\top} b_{ig}\right\} \right. \cr
  && \left. -  \Lambda_{0k}(T_i)\exp\left(W_i^{\top} \gamma_k + \sum_{g=1}^G \alpha_{kg}^{\top} b_{ig}\right)\right]  \cr
  &=& \sum_{k=1}^K\left[I(D_i=k)\left\{\log \Delta \Lambda_{0k}(T_i) + W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i}\right\}\right.  \cr
  && \left.-  \Lambda_{0k}(T_i)\exp(W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i})\right].
\end{eqnarray*}

We now set the log likelihood w.r.t. $\Delta \Lambda_{0k}(.)$
\begin{eqnarray*}
    l_i(\Delta \Lambda_{0k}) &\propto& I(D_i = k) \log \Delta \Lambda_{0k}(T_i) -  \Lambda_{0k}(T_i)\exp(W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i}) \\
    E_i\left[l_i(\Delta \Lambda_{0k})\right] &=& I(D_i = k) \log \Delta \Lambda_{0k}(T_i) -  \Lambda_{0k}(T_i) E_i\left[\exp(W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i})\right].
\end{eqnarray*}
Using the approximation (\ref{biappro}), we have 
\begin{eqnarray}
\label{EWb}
   W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i} \sim N\left(W_i^{\top} \gamma_k + \alpha_k^{\top}\hat{\bbf}_{i}, \alpha_k^{\top} \hat{\Sigma}_i \alpha_k  \right) = N\left(\mu_{ik}, \tau_{ik}^2\right).
\end{eqnarray}

Based upon equation (\ref{EWb}), calculating $E_i\left[\exp\left\{ \alpha_k^{\top} \bbf_{i}\right\}\right]$ is equivalent to the moment generating function (MGF) $M_{\bbf_{i}}(t) = \exp\left\{\hat{\bbf}_{i}^{\top} t + \frac{1}{2}t^{\top} \hat{\Sigma}_i t\right\}$ evaluated at $t = \alpha_k$. Therefore, we can approximate the expectation above as
\begin{eqnarray*}
    E_i\left[l_i(\Delta \Lambda_{0k})\right] &\approx& \Tilde{E}_i\left[l_i(\Delta \Lambda_{0k})\right] \\
    &=& I(D_i = k) \log \Delta \Lambda_{0k}(T_i) -  \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k + \alpha_k^{\top}\hat{\bbf}_{i} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_i \alpha_k\right).
\end{eqnarray*}
Take the first derivative w.r.t. $\Delta \Lambda_{0k}(.)$, we obtain the closed-form update of $ \Lambda_{0k}(.)$
\begin{eqnarray}
\label{Mstep:lambda}
    \hat{\Lambda}_{0k}(t) = \sum_{l: s< t_{kl} \leq t}  \frac{d_{kl}}{\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)},
\end{eqnarray}
where $R(t_{kl})$ is the risk set at the uncensored $k$-th failure time $t_{kl}$, and $d_{kl}$ is the number of type $k$ failures at $t_{kl}$, for $k=1, \ldots, K.$

\subsection{\texorpdfstring{Update for $\gamma$ and $\alpha$}{Update for gamma and alpha}}
Using the survival log-likelihood, we can calculate the expectation on the survival fixed effects $\phi_k = (\gamma_k^{\top}, \alpha_k^{\top})^{\top}$:
\begin{eqnarray*}
    l_i(\phi_k) &\propto&
    I(D_i = k) (W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i}) -  \Lambda_{0k}(T_i) \exp(W_i^{\top} \gamma_k +  \alpha_k^{\top} \bbf_{i}), \cr
    E_i\left\{l_i(\phi_k)\right\} &=&  I(D_i = k) \left\{W_i^{\top} \gamma_k + E_i (\alpha_k^{\top} \bbf_{i})\right\} -  \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k\right) E_i \left\{\exp(\alpha_k^{\top} \bbf_{i})\right\},
\end{eqnarray*}
where $\Lambda_{0k}(.)$ will be substituted with $\hat{\Lambda}_{0k}(.)$ from (\ref{Mstep:lambda}).
 We note that there is no closed-form solution for $\phi_k$ and it will be updated via an one-step Newton-Raphson algorithm from the current estimate:
\begin{eqnarray*}
    \hat{\phi_k} &=& \phi_k + I_{\phi_k}^{-1}S_{\phi_k},\quad k=1,\ldots,K,
\end{eqnarray*}
where 
\begin{eqnarray}
\label{Mstepscorefunc}
    S_{\phi_k} &=& (S_{\gamma_k}^{T}, S_{\alpha_k}^{T})^{T}, \\
    \label{Mstepinfo}
    I_{\phi_k} &=& 
    \begin{pmatrix}
I_{\gamma_k} & I_{\gamma_k \alpha_k} \\
I_{\gamma_k \alpha_k}^{T} & I_{\alpha_k}
\end{pmatrix}.
\end{eqnarray}
The explicit formulas of all the quantities in (\ref{Mstepscorefunc}) - (\ref{Mstepinfo}) are given by
\begin{eqnarray*}
    S_{\gamma_k} &=& \sum_{i=1}^n I(D_i = k) W_i -  \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k\right)E_i\left\{\exp(\alpha_k^{\top} \bbf_{i})\right\}W_i, \cr
     S_{\alpha_k} &=& \sum_{i=1}^n I(D_i = k) E_i (\bbf_{i}) -  \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k\right)E_i\left\{\bbf_{i}\exp( \alpha_k^{\top} \bbf_{i})\right\},\cr
     I_{\gamma_k} &=& \sum_{i=1}^n \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k\right)E_i\left\{\exp(\alpha_k^{\top} \bbf_{i})\right\}W_iW_i^{\top},\cr
     I_{\alpha_k} &=& \sum_{i=1}^n   \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k\right) E_i\left\{\bbf_{i} \bbf_{i}^{\top}\exp(\alpha_k^{\top} \bbf_{i})\right\}, \cr
     I_{\gamma_k \alpha_k} &=& \sum_{i=1}^n \Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k\right) W_iE_i\left\{\bbf_{i}\exp( \alpha_k^{\top} \bbf_{i})\right\}^{\top}.
\end{eqnarray*}
Using the approximation (\ref{EWb}), approximating $E_i\left\{\exp(\alpha_k^{\top} \bbf_{i})\right\}$ will be the same as in updating $\Lambda_{0k}(.)$. The two expected values $E_i\left\{\bbf_{i}\exp(\alpha_k^{\top} \bbf_{i})\right\}$ and $E_i\left\{\bbf_{i} \bbf_{i}^{\top}\exp(\alpha_k^{\top} \bbf_{i})\right\}$ can be approximated by the first and second derivative of $M_{\bbf_{i}}(t)$ evaluated at $t = \alpha_k$, respectively:
\begin{eqnarray*}
   E_i\left\{\bbf_{i}\exp( \alpha_k^{\top} \bbf_{i})\right\} &\approx& \exp\left(\alpha_k^{\top}\hat{\bbf}_{i} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_i \alpha_k\right)\left(\hat{\Sigma}_i \alpha_k + \hat{\bbf}_{i}\right),
\end{eqnarray*}
\begin{eqnarray*}
    E_i\left[\bbf_{i} \bbf_{i}^{\top}\exp\left\{ \alpha_k^{\top} \bbf_{i}\right\}\right] &\approx& \exp\left(\alpha_k^{\top}\hat{\bbf}_{i} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_i \alpha_k\right) \left\{\left(\hat{\Sigma}_i \alpha_k + \hat{\bbf}_{i}\right)\left(\hat{\Sigma}_i \alpha_k + \hat{\bbf}_{i}\right)^{\top} + \hat{\Sigma}_i\right\}.
\end{eqnarray*}

\section{Score function formulas for standard error estimation}
\label{Appen:computational-details-SE}
Note that $l^{(i)}(\Omega)$ is the profile likelihood obtained by profiling out the baseline hazard $\lambda_0(.)$ from the observed data likelihood. Calculating its gradient, however, is difficult because there is no explicit expression for the profile likelihood. Here we approximate $\nabla_{\Omega}l^{(i)}(\hat{\Omega})$ by the derivative of the profile expected complete-data log-likelihood, obtained in the last E-step when the EM algorithm has converged. The parametric components of the observed score function $\nabla_{\Omega}l^{(i)}(\hat{\Omega})$ in equation (\ref{SEestimation}) can be calculated via normal approximation:

{\footnotesize
\begin{eqnarray}
\label{Appen:SEbeta}
\nabla_{\beta_g}l^{(i)} (\hat{\Omega})\!\!\! &=& \!\!\! \frac{1}{\sigma_g^2}\sum_{j=1}^{n_{ig}} E_i\left\{Y_{ig}(t_{ijg})-X_{ig}^{\top}(t_{ijg})\beta_g - Z_{ig}^{\top}(t_{ijg}) b_{ig}\right\} X_{ig}(t_{ijg})\Bigg |_{\Omega = \hat{\Omega}}, \cr
&\approx& \frac{1}{\sigma_g^2} \sum_{j=1}^{n_{ig}} \left\{Y_{ig}(t_{ijg})-X_{ig}^{\top}(t_{ijg})\beta_g\right\}X_{ig}(t_{ijg}) - X_{ig}(t_{ijg}) Z_{ig}^{\top}(t_{ijg}) \hat{b}_{ig} \Bigg |_{\Omega = \hat{\Omega}} \\
\label{Appen:SEsigma2}
\nabla_{\sigma_g^2}l^{(i)} (\hat{\Omega})\!\!\! &=&\!\!\! \left[ \frac{1}{2\sigma_g^4} \sum_{j=1}^{n_{ig}} E_i\left\{Y_{ig}(t_{ijg})-X_{ig}^{\top}(t_{ijg})\beta_g - Z_{ig}^{\top}(t_{ijg}) b_{ig}\right\}^2 \! - \! \frac{n_{ig}}{2\sigma_g^2} \right]\Bigg |_{\Omega = \hat{\Omega}}, \cr
&\approx& \sum_{j=1}^{n_{ig}}\frac{\left[r_{ig}^2(t_{ijg}) -  2 r_{ig}(t_{ijg}) Z_{ig}^{\top}(t_{ijg}) \hat{b}_{ig} +  \text{Tr}\left\{Z_{ig}(t_{ijg})Z_{ig}^{\top}(t_{ijg}) (\hat{\Sigma}_{ig} + \hat{b}_{ig} \hat{b}_{ig}^{\top})\right\}\right]}{2\sigma_g^4} - \frac{n_{ig}}{2\sigma_g^2}, \\
\label{Appen:SESigma}
\nabla_{\Sigma}l^{(i)} (\hat{\Omega}) \!\!\!  &=& \!\!\! \frac{1}{2}\left[2\Sigma^{-1}E_i(\bbf_i \bbf_i^{\top}) \Sigma^{-1}\!\! -\!\!  \left\{\Sigma^{-1}E_i(\bbf_i \bbf_i^{\top}) \Sigma^{-1} \circ I\right\} \!\! -\!\! 2\Sigma^{-1}\! + \!\Sigma^{-1} \circ I\right]\Bigg |_{\Omega = \hat{\Omega}}, \cr
&\approx& \frac{1}{2}\left[2\Sigma^{-1} (\hat{\Sigma}_i + \hat{\bbf}_i \hat{\bbf}_i^{\top}) \Sigma^{-1}\!\! -\!\!  \left\{\Sigma^{-1} (\hat{\Sigma}_i + \hat{\bbf}_i \hat{\bbf}_i^{\top}) \Sigma^{-1} \circ I\right\} \!\! -\!\! 2\Sigma^{-1}\! + \!\Sigma^{-1} \circ I\right], \\
\label{Appen:SEgamma}
\nabla_{\gamma_k}l^{(i)}(\hat{\Omega})\!\!\! &=& \!\!\! I(D_i = k) \left[ W_i - \frac{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k\right)  E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}W_r}{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k\right)  E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}} \right] \cr
&& + \left( \sum_{j: t_{kl} \leq T_i} \frac{d_{kj}\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k\right)  E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}W_r}{\left[\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k\right)  E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}\right]^2} \right. \cr
&& \left. -\sum_{j: t_{kl} \leq T_i}\frac{d_{kj}}{\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k\right)  E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}}W_i \right) \cr
&& \times \exp\left(W_i^{\top} \gamma_k\right)E_i\left\{\exp(\alpha_k^{\top}\bbf_{i})\right\}\Bigg |_{\Omega = \hat{\Omega}}, \cr
 &\approx& \!\!\! I(D_i = k) \left\{ W_i - \frac{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right) W_r}{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)} \right\} \cr
&& + \left[ \sum_{j: t_{kl} \leq T_i} \frac{d_{kj}\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)W_r}{\left\{\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)\right\}^2} \right. \cr
&& \left. -\sum_{j: t_{kl} \leq T_i}\frac{d_{kj}}{\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)}W_i \right] \cr
&& \times \exp\left(W_i^{\top} \gamma_k + \alpha_k^{\top} \bbf_{i} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_i \alpha_k\right)\Bigg |_{\Omega = \hat{\Omega}}, \\
\label{Appen:SEnu}
\nabla_{\alpha_k}l^{(i)}(\hat{\Omega}) &=& I(D_i = k)\left[ E_i\left(\bbf_{i}\right) - \frac{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k\right) E_r\left\{\bbf_{r}\exp\left(\alpha_k^{\top}\bbf_{r}\right)\right\}}{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k\right) E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}}\right] \cr
&& + \left( \sum_{j: t_{kl} \leq T_i} \frac{d_{kj}\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k\right) E_r\left\{\bbf_{r}\exp\left(\alpha_k^{\top}\bbf_{r}\right)\right\}}{\left[\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k\right) E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}\right]^2} E_i\left\{\exp(\alpha_k^{\top}\bbf_{i})\right\} \right. \cr
&& \left. - \sum_{j: t_{kl} \leq T_i}\frac{d_{kj}}{\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k\right) E_r\left\{\exp(\alpha_k^{\top}\bbf_{r})\right\}} E_i\left\{\bbf_{i}\exp\left(\alpha_k^{\top}\bbf_{i}\right)\right\} \right) \cr
&& \times \exp\left(W_i^{\top} \gamma_k\right)\Bigg |_{\Omega = \hat{\Omega}}, \cr
&\approx& I(D_i = k)\left\{\hat{\bbf}_{i} - \frac{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)\left(\hat{\Sigma}_r \alpha_k + \hat{\bbf}_{r}\right)}{\sum_{r \in R(T_i)} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)}\right\} \cr
&& + \left( \sum_{j: t_{kl} \leq T_i} \frac{d_{kj}\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)\left(\hat{\Sigma}_r \alpha_k + \hat{\bbf}_{r}\right)}{\left[\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)\right]^2} \right. \cr
&& \times \left. \exp\left(\alpha_k^{\top} \hat{\bbf}_{i} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_i \alpha_k\right) \right. \cr
&& \left. - \sum_{j: t_{kl} \leq T_i}\frac{d_{kj}}{\sum_{r \in R(t_{kl})} \exp\left(W_r^{\top} \gamma_k + \alpha_k^{\top} \hat{\bbf}_{r} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_r \alpha_k\right)} \right.\cr
&& \times \left. \exp\left\{\alpha_k^{\top} \bbf_{i} + \frac{1}{2}\alpha_k^{\top} \hat{\Sigma}_i \alpha_k\right\}\left\{\hat{\Sigma}_i \alpha_k + \hat{\bbf}_{i}\right\} \right)  \exp\left(W_i^{\top} \gamma_k\right)\Bigg |_{\Omega = \hat{\Omega}}. 
\end{eqnarray}
}

\section{Linear scan algorithms for efficient implementation for the shared random effects model}% in the EM steps and standard error estimation}
\label{Appen:Comp}
Here, we derive linear scan algorithms to reduce the computational burden using similar ideas to \citet{li2022efficient}. Below we discuss some linear scan algorithms for implementation of the EM steps and standard error estimation.  
\subsection{Linear scan for the E-step}
The E-step involves evaluating the expectations of $h(\bbf_i)$ at each EM iteration, which requires calculating $f(T_i, D_i\mid \bbf_i, \Psi^{(m)})$ across all subjects. Note that $f(T_i, D_i\mid \bbf_i, \Psi^{(m)})$ can be rewritten as 
\begin{eqnarray*}
f(T_i, D_i\mid \bbf_i, \Psi) & = & \prod_{k=1}^K \left\{\Delta\Lambda_{0k}(T_i) \exp\left(W_i^{\top} \gamma_k + \alpha_k^{\top} \bbf_i\right)\right\}^{I(D_i=k)} \cr
     &&\times  \exp\left\{-\sum_{k=1}^K \int_0^{T_i} \exp\left(W_i^{\top} \gamma_k + \alpha_k^{\top} \bbf_i\right)d\Lambda_{0k}(t)\right\} \cr
& = & \prod_{k=1}^K \left\{\Delta\Lambda_{0k}(T_i) \exp(W_i^{\top} \gamma_k + \alpha_k^{\top} \bbf_i)\right\}^{I(D_i=k)}  \cr
&& \quad \times \exp \left\{-\sum_{k=1}^K \Lambda_{0k}(T_i) \exp(W_i^{\top} \gamma_k + \alpha_k^{\top} \bbf_i) \right\}.
\end{eqnarray*}
For each subject $i$, calculating $\Lambda_{0k}(T_i)$ would involve $O(n)$ operations if a global search is performed to find an interval of two adjacent uncensored event times that contains $T_i$. Consequently, calculating all $\Lambda_{0k}(T_i)$'s will require $O(n^2)$ operations. Similar to \citet{li2022efficient}, by taking advantage of the fact that $\Lambda_{0k}(t)$ is a right-continuous and non-decreasing step function, we define the following a linear scan map 
{\small
\begin{eqnarray}
\label{eqn:Lscan}
\{\Lambda_{0k}(t_{k1}), \Lambda_{0k}(t_{k2}), \ldots \Lambda_{0k}(t_{kq_k}) \} \mapsto \{\Lambda_{0k}(T_{(1)}), \Lambda_{0k}(T_{(2)}), \ldots, \Lambda_{0k}(T_{(n)})\},
\end{eqnarray}
}
where $t_{k1} > \cdots > t_{kq_k}$ are scanned forward from the largest to the smallest, and for each $t_{kl}$, only a subset of the ranked observation times $T_{(i)}$ are scanned forward to calculate  $\Lambda_{0k}(T_{(i)})$ as follows
\begin{equation*}
  \Lambda_{0k}(T_{(i)}) =
    \begin{cases}
     \Lambda_{0k}(t_{k1}) , & \text{if $T_{(i)} \geq t_{k1}$,}\\
      \Lambda_{0k}(t_{k(l+1)}), & \text{if $T_{(i)} \in [t_{k(l+1)}, t_{kl}), $ for some $l\in\{1,\ldots, q_k-1 \}$},\\
      0, & \text{$T_{(i)}<t_{kq_k}$}.
    \end{cases}       
\end{equation*}
Consequently, the entire algorithm for calculating all $\Lambda_{0k}(T_i)$'s costs only $O(n)$ operations since the scanned $T_{(i)}$'s for different $t_{kl}$'s do not overlap.

\subsection{Linear risk set scan for the M-step}
Multiple quantities in (\ref{Mstep:lambda})-(\ref{Mstepinfo}) including the cumulative baseline hazard functions involve aggregating information over the risk set $R(t_{kl}) = \{r: T_r \geq t_{kl}\}$ at each uncensored event time $t_{kl}$, which are further aggregated across all $t_{kl}$'s. All subjects are scanned to determine the risk set $R(t_{kl})$ for all uncensored event times will require $O(n^2)$ operations. Specifically, to update $\Lambda_{0k}(t_{kl})$, $\gamma_k$ and $\alpha_k$, one needs to compute $\sum_{r \in R(t_{kl})} a_r$, where $a_r$ is any time-independent quantity defined in equations (\ref{Mstep:lambda})-(\ref{Mstepinfo}). The risk set $R(t_{k(l+1)})$ can be decomposed into two disjoint sets: 
\begin{eqnarray}
\label{Appen:MstepScan}
\sum_{r \in R(t_{k(l+1)})} a_{r} = \sum_{r \in R(t_{kl})} a_{r} +\sum_{\{r: T_{(r)} \in [t_{k(l+1)}, t_{kl})\}}  a_{r},
\end{eqnarray}
where the distinct uncensored event times $t_{k1}> \cdots>t_{kq_k}$ are arranged in a decreasing order. 
it is easy to see that calculating $\sum_{r \in R(t_{kl})} a_{r}$, $j=1, \ldots q_k$, takes $O(n)$ operations when 
$T_{(r)}$'s are scanned backward in time, by following the recursive formula (\ref{Appen:MstepScan}) where the subjects in $R(t_{kl})$ do not need to be scanned to calculate the second term.

\subsection{Linear risk set scan for standard error estimation}
Standard error estimation formula in (\ref{SEestimation}) relies on the observed score vectors from the profile likelihood where the baseline hazards are profiled out. It is seen from equations (\ref{Appen:SEgamma})-(\ref{Appen:SEnu}) that obtaining the observed score vectors $\nabla_{\gamma_k}l^{(i)}(\hat{\Omega})$ and $\nabla_{\alpha_k}l^{(i)}(\hat{\Omega})$ involve aggregating information either over $\{ r\in R(T_i) \}$ or over both $\{r \in R(t_{kl})\}$ and $\{ j: t_{kl} \le T_i\}$,  which can takes either $O(n)$ or $O(n^2)$ operations, respectively, if not optimized. As a result, the empirical Fisher information matrix can take $O(n^3)$ operations as it requires summing up the information across all subjects. Specifically, to calculate the gradient $\nabla_{\gamma_k}l^{(i)}(\hat{\Omega})$ and $\nabla_{\alpha_k}l^{(i)}(\hat{\Omega})$, one needs to compute
\begin{eqnarray*}
    B(T_i) = \sum_{l: t_{kl} \le T_i}b_{kl}, \quad\mbox{for $i=1,..., n$,}
\end{eqnarray*}
where $B(.)$ is a right-continuous non-decreasing step function and $b_{kl} = \sum_{r \in R(t_{kl})} a_{r}$ is any time-independent quantity defined in equations (\ref{Appen:SEgamma}) - (\ref{Appen:SEnu}). Note that $B(t_{k1}), \ldots, B(t_{kq_k})$ can be computed in $O(n)$ operations as one scans through $t_{k1}, \ldots, t_{kq_k}$ backward in time, following the recursive formula (\ref{Appen:MstepScan}). Furthermore, analogous to (\ref{eqn:Lscan}), the following linear scan algorithm can be used to calculate $\{B(T_{(1)}), B(T_{(2)}), \cdots, B(T_{(n)})\}$ from $\{B(t_{k1}),\ldots, B(t_{kq_k})\}$:
\begin{eqnarray*}
\{B(t_{k1}),\ldots, B(t_{kq_k})\} \mapsto \{B(T_{(1)}), B(T_{(2)}), \cdots, B(T_{(n)})\},
\end{eqnarray*}
where for each $t_{kl}$, only a subset of the ranked observation times $T_{(i)}$'s are scanned forward to calculate  $B(T_{(i)})$'s as follows
\begin{equation*}
  B(T_{(i)}) =
    \begin{cases}
      B(t_{k1}), & \text{if $T_{(i)} \geq t_{k1}$,}\\
      B(t_{k(l+1)}), & \text{if $T_{(i)} \in [t_{k(l+1)}, t_{kl}), \; $ for some $l\in\{1,\ldots, q_k-1 \}$,}\\
      0, & \text{otherwise}.
    \end{cases}       
\end{equation*}
Consequently, calculating all $B(T_{(i)})$'s takes $O(n)$ operations.

